INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37836, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この魚は水の外でも一時間ほど生きだ。", "corrected_sentence": "この魚は水の外でも一時間ほど生きている。", "error_description": "誤りは「生きだ」。「だ」は名詞に続く形で、動詞「生きる」には続かない。正しくは「生きている」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "生きた", "is_correct": true, "explanation": "過去形で、「九十歳まで元気に生きた」と過去の出来事を述べて文が成り立つ。"}, {"text": "生きて", "is_correct": false, "explanation": "て形では文が終わらず、文が成り立たない。"}, {"text": "生きない", "is_correct": false, "explanation": "否定形は「元気に生きなかった」の意味になり、文の内容が合わない。"}, {"text": "生きよう", "is_correct": false, "explanation": "意志形は「生きよう」となり、過去の出来事を述べる文とは合わない。"}], "correct_form": "生きた", "base_form": "生きる", "form_label": "過去形", "sentence_index": 1, "explanations": {"生きた": "過去形で、「九十歳まで元気に生きた」と過去の出来事を述べて文が成り立つ。", "生きて": "て形では文が終わらず、文が成り立たない。", "生きない": "否定形は「元気に生きなかった」の意味になり、文の内容が合わない。", "生きよう": "意志形は「生きよう」となり、過去の出来事を述べる文とは合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ec7c81a-a7fa-4224-baaa-5668fe3bbedd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37836, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼女は強く生きれられる。", "corrected_sentence": "彼女は強く生きられる。", "error_description": "誤りは「生きれられる」。可能形の「れる」と「られる」が重なっている（二重の可能形）。正しくは「生きられる」。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "生きない", "is_correct": true, "explanation": "否定形で、「十五年ほどしか生きない」と文が成り立つ。"}, {"text": "生きた", "is_correct": false, "explanation": "「しか」は否定を伴うので、過去形では文が成り立たない。"}, {"text": "生きて", "is_correct": false, "explanation": "て形では文が終わらず、「しか生きて」は成り立たない。"}, {"text": "生きる", "is_correct": false, "explanation": "「しか」の後は否定形が必要で、辞書形は文として成り立たない。"}], "correct_form": "生きない", "base_form": "生きる", "form_label": "否定形", "sentence_index": 7, "explanations": {"生きない": "否定形で、「十五年ほどしか生きない」と文が成り立つ。", "生きた": "「しか」は否定を伴うので、過去形では文が成り立たない。", "生きて": "て形では文が終わらず、「しか生きて」は成り立たない。", "生きる": "「しか」の後は否定形が必要で、辞書形は文として成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ec7c81a-a7fa-4224-baaa-5668fe3bbedd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37837, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「時代を生きた」の〈を〉。経験する場（時代）を表す目的語で、ここに入る。"}, {"text": "が", "is_correct": false, "explanation": "「時代が生きた」は時代が生きるという意味になり、人物が主語の文として不自然。"}, {"text": "や", "is_correct": false, "explanation": "並列を表すが、「時代や生きた人だ」は文の形が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表すが、「時代へ生きた」は文として成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「時代を生きた」の〈を〉。経験する場（時代）を表す目的語で、ここに入る。", "が": "「時代が生きた」は時代が生きるという意味になり、人物が主語の文として不自然。", "や": "並列を表すが、「時代や生きた人だ」は文の形が成り立たない。", "へ": "方向を表すが、「時代へ生きた」は文として成り立たない。"}, "error_tags": {"が": "「時代が生きた」は時代が生きるという意味になり、人物が主語の文として不自然。", "へ": "方向を表すが、「時代へ生きた」は文として成り立たない。", "や": "並列を表すが、「時代や生きた人だ」は文の形が成り立たない。"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ec7c81a-a7fa-4224-baaa-5668fe3bbedd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37837, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "「田舎で生きる」の〈で〉。生きる場所（田舎）を表し、ここに入る。"}, {"text": "を", "is_correct": false, "explanation": "「田舎を生きる」は場所を表さず、「田舎で生きる」が正しい。"}, {"text": "の", "is_correct": false, "explanation": "「田舎の静かに生きる」は文の形が成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「田舎と静かに生きる」は一緒に生きるという意味になり、場所を表せない。"}], "correct_answer": "で", "explanations": {"で": "「田舎で生きる」の〈で〉。生きる場所（田舎）を表し、ここに入る。", "を": "「田舎を生きる」は場所を表さず、「田舎で生きる」が正しい。", "の": "「田舎の静かに生きる」は文の形が成り立たない。", "と": "「田舎と静かに生きる」は一緒に生きるという意味になり、場所を表せない。"}, "error_tags": {"を": "「田舎を生きる」は場所を表さず、「田舎で生きる」が正しい。", "の": "「田舎の静かに生きる」は文の形が成り立たない。", "と": "「田舎と静かに生きる」は一緒に生きるという意味になり、場所を表せない。"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ec7c81a-a7fa-4224-baaa-5668fe3bbedd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37837, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "自分の考え方や環境のもとで、人生を送ること。", "primary_collocate": null, "pronunciation": "いきる", "ipa": "ikiɾɯ", "syllable_count": 3, "sentences": [{"text": "私は自分の信じる道を生きたい。", "target_word": "生きたい", "complexity_tier": "T3", "furigana": "私[わたし]は自分[じぶん]の信[しん]じる道[みち]を生[い]きたい。", "sentence_source": "generated"}, {"text": "祖母は戦争の時代を生きた人だ。", "target_word": "生きた", "complexity_tier": "T3", "furigana": "祖母[そぼ]は戦争[せんそう]の時代[じだい]を生[い]きた人[ひと]だ。", "sentence_source": "generated"}, {"text": "彼は一生を音楽とともに生きた。", "target_word": "生きた", "complexity_tier": "T3", "furigana": "彼[かれ]は一生[いっしょう]を音楽[おんがく]とともに生[い]きた。", "sentence_source": "generated"}, {"text": "人の目を気にせず、自分らしく生きることが大切だ。", "target_word": "生きること", "complexity_tier": "T4", "furigana": "人[ひと]の目[め]を気[き]にせず、自分[じぶん]らしく生[い]きることが大切[たいせつ]だ。", "sentence_source": "generated"}, {"text": "毎日を楽しく生きるために、新しい趣味を始めた。", "target_word": "生きる", "complexity_tier": "T3", "furigana": "毎日[まいにち]を楽[たの]しく生[い]きるために、新[あたら]しい趣味[しゅみ]を始[はじ]めた。", "sentence_source": "generated"}, {"text": "彼女は夢をあきらめずに、強く生きている。", "target_word": "生きている", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は夢[ゆめ]をあきらめずに、強[つよ]く生[い]きている。", "sentence_source": "generated"}, {"text": "後悔しないように、今日を精いっぱい生きよう。", "target_word": "生きよう", "complexity_tier": "T3", "furigana": "後悔[こうかい]しないように、今日[きょう]を精[せい]いっぱい生[い]きよう。", "sentence_source": "generated"}, {"text": "田舎で静かに生きる暮らしにあこがれている。", "target_word": "生きる", "complexity_tier": "T3", "furigana": "田舎[いなか]で静[しず]かに生[い]きる暮[く]らしにあこがれている。", "sentence_source": "generated"}, {"text": "兄は家族のために生きてきた。", "target_word": "生きてきた", "complexity_tier": "T3", "furigana": "兄[あに]は家族[かぞく]のために生[い]きてきた。", "sentence_source": "generated"}, {"text": "周りに合わせるだけでは、自分の人生を生きているとは言えない。", "target_word": "生きている", "complexity_tier": "T4", "furigana": "周[まわ]りに合[あ]わせるだけでは、自分[じぶん]の人生[じんせい]を生[い]きているとは言[い]えない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "生きる", "label": "終止形"}, {"form": "生きない", "label": "否定形"}, {"form": "生きた", "label": "過去形"}, {"form": "生きて", "label": "て形"}, {"form": "生きれば", "label": "仮定形"}, {"form": "生きよう", "label": "意志形"}, {"form": "生きられる", "label": "可能形"}], "register": "neutral", "sense_fingerprint": "ある考え方や状況のもとで人生を送る、生活する", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e58768ae-8131-4a19-a152-42a2f9901ab2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37837, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "生きたい", "is_correct": true, "explanation": "願望の形で、「信じる道を生きたい」と文が成り立つ。"}, {"text": "生きて", "is_correct": false, "explanation": "て形では文が終わらず、「信じる道を生きて。」は成り立たない。"}, {"text": "生きれば", "is_correct": false, "explanation": "仮定形では文が終わらず、成り立たない。"}, {"text": "生きたがる", "is_correct": false, "explanation": "「がる」は第三者の感情を表すので、一人称の文「私は〜生きたがる」は不自然。"}], "explanations": {"生きたい": "願望の形で、「信じる道を生きたい」と文が成り立つ。", "生きて": "て形では文が終わらず、「信じる道を生きて。」は成り立たない。", "生きれば": "仮定形では文が終わらず、成り立たない。", "生きたがる": "「がる」は第三者の感情を表すので、一人称の文「私は〜生きたがる」は不自然。"}, "sentence_index": 0, "correct_answer": "生きたい"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は毎晩、寝る前に日記を生きた。", "explanation": "ここは〈書く〉の意味。日記は書くものなので、〈生きる〉ではなく〈書く〉を使う。"}, {"text": "日曜日は一日中、家でテレビを見て生きた。", "explanation": "ここは〈過ごす〉の意味。時間を過ごす場合は〈生きる〉ではなく〈過ごす〉を使う。"}, {"text": "毎朝、パンを生きてから出かけた。", "explanation": "ここは〈食べる〉の意味。食事は〈生きる〉ではなく〈食べる〉で表す。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ec7c81a-a7fa-4224-baaa-5668fe3bbedd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37837, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "生きよう", "is_correct": true, "explanation": "意志形で、「今日を精いっぱい生きよう」と決意の文として成り立つ。"}, {"text": "生きられ", "is_correct": false, "explanation": "可能形の語幹のみでは文が終わらず、成り立たない。"}, {"text": "生き", "is_correct": false, "explanation": "連用形では文を言い切れず、「精いっぱい生き。」は成り立たない。"}, {"text": "生きさせ", "is_correct": false, "explanation": "使役の語幹のみでは文が終わらず、「生きさせ。」は成り立たない。"}], "explanations": {"生きよう": "意志形で、「今日を精いっぱい生きよう」と決意の文として成り立つ。", "生きられ": "可能形の語幹のみでは文が終わらず、成り立たない。", "生き": "連用形では文を言い切れず、「精いっぱい生き。」は成り立たない。", "生きさせ": "使役の語幹のみでは文が終わらず、「生きさせ。」は成り立たない。"}, "sentence_index": 6, "correct_answer": "生きよう"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "寝る前に、彼は好きな小説を生きて楽しんだ。", "explanation": "ここは〈読む〉の意味。本を読むことは〈生きる〉ではなく〈読む〉で表す。"}, {"text": "毎朝、川沿いの道を生きて走った。", "explanation": "ここは〈走る〉の意味。走る動作は〈生きる〉ではなく〈走る〉で表す。"}, {"text": "祭りの日、子どもたちはりんご飴を生きた。", "explanation": "ここは〈買う〉の意味。買い物は〈生きる〉ではなく〈買う〉で表す。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ec7c81a-a7fa-4224-baaa-5668fe3bbedd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37837, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "明日からは、もっと正直に生きれ。", "corrected_sentence": "明日からは、もっと正直に生きよう。", "error_description": "誤りは「生きれ」。文の形が成り立たない。意志の文として正しい形は「生きよう」（意志形）。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "生きた", "is_correct": true, "explanation": "過去形で、「戦争の時代を生きた人だ」と過去の人物を述べる文として正しい。"}, {"text": "生きて", "is_correct": false, "explanation": "て形では「人だ」の前に続かず、名詞を修飾できない。"}, {"text": "生きない", "is_correct": false, "explanation": "否定形では「生きない人」となり、過去の人物の説明と合わない。"}, {"text": "生きよう", "is_correct": false, "explanation": "意志形では「生きよう人だ」となり、文として成り立たない。"}], "correct_form": "生きた", "base_form": "生きる", "form_label": "過去形", "sentence_index": 1, "explanations": {"生きた": "過去形で、「戦争の時代を生きた人だ」と過去の人物を述べる文として正しい。", "生きて": "て形では「人だ」の前に続かず、名詞を修飾できない。", "生きない": "否定形では「生きない人」となり、過去の人物の説明と合わない。", "生きよう": "意志形では「生きよう人だ」となり、文として成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ec7c81a-a7fa-4224-baaa-5668fe3bbedd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37837, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼はいつも自分らしく生きいる。", "corrected_sentence": "彼はいつも自分らしく生きている。", "error_description": "誤りは「生きいる」。「て」が抜けている。正しくは「生きている」（〜ている）。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "生きる", "is_correct": true, "explanation": "辞書形で、「暮らし」を修飾する形として正しい。"}, {"text": "生きれ", "is_correct": false, "explanation": "命令形は名詞「暮らし」を修飾できず、「生きれ暮らし」は成り立たない。"}, {"text": "生き", "is_correct": false, "explanation": "連用形は名詞を直接修飾できず、「生き暮らし」は文が成り立たない。"}, {"text": "生きられ", "is_correct": false, "explanation": "可能形の語幹のみでは名詞を修飾できず、「生きられ暮らし」は成り立たない。"}], "correct_form": "生きる", "base_form": "生きる", "form_label": "辞書形", "sentence_index": 7, "explanations": {"生きる": "辞書形で、「暮らし」を修飾する形として正しい。", "生きれ": "命令形は名詞「暮らし」を修飾できず、「生きれ暮らし」は成り立たない。", "生き": "連用形は名詞を直接修飾できず、「生き暮らし」は文が成り立たない。", "生きられ": "可能形の語幹のみでは名詞を修飾できず、「生きられ暮らし」は成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ec7c81a-a7fa-4224-baaa-5668fe3bbedd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
