INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37838, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "property", "definition": "うそをつかないこと。まじめなこと。", "primary_collocate": null, "pronunciation": "しょうじき", "ipa": "ɕoːdʑiki", "syllable_count": 4, "sentences": [{"text": "正直は、人にとって大切なことです。", "target_word": "正直", "complexity_tier": "T3", "furigana": "正直[しょうじき]は、人[ひと]にとって大切[たいせつ]なことです。", "sentence_source": "generated"}, {"text": "先生は、子どもに正直の大切さを教えました。", "target_word": "正直", "complexity_tier": "T3", "furigana": "先生[せんせい]は、子[こ]どもに正直[しょうじき]の大切[たいせつ]さを教[おし]えました。", "sentence_source": "generated"}, {"text": "彼の正直が、みんなの信頼を集めました。", "target_word": "正直", "complexity_tier": "T3", "furigana": "彼[かれ]の正直[しょうじき]が、みんなの信頼[しんらい]を集[あつ]めました。", "sentence_source": "generated"}, {"text": "母は、正直を何より大事にしています。", "target_word": "正直", "complexity_tier": "T3", "furigana": "母[はは]は、正直[しょうじき]を何[なに]より大事[だいじ]にしています。", "sentence_source": "generated"}, {"text": "商売では、正直が一番の力になります。", "target_word": "正直", "complexity_tier": "T3", "furigana": "商売[しょうばい]では、正直[しょうじき]が一番[いちばん]の力[ちから]になります。", "sentence_source": "generated"}, {"text": "正直を貫いて、失敗を自分から話しました。", "target_word": "正直", "complexity_tier": "T3", "furigana": "正直[しょうじき]を貫[つらぬ]いて、失敗[しっぱい]を自分[じぶん]から話[はな]しました。", "sentence_source": "generated"}, {"text": "彼女の正直には、いつも感心します。", "target_word": "正直", "complexity_tier": "T3", "furigana": "彼女[かのじょ]の正直[しょうじき]には、いつも感心[かんしん]します。", "sentence_source": "generated"}, {"text": "「正直は一番の策」ということわざがあります。", "target_word": "正直", "complexity_tier": "T3", "furigana": "「正直[しょうじき]は一番[いちばん]の策[さく]」ということわざがあります。", "sentence_source": "generated"}, {"text": "祖父は正直を大切にして、一生を送りました。", "target_word": "正直", "complexity_tier": "T3", "furigana": "祖父[そふ]は正直[しょうじき]を大切[たいせつ]にして、一生[いっしょう]を送[おく]りました。", "sentence_source": "generated"}, {"text": "正直が一番だと、父はいつも言います。", "target_word": "正直", "complexity_tier": "T3", "furigana": "正直[しょうじき]が一番[いちばん]だと、父[ちち]はいつも言[い]います。", "sentence_source": "generated"}], "morphological_forms": [{"form": "正直", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "うそをつかない誠実さ（名詞として）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1008a082-97df-4e54-bb3b-338a2360e5cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37838, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "正直", "is_correct": true, "explanation": "「うそをつかない誠実さ」の意味で、「人にとって大切なこと」と評価できる。"}, {"text": "正面", "is_correct": false, "explanation": "「前の方」を指す語で、人にとっての大切さを述べる文には合わない。"}, {"text": "正門", "is_correct": false, "explanation": "「建物の正面の門」を指す語で、人の大切さの話には成り立たない。"}, {"text": "正午", "is_correct": false, "explanation": "「昼の十二時」という時刻で、性質を表さないので文が成り立たない。"}], "explanations": {"正直": "「うそをつかない誠実さ」の意味で、「人にとって大切なこと」と評価できる。", "正面": "「前の方」を指す語で、人にとっての大切さを述べる文には合わない。", "正門": "「建物の正面の門」を指す語で、人の大切さの話には成り立たない。", "正午": "「昼の十二時」という時刻で、性質を表さないので文が成り立たない。"}, "sentence_index": 0, "correct_answer": "正直"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は正直を三つ持っていて、かばんに入れています。", "explanation": "ここは〈持ち物〉の意味。正直は人の性質で、数えてかばんに入れる物ではないので合わない。"}, {"text": "彼は正直が豊富で、難しい質問にも何でも答える。", "explanation": "ここは〈知識〉の意味。正直は人の性質で、「豊富」と量で言う語ではないので合わない。"}, {"text": "彼は正直を出して、本当のことを言った。", "explanation": "ここは〈勇気〉の意味。正直は「出す」ものではなく人の性質なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7fa5edfe-0c0f-4bc2-8079-af983ceda906') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37838, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "正直", "is_correct": true, "explanation": "「うそをつかない誠実さ」の意味で、「彼女の〜には感心する」の空欄に入る。"}, {"text": "正夢", "is_correct": false, "explanation": "「夢が現実になること」を指し、人の振る舞いには感心の対象にならない。"}, {"text": "正札", "is_correct": false, "explanation": "「値札」のことで、人の性質に感心する文には合わない。"}, {"text": "正誤", "is_correct": false, "explanation": "「正しいか誤りか」の意味で、感心の対象として成り立たない。"}], "explanations": {"正直": "「うそをつかない誠実さ」の意味で、「彼女の〜には感心する」の空欄に入る。", "正夢": "「夢が現実になること」を指し、人の振る舞いには感心の対象にならない。", "正札": "「値札」のことで、人の性質に感心する文には合わない。", "正誤": "「正しいか誤りか」の意味で、感心の対象として成り立たない。"}, "sentence_index": 6, "correct_answer": "正直"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は料理が正直で、毎晩みんなにふるまいます。", "explanation": "ここは〈上手〉の意味。料理の腕前には「正直」は使えないので合わない。"}, {"text": "その正直な色で、壁を塗りました。", "explanation": "ここは〈色〉の意味。正直は人の態度を表す語で、色の様子には使わないので合わない。"}, {"text": "彼は会社を辞める正直を決めて、家族に話しました。", "explanation": "ここは〈決心〉の意味。決めるのは覚悟や決心で、正直は決めるものではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7fa5edfe-0c0f-4bc2-8079-af983ceda906') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37838, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "父は子どもに正直を大切さを話しました。", "corrected_sentence": "父は子どもに正直の大切さを話しました。", "error_description": "「正直」が「大切さ」を修飾するには「の」が必要。「を」は目的語を示すため誤り（正しくは「正直の大切さ」）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7fa5edfe-0c0f-4bc2-8079-af983ceda906') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37838, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼は正直を、誰からも信頼されています。", "corrected_sentence": "彼は正直で、誰からも信頼されています。", "error_description": "断定の「で」が正しい。「正直を」は目的語を示す助詞で、「信頼されている」の文の成分として合わないため誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7fa5edfe-0c0f-4bc2-8079-af983ceda906') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
