INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37839, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "心がまっすぐで、うそやごまかしをしないこと。また、そのさま。", "primary_collocate": null, "pronunciation": "しょうじき", "ipa": "ɕoːdʑiki", "syllable_count": 4, "sentences": [{"text": "彼は正直な人で、うそをつきません。", "target_word": "正直", "complexity_tier": "T3", "furigana": "彼[かれ]は正直[しょうじき]な人[ひと]で、うそをつきません。", "sentence_source": "generated"}, {"text": "正直に話してくれて、ありがとうございます。", "target_word": "正直", "complexity_tier": "T3", "furigana": "正直[しょうじき]に話[はな]してくれて、ありがとうございます。", "sentence_source": "generated"}, {"text": "正直に言うと、この料理は少し辛いです。", "target_word": "正直", "complexity_tier": "T3", "furigana": "正直[しょうじき]に言[い]うと、この料理[りょうり]は少[すこ]し辛[から]いです。", "sentence_source": "generated"}, {"text": "店の人は正直で、余計な品を勧めませんでした。", "target_word": "正直", "complexity_tier": "T3", "furigana": "店[みせ]の人[ひと]は正直[しょうじき]で、余計[よけい]な品[しな]を勧[すす]めませんでした。", "sentence_source": "generated"}, {"text": "子どもは正直なので、思ったことを口にします。", "target_word": "正直", "complexity_tier": "T3", "furigana": "子[こ]どもは正直[しょうじき]なので、思[おも]ったことを口[くち]にします。", "sentence_source": "generated"}, {"text": "失敗したことを、正直に先生に伝えました。", "target_word": "正直", "complexity_tier": "T3", "furigana": "失敗[しっぱい]したことを、正直[しょうじき]に先生[せんせい]に伝[つた]えました。", "sentence_source": "generated"}, {"text": "財布を拾って、正直に交番へ届けました。", "target_word": "正直", "complexity_tier": "T3", "furigana": "財布[さいふ]を拾[ひろ]って、正直[しょうじき]に交番[こうばん]へ届[とど]けました。", "sentence_source": "generated"}, {"text": "正直な気持ちを、手紙に書きました。", "target_word": "正直", "complexity_tier": "T3", "furigana": "正直[しょうじき]な気持[きも]ちを、手紙[てがみ]に書[か]きました。", "sentence_source": "generated"}, {"text": "あの店は、説明も正直で安心です。", "target_word": "正直", "complexity_tier": "T3", "furigana": "あの店[みせ]は、説明[せつめい]も正直[しょうじき]で安心[あんしん]です。", "sentence_source": "generated"}, {"text": "正直に答えたので、母は怒りませんでした。", "target_word": "正直", "complexity_tier": "T3", "furigana": "正直[しょうじき]に答[こた]えたので、母[はは]は怒[おこ]りませんでした。", "sentence_source": "generated"}], "morphological_forms": [{"form": "正直", "label": "基本形"}, {"form": "正直な", "label": "連体形"}, {"form": "正直に", "label": "連用形"}], "register": "neutral", "sense_fingerprint": "うそやごまかしがないさま（正直な・正直に）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1008a082-97df-4e54-bb3b-338a2360e5cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37839, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "正直", "is_correct": true, "explanation": "「うそやごまかしがないさま」の意味で、「な人」の形で人の性質を表す。"}, {"text": "高価", "is_correct": false, "explanation": "値段が高いことを表し、人の性質には使えないので「高価な人」は成り立たない。"}, {"text": "無料", "is_correct": false, "explanation": "料金がかからないことで、人の性質を表さないので文が成り立たない。"}, {"text": "満開", "is_correct": false, "explanation": "花が咲き揃った状態を表すので、人を形容する文には合わない。"}], "explanations": {"正直": "「うそやごまかしがないさま」の意味で、「な人」の形で人の性質を表す。", "高価": "値段が高いことを表し、人の性質には使えないので「高価な人」は成り立たない。", "無料": "料金がかからないことで、人の性質を表さないので文が成り立たない。", "満開": "花が咲き揃った状態を表すので、人を形容する文には合わない。"}, "sentence_index": 0, "correct_answer": "正直"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この電車は正直で、すぐに着きます。", "explanation": "ここは〈速い〉の意味。正直は人の態度を表す語で、乗り物の速さには使わないので合わない。"}, {"text": "この肉は正直で、口の中でほどけます。", "explanation": "ここは〈柔らかい〉の意味。正直は人の態度に使い、肉の状態には使わないので合わない。"}, {"text": "机の上に、正直な箱が置いてあります。", "explanation": "ここは〈四角い〉の意味。正直は人の性質を表す語で、箱の形には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7fa5edfe-0c0f-4bc2-8079-af983ceda906') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37839, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "正直", "is_correct": true, "explanation": "「うそやごまかしがないさま」の意味で、「正直に交番へ届けた」と副詞的に続く。"}, {"text": "豪華", "is_correct": false, "explanation": "ぜいたくで華やかなさまを表し、届ける行為の様子としては「豪華に届けた」と言えない。"}, {"text": "永遠", "is_correct": false, "explanation": "時間が限りなく続くことで、届ける行為の様子に合わないため文が成り立たない。"}, {"text": "大急ぎ", "is_correct": false, "explanation": "「大急ぎで届けた」の形で「で」を取り、「に」では続かないので文が成り立たない。"}], "explanations": {"正直": "「うそやごまかしがないさま」の意味で、「正直に交番へ届けた」と副詞的に続く。", "豪華": "ぜいたくで華やかなさまを表し、届ける行為の様子としては「豪華に届けた」と言えない。", "永遠": "時間が限りなく続くことで、届ける行為の様子に合わないため文が成り立たない。", "大急ぎ": "「大急ぎで届けた」の形で「で」を取り、「に」では続かないので文が成り立たない。"}, "sentence_index": 6, "correct_answer": "正直"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は料理の腕が正直で、毎晩みんなにふるまいます。", "explanation": "ここは〈上手〉の意味。料理の腕前は「正直」では表せない。"}, {"text": "今日の空は正直で、雨が降りそうです。", "explanation": "ここは〈重い〉の意味。正直は人の態度に使い、空の様子には使わない。"}, {"text": "会議は正直な時間が長くて、夕方まで続きました。", "explanation": "ここは〈長い〉の意味。正直は人の態度を表す語で、時間の長さは表さないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7fa5edfe-0c0f-4bc2-8079-af983ceda906') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37839, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "父は正直の人で、約束をよく守ります。", "corrected_sentence": "父は正直な人で、約束をよく守ります。", "error_description": "形状詞は名詞を修飾するとき「な」を付ける。「の」は名詞同士をつなぐ助詞なので誤り（正しくは「正直な人」）。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "正直に", "is_correct": true, "explanation": "連用形で、「話してくれて」を修飾する「正直に話す」の形になる。"}, {"text": "正直な", "is_correct": false, "explanation": "連体形なので名詞の前に来る形。動詞「話す」を直接修飾できず、「正直な話してくれて」は不自然。"}, {"text": "正直で", "is_correct": false, "explanation": "断定の中止形で、動詞を修飾する形ではないため、「正直で話してくれて」は成り立たない。"}, {"text": "正直だ", "is_correct": false, "explanation": "言い切りの断定形で、動詞の前に置いて修飾できない。文を言い切る形なので空欄には入らない。"}], "correct_form": "正直に", "base_form": "正直", "form_label": "連用形", "sentence_index": 1, "explanations": {"正直に": "連用形で、「話してくれて」を修飾する「正直に話す」の形になる。", "正直な": "連体形なので名詞の前に来る形。動詞「話す」を直接修飾できず、「正直な話してくれて」は不自然。", "正直で": "断定の中止形で、動詞を修飾する形ではないため、「正直で話してくれて」は成り立たない。", "正直だ": "言い切りの断定形で、動詞の前に置いて修飾できない。文を言い切る形なので空欄には入らない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7fa5edfe-0c0f-4bc2-8079-af983ceda906') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37839, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼は正直の答えてくれたので、助かりました。", "corrected_sentence": "彼は正直に答えてくれたので、助かりました。", "error_description": "動詞「答える」を修飾するには副詞形の「に」が必要。「の」は名詞同士をつなぐ助詞で、動詞の前に置くと文が成り立たないため誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "正直な", "is_correct": true, "explanation": "連体形で、名詞「気持ち」を修飾して「正直な気持ち」となる。"}, {"text": "正直では", "is_correct": false, "explanation": "「では」の形で、名詞「気持ち」を直接修飾できない。「正直では気持ち」は成り立たない。"}, {"text": "正直なら", "is_correct": false, "explanation": "仮定の形で条件を表すため、名詞「気持ち」の前に置いて修飾することはできない。「正直なら気持ち」は誤り。"}, {"text": "正直だ", "is_correct": false, "explanation": "言い切りの断定形で、名詞「気持ち」の前に置いて修飾することはできない。「正直だ気持ち」は誤り。"}], "correct_form": "正直な", "base_form": "正直", "form_label": "連体形", "sentence_index": 7, "explanations": {"正直な": "連体形で、名詞「気持ち」を修飾して「正直な気持ち」となる。", "正直では": "「では」の形で、名詞「気持ち」を直接修飾できない。「正直では気持ち」は成り立たない。", "正直なら": "仮定の形で条件を表すため、名詞「気持ち」の前に置いて修飾することはできない。「正直なら気持ち」は誤り。", "正直だ": "言い切りの断定形で、名詞「気持ち」の前に置いて修飾することはできない。「正直だ気持ち」は誤り。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7fa5edfe-0c0f-4bc2-8079-af983ceda906') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37840, 3, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ec7c81a-a7fa-4224-baaa-5668fe3bbedd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37840, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "「という形で報われた」の手段・様態を示す。"}, {"text": "に", "is_correct": false, "explanation": "「形に報われた」では、どんな形で報われたかを表せない。", "error_tag": "方向・相手"}, {"text": "から", "is_correct": false, "explanation": "起点を示す。「形から報われた」では意味が通らない。"}, {"text": "の", "is_correct": false, "explanation": "修飾を示す。「形の報われた」では文が成り立たない。"}], "correct_answer": "で", "explanations": {"で": "「という形で報われた」の手段・様態を示す。", "に": "「形に報われた」では、どんな形で報われたかを表せない。", "から": "起点を示す。「形から報われた」では意味が通らない。", "の": "修飾を示す。「形の報われた」では文が成り立たない。"}, "error_tags": {"に": "方向・相手", "から": "起点・理由", "の": "修飾"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ec7c81a-a7fa-4224-baaa-5668fe3bbedd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37840, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "良いことをすると、後で良いことが返ってくること。", "primary_collocate": null, "pronunciation": "むくう", "ipa": "mɯkɯɯ", "syllable_count": 3, "sentences": [{"text": "困っている人を助けたら、あとで自分も助けられた。善い行いは報われるものだ。", "target_word": "報われる", "complexity_tier": "T4", "furigana": "困[こま]っている人[ひと]を助[たす]けたら、あとで自分[じぶん]も助[たす]けられた。善[よ]い行[おこな]いは報[むく]われるものだ。", "sentence_source": "generated"}, {"text": "毎日ゴミを拾っていた彼の行いが、ついに報われた。", "target_word": "報われた", "complexity_tier": "T3", "furigana": "毎日[まいにち]ゴミを拾[ひろ]っていた彼[かれ]の行[おこな]いが、ついに報[むく]われた。", "sentence_source": "generated"}, {"text": "人に親切にすれば、いつか報われると祖母は言った。", "target_word": "報われる", "complexity_tier": "T3", "furigana": "人[ひと]に親切[しんせつ]にすれば、いつか報[むく]われると祖母[そぼ]は言[い]った。", "sentence_source": "generated"}, {"text": "正直に生きてきた父は、老後に周りの人に支えられ、報われたようだ。", "target_word": "報われた", "complexity_tier": "T4", "furigana": "正直[しょうじき]に生[い]きてきた父[ちち]は、老後[ろうご]に周[まわ]りの人[ひと]に支[ささ]えられ、報[むく]われたようだ。", "sentence_source": "generated"}, {"text": "誰も見ていなくても、良い行いはきっと報われる。", "target_word": "報われる", "complexity_tier": "T3", "furigana": "誰[だれ]も見[み]ていなくても、良[よ]い行[おこな]いはきっと報[むく]われる。", "sentence_source": "generated"}, {"text": "近所の人に親切にしていた彼女は、病気のときに皆に助けられて報われた。", "target_word": "報われた", "complexity_tier": "T4", "furigana": "近所[きんじょ]の人[ひと]に親切[しんせつ]にしていた彼女[かのじょ]は、病気[びょうき]のときに皆[みな]に助[たす]けられて報[むく]われた。", "sentence_source": "generated"}, {"text": "困っている人に親切にし続けたのに、彼の善意は最後まで報われなかった。", "target_word": "報われなかった", "complexity_tier": "T3", "furigana": "困[こま]っている人[ひと]に親切[しんせつ]にし続[つづ]けたのに、彼[かれ]の善意[ぜんい]は最後[さいご]まで報[むく]われなかった。", "sentence_source": "generated"}, {"text": "寄付を続けた男性の善意は、町の人の感謝という形で報われた。", "target_word": "報われた", "complexity_tier": "T4", "furigana": "寄付[きふ]を続[つづ]けた男性[だんせい]の善意[ぜんい]は、町[まち]の人[ひと]の感謝[かんしゃ]という形[かたち]で報[むく]われた。", "sentence_source": "generated"}, {"text": "人を助けても、すぐに報われるとは限らない。", "target_word": "報われる", "complexity_tier": "T3", "furigana": "人[ひと]を助[たす]けても、すぐに報[むく]われるとは限[かぎ]らない。", "sentence_source": "generated"}, {"text": "席をゆずった少年は、あとで先生にほめられて報われた気持ちになった。", "target_word": "報われた", "complexity_tier": "T4", "furigana": "席[せき]をゆずった少年[しょうねん]は、あとで先生[せんせい]にほめられて報[むく]われた気持[きも]ちになった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "報う", "label": "終止形"}, {"form": "報わない", "label": "否定形"}, {"form": "報った", "label": "過去形"}, {"form": "報って", "label": "て形"}, {"form": "報えば", "label": "仮定形"}, {"form": "報おう", "label": "意志形"}, {"form": "報われる", "label": "受身形"}], "register": "neutral", "sense_fingerprint": "善い行いに対して、あとで良い結果が返ってくる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e58768ae-8131-4a19-a152-42a2f9901ab2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37840, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "報われる", "is_correct": true, "explanation": "「善い行いは報われるものだ」の形で、善い行いには良い結果が返るという一般論になる。"}, {"text": "報われ", "is_correct": false, "explanation": "連用形なので「ものだ」に続かない。文が途中で切れてしまう。"}, {"text": "報えば", "is_correct": false, "explanation": "仮定形で「報えば、〜」という条件節になる。「ものだ」に続けると文が成り立たない。"}, {"text": "報おう", "is_correct": false, "explanation": "意志形なので「報おうものだ」とは続かない。結果を述べる文の形にならない。"}], "explanations": {"報われる": "「善い行いは報われるものだ」の形で、善い行いには良い結果が返るという一般論になる。", "報われ": "連用形なので「ものだ」に続かない。文が途中で切れてしまう。", "報えば": "仮定形で「報えば、〜」という条件節になる。「ものだ」に続けると文が成り立たない。", "報おう": "意志形なので「報おうものだ」とは続かない。結果を述べる文の形にならない。"}, "sentence_index": 0, "correct_answer": "報われる"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "ひどい嘘をついた彼は、当然の罰が報われた。", "explanation": "報うは善い行いへの良い見返りに使うので、悪い結果である罰には合わない。"}, {"text": "貸したお金が、ついに報われた。", "explanation": "報うは善い行いへの良い見返りに使うので、貸した金の返済には合わない。"}, {"text": "その男は不当な扱いを裁判所に報われた。", "explanation": "報うは善い行いへの見返りを受ける意味なので、裁判所へ訴える文には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ec7c81a-a7fa-4224-baaa-5668fe3bbedd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37840, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "報われなかった", "is_correct": true, "explanation": "過去の否定で文を言い切れる。「最後まで報われなかった」の意味に合う。"}, {"text": "報わず", "is_correct": false, "explanation": "文中止の形で、ここで文を終えられない。"}, {"text": "報わなく", "is_correct": false, "explanation": "連用形で、文末にならない。「報わなくて」などの続きが必要になる。"}, {"text": "報われなく", "is_correct": false, "explanation": "「なく」は文末で使えない。文を言い切るには「報われなかった」が必要。"}], "explanations": {"報われなかった": "過去の否定で文を言い切れる。「最後まで報われなかった」の意味に合う。", "報わず": "文中止の形で、ここで文を終えられない。", "報わなく": "連用形で、文末にならない。「報わなくて」などの続きが必要になる。", "報われなく": "「なく」は文末で使えない。文を言い切るには「報われなかった」が必要。"}, "sentence_index": 6, "correct_answer": "報われなかった"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この部屋の窓は南に報われている。", "explanation": "報うは善い行いへの良い見返りに使うので、窓の向きを表す文には合わない。"}, {"text": "その男の罪が報われた。", "explanation": "報うは見返りを受ける意味なので、罪のつぐないを表す文には合わない。"}, {"text": "その事件は昨日の新聞で報われた。", "explanation": "報うは善い行いへの見返りの意味なので、事件を伝える文には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ec7c81a-a7fa-4224-baaa-5668fe3bbedd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37840, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "小さな親切を、いつか必ず報われると信じている。", "corrected_sentence": "小さな親切が、いつか必ず報われると信じている。", "error_description": "「報われる」は自動詞で、その主語は「が」で示す。「を」にすると目的語になり、文が不自然になる。正しくは「が」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "報われた", "is_correct": true, "explanation": "受身の過去形で、善い行いが報われたという意味になる。"}, {"text": "報われる", "is_correct": false, "explanation": "受身の終止形で、過去ではない。ここは過去の出来事を述べている。"}, {"text": "報わない", "is_correct": false, "explanation": "能動の否定形で、受身ではない。「報われた」とは形も意味も違う。"}, {"text": "報えば", "is_correct": false, "explanation": "仮定形で「〜ば」の条件を作る。過去を述べる文の形にならない。"}], "correct_form": "報われた", "base_form": "報う", "form_label": "受身・過去", "sentence_index": 1, "explanations": {"報われた": "受身の過去形で、善い行いが報われたという意味になる。", "報われる": "受身の終止形で、過去ではない。ここは過去の出来事を述べている。", "報わない": "能動の否定形で、受身ではない。「報われた」とは形も意味も違う。", "報えば": "仮定形で「〜ば」の条件を作る。過去を述べる文の形にならない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ec7c81a-a7fa-4224-baaa-5668fe3bbedd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37840, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "努力は必ず報われるだ。", "corrected_sentence": "努力は必ず報われるものだ。", "error_description": "動詞の終止形に「だ」は直接つかない。一般の真理を言うときは「報われるものだ」とする。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "報われた", "is_correct": true, "explanation": "受身の過去形で、善意が報われたという意味になる。"}, {"text": "報った", "is_correct": false, "explanation": "能動の過去形で受身ではない。「報われた」の受身の意味が出ない。"}, {"text": "報わなかった", "is_correct": false, "explanation": "能動の否定過去で、報われなかったという否定の意味になる。ここは肯定の文。"}, {"text": "報って", "is_correct": false, "explanation": "て形で、文末にならず過去の意味を作らない。"}], "correct_form": "報われた", "base_form": "報う", "form_label": "受身・過去", "sentence_index": 7, "explanations": {"報われた": "受身の過去形で、善意が報われたという意味になる。", "報った": "能動の過去形で受身ではない。「報われた」の受身の意味が出ない。", "報わなかった": "能動の否定過去で、報われなかったという否定の意味になる。ここは肯定の文。", "報って": "て形で、文末にならず過去の意味を作らない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ec7c81a-a7fa-4224-baaa-5668fe3bbedd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37841, 3, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ec7c81a-a7fa-4224-baaa-5668fe3bbedd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37841, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「努力が報われ」で、報われる主語を示す。"}, {"text": "を", "is_correct": false, "explanation": "目的語を示す。「報われる」は自動詞なので「努力を報われ」は成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "相手や場所を示す。「努力に報われ」とは言わない。"}, {"text": "の", "is_correct": false, "explanation": "修飾を示す。「努力の報われ」では文の主語にならない。"}], "correct_answer": "が", "explanations": {"が": "「努力が報われ」で、報われる主語を示す。", "を": "目的語を示す。「報われる」は自動詞なので「努力を報われ」は成り立たない。", "に": "相手や場所を示す。「努力に報われ」とは言わない。", "の": "修飾を示す。「努力の報われ」では文の主語にならない。"}, "error_tags": {"を": "目的語の格", "に": "相手・場所", "の": "修飾"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ec7c81a-a7fa-4224-baaa-5668fe3bbedd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37841, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "努力や善行に対して、結果として良いことが返ってくること。", "primary_collocate": null, "pronunciation": "むくう", "ipa": "mɯkɯɯ", "syllable_count": 3, "sentences": [{"text": "三年間の努力が報われて、試験に合格した。", "target_word": "報われて", "complexity_tier": "T3", "furigana": "三年間[さんねんかん]の努力[どりょく]が報[むく]われて、試験[しけん]に合格[ごうかく]した。", "sentence_source": "generated"}, {"text": "毎日練習したのに、結果が出ず、報われない気持ちだった。", "target_word": "報われない", "complexity_tier": "T3", "furigana": "毎日[まいにち]練習[れんしゅう]したのに、結果[けっか]が出[で]ず、報[むく]われない気持[きも]ちだった。", "sentence_source": "generated"}, {"text": "努力は必ず報われるとは限らないが、続ける価値はある。", "target_word": "報われる", "complexity_tier": "T4", "furigana": "努力[どりょく]は必[かなら]ず報[むく]われるとは限[かぎ]らないが、続[つづ]ける価値[かち]はある。", "sentence_source": "generated"}, {"text": "長い間の苦労が報われ、店は有名になった。", "target_word": "報われ", "complexity_tier": "T3", "furigana": "長[なが]い間[あいだ]の苦労[くろう]が報[むく]われ、店[みせ]は有名[ゆうめい]になった。", "sentence_source": "generated"}, {"text": "徹夜で準備した発表がほめられて、報われた。", "target_word": "報われた", "complexity_tier": "T3", "furigana": "徹夜[てつや]で準備[じゅんび]した発表[はっぴょう]がほめられて、報[むく]われた。", "sentence_source": "generated"}, {"text": "彼の努力が報われる日がやっと来た。", "target_word": "報われる", "complexity_tier": "T3", "furigana": "彼[かれ]の努力[どりょく]が報[むく]われる日[ひ]がやっと来[き]た。", "sentence_source": "generated"}, {"text": "たとえ報われなくても、私は最後までやり遂げたい。", "target_word": "報われなくても", "complexity_tier": "T4", "furigana": "たとえ報[むく]われなくても、私[わたし]は最後[さいご]までやり遂[と]げたい。", "sentence_source": "generated"}, {"text": "毎朝走り続けた努力が報われ、大会で優勝した。", "target_word": "報われ", "complexity_tier": "T3", "furigana": "毎朝[まいあさ]走[はし]り続[つづ]けた努力[どりょく]が報[むく]われ、大会[たいかい]で優勝[ゆうしょう]した。", "sentence_source": "generated"}, {"text": "仕事を認めてもらえず、報われないと感じている。", "target_word": "報われない", "complexity_tier": "T3", "furigana": "仕事[しごと]を認[みと]めてもらえず、報[むく]われないと感[かん]じている。", "sentence_source": "generated"}, {"text": "練習の成果が出て、苦しかった日々が報われた。", "target_word": "報われた", "complexity_tier": "T3", "furigana": "練習[れんしゅう]の成果[せいか]が出[で]て、苦[くる]しかった日々[ひび]が報[むく]われた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "報う", "label": "終止形"}, {"form": "報わない", "label": "否定形"}, {"form": "報った", "label": "過去形"}, {"form": "報って", "label": "て形"}, {"form": "報えば", "label": "仮定形"}, {"form": "報おう", "label": "意志形"}, {"form": "報われる", "label": "受身形"}], "register": "neutral", "sense_fingerprint": "努力や苦労が、成功や評価という良い結果につながる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e58768ae-8131-4a19-a152-42a2f9901ab2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37841, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "報われて", "is_correct": true, "explanation": "て形で文を続けられる。努力が報われた結果、合格したという流れになる。"}, {"text": "報われる", "is_correct": false, "explanation": "終止形なので、文が途中で切れて「試験に合格した」と続かない。"}, {"text": "報おう", "is_correct": false, "explanation": "意志形で、「努力が報おう、〜」の形は成り立たない。"}, {"text": "報った", "is_correct": false, "explanation": "能動の過去形で受身ではない。努力が報われた意味にならず、文も続かない。"}], "explanations": {"報われて": "て形で文を続けられる。努力が報われた結果、合格したという流れになる。", "報われる": "終止形なので、文が途中で切れて「試験に合格した」と続かない。", "報おう": "意志形で、「努力が報おう、〜」の形は成り立たない。", "報った": "能動の過去形で受身ではない。努力が報われた意味にならず、文も続かない。"}, "sentence_index": 0, "correct_answer": "報われて"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "大切な財布が報われた。", "explanation": "大切な物をなくす意味は報うにはない。報うは努力への見返りに使うので、この文には合わない。"}, {"text": "彼は解雇の不当さを裁判所に報われた。", "explanation": "裁判所に訴える意味は報うにはない。報うは努力への見返りを得る意味なので、この文には合わない。"}, {"text": "その事故は昨日の新聞で報われた。", "explanation": "事故を伝える意味は報うにはない。報うは努力への見返りの意味なので、この文には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ec7c81a-a7fa-4224-baaa-5668fe3bbedd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37841, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "報われなくても", "is_correct": true, "explanation": "「たとえ〜ても」の形で、結果が出なくても、という意味に合う。"}, {"text": "報えば", "is_correct": false, "explanation": "仮定形で「たとえ」と組み合わさらず、文の流れが通らない。"}, {"text": "報って", "is_correct": false, "explanation": "て形で、「たとえ」の後に続けられない。"}, {"text": "報われ", "is_correct": false, "explanation": "連用形なので、「たとえ」の後に続く条件の形にならない。"}], "explanations": {"報われなくても": "「たとえ〜ても」の形で、結果が出なくても、という意味に合う。", "報えば": "仮定形で「たとえ」と組み合わさらず、文の流れが通らない。", "報って": "て形で、「たとえ」の後に続けられない。", "報われ": "連用形なので、「たとえ」の後に続く条件の形にならない。"}, "sentence_index": 6, "correct_answer": "報われなくても"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "足りない人手が報われた。", "explanation": "不足を補う意味は報うにはない。報うは努力への良い見返りに使うので、この文には合わない。"}, {"text": "彼の横領の罪が報われた。", "explanation": "罪をつぐなう意味は報うにはない。報うは努力への見返りを得る意味なので、この文には合わない。"}, {"text": "問題が、ついに報われた。", "explanation": "問題を解決する意味は報うにはない。報うは努力への良い見返りに使うので、この文には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ec7c81a-a7fa-4224-baaa-5668fe3bbedd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37841, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "毎年の努力に報われて、賞をもらった。", "corrected_sentence": "毎年の努力が報われて、賞をもらった。", "error_description": "「報われる」の主語（努力）は「が」で示す。「に」にすると、努力が報われる関係が成り立たず誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "報われない", "is_correct": true, "explanation": "受身の否定形で、努力が報われないという意味になる。"}, {"text": "報われる", "is_correct": false, "explanation": "受身の肯定形で否定にならない。結果が出ないという意味にはならない。"}, {"text": "報わない", "is_correct": false, "explanation": "能動の否定形で受身ではない。「報われない」とは形が違う。"}, {"text": "報った", "is_correct": false, "explanation": "能動の過去形で、否定でも受身でもない。"}], "correct_form": "報われない", "base_form": "報う", "form_label": "受身・否定", "sentence_index": 1, "explanations": {"報われない": "受身の否定形で、努力が報われないという意味になる。", "報われる": "受身の肯定形で否定にならない。結果が出ないという意味にはならない。", "報わない": "能動の否定形で受身ではない。「報われない」とは形が違う。", "報った": "能動の過去形で、否定でも受身でもない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ec7c81a-a7fa-4224-baaa-5668fe3bbedd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37841, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "練習の成果は、ついに報われるだ。", "corrected_sentence": "練習の成果は、ついに報われる。", "error_description": "動詞の後に「だ」はつかない。文末は動詞の終止形で言い切る。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "報われ", "is_correct": true, "explanation": "受身の連用形で、「報われ、〜」と文を続ける形になる。"}, {"text": "報えば", "is_correct": false, "explanation": "仮定形で、条件を作る形。受身の連用形ではない。"}, {"text": "報わなかった", "is_correct": false, "explanation": "能動の否定過去で、受身の連用形とは形が違う。"}, {"text": "報わなく", "is_correct": false, "explanation": "能動の否定連用形で、受身の連用形とは形が違う。"}], "correct_form": "報われ", "base_form": "報う", "form_label": "受身・連用形", "sentence_index": 7, "explanations": {"報われ": "受身の連用形で、「報われ、〜」と文を続ける形になる。", "報えば": "仮定形で、条件を作る形。受身の連用形ではない。", "報わなかった": "能動の否定過去で、受身の連用形とは形が違う。", "報わなく": "能動の否定連用形で、受身の連用形とは形が違う。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ec7c81a-a7fa-4224-baaa-5668fe3bbedd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37842, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "「作業は」の「は」は文の主題を示す。"}, {"text": "に", "is_correct": false, "explanation": "時点や場所を示す「に」。主題を表せず、文が不自然になる。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す「へ」。主題を表す場面では使えない。"}, {"text": "より", "is_correct": false, "explanation": "比較の「より」。「毎日」の前に立って動作を表せず、文が成り立たない。"}], "correct_answer": "は", "explanations": {"は": "「作業は」の「は」は文の主題を示す。", "に": "時点や場所を示す「に」。主題を表せず、文が不自然になる。", "へ": "方向を示す「へ」。主題を表す場面では使えない。", "より": "比較の「より」。「毎日」の前に立って動作を表せず、文が成り立たない。"}, "error_tags": {"に": "場所", "へ": "方向", "より": "比較"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6223e701-db4d-4fad-8ad6-90e467be2509') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37842, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「言葉を」は「繰り返す」の対象を示す目的語の「を」。"}, {"text": "が", "is_correct": false, "explanation": "主語の「が」。「言葉が」とすると「読む」の主語が言葉になり、先生が読む文の意味が崩れる。"}, {"text": "の", "is_correct": false, "explanation": "連体修飾の「の」。「言葉の繰り返して」は名詞を修飾できず、文が成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "並列の「と」。後ろに並べる名詞がなく、「繰り返して読む」とは続かない。"}], "correct_answer": "を", "explanations": {"を": "「言葉を」は「繰り返す」の対象を示す目的語の「を」。", "が": "主語の「が」。「言葉が」とすると「読む」の主語が言葉になり、先生が読む文の意味が崩れる。", "の": "連体修飾の「の」。「言葉の繰り返して」は名詞を修飾できず、文が成り立たない。", "と": "並列の「と」。後ろに並べる名詞がなく、「繰り返して読む」とは続かない。"}, "error_tags": {"が": "主語", "の": "連体修飾", "と": "並列"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6223e701-db4d-4fad-8ad6-90e467be2509') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37842, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "同じことをもう一度言ったり、したりすること。", "primary_collocate": null, "pronunciation": "くりかえす", "ipa": "kɯɾikaesɯ", "syllable_count": 5, "sentences": [{"text": "電話番号をもう一度繰り返してもらえますか。", "target_word": "繰り返して", "complexity_tier": "T3", "furigana": "電話番号[でんわばんごう]をもう一度[いちど]繰[く]り返[かえ]してもらえますか。", "sentence_source": "generated"}, {"text": "この作業は毎日繰り返すので、すぐに慣れた。", "target_word": "繰り返す", "complexity_tier": "T3", "furigana": "この作業[さぎょう]は毎日[まいにち]繰[く]り返[かえ]すので、すぐに慣[な]れた。", "sentence_source": "generated"}, {"text": "兄は同じ冗談を繰り返して、みんなに笑われた。", "target_word": "繰り返して", "complexity_tier": "T3", "furigana": "兄[あに]は同[おな]じ冗談[じょうだん]を繰[く]り返[かえ]して、みんなに笑[わら]われた。", "sentence_source": "generated"}, {"text": "試験の前に、間違えた問題を繰り返して解いた。", "target_word": "繰り返して", "complexity_tier": "T3", "furigana": "試験[しけん]の前[まえ]に、間違[まちが]えた問題[もんだい]を繰[く]り返[かえ]して解[と]いた。", "sentence_source": "generated"}, {"text": "彼女は小さな声で名前を繰り返した。", "target_word": "繰り返した", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は小[ちい]さな声[こえ]で名前[なまえ]を繰[く]り返[かえ]した。", "sentence_source": "generated"}, {"text": "失敗を繰り返しても、あきらめずに続けることが大切だ。", "target_word": "繰り返しても", "complexity_tier": "T3", "furigana": "失敗[しっぱい]を繰[く]り返[かえ]しても、あきらめずに続[つづ]けることが大切[たいせつ]だ。", "sentence_source": "generated"}, {"text": "雨と晴れを繰り返す天気が、一週間続いている。", "target_word": "繰り返す", "complexity_tier": "T3", "furigana": "雨[あめ]と晴[は]れを繰[く]り返[かえ]す天気[てんき]が、一週間[いっしゅうかん]続[つづ]いている。", "sentence_source": "generated"}, {"text": "先生の言葉を繰り返して読むと、発音がよくなる。", "target_word": "繰り返して", "complexity_tier": "T3", "furigana": "先生[せんせい]の言葉[ことば]を繰[く]り返[かえ]して読[よ]むと、発音[はつおん]がよくなる。", "sentence_source": "generated"}, {"text": "同じ道を何度も往復するだけの仕事を繰り返している。", "target_word": "繰り返している", "complexity_tier": "T3", "furigana": "同[おな]じ道[みち]を何度[なんど]も往復[おうふく]するだけの仕事[しごと]を繰[く]り返[かえ]している。", "sentence_source": "generated"}, {"text": "彼は何度も謝りの言葉を繰り返したが、相手は許さなかった。", "target_word": "繰り返した", "complexity_tier": "T3", "furigana": "彼[かれ]は何度[なんど]も謝[あやま]りの言葉[ことば]を繰[く]り返[かえ]したが、相手[あいて]は許[ゆる]さなかった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "繰り返す", "label": "終止形"}, {"form": "繰り返し", "label": "連用形"}, {"form": "繰り返した", "label": "過去形"}, {"form": "繰り返して", "label": "て形"}, {"form": "繰り返さない", "label": "否定形"}, {"form": "繰り返せば", "label": "仮定形"}, {"form": "繰り返される", "label": "受身形"}], "register": "標準", "sense_fingerprint": "すでに言ったこと・したことを、もう一度言う、またはやり直す", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1e5117e-6210-437d-8c4a-90abcde11eb5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37842, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "繰り返して", "is_correct": true, "explanation": "て形。「繰り返してもらえますか」の形で、依頼の文になる。"}, {"text": "繰り返す", "is_correct": false, "explanation": "終止形では「もらえますか」と続かず、文が成り立たない。"}, {"text": "繰り返した", "is_correct": false, "explanation": "過去形では「もらえますか」と続かず、不自然になる。"}, {"text": "繰り返せば", "is_correct": false, "explanation": "仮定形では依頼の文にならず、意味が通らない。"}], "explanations": {"繰り返して": "て形。「繰り返してもらえますか」の形で、依頼の文になる。", "繰り返す": "終止形では「もらえますか」と続かず、文が成り立たない。", "繰り返した": "過去形では「もらえますか」と続かず、不自然になる。", "繰り返せば": "仮定形では依頼の文にならず、意味が通らない。"}, "sentence_index": 0, "correct_answer": "繰り返して"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "大事な財布を、うっかり繰り返した。", "explanation": "ここは〈忘れる〉の意味。繰り返すは同じ動作や言葉をもう一度行うことで、物を置き忘れる意味では使わない。"}, {"text": "夜空の星が、静かに繰り返した。", "explanation": "ここは〈光る〉の意味。繰り返すは同じことをもう一度行うことで、星が輝く意味では使わない。"}, {"text": "彼は夜遅く、ぐっすり繰り返した。", "explanation": "ここは〈眠る〉の意味。繰り返すは同じことを行う意味で、深く寝入る状態は表さない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6223e701-db4d-4fad-8ad6-90e467be2509') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37842, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "繰り返す", "is_correct": true, "explanation": "連体形。「天気」を修飾する形で、「雨と晴れを繰り返す天気」となる。"}, {"text": "繰り返せば", "is_correct": false, "explanation": "仮定形は名詞を修飾できず、文が成り立たない。"}, {"text": "繰り返し", "is_correct": false, "explanation": "連用形は「天気」を修飾できず、文が不自然になる。"}, {"text": "繰り返される", "is_correct": false, "explanation": "受身形では「雨と晴れを」の「を」と合わず、文が成り立たない。"}], "explanations": {"繰り返す": "連体形。「天気」を修飾する形で、「雨と晴れを繰り返す天気」となる。", "繰り返せば": "仮定形は名詞を修飾できず、文が成り立たない。", "繰り返し": "連用形は「天気」を修飾できず、文が不自然になる。", "繰り返される": "受身形では「雨と晴れを」の「を」と合わず、文が成り立たない。"}, "sentence_index": 6, "correct_answer": "繰り返す"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "その店は、今年の春に繰り返した。", "explanation": "ここは〈閉店する〉の意味。繰り返すは同じことをもう一度行うことで、店の営業をやめる意味では使わない。"}, {"text": "旅行の日程を、急いで繰り返した。", "explanation": "ここは〈変更する〉の意味。繰り返すは日程を変える意味では使えない。"}, {"text": "電車が十分繰り返した。", "explanation": "ここは〈遅れる〉の意味。繰り返すは同じことを行う意味で、予定の時刻より後になる意味では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6223e701-db4d-4fad-8ad6-90e467be2509') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37842, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "兄は同じ冗談を繰り返すて、家族に笑われた。", "corrected_sentence": "兄は同じ冗談を繰り返して、家族に笑われた。", "error_description": "て形は「繰り返して」。「繰り返すて」は活用の誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "繰り返す", "is_correct": true, "explanation": "終止形。「毎日繰り返すので」と理由の「ので」に続く形。"}, {"text": "繰り返して", "is_correct": false, "explanation": "て形。「ので」の前には立たず、理由の文として成り立たない。"}, {"text": "繰り返せ", "is_correct": false, "explanation": "命令形。「ので」の前には立たず、文が成り立たない。"}, {"text": "繰り返せば", "is_correct": false, "explanation": "仮定形。「ので」と続く理由の文には合わない。"}], "correct_form": "繰り返す", "base_form": "繰り返す", "form_label": "終止形", "sentence_index": 1, "explanations": {"繰り返す": "終止形。「毎日繰り返すので」と理由の「ので」に続く形。", "繰り返して": "て形。「ので」の前には立たず、理由の文として成り立たない。", "繰り返せ": "命令形。「ので」の前には立たず、文が成り立たない。", "繰り返せば": "仮定形。「ので」と続く理由の文には合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6223e701-db4d-4fad-8ad6-90e467be2509') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37842, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "先生の文を繰り返しで読むと、発音がよくなる。", "corrected_sentence": "先生の文を繰り返して読むと、発音がよくなる。", "error_description": "「繰り返して読む」の形が正しい。「繰り返しで」は連用形に「で」をつけた誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "繰り返して", "is_correct": true, "explanation": "て形。後ろの「読むと」へ続く形。"}, {"text": "繰り返される", "is_correct": false, "explanation": "受身形。「言葉を」を受ける動作の文にはならず、「読むと」へ続けると意味が合わない。"}, {"text": "繰り返している", "is_correct": false, "explanation": "進行形。「読むと」へ続けると動作の途中を表し、条件の文として不自然になる。"}, {"text": "繰り返しても", "is_correct": false, "explanation": "逆接の「〜ても」の形。「読むと」の条件の文には続かず、意味が合わない。"}], "correct_form": "繰り返して", "base_form": "繰り返す", "form_label": "て形", "sentence_index": 7, "explanations": {"繰り返して": "て形。後ろの「読むと」へ続く形。", "繰り返される": "受身形。「言葉を」を受ける動作の文にはならず、「読むと」へ続けると意味が合わない。", "繰り返している": "進行形。「読むと」へ続けると動作の途中を表し、条件の文として不自然になる。", "繰り返しても": "逆接の「〜ても」の形。「読むと」の条件の文には続かず、意味が合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6223e701-db4d-4fad-8ad6-90e467be2509') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37843, 3, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6223e701-db4d-4fad-8ad6-90e467be2509') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37843, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「練習を」は「繰り返す」の対象を示す目的語の「を」。"}, {"text": "に", "is_correct": false, "explanation": "時点や場所を示す「に」。対象を表せないので合わない。"}, {"text": "と", "is_correct": false, "explanation": "相手や並列を示す「と」。対象を表す文脈では合わない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す「へ」。対象を示す場面では使えない。"}], "correct_answer": "を", "explanations": {"を": "「練習を」は「繰り返す」の対象を示す目的語の「を」。", "に": "時点や場所を示す「に」。対象を表せないので合わない。", "と": "相手や並列を示す「と」。対象を表す文脈では合わない。", "へ": "方向を示す「へ」。対象を示す場面では使えない。"}, "error_tags": {"に": "場所", "と": "相手", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6223e701-db4d-4fad-8ad6-90e467be2509') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37843, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "同じ動作や言葉、出来事を、もう一度または何度も行うこと。また、同じことを何度も言うこと。", "primary_collocate": null, "pronunciation": "くりかえす", "ipa": "kɯɾikaesɯ", "syllable_count": 5, "sentences": [{"text": "なぜならば、無数の主体が限られた情報に基づき絶えず適応を繰り返す過程で、意図せぬイノベーションやシステミック・リスクが突発的に顕現するからに他ならない。", "target_word": "繰り返す", "complexity_tier": "T4", "furigana": "なぜならば、無数[むすう]の主体[しゅたい]が限[かぎ]られた情報[じょうほう]に基[もと]づき絶[た]えず適応[てきおう]を繰[く]り返[かえ]す過程[かてい]で、意図[いと]せぬイノベーションやシステミック・リスクが突発的[とっぱつてき]に顕現[けんげん]するからに他[ほか]ならない。", "sentence_source": "mined"}, {"text": "先生は大事なところを、ゆっくり二度繰り返した。", "target_word": "繰り返した", "complexity_tier": "T3", "furigana": "先生[せんせい]は大事[だいじ]なところを、ゆっくり二度[にど]繰[く]り返[かえ]した。", "sentence_source": "generated"}, {"text": "同じ失敗を繰り返さないように、毎日ノートに書いている。", "target_word": "繰り返さない", "complexity_tier": "T3", "furigana": "同[おな]じ失敗[しっぱい]を繰[く]り返[かえ]さないように、毎日[まいにち]ノートに書[か]いている。", "sentence_source": "generated"}, {"text": "彼は「大丈夫」と繰り返して、不安な顔をかくそうとした。", "target_word": "繰り返して", "complexity_tier": "T3", "furigana": "彼[かれ]は「大丈夫[だいじょうぶ]」と繰[く]り返[かえ]して、不安[ふあん]な顔[かお]をかくそうとした。", "sentence_source": "generated"}, {"text": "波は、岸に寄せては引くことを繰り返している。", "target_word": "繰り返している", "complexity_tier": "T3", "furigana": "波[なみ]は、岸[きし]に寄[よ]せては引[ひ]くことを繰[く]り返[かえ]している。", "sentence_source": "generated"}, {"text": "新しい単語は、声に出して繰り返すと覚えやすい。", "target_word": "繰り返す", "complexity_tier": "T3", "furigana": "新[あたら]しい単語[たんご]は、声[こえ]に出[だ]して繰[く]り返[かえ]すと覚[おぼ]えやすい。", "sentence_source": "generated"}, {"text": "母は「気をつけてね」と何度も繰り返して、私を送り出した。", "target_word": "繰り返して", "complexity_tier": "T3", "furigana": "母[はは]は「気[き]をつけてね」と何度[なんど]も繰[く]り返[かえ]して、私[わたし]を送[おく]り出[だ]した。", "sentence_source": "generated"}, {"text": "練習を繰り返すうちに、むずかしい曲も弾けるようになった。", "target_word": "繰り返す", "complexity_tier": "T3", "furigana": "練習[れんしゅう]を繰[く]り返[かえ]すうちに、むずかしい曲[きょく]も弾[ひ]けるようになった。", "sentence_source": "generated"}, {"text": "質問がよく聞こえなかったので、もう一度繰り返してください。", "target_word": "繰り返して", "complexity_tier": "T3", "furigana": "質問[しつもん]がよく聞[き]こえなかったので、もう一度[いちど]繰[く]り返[かえ]してください。", "sentence_source": "generated"}, {"text": "歴史は繰り返すと言われるが、全く同じことが起こるわけではない。", "target_word": "繰り返す", "complexity_tier": "T3", "furigana": "歴史[れきし]は繰[く]り返[かえ]すと言[い]われるが、全[まった]く同[おな]じことが起[お]こるわけではない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "繰り返す", "label": "終止形"}, {"form": "繰り返し", "label": "連用形"}, {"form": "繰り返した", "label": "過去形"}, {"form": "繰り返して", "label": "て形"}, {"form": "繰り返さない", "label": "否定形"}, {"form": "繰り返せば", "label": "仮定形"}, {"form": "繰り返される", "label": "受身形"}], "register": "標準", "sense_fingerprint": "同じ動作・言葉・出来事を何度も行う、または何度も言う", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 3 above tier T3: contains vocabulary far above tier T3: かくそ (Zipf 1.29)']::text[], 'c1e5117e-6210-437d-8c4a-90abcde11eb5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37843, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "繰り返す", "is_correct": true, "explanation": "「過程」を修飾する連体形で、ここにだけ入る。"}, {"text": "繰り返して", "is_correct": false, "explanation": "て形は名詞「過程」を直接修飾できず、文が成り立たない。"}, {"text": "繰り返せば", "is_correct": false, "explanation": "仮定形は名詞を修飾できない。「繰り返せば過程で」は不自然。"}, {"text": "繰り返し", "is_correct": false, "explanation": "連用形は「過程」を修飾できず、「適応を繰り返し過程」は成り立たない。"}], "explanations": {"繰り返す": "「過程」を修飾する連体形で、ここにだけ入る。", "繰り返して": "て形は名詞「過程」を直接修飾できず、文が成り立たない。", "繰り返せば": "仮定形は名詞を修飾できない。「繰り返せば過程で」は不自然。", "繰り返し": "連用形は「過程」を修飾できず、「適応を繰り返し過程」は成り立たない。"}, "sentence_index": 0, "correct_answer": "繰り返す"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "昔の友人の顔を、ふと繰り返した。", "explanation": "ここは〈思い出す〉の意味。繰り返すは同じ動作や言葉をもう一度行うことで、人の顔を思い浮かべる意味では使わない。"}, {"text": "友達に借りたお金を、すぐに繰り返した。", "explanation": "ここは〈返す〉の意味。繰り返すは同じことをもう一度行うことで、借りたお金を戻す意味では使わない。"}, {"text": "彼は屋台で、ラーメンを一杯繰り返した。", "explanation": "ここは〈おかわりする〉の意味。繰り返すは同じことを何度も行うことで、一杯追加する意味では使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6223e701-db4d-4fad-8ad6-90e467be2509') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37843, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "繰り返して", "is_correct": true, "explanation": "て形。後ろの「送り出した」へ続く形で、「何度も繰り返して」となる。"}, {"text": "繰り返そう", "is_correct": false, "explanation": "意志形は過去の叙述文に合わない。"}, {"text": "繰り返せば", "is_correct": false, "explanation": "仮定形では「私を送り出した」と続かず、文が成り立たない。"}, {"text": "繰り返される", "is_correct": false, "explanation": "受身形。母が主体的に行う動作を表す文には合わない。"}], "explanations": {"繰り返して": "て形。後ろの「送り出した」へ続く形で、「何度も繰り返して」となる。", "繰り返そう": "意志形は過去の叙述文に合わない。", "繰り返せば": "仮定形では「私を送り出した」と続かず、文が成り立たない。", "繰り返される": "受身形。母が主体的に行う動作を表す文には合わない。"}, "sentence_index": 6, "correct_answer": "繰り返して"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "机の角に当たって、コップが繰り返した。", "explanation": "ここは〈割れる〉の意味。繰り返すは同じ動作や言葉をもう一度行うことで、物が壊れる意味では使わない。"}, {"text": "旅行の日程を、急いで繰り返した。", "explanation": "ここは〈変更する〉の意味。繰り返すは予定を別のものに変える意味では使えない。"}, {"text": "十年ぶりに、先生を繰り返した。", "explanation": "ここは〈再会する〉の意味。繰り返すは同じことをもう一度行う意味で、人に久しぶりに会う意味にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6223e701-db4d-4fad-8ad6-90e467be2509') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37843, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "同じ失敗を繰り返すないように、毎日メモを取っている。", "corrected_sentence": "同じ失敗を繰り返さないように、毎日メモを取っている。", "error_description": "否定形は「繰り返さない」。「繰り返すない」は活用の誤りで、正しくは「さない」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "繰り返した", "is_correct": true, "explanation": "過去形。「二度繰り返した」の「した」にあたる。"}, {"text": "繰り返さない", "is_correct": false, "explanation": "否定形。文は実際に行われた過去の動作なので合わない。"}, {"text": "繰り返せば", "is_correct": false, "explanation": "仮定形。条件を表すが、文は事実の報告なので合わない。"}, {"text": "繰り返して", "is_correct": false, "explanation": "て形。後ろに「ゆっくり二度」を受けて文を終える形ではない。"}], "correct_form": "繰り返した", "base_form": "繰り返す", "form_label": "過去形", "sentence_index": 1, "explanations": {"繰り返した": "過去形。「二度繰り返した」の「した」にあたる。", "繰り返さない": "否定形。文は実際に行われた過去の動作なので合わない。", "繰り返せば": "仮定形。条件を表すが、文は事実の報告なので合わない。", "繰り返して": "て形。後ろに「ゆっくり二度」を受けて文を終える形ではない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6223e701-db4d-4fad-8ad6-90e467be2509') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37843, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "基本に繰り返すうちに、むずかしい曲も弾けるようになった。", "corrected_sentence": "基本を繰り返すうちに、むずかしい曲も弾けるようになった。", "error_description": "「繰り返す」の対象は「を」で示す。「基本に」は誤りで、正しくは「基本を」。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "繰り返す", "is_correct": true, "explanation": "連体形。「繰り返すうちに」と続く形。"}, {"text": "繰り返し", "is_correct": false, "explanation": "連用形。「繰り返しうちに」とは続かない。"}, {"text": "繰り返そう", "is_correct": false, "explanation": "意志形。「繰り返そうちに」の形では「うちに」の前に立てず、文が成り立たない。"}, {"text": "繰り返せ", "is_correct": false, "explanation": "命令形。相手に命じる形で、「うちに」の前には立たず、文が成り立たない。"}], "correct_form": "繰り返す", "base_form": "繰り返す", "form_label": "連体形", "sentence_index": 7, "explanations": {"繰り返す": "連体形。「繰り返すうちに」と続く形。", "繰り返し": "連用形。「繰り返しうちに」とは続かない。", "繰り返そう": "意志形。「繰り返そうちに」の形では「うちに」の前に立てず、文が成り立たない。", "繰り返せ": "命令形。相手に命じる形で、「うちに」の前には立たず、文が成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6223e701-db4d-4fad-8ad6-90e467be2509') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37844, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「教えを受ける」の目的語を示す。"}, {"text": "が", "is_correct": false, "explanation": "主語を示す。「教えが受けて」では、受ける人が示せず文が成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "相手を示す。「教えに受けて」とは言わない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す。「教えへ受けて」では意味が通らない。"}], "correct_answer": "を", "explanations": {"を": "「教えを受ける」の目的語を示す。", "が": "主語を示す。「教えが受けて」では、受ける人が示せず文が成り立たない。", "に": "相手を示す。「教えに受けて」とは言わない。", "へ": "方向を示す。「教えへ受けて」では意味が通らない。"}, "error_tags": {"が": "主語の格", "に": "相手・場所", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ec7c81a-a7fa-4224-baaa-5668fe3bbedd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37844, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「母の教えを聞きながら」で、聞く対象の目的語を示す。"}, {"text": "で", "is_correct": false, "explanation": "手段や場所を示す。「教えで聞きながら」は意味が通らない。"}, {"text": "と", "is_correct": false, "explanation": "相手や引用を示す。「教えと聞きながら」とは言わない。"}, {"text": "の", "is_correct": false, "explanation": "修飾を示す。「教えの聞きながら」では文が成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「母の教えを聞きながら」で、聞く対象の目的語を示す。", "で": "手段や場所を示す。「教えで聞きながら」は意味が通らない。", "と": "相手や引用を示す。「教えと聞きながら」とは言わない。", "の": "修飾を示す。「教えの聞きながら」では文が成り立たない。"}, "error_tags": {"で": "手段・場所", "と": "相手・引用", "の": "修飾"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ec7c81a-a7fa-4224-baaa-5668fe3bbedd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37844, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "師や年上の人が、やり方や知識を相手に伝えること。また、その指導の内容。", "primary_collocate": null, "pronunciation": "おしえ", "ipa": "oɕie", "syllable_count": 3, "sentences": [{"text": "先生の教えのおかげで、やり方がよくわかった。", "target_word": "教え", "complexity_tier": "T3", "furigana": "先生[せんせい]の教[おし]えのおかげで、やり方[かた]がよくわかった。", "sentence_source": "generated"}, {"text": "先輩の教えを受けて、仕事に慣れた。", "target_word": "教え", "complexity_tier": "T3", "furigana": "先輩[せんぱい]の教[おし]えを受[う]けて、仕事[しごと]に慣[な]れた。", "sentence_source": "generated"}, {"text": "父の教えは短いが、いつもわかりやすい。", "target_word": "教え", "complexity_tier": "T2", "furigana": "父[ちち]の教[おし]えは短[みじか]いが、いつもわかりやすい。", "sentence_source": "generated"}, {"text": "兄の教えで、自転車に乗れるようになった。", "target_word": "教え", "complexity_tier": "T2", "furigana": "兄[あに]の教[おし]えで、自転車[じてんしゃ]に乗[の]れるようになった。", "sentence_source": "generated"}, {"text": "山のガイドの教えに従って、安全な道を歩いた。", "target_word": "教え", "complexity_tier": "T3", "furigana": "山[やま]のガイドの教[おし]えに従[したが]って、安全[あんぜん]な道[みち]を歩[ある]いた。", "sentence_source": "generated"}, {"text": "上手になりたくて、有名な料理人に教えを請うた。", "target_word": "教え", "complexity_tier": "T4", "furigana": "上手[じょうず]になりたくて、有名[ゆうめい]な料理人[りょうりにん]に教[おし]えを請[こ]うた。", "sentence_source": "generated"}, {"text": "説明は下手でも、彼の教えは心に残った。", "target_word": "教え", "complexity_tier": "T3", "furigana": "説明[せつめい]は下手[へた]でも、彼[かれ]の教[おし]えは心[こころ]に残[のこ]った。", "sentence_source": "generated"}, {"text": "母の教えを聞きながら、料理を作った。", "target_word": "教え", "complexity_tier": "T2", "furigana": "母[はは]の教[おし]えを聞[き]きながら、料理[りょうり]を作[つく]った。", "sentence_source": "generated"}, {"text": "師匠の教えが厳しくて、毎日泣きそうだった。", "target_word": "教え", "complexity_tier": "T3", "furigana": "師匠[ししょう]の教[おし]えが厳[きび]しくて、毎日[まいにち]泣[な]きそうだった。", "sentence_source": "generated"}, {"text": "先生の教えがなければ、この問題は解けなかった。", "target_word": "教え", "complexity_tier": "T3", "furigana": "先生[せんせい]の教[おし]えがなければ、この問題[もんだい]は解[と]けなかった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "教え", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "師や年上の人が、やり方や知識を相手に伝える指導", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e58768ae-8131-4a19-a152-42a2f9901ab2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37844, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "教え", "is_correct": true, "explanation": "「先生の教えのおかげ」で、指導の内容を指す。"}, {"text": "生徒", "is_correct": false, "explanation": "人を指す。「先生の生徒のおかげ」では、やり方がわかった理由にならない。"}, {"text": "黒板", "is_correct": false, "explanation": "授業で使う物で、指導の内容を指さない。"}, {"text": "出席", "is_correct": false, "explanation": "授業に来ることで、やり方がわかった理由の指導内容を表さない。"}], "explanations": {"教え": "「先生の教えのおかげ」で、指導の内容を指す。", "生徒": "人を指す。「先生の生徒のおかげ」では、やり方がわかった理由にならない。", "黒板": "授業で使う物で、指導の内容を指さない。", "出席": "授業に来ることで、やり方がわかった理由の指導内容を表さない。"}, "sentence_index": 0, "correct_answer": "教え"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この料理には新鮮な教えが欠かせない。", "explanation": "食材を表す使い方は教えにはない。教えは知識や指導なので、料理の材料にはならない。"}, {"text": "この教えで熱が下がった。", "explanation": "薬の意味は教えにはない。教えは指導の内容で、熱を下げる働きはない。"}, {"text": "この教えは、毎朝ごはんと一緒に食べた。", "explanation": "食べ物の意味は教えにはない。教えは指導の内容で、食べられるものではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ec7c81a-a7fa-4224-baaa-5668fe3bbedd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37844, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "教え", "is_correct": true, "explanation": "「彼の教えは心に残った」で、心に残るものとして主語になる。"}, {"text": "体重", "is_correct": false, "explanation": "心に残る内容ではないので、主語として意味が通らない。"}, {"text": "寝床", "is_correct": false, "explanation": "場所を指し、心に残るものではない。"}, {"text": "財布", "is_correct": false, "explanation": "持ち物を指し、心に残る内容にはならない。"}], "explanations": {"教え": "「彼の教えは心に残った」で、心に残るものとして主語になる。", "体重": "心に残る内容ではないので、主語として意味が通らない。", "寝床": "場所を指し、心に残るものではない。", "財布": "持ち物を指し、心に残る内容にはならない。"}, "sentence_index": 6, "correct_answer": "教え"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この教えで、家の鍵を開けた。", "explanation": "鍵の意味は教えにはない。教えは指導の内容で、扉を開ける働きはない。"}, {"text": "教えがなければ、車は動かない。", "explanation": "燃料の意味は教えにはない。教えは車を動かす力にはならない。"}, {"text": "教えがなければ、この店で代金を払えない。", "explanation": "お金の意味は教えにはない。教えは指導の内容で、代金の代わりにはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ec7c81a-a7fa-4224-baaa-5668fe3bbedd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37844, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "新人の頃、先輩の教えに受けて仕事を覚えた。", "corrected_sentence": "新人の頃、先輩の教えを受けて仕事を覚えた。", "error_description": "「教えを受ける」の目的語は「を」で示す。「に」にすると「教えに受ける」となり、誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ec7c81a-a7fa-4224-baaa-5668fe3bbedd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37844, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "先生の教えしは、いつまでも大切だ。", "corrected_sentence": "先生の教えは、いつまでも大切だ。", "error_description": "名詞「教え」に余分な「し」はつかない。「し」を取り除く。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ec7c81a-a7fa-4224-baaa-5668fe3bbedd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37845, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "「仏教の教えでは」で、話題の範囲を示す。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す。話題の範囲は表せず、「教えへは」では意味が通らない。", "error_tag": "方向"}, {"text": "を", "is_correct": false, "explanation": "目的語を示す。「教えを、は」では述語がなく文が成り立たない。", "error_tag": "目的語の格"}, {"text": "の", "is_correct": false, "explanation": "修飾を示す。「教えのは」では文が成り立たない。", "error_tag": "修飾"}], "correct_answer": "で", "explanations": {"で": "「仏教の教えでは」で、話題の範囲を示す。", "へ": "方向を示す。話題の範囲は表せず、「教えへは」では意味が通らない。", "を": "目的語を示す。「教えを、は」では述語がなく文が成り立たない。", "の": "修飾を示す。「教えのは」では文が成り立たない。"}, "error_tags": {"へ": "方向", "を": "目的語の格", "の": "修飾"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ec7c81a-a7fa-4224-baaa-5668fe3bbedd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37845, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「師の教えを心に刻んで」で、刻む対象の目的語を示す。"}, {"text": "に", "is_correct": false, "explanation": "相手や場所を示す。「教えに心に刻んで」は意味が通らない。"}, {"text": "の", "is_correct": false, "explanation": "修飾を示す。「教えの心に刻んで」では文が成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "比較を示す。「教えより心に刻んで」では、刻む対象を表せない。"}], "correct_answer": "を", "explanations": {"を": "「師の教えを心に刻んで」で、刻む対象の目的語を示す。", "に": "相手や場所を示す。「教えに心に刻んで」は意味が通らない。", "の": "修飾を示す。「教えの心に刻んで」では文が成り立たない。", "より": "比較を示す。「教えより心に刻んで」では、刻む対象を表せない。"}, "error_tags": {"に": "相手・場所", "の": "修飾", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ec7c81a-a7fa-4224-baaa-5668fe3bbedd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37845, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "宗教や人生について伝えられた教訓や考え方。", "primary_collocate": null, "pronunciation": "おしえ", "ipa": "oɕie", "syllable_count": 3, "sentences": [{"text": "祖父の教えを守って、毎日あいさつをしている。", "target_word": "教え", "complexity_tier": "T3", "furigana": "祖父[そふ]の教[おし]えを守[まも]って、毎日[まいにち]あいさつをしている。", "sentence_source": "generated"}, {"text": "仏教の教えでは、命は大切にするものだ。", "target_word": "教え", "complexity_tier": "T3", "furigana": "仏教[ぶっきょう]の教[おし]えでは、命[いのち]は大切[たいせつ]にするものだ。", "sentence_source": "generated"}, {"text": "「人に親切に」という母の教えを忘れない。", "target_word": "教え", "complexity_tier": "T3", "furigana": "「人[ひと]に親切[しんせつ]に」という母[はは]の教[おし]えを忘[わす]れない。", "sentence_source": "generated"}, {"text": "この学校では、創立者の教えを大切にしている。", "target_word": "教え", "complexity_tier": "T3", "furigana": "この学校[がっこう]では、創立者[そうりつしゃ]の教[おし]えを大切[たいせつ]にしている。", "sentence_source": "generated"}, {"text": "宗教の教えに従って、肉を食べない人もいる。", "target_word": "教え", "complexity_tier": "T3", "furigana": "宗教[しゅうきょう]の教[おし]えに従[したが]って、肉[にく]を食[た]べない人[ひと]もいる。", "sentence_source": "generated"}, {"text": "昔の人の教えは、今でも役に立つ。", "target_word": "教え", "complexity_tier": "T2", "furigana": "昔[むかし]の人[ひと]の教[おし]えは、今[いま]でも役[やく]に立[た]つ。", "sentence_source": "generated"}, {"text": "父の教えに背いて、嘘をついてしまった。", "target_word": "教え", "complexity_tier": "T3", "furigana": "父[ちち]の教[おし]えに背[そむ]いて、嘘[うそ]をついてしまった。", "sentence_source": "generated"}, {"text": "彼は師の教えを心に刻んで、旅に出た。", "target_word": "教え", "complexity_tier": "T4", "furigana": "彼[かれ]は師[し]の教[おし]えを心[こころ]に刻[きざ]んで、旅[たび]に出[で]た。", "sentence_source": "generated"}, {"text": "古い本には、先祖の教えが書かれている。", "target_word": "教え", "complexity_tier": "T3", "furigana": "古[ふる]い本[ほん]には、先祖[せんぞ]の教[おし]えが書[か]かれている。", "sentence_source": "generated"}, {"text": "教えを守らなかったことを、今も後悔している。", "target_word": "教え", "complexity_tier": "T3", "furigana": "教[おし]えを守[まも]らなかったことを、今[いま]も後悔[こうかい]している。", "sentence_source": "generated"}], "morphological_forms": [{"form": "教え", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "宗教や人生について伝えられた教訓・考え方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e58768ae-8131-4a19-a152-42a2f9901ab2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37845, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "教え", "is_correct": true, "explanation": "「祖父の教えを守って」で、守る対象の教訓を指す。"}, {"text": "天気", "is_correct": false, "explanation": "守る対象にならず、「祖父の天気を守って」は成り立たない。"}, {"text": "手袋", "is_correct": false, "explanation": "身につける物で、守る対象にはならない。"}, {"text": "鍋", "is_correct": false, "explanation": "調理器具で、守る対象にはならない。"}], "explanations": {"教え": "「祖父の教えを守って」で、守る対象の教訓を指す。", "天気": "守る対象にならず、「祖父の天気を守って」は成り立たない。", "手袋": "身につける物で、守る対象にはならない。", "鍋": "調理器具で、守る対象にはならない。"}, "sentence_index": 0, "correct_answer": "教え"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "祖父の教えは、庭の木の高さを測る道具だった。", "explanation": "道具の意味は教えにはない。教えは教訓で、木の高さを測る働きはない。"}, {"text": "この店の教えは、どれも大切に作られている。", "explanation": "料理の意味は教えにはない。教えは教訓で、作って食べられるものではない。"}, {"text": "祖父の教えは、庭で飼っている犬だ。", "explanation": "動物の意味は教えにはない。教えは生き物ではないので、この文には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ec7c81a-a7fa-4224-baaa-5668fe3bbedd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37845, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "教え", "is_correct": true, "explanation": "「父の教えに背いて」で、背く対象の教訓を指す。"}, {"text": "靴", "is_correct": false, "explanation": "物を指し、背く対象にはならない。"}, {"text": "指紋", "is_correct": false, "explanation": "身体の跡で、背く対象にはならない。"}, {"text": "窓", "is_correct": false, "explanation": "建物の一部で、背く対象にはならない。"}], "explanations": {"教え": "「父の教えに背いて」で、背く対象の教訓を指す。", "靴": "物を指し、背く対象にはならない。", "指紋": "身体の跡で、背く対象にはならない。", "窓": "建物の一部で、背く対象にはならない。"}, "sentence_index": 6, "correct_answer": "教え"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "祖父の教えは、毎朝遊びに来る友達だ。", "explanation": "友達の意味は教えにはない。教えは人ではないので、遊びに来ることはない。"}, {"text": "祖父の教えは、庭で育てた花だ。", "explanation": "植物の意味は教えにはない。教えは生き物ではなく、花として育てられない。"}, {"text": "祖父の教えは、冬に使う暖房だ。", "explanation": "機械の意味は教えにはない。教えは物ではなく、暖める働きはない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ec7c81a-a7fa-4224-baaa-5668fe3bbedd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37845, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "祖母の教えに守って、毎朝早く起きる。", "corrected_sentence": "祖母の教えを守って、毎朝早く起きる。", "error_description": "「守る」の目的語は「を」で示す。「に」にすると、教えを守る関係が成り立たず誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ec7c81a-a7fa-4224-baaa-5668fe3bbedd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37845, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "父の教えのは、今も忘れられない。", "corrected_sentence": "父の教えは、今も忘れられない。", "error_description": "「教え」に余分な「の」がついている。主題を示す「は」を使い、「の」は取り除く。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ec7c81a-a7fa-4224-baaa-5668fe3bbedd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
