INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37846, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "から", "options": [{"text": "から", "is_correct": true, "explanation": "「災害から身を守る」は災害を起点とする自然な表現。"}, {"text": "に", "is_correct": false, "explanation": "「身を守る」の相手は「から」で示す。「災害に身を守る」は不自然。"}, {"text": "の", "is_correct": false, "explanation": "「の」は名詞をつなぐ働きで、動詞「守る」の対象を示せない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や相手を示すが、「災害と身を守る」は意味が通らない。"}], "correct_answer": "から", "explanations": {"から": "「災害から身を守る」は災害を起点とする自然な表現。", "に": "「身を守る」の相手は「から」で示す。「災害に身を守る」は不自然。", "の": "「の」は名詞をつなぐ働きで、動詞「守る」の対象を示せない。", "と": "「と」は並列や相手を示すが、「災害と身を守る」は意味が通らない。"}, "error_tags": {"に": "対象（守るの相手に不適）", "の": "連体修飾", "と": "並列・相手"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25a27df5-4741-4b2c-abc8-2a6286747f67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37846, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "人がけがをしたり、家がこわれたりする、とてもこわいできごとです。", "primary_collocate": null, "pronunciation": "さいがい", "ipa": "saiɡai", "syllable_count": 4, "sentences": [{"text": "日本は地震が多く、災害にそなえる家が増えています。", "target_word": "災害", "complexity_tier": "T3", "furigana": "日本[にほん]は地震[じしん]が多[おお]く、災害[さいがい]にそなえる家[いえ]が増[ふ]えています。", "sentence_source": "generated"}, {"text": "台風による災害で、多くの家がこわれました。", "target_word": "災害", "complexity_tier": "T3", "furigana": "台風[たいふう]による災害[さいがい]で、多[おお]くの家[いえ]がこわれました。", "sentence_source": "generated"}, {"text": "災害が起きたときは、まず安全な場所に逃げてください。", "target_word": "災害", "complexity_tier": "T3", "furigana": "災害[さいがい]が起[お]きたときは、まず安全[あんぜん]な場所[ばしょ]に逃[に]げてください。", "sentence_source": "generated"}, {"text": "学校では毎年、災害の訓練をしています。", "target_word": "災害", "complexity_tier": "T3", "furigana": "学校[がっこう]では毎年[まいとし]、災害[さいがい]の訓練[くんれん]をしています。", "sentence_source": "generated"}, {"text": "大雨の災害のニュースを見て、友だちが心配になりました。", "target_word": "災害", "complexity_tier": "T3", "furigana": "大雨[おおあめ]の災害[さいがい]のニュースを見[み]て、友[とも]だちが心配[しんぱい]になりました。", "sentence_source": "generated"}, {"text": "災害のあと、町の人たちは助け合って生活しました。", "target_word": "災害", "complexity_tier": "T3", "furigana": "災害[さいがい]のあと、町[まち]の人[ひと]たちは助[たす]け合[あ]って生活[せいかつ]しました。", "sentence_source": "generated"}, {"text": "災害にあった人に、毛布や水を送りました。", "target_word": "災害", "complexity_tier": "T3", "furigana": "災害[さいがい]にあった人[ひと]に、毛布[もうふ]や水[みず]を送[おく]りました。", "sentence_source": "generated"}, {"text": "災害から身を守るために、非常用の食べ物を用意しています。", "target_word": "災害", "complexity_tier": "T3", "furigana": "災害[さいがい]から身[み]を守[まも]るために、非常用[ひじょうよう]の食[た]べ物[もの]を用意[ようい]しています。", "sentence_source": "generated"}, {"text": "火山の噴火は大きな災害になることがあります。", "target_word": "災害", "complexity_tier": "T3", "furigana": "火山[かざん]の噴火[ふんか]は大[おお]きな災害[さいがい]になることがあります。", "sentence_source": "generated"}, {"text": "災害が起きても落ち着いて行動できるよう、家族で話し合いました。", "target_word": "災害", "complexity_tier": "T3", "furigana": "災害[さいがい]が起[お]きても落[お]ち着[つ]いて行動[こうどう]できるよう、家族[かぞく]で話[はな]し合[あ]いました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "災害", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "地震や台風などで人がけがをしたり家がこわれたりする、こわい出来事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T2: contains vocabulary far above tier T2: そなえる (Zipf 1.97)']::text[], '226e73b8-df71-4110-ab40-d23c9c97d88d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37846, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "災害", "is_correct": true, "explanation": "「地震にそなえる」と並び、災害対策の文脈に合う語。"}, {"text": "読書", "is_correct": false, "explanation": "「読書にそなえる家」は文として成り立たず、地震の文脈とも合わない。"}, {"text": "掃除", "is_correct": false, "explanation": "「掃除にそなえる」は不自然で、家が増えている理由にならない。"}, {"text": "料理", "is_correct": false, "explanation": "「料理にそなえる」とは言わず、地震への備えの話と合わない。"}], "explanations": {"災害": "「地震にそなえる」と並び、災害対策の文脈に合う語。", "読書": "「読書にそなえる家」は文として成り立たず、地震の文脈とも合わない。", "掃除": "「掃除にそなえる」は不自然で、家が増えている理由にならない。", "料理": "「料理にそなえる」とは言わず、地震への備えの話と合わない。"}, "sentence_index": 0, "correct_answer": "災害"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "自転車の災害で、ひざをすりむいた。", "explanation": "ここは〈事故〉の意味。災害は地震や台風など、多くの人や社会に及ぶ出来事を指すので、自転車の事故には使わない。"}, {"text": "空き巣の災害にあって、財布を取られた。", "explanation": "ここは〈被害〉の意味。災害は自然や社会規模の出来事なので、空き巣のような犯罪の被害には使わない。"}, {"text": "冷蔵庫の災害で、中の食べ物が傷んだ。", "explanation": "ここは〈故障〉の意味。災害は個人の機械の不具合ではなく、多くの人に影響する出来事に使うので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25a27df5-4741-4b2c-abc8-2a6286747f67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37846, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "災害", "is_correct": true, "explanation": "「災害にあう」で被災者を指し、毛布や水を送る文脈に合う。"}, {"text": "手紙", "is_correct": false, "explanation": "「手紙にあう」とは言わず、支援物資の文脈と合わない。"}, {"text": "散歩", "is_correct": false, "explanation": "「散歩にあう」は不自然で、被災者への支援と結びつかない。"}, {"text": "音楽", "is_correct": false, "explanation": "「音楽にあう」は意味が通らず、毛布や水を送る話と合わない。"}], "explanations": {"災害": "「災害にあう」で被災者を指し、毛布や水を送る文脈に合う。", "手紙": "「手紙にあう」とは言わず、支援物資の文脈と合わない。", "散歩": "「散歩にあう」は不自然で、被災者への支援と結びつかない。", "音楽": "「音楽にあう」は意味が通らず、毛布や水を送る話と合わない。"}, "sentence_index": 6, "correct_answer": "災害"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "夜中に泥棒が家に入る災害があった。", "explanation": "ここは〈事件〉の意味。災害は自然や社会規模の出来事なので、盗みのような犯罪には使わない。"}, {"text": "足をくじき、財布もなくすという災害に遭った。", "explanation": "ここは〈災難〉の意味。災害は多くの人や社会に及ぶ出来事なので、個人の不運には使わない。"}, {"text": "取引先との災害で、社長が頭を下げた。", "explanation": "ここは〈もめごと〉の意味。災害は自然や社会規模の大きな出来事を指すので、取引先との言い争いには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25a27df5-4741-4b2c-abc8-2a6286747f67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37846, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "大雨による災害を、川の水があふれた。", "corrected_sentence": "大雨による災害で、川の水があふれた。", "error_description": "「災害で」は原因を表す。「災害を」だと災害が目的語になり、自動詞の「あふれた」と合わず不自然。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25a27df5-4741-4b2c-abc8-2a6286747f67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37846, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "地震による災害で備えて、水を用意した。", "corrected_sentence": "地震による災害に備えて、水を用意した。", "error_description": "「備える」の対象は「に」で示す。「で」は手段や場所を表すので、ここでは合わない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25a27df5-4741-4b2c-abc8-2a6286747f67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37847, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「災害の被害」と名詞をつなぎ、被害の対象を示す。"}, {"text": "を", "is_correct": false, "explanation": "「災害を被害を減らす」では目的語が二つになり不自然。"}, {"text": "に", "is_correct": false, "explanation": "「災害に被害を減らす」は意味が通らず、場所や相手の文にならない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すが、ここでは被害を減らす文に合わない。"}], "correct_answer": "の", "explanations": {"の": "「災害の被害」と名詞をつなぎ、被害の対象を示す。", "を": "「災害を被害を減らす」では目的語が二つになり不自然。", "に": "「災害に被害を減らす」は意味が通らず、場所や相手の文にならない。", "へ": "「へ」は方向を示すが、ここでは被害を減らす文に合わない。"}, "error_tags": {"を": "目的語（二重になる）", "に": "場所・相手", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25a27df5-4741-4b2c-abc8-2a6286747f67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37847, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25a27df5-4741-4b2c-abc8-2a6286747f67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37847, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "人や社会に大きな被害をもたらす、自然や人為的な出来事。", "primary_collocate": null, "pronunciation": "さいがい", "ipa": "saiɡai", "syllable_count": 4, "sentences": [{"text": "災害が発生すると、道路や電気が止まって社会が混乱する。", "target_word": "災害", "complexity_tier": "T3", "furigana": "災害[さいがい]が発生[はっせい]すると、道路[どうろ]や電気[でんき]が止[と]まって社会[しゃかい]が混乱[こんらん]する。", "sentence_source": "generated"}, {"text": "政府は災害の被害を減らすため、新しい堤防を作る計画だ。", "target_word": "災害", "complexity_tier": "T3", "furigana": "政府[せいふ]は災害[さいがい]の被害[ひがい]を減[へ]らすため、新[あたら]しい堤防[ていぼう]を作[つく]る計画[けいかく]だ。", "sentence_source": "generated"}, {"text": "大きな災害の後は、ボランティアが全国から集まった。", "target_word": "災害", "complexity_tier": "T3", "furigana": "大[おお]きな災害[さいがい]の後[あと]は、ボランティアが全国[ぜんこく]から集[あつ]まった。", "sentence_source": "generated"}, {"text": "工場の事故が原因の人為的な災害も、地域に深刻な影響を与える。", "target_word": "災害", "complexity_tier": "T3", "furigana": "工場[こうじょう]の事故[じこ]が原因[げんいん]の人為的[じんいてき]な災害[さいがい]も、地域[ちいき]に深刻[しんこく]な影響[えいきょう]を与[あた]える。", "sentence_source": "generated"}, {"text": "この地域は過去に何度も災害にみまわれてきた。", "target_word": "災害", "complexity_tier": "T3", "furigana": "この地域[ちいき]は過去[かこ]に何度[なんど]も災害[さいがい]にみまわれてきた。", "sentence_source": "generated"}, {"text": "災害の被害額は、数百億円にのぼると発表された。", "target_word": "災害", "complexity_tier": "T3", "furigana": "災害[さいがい]の被害額[ひがいがく]は、数百億円[すうひゃくおくえん]にのぼると発表[はっぴょう]された。", "sentence_source": "generated"}, {"text": "市は災害に強い町づくりを進めている。", "target_word": "災害", "complexity_tier": "T3", "furigana": "市[し]は災害[さいがい]に強[つよ]い町[まち]づくりを進[すす]めている。", "sentence_source": "generated"}, {"text": "災害時には、正確な情報を早く伝えることが大切だ。", "target_word": "災害", "complexity_tier": "T3", "furigana": "災害時[さいがいじ]には、正確[せいかく]な情報[じょうほう]を早[はや]く伝[つた]えることが大切[たいせつ]だ。", "sentence_source": "generated"}, {"text": "気候の変化で、豪雨による災害が増えているといわれる。", "target_word": "災害", "complexity_tier": "T3", "furigana": "気候[きこう]の変化[へんか]で、豪雨[ごうう]による災害[さいがい]が増[ふ]えているといわれる。", "sentence_source": "generated"}, {"text": "災害の記録を残すことは、次の世代への大切な役目だ。", "target_word": "災害", "complexity_tier": "T3", "furigana": "災害[さいがい]の記録[きろく]を残[のこ]すことは、次[つぎ]の世代[せだい]への大切[たいせつ]な役目[やくめ]だ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "災害", "label": "基本形"}], "register": "formal", "sense_fingerprint": "社会全体に大きな被害を与える自然または人為的な出来事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 4 above tier T2: contains vocabulary far above tier T2: みまわ (Zipf 1.96)']::text[], '226e73b8-df71-4110-ab40-d23c9c97d88d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37847, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "災害", "is_correct": true, "explanation": "「災害が発生する」は、社会の混乱の原因として自然に続く。"}, {"text": "挨拶", "is_correct": false, "explanation": "「挨拶が発生する」とは言わず、道路や電気が止まる原因にならない。"}, {"text": "洗濯", "is_correct": false, "explanation": "「洗濯が発生する」は不自然で、社会の混乱とつながらない。"}, {"text": "掃除", "is_correct": false, "explanation": "「掃除が発生する」は意味が通らず、インフラが止まる話と合わない。"}], "explanations": {"災害": "「災害が発生する」は、社会の混乱の原因として自然に続く。", "挨拶": "「挨拶が発生する」とは言わず、道路や電気が止まる原因にならない。", "洗濯": "「洗濯が発生する」は不自然で、社会の混乱とつながらない。", "掃除": "「掃除が発生する」は意味が通らず、インフラが止まる話と合わない。"}, "sentence_index": 0, "correct_answer": "災害"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "駅前で殴り合いの災害が起きて、警察が集まった。", "explanation": "ここは〈事件〉の意味。災害は自然や社会の大きな出来事を指し、人同士の喧嘩や犯罪には使わない。"}, {"text": "偽の電話による災害が増えている。", "explanation": "ここは〈詐欺〉の意味。災害は自然や社会の大きな出来事で、人をだます犯罪には使わない。"}, {"text": "役所で書類の災害が見つかった。", "explanation": "ここは〈不正〉の意味。災害は被害を生む大きな出来事を指し、書類のごまかしには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25a27df5-4741-4b2c-abc8-2a6286747f67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37847, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "災害", "is_correct": true, "explanation": "「災害に強い」は自然な慣用表現で、町づくりの目的に合う。"}, {"text": "手紙", "is_correct": false, "explanation": "「手紙に強い」とは言わず、町づくりの文脈に合わない。"}, {"text": "読書", "is_correct": false, "explanation": "「読書に強い町」は意味が通らず、町づくりとつながらない。"}, {"text": "教科書", "is_correct": false, "explanation": "「教科書に強い」とは言わず、町づくりの話と合わない。"}], "explanations": {"災害": "「災害に強い」は自然な慣用表現で、町づくりの目的に合う。", "手紙": "「手紙に強い」とは言わず、町づくりの文脈に合わない。", "読書": "「読書に強い町」は意味が通らず、町づくりとつながらない。", "教科書": "「教科書に強い」とは言わず、町づくりの話と合わない。"}, "sentence_index": 6, "correct_answer": "災害"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "実験の災害を記録に残して、次に生かす。", "explanation": "ここは〈失敗〉の意味。災害は多くの人や社会に大きな被害を与える出来事なので、実験の不首尾には使わない。"}, {"text": "大切な書類の災害を届け出た。", "explanation": "ここは〈紛失〉の意味。災害は自然や社会の大きな出来事を指し、書類をなくした場合には使わない。"}, {"text": "根も葉もない災害が広がった。", "explanation": "ここは〈噂〉の意味。災害は現実の大きな出来事で、根拠のない話には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25a27df5-4741-4b2c-abc8-2a6286747f67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37847, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "大雨による災害を、多くの人が避難した。", "corrected_sentence": "大雨による災害で、多くの人が避難した。", "error_description": "「災害で」は原因を表す。「災害を」だと目的語になり、「避難した」と合わず不自然。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25a27df5-4741-4b2c-abc8-2a6286747f67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37847, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "災害な記録を後世に残すことは大切だ。", "corrected_sentence": "災害の記録を後世に残すことは大切だ。", "error_description": "「災害」は名詞なので、名詞を修飾するときは「の」を使う。「な」は形容動詞につくため、ここでは誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25a27df5-4741-4b2c-abc8-2a6286747f67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37848, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「事故の記憶」では「事故」と「記憶」を結び、記憶の内容が事故であることを示す「の」が入る。"}, {"text": "を", "is_correct": false, "explanation": "「事故を記憶がない」は成り立たず、文の流れが崩れる。"}, {"text": "へ", "is_correct": false, "explanation": "「事故へ記憶がない」は方向を示すが、文の意味が通らない。"}, {"text": "や", "is_correct": false, "explanation": "並列の「や」は「事故や記憶がない」と続けても主語が立たず、意味が通らない。"}], "correct_answer": "の", "explanations": {"の": "「事故の記憶」では「事故」と「記憶」を結び、記憶の内容が事故であることを示す「の」が入る。", "を": "「事故を記憶がない」は成り立たず、文の流れが崩れる。", "へ": "「事故へ記憶がない」は方向を示すが、文の意味が通らない。", "や": "並列の「や」は「事故や記憶がない」と続けても主語が立たず、意味が通らない。"}, "error_tags": {"を": "対象", "へ": "方向", "や": "並列"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "忘却", "is_correct": true, "explanation": "覚えておくことの反対で、忘れてしまうことを表す対義語。"}, {"text": "想像", "is_correct": false, "explanation": "頭の中で思い描く意味で、記憶の対義語ではない。"}, {"text": "感覚", "is_correct": false, "explanation": "五感で感じる働きの意味で、記憶の対義語ではない。"}, {"text": "規律", "is_correct": false, "explanation": "守るべき決まりの意味で、記憶の対義語ではない。"}], "correct_answer": "忘却", "explanations": {"忘却": "覚えておくことの反対で、忘れてしまうことを表す対義語。", "想像": "頭の中で思い描く意味で、記憶の対義語ではない。", "感覚": "五感で感じる働きの意味で、記憶の対義語ではない。", "規律": "守るべき決まりの意味で、記憶の対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c79bc46-19d9-45e5-9271-8227047950b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37848, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「記憶があいまい」の「記憶」は形容詞「あいまい」の主語なので、「が」が入る。"}, {"text": "に", "is_correct": false, "explanation": "「記憶にあいまい」は成り立たず、あいまいだと感じる対象を示す形にもならない。"}, {"text": "で", "is_correct": false, "explanation": "「記憶であいまい」は理由や手段の「で」になり、「あいまい」と続くのは不自然。"}, {"text": "と", "is_correct": false, "explanation": "「記憶とあいまい」は並列の形になり、文の主語が決まらない。"}], "correct_answer": "が", "explanations": {"が": "「記憶があいまい」の「記憶」は形容詞「あいまい」の主語なので、「が」が入る。", "に": "「記憶にあいまい」は成り立たず、あいまいだと感じる対象を示す形にもならない。", "で": "「記憶であいまい」は理由や手段の「で」になり、「あいまい」と続くのは不自然。", "と": "「記憶とあいまい」は並列の形になり、文の主語が決まらない。"}, "error_tags": {"に": "方向・対象", "で": "手段・場所", "と": "並列・相手"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "忘却", "is_correct": true, "explanation": "覚えておくことの反対で、忘れてしまうことを表す対義語。"}, {"text": "思考", "is_correct": false, "explanation": "考えを巡らせる意味で、記憶の対義語ではない。"}, {"text": "判断", "is_correct": false, "explanation": "物事を見極める意味で、記憶の対義語ではない。"}, {"text": "習慣", "is_correct": false, "explanation": "繰り返して身についた行動の意味で、記憶の対義語ではない。"}], "correct_answer": "忘却", "explanations": {"忘却": "覚えておくことの反対で、忘れてしまうことを表す対義語。", "思考": "考えを巡らせる意味で、記憶の対義語ではない。", "判断": "物事を見極める意味で、記憶の対義語ではない。", "習慣": "繰り返して身についた行動の意味で、記憶の対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c79bc46-19d9-45e5-9271-8227047950b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37848, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "前に見たり聞いたりしたことを、心の中に覚えておくこと。", "primary_collocate": null, "pronunciation": "きおく", "ipa": "kioku", "syllable_count": 3, "sentences": [{"text": "子どものころの記憶は、いまでもはっきり残っている。", "target_word": "記憶", "complexity_tier": "T3", "furigana": "子[こ]どものころの記憶[きおく]は、いまでもはっきり残[のこ]っている。", "sentence_source": "generated"}, {"text": "事故の記憶がないと、彼は医者に話した。", "target_word": "記憶", "complexity_tier": "T3", "furigana": "事故[じこ]の記憶[きおく]がないと、彼[かれ]は医者[いしゃ]に話[はな]した。", "sentence_source": "generated"}, {"text": "古い写真を見ると、楽しい記憶がよみがえる。", "target_word": "記憶", "complexity_tier": "T3", "furigana": "古[ふる]い写真[しゃしん]を見[み]ると、楽[たの]しい記憶[きおく]がよみがえる。", "sentence_source": "generated"}, {"text": "私の記憶が正しければ、この店は十年前からある。", "target_word": "記憶", "complexity_tier": "T3", "furigana": "私[わたし]の記憶[きおく]が正[ただ]しければ、この店[みせ]は十年前[じゅうねんまえ]からある。", "sentence_source": "generated"}, {"text": "祖父は年をとって、最近の記憶があいまいになった。", "target_word": "記憶", "complexity_tier": "T3", "furigana": "祖父[そふ]は年[とし]をとって、最近[さいきん]の記憶[きおく]があいまいになった。", "sentence_source": "generated"}, {"text": "初めて海を見た日の記憶は、一生忘れない。", "target_word": "記憶", "complexity_tier": "T3", "furigana": "初[はじ]めて海[うみ]を見[み]た日[ひ]の記憶[きおく]は、一生[いっしょう]忘[わす]れない。", "sentence_source": "generated"}, {"text": "彼女の顔に見覚えはあるが、どこで会ったか記憶にない。", "target_word": "記憶", "complexity_tier": "T3", "furigana": "彼女[かのじょ]の顔[かお]に見覚[みおぼ]えはあるが、どこで会[あ]ったか記憶[きおく]にない。", "sentence_source": "generated"}, {"text": "記憶があいまいなので、日付は確かではありません。", "target_word": "記憶", "complexity_tier": "T3", "furigana": "記憶[きおく]があいまいなので、日付[ひづけ]は確[たし]かではありません。", "sentence_source": "generated"}, {"text": "旅行の記憶を、日記に書いて残している。", "target_word": "記憶", "complexity_tier": "T3", "furigana": "旅行[りょこう]の記憶[きおく]を、日記[にっき]に書[か]いて残[のこ]している。", "sentence_source": "generated"}, {"text": "悲しい記憶を、無理に思い出さなくてもいい。", "target_word": "記憶", "complexity_tier": "T3", "furigana": "悲[かな]しい記憶[きおく]を、無理[むり]に思[おも]い出[だ]さなくてもいい。", "sentence_source": "generated"}], "morphological_forms": [{"form": "記憶", "label": "基本形"}, {"form": "記憶する", "label": "サ変動詞形"}, {"form": "記憶した", "label": "過去形"}], "register": "中立", "sense_fingerprint": "経験したことを心に覚えておくこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '725786b7-83d1-4185-8797-adecf4153e68') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37848, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "記憶", "is_correct": true, "explanation": "子どものころの出来事が残っているという文の意味に合う正解。"}, {"text": "規則", "is_correct": false, "explanation": "決まりの意味で、子どものころの出来事が残っているという文に合わない。"}, {"text": "責任", "is_correct": false, "explanation": "引き受けるべき義務の意味で、残っているという文に合わない。"}, {"text": "注意", "is_correct": false, "explanation": "気を配る意味で、思い出として残っているという文に合わない。"}], "explanations": {"記憶": "子どものころの出来事が残っているという文の意味に合う正解。", "規則": "決まりの意味で、子どものころの出来事が残っているという文に合わない。", "責任": "引き受けるべき義務の意味で、残っているという文に合わない。", "注意": "気を配る意味で、思い出として残っているという文に合わない。"}, "sentence_index": 0, "correct_answer": "記憶"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "市役所で、祖父の住所の記憶を取り寄せた。", "explanation": "ここは〈記録〉の意味。書類として残された情報の話で、覚えておくことの意味ではないので合わない。"}, {"text": "彼は鋭い記憶で、遠くの足音を聞き分けた。", "explanation": "ここは〈感覚〉の意味。耳の鋭さで聞き分けるのは感覚の働きで、覚えておく記憶の意味とは合わない。"}, {"text": "彼はテストの点数を、記憶に書いてノートに貼った。", "explanation": "記憶は心の中で覚えておくことで、紙に書き留めるのは〈記録〉の仕事なので、この文では合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c79bc46-19d9-45e5-9271-8227047950b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37848, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "記憶", "is_correct": true, "explanation": "「どこで会ったか記憶にない」と、覚えていないことを表す正解。"}, {"text": "感情", "is_correct": false, "explanation": "心の動きの意味で、「感情にない」とは言わず、文が成り立たない。"}, {"text": "予感", "is_correct": false, "explanation": "前もって感じることの意味で、「予感にない」では文が成り立たない。"}, {"text": "食欲", "is_correct": false, "explanation": "食べたい気持ちの意味で、「食欲にない」では文が成り立たない。"}], "explanations": {"記憶": "「どこで会ったか記憶にない」と、覚えていないことを表す正解。", "感情": "心の動きの意味で、「感情にない」とは言わず、文が成り立たない。", "予感": "前もって感じることの意味で、「予感にない」では文が成り立たない。", "食欲": "食べたい気持ちの意味で、「食欲にない」では文が成り立たない。"}, "sentence_index": 6, "correct_answer": "記憶"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "体温を測ったら、記憶が三十八度もあった。", "explanation": "ここは〈熱〉の意味。体温の数値を言う場面で記憶は使わないので、この文では合わない。"}, {"text": "祖父は味の記憶を塩辛くして、料理を出した。", "explanation": "ここは〈味付け〉の意味。記憶は覚えておく働きなので、料理の味を変える場面では使わない。"}, {"text": "彼は床の上の記憶を、掃除機で吸い取った。", "explanation": "ここは〈ゴミ・ほこり〉の意味。記憶は形のない覚えておく働きなので、掃除機で吸い取るゴミとは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c79bc46-19d9-45e5-9271-8227047950b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37848, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "祖父は、昔の記憶に大切にしている。", "corrected_sentence": "祖父は、昔の記憶を大切にしている。", "error_description": "誤りは「記憶に」。「大切にする」は目的語に「を」を取るので、正しくは「記憶を」。「に」は対象や方向のニュアンスになり、この形では合わない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c79bc46-19d9-45e5-9271-8227047950b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37848, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "私は、昨夜の出来事を記憶ている。", "corrected_sentence": "私は、昨夜の出来事を記憶している。", "error_description": "誤りは「記憶ている」。「記憶」は名詞なので、「ている」を続けるには「している」と動詞化する必要がある。「記憶ている」は文法として成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c79bc46-19d9-45e5-9271-8227047950b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37850, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "正解。「過去の失敗」で、後ろの「失敗」を修飾する。"}, {"text": "が", "is_correct": false, "explanation": "「過去が失敗から学んだ」では過去が主語になり、学ぶ主体と合わない。"}, {"text": "で", "is_correct": false, "explanation": "「過去で失敗から」は場所や手段の意味になり、名詞をつなげない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表すが、「過去へ失敗から」では名詞をつなげず、意味が通らない。"}], "correct_answer": "の", "explanations": {"の": "正解。「過去の失敗」で、後ろの「失敗」を修飾する。", "が": "「過去が失敗から学んだ」では過去が主語になり、学ぶ主体と合わない。", "で": "「過去で失敗から」は場所や手段の意味になり、名詞をつなげない。", "へ": "方向を表すが、「過去へ失敗から」では名詞をつなげず、意味が通らない。"}, "error_tags": {"が": "主語の誤り", "で": "手段・場所の誤り", "へ": "方向の誤り"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "未来", "is_correct": true, "explanation": "正解。すぎ去った時を表す語の対義語で、これから来る時を指す。"}, {"text": "昼", "is_correct": false, "explanation": "時間の区切りを表すが、過去の対義語ではない。"}, {"text": "週末", "is_correct": false, "explanation": "曜日の一つで、過去と対になる語ではない。"}, {"text": "深夜", "is_correct": false, "explanation": "夜の時間帯を表すが、過去の対義語ではない。"}], "correct_answer": "未来", "explanations": {"未来": "正解。すぎ去った時を表す語の対義語で、これから来る時を指す。", "昼": "時間の区切りを表すが、過去の対義語ではない。", "週末": "曜日の一つで、過去と対になる語ではない。", "深夜": "夜の時間帯を表すが、過去の対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39b77179-de73-4edd-b945-3cf1952683bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37850, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "正解。「過去に起きたことを」で時点を示し、「起きた」につながる。"}, {"text": "を", "is_correct": false, "explanation": "「起きる」は自動詞なので目的語の「を」を取らず、「過去を起きた」は成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "比較を表すが、「過去より起きた」は比べる対象がなく、意味が通らない。"}, {"text": "で", "is_correct": false, "explanation": "「過去で起きたこと」では過去を場所や手段のように扱うことになり、時期を表せない。"}], "correct_answer": "に", "explanations": {"に": "正解。「過去に起きたことを」で時点を示し、「起きた」につながる。", "を": "「起きる」は自動詞なので目的語の「を」を取らず、「過去を起きた」は成り立たない。", "より": "比較を表すが、「過去より起きた」は比べる対象がなく、意味が通らない。", "で": "「過去で起きたこと」では過去を場所や手段のように扱うことになり、時期を表せない。"}, "error_tags": {"を": "自動詞の目的語の誤り", "より": "比較の誤り", "で": "手段・場所の誤り"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "未来", "is_correct": true, "explanation": "正解。すぎ去った時を表す語の対義語で、これから来る時を指す。"}, {"text": "朝", "is_correct": false, "explanation": "時間帯を表すが、過去の対義語ではない。"}, {"text": "夕方", "is_correct": false, "explanation": "時間帯を表すが、過去と対になる語ではない。"}, {"text": "冬", "is_correct": false, "explanation": "季節を表すが、過去の対義語ではない。"}], "correct_answer": "未来", "explanations": {"未来": "正解。すぎ去った時を表す語の対義語で、これから来る時を指す。", "朝": "時間帯を表すが、過去の対義語ではない。", "夕方": "時間帯を表すが、過去と対になる語ではない。", "冬": "季節を表すが、過去の対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39b77179-de73-4edd-b945-3cf1952683bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37850, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "前にあった時間のこと。", "primary_collocate": null, "pronunciation": "かこ", "ipa": "kako", "syllable_count": 2, "sentences": [{"text": "過去は変えられませんが、未来は自分で作れます。", "target_word": "過去", "complexity_tier": "T3", "furigana": "過去[かこ]は変[か]えられませんが、未来[みらい]は自分[じぶん]で作[つく]れます。", "sentence_source": "generated"}, {"text": "彼は過去の失敗から多くのことを学びました。", "target_word": "過去", "complexity_tier": "T3", "furigana": "彼[かれ]は過去[かこ]の失敗[しっぱい]から多[おお]くのことを学[まな]びました。", "sentence_source": "generated"}, {"text": "過去にこの町で大きな地震があったと聞きました。", "target_word": "過去", "complexity_tier": "T3", "furigana": "過去[かこ]にこの町[まち]で大[おお]きな地震[じしん]があったと聞[き]きました。", "sentence_source": "generated"}, {"text": "昔の写真を見ると、過去の思い出がよみがえります。", "target_word": "過去", "complexity_tier": "T3", "furigana": "昔[むかし]の写真[しゃしん]を見[み]ると、過去[かこ]の思[おも]い出[で]がよみがえります。", "sentence_source": "generated"}, {"text": "過去を忘れて、新しい生活を始めたいです。", "target_word": "過去", "complexity_tier": "T3", "furigana": "過去[かこ]を忘[わす]れて、新[あたら]しい生活[せいかつ]を始[はじ]めたいです。", "sentence_source": "generated"}, {"text": "博物館では、過去の人々の暮らしを知ることができます。", "target_word": "過去", "complexity_tier": "T3", "furigana": "博物館[はくぶつかん]では、過去[かこ]の人々[ひとびと]の暮[く]らしを知[し]ることができます。", "sentence_source": "generated"}, {"text": "過去には、この川で泳ぐ子どもがたくさんいました。", "target_word": "過去", "complexity_tier": "T3", "furigana": "過去[かこ]には、この川[かわ]で泳[およ]ぐ子[こ]どもがたくさんいました。", "sentence_source": "generated"}, {"text": "歴史は、過去に起きたことを調べる学問です。", "target_word": "過去", "complexity_tier": "T3", "furigana": "歴史[れきし]は、過去[かこ]に起[お]きたことを調[しら]べる学問[がくもん]です。", "sentence_source": "generated"}, {"text": "過去と現在を比べると、町はずいぶん変わりました。", "target_word": "過去", "complexity_tier": "T3", "furigana": "過去[かこ]と現在[げんざい]を比[くら]べると、町[まち]はずいぶん変[か]わりました。", "sentence_source": "generated"}, {"text": "彼女は過去のことを話したがらないので、私は聞きませんでした。", "target_word": "過去", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は過去[かこ]のことを話[はな]したがらないので、私[わたし]は聞[き]きませんでした。", "sentence_source": "generated"}], "morphological_forms": [{"form": "過去", "label": "基本形"}], "register": "丁寧（です・ます体）", "sense_fingerprint": "現在より前の時間、すでに過ぎた時", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c24002b6-c864-4b47-b0ab-4d78dc52710d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37850, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "過去", "is_correct": true, "explanation": "正解。すぎた時間を指し、「変えられない」の主語になる。"}, {"text": "窓", "is_correct": false, "explanation": "物なので、すぎた時間の意味とは合わない。「窓は変えられない」も対比として成り立たない。"}, {"text": "机", "is_correct": false, "explanation": "家具で、時間を表さない。「変えられませんが、未来は」の対比の主題にならない。"}, {"text": "階段", "is_correct": false, "explanation": "建物の一部で、時間を指さない。文の主題として対比が成り立たない。"}], "explanations": {"過去": "正解。すぎた時間を指し、「変えられない」の主語になる。", "窓": "物なので、すぎた時間の意味とは合わない。「窓は変えられない」も対比として成り立たない。", "机": "家具で、時間を表さない。「変えられませんが、未来は」の対比の主題にならない。", "階段": "建物の一部で、時間を指さない。文の主題として対比が成り立たない。"}, "sentence_index": 0, "correct_answer": "過去"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "過去は医者になりたいと、子どものころから思っている。", "explanation": "ここは〈将来〉の意味。これから先の夢や予定を表すので、すぎ去った時間の過去とは合わない。"}, {"text": "過去は毎朝この道を歩いて通勤していた。", "explanation": "ここは〈昔〉の意味。昔は時を示す語として習慣の時期を表せるが、過去は人の通勤の主語にはならないので合わない。"}, {"text": "過去は、もっと練習しようと思う。", "explanation": "ここは〈今後〉の意味。これからの計画を表すので、すぎた時間の過去とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39b77179-de73-4edd-b945-3cf1952683bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37850, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "過去", "is_correct": true, "explanation": "正解。すぎた時期を指し、「には」で時点を示す。"}, {"text": "機械", "is_correct": false, "explanation": "機械は時期を示さず、「この川で泳ぐ子どもがいた」と結びつかない。"}, {"text": "宝石", "is_correct": false, "explanation": "時期を指さない物で、この川で子どもが泳いでいた場面とは結びつかない。"}, {"text": "郵便局", "is_correct": false, "explanation": "場所を表すので、ここでは時期の説明にならない。"}], "explanations": {"過去": "正解。すぎた時期を指し、「には」で時点を示す。", "機械": "機械は時期を示さず、「この川で泳ぐ子どもがいた」と結びつかない。", "宝石": "時期を指さない物で、この川で子どもが泳いでいた場面とは結びつかない。", "郵便局": "場所を表すので、ここでは時期の説明にならない。"}, "sentence_index": 6, "correct_answer": "過去"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "過去は毎晩、母が本を読んでくれた。", "explanation": "ここは〈以前〉の意味。以前は時を示す語として習慣の時期を表せるが、過去は人の行為の主語にはならないので合わない。"}, {"text": "過去は失礼しました。", "explanation": "ここは〈先ほど〉の意味。先ほどは直前のできごとを指すが、過去は昔のことを指す名詞で、謝罪の場面には合わない。"}, {"text": "過去は仕事が忙しい。", "explanation": "ここは〈最近〉の意味。最近は今に近い時期を指して現在の状態を述べるが、過去は今の状況の説明にはならないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39b77179-de73-4edd-b945-3cf1952683bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37850, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼女の過去を話は、誰も知らない。", "corrected_sentence": "彼女の過去の話は、誰も知らない。", "error_description": "『過去の話』の『の』は名詞をつなぐ。『過去を話』とすると『を』が名詞に付き、動詞の目的語にならず文が成り立たない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39b77179-de73-4edd-b945-3cf1952683bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37850, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "過去が経験が、今の仕事に役立っている。", "corrected_sentence": "過去の経験が、今の仕事に役立っている。", "error_description": "『過去の経験』の『の』は名詞をつなぐ。『過去が』とすると『が』が重なって主語が二つになり、文が成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39b77179-de73-4edd-b945-3cf1952683bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37851, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "正解。「過去は変えられない」と主題を示し、後ろの「変えられない」につながる。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表すが、「過去へ変えられない」は動詞と噛み合わず、意味が通らない。"}, {"text": "で", "is_correct": false, "explanation": "手段や場所を表すが、「過去で変えられない」は主題を示せず、文が成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "並列や相手を表すが、「過去と変えられない」は主題にならず、対比の文が成り立たない。"}], "correct_answer": "は", "explanations": {"は": "正解。「過去は変えられない」と主題を示し、後ろの「変えられない」につながる。", "へ": "方向を表すが、「過去へ変えられない」は動詞と噛み合わず、意味が通らない。", "で": "手段や場所を表すが、「過去で変えられない」は主題を示せず、文が成り立たない。", "と": "並列や相手を表すが、「過去と変えられない」は主題にならず、対比の文が成り立たない。"}, "error_tags": {"へ": "方向の誤り", "で": "手段・場所の誤り", "と": "並列の誤り"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "未来", "is_correct": true, "explanation": "正解。すぎ去った時を表す語の対義語で、これから来る時を指す。"}, {"text": "朝", "is_correct": false, "explanation": "時間帯を表すが、過去の対義語ではない。"}, {"text": "夕方", "is_correct": false, "explanation": "時間帯を表すが、過去と対になる語ではない。"}, {"text": "週末", "is_correct": false, "explanation": "曜日の一つで、過去の対義語ではない。"}], "correct_answer": "未来", "explanations": {"未来": "正解。すぎ去った時を表す語の対義語で、これから来る時を指す。", "朝": "時間帯を表すが、過去の対義語ではない。", "夕方": "時間帯を表すが、過去と対になる語ではない。", "週末": "曜日の一つで、過去の対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39b77179-de73-4edd-b945-3cf1952683bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37851, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "正解。「過去に」で時点を示し、「何があった」へつながる。"}, {"text": "を", "is_correct": false, "explanation": "「あった」は目的語を取らないので、「過去を何があった」は文が成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "比較を表すが、「過去より何があった」は比べる相手がなく、意味が通らない。"}, {"text": "の", "is_correct": false, "explanation": "名詞をつなぐが、「過去の何があった」は『何』が指すものが定まらず、自然な文にならない。"}], "correct_answer": "に", "explanations": {"に": "正解。「過去に」で時点を示し、「何があった」へつながる。", "を": "「あった」は目的語を取らないので、「過去を何があった」は文が成り立たない。", "より": "比較を表すが、「過去より何があった」は比べる相手がなく、意味が通らない。", "の": "名詞をつなぐが、「過去の何があった」は『何』が指すものが定まらず、自然な文にならない。"}, "error_tags": {"を": "目的語の誤り", "より": "比較の誤り", "の": "修飾の誤り"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "未来", "is_correct": true, "explanation": "正解。すぎ去った時を表す語の対義語で、これから来る時を指す。"}, {"text": "春", "is_correct": false, "explanation": "季節を表すが、過去の対義語ではない。"}, {"text": "冬", "is_correct": false, "explanation": "季節を表すが、過去と対になる語ではない。"}, {"text": "雪", "is_correct": false, "explanation": "天気の現象で、時間の対義語ではない。"}], "correct_answer": "未来", "explanations": {"未来": "正解。すぎ去った時を表す語の対義語で、これから来る時を指す。", "春": "季節を表すが、過去の対義語ではない。", "冬": "季節を表すが、過去と対になる語ではない。", "雪": "天気の現象で、時間の対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39b77179-de73-4edd-b945-3cf1952683bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37851, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "今より前の時。すでに過ぎ去った時間やできごと。", "primary_collocate": null, "pronunciation": "かこ", "ipa": "kako", "syllable_count": 2, "sentences": [{"text": "彼は過去の失敗から学んで、同じ間違いをしなくなった。", "target_word": "過去", "complexity_tier": "T3", "furigana": "彼(かれ)は過去(かこ)の失敗(しっぱい)から学(まな)んで、同(おな)じ間違(まちが)いをしなくなった。", "sentence_source": "generated"}, {"text": "過去は変えられないが、未来は自分で作ることができる。", "target_word": "過去", "complexity_tier": "T3", "furigana": "過去(かこ)は変(か)えられないが、未来(みらい)は自分(じぶん)で作(つく)ることができる。", "sentence_source": "generated"}, {"text": "この町には、過去に大きな地震があったという記録が残っている。", "target_word": "過去", "complexity_tier": "T3", "furigana": "この町(まち)には、過去(かこ)に大(おお)きな地震(じしん)があったという記録(きろく)が残(のこ)っている。", "sentence_source": "generated"}, {"text": "彼女は自分の過去について、友達にもほとんど話さない。", "target_word": "過去", "complexity_tier": "T3", "furigana": "彼女(かのじょ)は自分(じぶん)の過去(かこ)について、友達(ともだち)にもほとんど話(はな)さない。", "sentence_source": "generated"}, {"text": "過去の写真を見ていたら、子どものころが懐かしくなった。", "target_word": "過去", "complexity_tier": "T3", "furigana": "過去(かこ)の写真(しゃしん)を見(み)ていたら、子(こ)どものころが懐(なつ)かしくなった。", "sentence_source": "generated"}, {"text": "過去を忘れたいと思っても、簡単には忘れられない。", "target_word": "過去", "complexity_tier": "T3", "furigana": "過去(かこ)を忘(わす)れたいと思(おも)っても、簡単(かんたん)には忘(わす)れられない。", "sentence_source": "generated"}, {"text": "この古い手紙は、祖父の過去を知るための大切な手がかりだ。", "target_word": "過去", "complexity_tier": "T3", "furigana": "この古(ふる)い手紙(てがみ)は、祖父(そふ)の過去(かこ)を知(し)るための大切(たいせつ)な手(て)がかりだ。", "sentence_source": "generated"}, {"text": "過去に何があったとしても、今の君を信じている。", "target_word": "過去", "complexity_tier": "T3", "furigana": "過去(かこ)に何(なに)があったとしても、今(いま)の君(きみ)を信(しん)じている。", "sentence_source": "generated"}, {"text": "先生は過去の試験の問題を使って、練習させてくれた。", "target_word": "過去", "complexity_tier": "T3", "furigana": "先生(せんせい)は過去(かこ)の試験(しけん)の問題(もんだい)を使(つか)って、練習(れんしゅう)させてくれた。", "sentence_source": "generated"}, {"text": "過去と現在を比べると、この町はずいぶん静かになった。", "target_word": "過去", "complexity_tier": "T3", "furigana": "過去(かこ)と現在(げんざい)を比(くら)べると、この町(まち)はずいぶん静(しず)かになった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "過去", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "現在より前に過ぎ去った時間やできごと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c24002b6-c864-4b47-b0ab-4d78dc52710d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37851, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "過去", "is_correct": true, "explanation": "正解。すぎ去ったできごとを指し、「の失敗」を修飾して「から学ぶ」の対象になる。"}, {"text": "天気", "is_correct": false, "explanation": "「天気の失敗」は意味が通らず、学びの対象にならない。"}, {"text": "眼鏡", "is_correct": false, "explanation": "物なので、「眼鏡の失敗」は学びの対象として成り立たない。"}, {"text": "階段", "is_correct": false, "explanation": "建物の一部で、「階段の失敗」は意味が通らない。"}], "explanations": {"過去": "正解。すぎ去ったできごとを指し、「の失敗」を修飾して「から学ぶ」の対象になる。", "天気": "「天気の失敗」は意味が通らず、学びの対象にならない。", "眼鏡": "物なので、「眼鏡の失敗」は学びの対象として成り立たない。", "階段": "建物の一部で、「階段の失敗」は意味が通らない。"}, "sentence_index": 0, "correct_answer": "過去"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "過去は雨が降るでしょうから、傘を持って行きましょう。", "explanation": "ここは〈明日〉の意味。これから来る日の予想に使うので、すぎ去った時間の過去とは合わない。"}, {"text": "過去は毎朝この道を通って学校に行った。", "explanation": "ここは〈昔〉の意味。昔は時を示す語として習慣の時期を表せるが、過去は人の通学の主語にはならないので合わない。"}, {"text": "過去は、もっと丁寧に説明するようにします。", "explanation": "ここは〈今後〉の意味。これからの方針を表すので、すぎた時間の過去とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39b77179-de73-4edd-b945-3cf1952683bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37851, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "過去", "is_correct": true, "explanation": "正解。祖父のすぎた時間や経歴を指し、「を知る」の目的語になる。"}, {"text": "雨", "is_correct": false, "explanation": "天気の現象で、人の経歴を指さない。「祖父の雨を知る」は意味が通らない。"}, {"text": "窓", "is_correct": false, "explanation": "物で、祖父の経歴を表す語にならない。文の目的語として成り立たない。"}, {"text": "鍋", "is_correct": false, "explanation": "調理器具で、祖父の経歴を表さない。「知るための手がかり」とも結びつかない。"}], "explanations": {"過去": "正解。祖父のすぎた時間や経歴を指し、「を知る」の目的語になる。", "雨": "天気の現象で、人の経歴を指さない。「祖父の雨を知る」は意味が通らない。", "窓": "物で、祖父の経歴を表す語にならない。文の目的語として成り立たない。", "鍋": "調理器具で、祖父の経歴を表さない。「知るための手がかり」とも結びつかない。"}, "sentence_index": 6, "correct_answer": "過去"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "過去は毎朝、父と一緒に散歩をした。", "explanation": "ここは〈以前〉の意味。以前は時を示す語として習慣の時期を表せるが、過去は人の行為の主語にはならないので合わない。"}, {"text": "過去は、遅れてすみませんでした。", "explanation": "ここは〈先ほど〉の意味。先ほどは直前のできごとを指すが、過去は昔のことを指す名詞で、謝罪の場面には合わない。"}, {"text": "過去は、この店が混んでいる。", "explanation": "ここは〈最近〉の意味。最近は今に近い時期を指して現在の状態を述べるが、過去は今の状況の説明にはならないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39b77179-de73-4edd-b945-3cf1952683bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37851, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "過去で起きた出来事を、町の記録で調べた。", "corrected_sentence": "過去に起きた出来事を、町の記録で調べた。", "error_description": "『過去に起きた』の『に』は時点を表す。『過去で』とすると場所や手段の意味になり、時間を指せない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39b77179-de73-4edd-b945-3cf1952683bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37851, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "過去が災害について、町の記録を読んだ。", "corrected_sentence": "過去の災害について、町の記録を読んだ。", "error_description": "『過去の災害』の『の』は名詞をつなぐ。『過去が』とすると、『過去』が『災害』の主語のようになり、文の成り立ちが崩れる。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39b77179-de73-4edd-b945-3cf1952683bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37852, 3, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e589b8e-9cc9-489a-8888-642aa7b09f4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37852, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "正解。「絆が強くなった」の「が」で、変化する主体（絆）を示す。"}, {"text": "を", "is_correct": false, "explanation": "「絆をいっそう強くなった」は、強くなるの主語にならず不自然。"}, {"text": "と", "is_correct": false, "explanation": "「絆と強くなった」は並列や相手を示す形になり、強くなる主語にはならない。"}, {"text": "へ", "is_correct": false, "explanation": "「絆へいっそう強くなった」は方向を示すが、強くなる主語にならない。"}], "correct_answer": "が", "explanations": {"が": "正解。「絆が強くなった」の「が」で、変化する主体（絆）を示す。", "を": "「絆をいっそう強くなった」は、強くなるの主語にならず不自然。", "と": "「絆と強くなった」は並列や相手を示す形になり、強くなる主語にはならない。", "へ": "「絆へいっそう強くなった」は方向を示すが、強くなる主語にならない。"}, "error_tags": {"を": "目的語を示すが、ここは主語", "と": "並列・相手を示す", "へ": "方向を示す"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e589b8e-9cc9-489a-8888-642aa7b09f4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37852, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "人と人の間にある、心と心のつながり。", "primary_collocate": null, "pronunciation": "きずな", "ipa": "kizɯna", "syllable_count": 3, "sentences": [{"text": "長い間いっしょに働いて、仲間との絆が深まった。", "target_word": "絆", "complexity_tier": "T3", "furigana": "長(なが)い間(あいだ)いっしょに働(はたら)いて、仲間(なかま)との絆(きずな)が深(ふか)まった。", "sentence_source": "generated"}, {"text": "私たち家族の絆は、何があっても変わらない。", "target_word": "絆", "complexity_tier": "T3", "furigana": "私(わたし)たち家族(かぞく)の絆(きずな)は、何(なに)があっても変(か)わらない。", "sentence_source": "generated"}, {"text": "手紙のやりとりを通して、二人の心の絆が生まれた。", "target_word": "絆", "complexity_tier": "T3", "furigana": "手紙(てがみ)のやりとりを通(とお)して、二人(ふたり)の心(こころ)の絆(きずな)が生(う)まれた。", "sentence_source": "generated"}, {"text": "母と娘の絆を感じて、思わず涙が出た。", "target_word": "絆", "complexity_tier": "T3", "furigana": "母(はは)と娘(むすめ)の絆(きずな)を感(かん)じて、思(おも)わず涙(なみだ)が出(で)た。", "sentence_source": "generated"}, {"text": "先生と生徒の間に、信頼という絆ができた。", "target_word": "絆", "complexity_tier": "T3", "furigana": "先生(せんせい)と生徒(せいと)の間(あいだ)に、信頼(しんらい)という絆(きずな)ができた。", "sentence_source": "generated"}, {"text": "遠くに住んでいても、友だちとの絆は消えない。", "target_word": "絆", "complexity_tier": "T3", "furigana": "遠(とお)くに住(す)んでいても、友(とも)だちとの絆(きずな)は消(き)えない。", "sentence_source": "generated"}, {"text": "祖父との絆を大切にして、毎週電話をしている。", "target_word": "絆", "complexity_tier": "T3", "furigana": "祖父(そふ)との絆(きずな)を大切(たいせつ)にして、毎週(まいしゅう)電話(でんわ)をしている。", "sentence_source": "generated"}, {"text": "震災のあと、町の人々の絆がいっそう強くなった。", "target_word": "絆", "complexity_tier": "T3", "furigana": "震災(しんさい)のあと、町(まち)の人々(ひとびと)の絆(きずな)がいっそう強(つよ)くなった。", "sentence_source": "generated"}, {"text": "犬を飼い始めてから、子どもと動物の間に温かい絆が育った。", "target_word": "絆", "complexity_tier": "T3", "furigana": "犬(いぬ)を飼(か)い始(はじ)めてから、子(こ)どもと動物(どうぶつ)の間(あいだ)に温(あたた)かい絆(きずな)が育(そだ)った。", "sentence_source": "generated"}, {"text": "絆を深めるために、チーム全員で食事に行った。", "target_word": "絆", "complexity_tier": "T3", "furigana": "絆(きずな)を深(ふか)めるために、チーム全員(ぜんいん)で食事(しょくじ)に行(い)った。", "sentence_source": "generated"}], "morphological_forms": [{"form": "絆", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "人と人の心のつながり、信頼や愛情で結ばれた関係", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '93788fa0-f2a6-402a-8dac-82f8c6817f01') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37852, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "絆", "is_correct": true, "explanation": "正解。「仲間との絆が深まる」の意味で、人の心のつながりを表し文意に合う。"}, {"text": "距離", "is_correct": false, "explanation": "「距離が深まった」は離れ具合が増す意味になり、仲が深まるという文脈と逆になる。"}, {"text": "温度", "is_correct": false, "explanation": "「温度が深まった」は言葉として不自然で、人との関係を表せない。"}, {"text": "証拠", "is_correct": false, "explanation": "「証拠が深まった」は文脈に合わず、仲間との関係を表せない。"}], "explanations": {"絆": "正解。「仲間との絆が深まる」の意味で、人の心のつながりを表し文意に合う。", "距離": "「距離が深まった」は離れ具合が増す意味になり、仲が深まるという文脈と逆になる。", "温度": "「温度が深まった」は言葉として不自然で、人との関係を表せない。", "証拠": "「証拠が深まった」は文脈に合わず、仲間との関係を表せない。"}, "sentence_index": 0, "correct_answer": "絆"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "二人は夜空に絆を打ち上げた。", "explanation": "絆は人のつながりなので、夜空に打ち上げるものではない。"}, {"text": "転んでひざにできた傷に、絆を貼った。", "explanation": "絆は人のつながりで、傷に貼るものではない。"}, {"text": "彼は父親としての絆を果たした。", "explanation": "絆は人との結びつきで、務めのように果たすものではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e589b8e-9cc9-489a-8888-642aa7b09f4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37852, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "絆", "is_correct": true, "explanation": "正解。「祖父との絆を大切にする」の意味で、人との関係を表し文意に合う。"}, {"text": "天井", "is_correct": false, "explanation": "「祖父との天井」は意味が通らず、大切にする対象にならない。"}, {"text": "年齢", "is_correct": false, "explanation": "「祖父との年齢」は意味が通らず、大切にする対象として不自然。"}, {"text": "天気", "is_correct": false, "explanation": "「祖父との天気」は意味が通らず、大切にする対象にならない。"}], "explanations": {"絆": "正解。「祖父との絆を大切にする」の意味で、人との関係を表し文意に合う。", "天井": "「祖父との天井」は意味が通らず、大切にする対象にならない。", "年齢": "「祖父との年齢」は意味が通らず、大切にする対象として不自然。", "天気": "「祖父との天気」は意味が通らず、大切にする対象にならない。"}, "sentence_index": 6, "correct_answer": "絆"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "チームは絆を達成するために、全員で食事に行った。", "explanation": "絆は人のつながりで、達成する目標にはならない。"}, {"text": "その選手は、大会で絆を更新した。", "explanation": "絆は数値ではないので、記録のように更新する対象にはならない。"}, {"text": "正月に、家族全員へ絆を出した。", "explanation": "絆は人のつながりで、年賀状のように出せるものではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e589b8e-9cc9-489a-8888-642aa7b09f4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37852, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "故郷の仲間へ絆を大切にして、毎年集まっている。", "corrected_sentence": "故郷の仲間との絆を大切にして、毎年集まっている。", "error_description": "「〜との絆」の形で関係の相手を示すのは「と」。「へ」は方向を示すので、「〜との絆」の形に合わない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e589b8e-9cc9-489a-8888-642aa7b09f4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37852, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "ふるさとの人々との絆を、今も大切にしてている。", "corrected_sentence": "ふるさとの人々との絆を、今も大切にしている。", "error_description": "「大切にしている」の「している」が正しい。「してている」は「している」の重複で、活用の誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e589b8e-9cc9-489a-8888-642aa7b09f4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
