INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37853, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "正解。「絆は揺るがなかった」で、絆を主題として示す。"}, {"text": "を", "is_correct": false, "explanation": "「絆を揺るがなかった」は、揺るがないという動詞が目的語を取らないため不自然。"}, {"text": "に", "is_correct": false, "explanation": "「絆に揺るがなかった」は対象を示す形にならず不自然。"}, {"text": "と", "is_correct": false, "explanation": "「絆と揺るがなかった」は並列や相手を示す形になり、揺るがない主語にはならない。"}], "correct_answer": "は", "explanations": {"は": "正解。「絆は揺るがなかった」で、絆を主題として示す。", "を": "「絆を揺るがなかった」は、揺るがないという動詞が目的語を取らないため不自然。", "に": "「絆に揺るがなかった」は対象を示す形にならず不自然。", "と": "「絆と揺るがなかった」は並列や相手を示す形になり、揺るがない主語にはならない。"}, "error_tags": {"を": "目的語を示すが、揺るがないは目的語を取らない", "と": "並列・相手を示す", "に": "対象を示す形にならない"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e589b8e-9cc9-489a-8888-642aa7b09f4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37853, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "人と人との間の強い結びつきや、離れがたい関係。", "primary_collocate": null, "pronunciation": "きずな", "ipa": "kizɯna", "syllable_count": 3, "sentences": [{"text": "兄弟の絆は強く、けんかをしてもすぐ仲直りする。", "target_word": "絆", "complexity_tier": "T3", "furigana": "兄弟(きょうだい)の絆(きずな)は強(つよ)く、けんかをしてもすぐ仲直(なかなお)りする。", "sentence_source": "generated"}, {"text": "戦争で離ればなれになっても、親子の絆は切れなかった。", "target_word": "絆", "complexity_tier": "T3", "furigana": "戦争(せんそう)で離(はな)ればなれになっても、親子(おやこ)の絆(きずな)は切(き)れなかった。", "sentence_source": "generated"}, {"text": "彼らは何十年も続く固い絆で結ばれている。", "target_word": "絆", "complexity_tier": "T3", "furigana": "彼(かれ)らは何十年(なんじゅうねん)も続(つづ)く固(かた)い絆(きずな)で結(むす)ばれている。", "sentence_source": "generated"}, {"text": "離れがたい絆があるから、二人は別々の道を選べなかった。", "target_word": "絆", "complexity_tier": "T3", "furigana": "離(はな)れがたい絆(きずな)があるから、二人(ふたり)は別々(べつべつ)の道(みち)を選(えら)べなかった。", "sentence_source": "generated"}, {"text": "長年の苦労をともにした仲間の絆は、簡単には壊れない。", "target_word": "絆", "complexity_tier": "T3", "furigana": "長年(ながねん)の苦労(くろう)をともにした仲間(なかま)の絆(きずな)は、簡単(かんたん)には壊(こわ)れない。", "sentence_source": "generated"}, {"text": "結婚して三十年、夫婦の絆はますます強くなった。", "target_word": "絆", "complexity_tier": "T3", "furigana": "結婚(けっこん)して三十年(さんじゅうねん)、夫婦(ふうふ)の絆(きずな)はますます強(つよ)くなった。", "sentence_source": "generated"}, {"text": "彼女は故郷との絆を断ち切れず、また町に戻ってきた。", "target_word": "絆", "complexity_tier": "T3", "furigana": "彼女(かのじょ)は故郷(こきょう)との絆(きずな)を断(た)ち切(き)れず、また町(まち)に戻(もど)ってきた。", "sentence_source": "generated"}, {"text": "試合に負けても、チームの絆は揺るがなかった。", "target_word": "絆", "complexity_tier": "T3", "furigana": "試合(しあい)に負(ま)けても、チームの絆(きずな)は揺(ゆ)るがなかった。", "sentence_source": "generated"}, {"text": "双子の姉妹には、他の人にはわからない特別な絆がある。", "target_word": "絆", "complexity_tier": "T3", "furigana": "双子(ふたご)の姉妹(しまい)には、他(ほか)の人(ひと)にはわからない特別(とくべつ)な絆(きずな)がある。", "sentence_source": "generated"}, {"text": "命を助けてくれた人との絆は、一生忘れない。", "target_word": "絆", "complexity_tier": "T3", "furigana": "命(いのち)を助(たす)けてくれた人(ひと)との絆(きずな)は、一生(いっしょう)忘(わす)れない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "絆", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "簡単には切れない、人と人の強く固い結びつき", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '93788fa0-f2a6-402a-8dac-82f8c6817f01') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37853, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "絆", "is_correct": true, "explanation": "正解。「兄弟の絆は強い」の意味で、人の強い結びつきを表し文意に合う。"}, {"text": "温度", "is_correct": false, "explanation": "「兄弟の温度は強く」は人の結びつきを表さず、文の意味に合わない。"}, {"text": "天井", "is_correct": false, "explanation": "「兄弟の天井」は意味が通らない。天井は建物の上部で、人間関係には使わない。"}, {"text": "手紙", "is_correct": false, "explanation": "「兄弟の手紙は強く」は文の意味に合わず、強さを述べる対象にならない。"}], "explanations": {"絆": "正解。「兄弟の絆は強い」の意味で、人の強い結びつきを表し文意に合う。", "温度": "「兄弟の温度は強く」は人の結びつきを表さず、文の意味に合わない。", "天井": "「兄弟の天井」は意味が通らない。天井は建物の上部で、人間関係には使わない。", "手紙": "「兄弟の手紙は強く」は文の意味に合わず、強さを述べる対象にならない。"}, "sentence_index": 0, "correct_answer": "絆"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は父親としての絆を果たした。", "explanation": "絆は人との結びつきで、務めのように果たすものではない。"}, {"text": "二人は靴ひもの絆をほどいた。", "explanation": "絆は人のつながりで、靴ひものようにほどくものではない。"}, {"text": "転んでひざにできた傷に、絆を貼った。", "explanation": "絆は人のつながりで、傷に貼るものではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e589b8e-9cc9-489a-8888-642aa7b09f4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37853, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "絆", "is_correct": true, "explanation": "正解。「故郷との絆を断ち切る」の意味で、人や場所とのつながりを表し文意に合う。"}, {"text": "地図", "is_correct": false, "explanation": "「故郷との地図を断ち切る」は意味が通らず、断ち切る対象にならない。"}, {"text": "年齢", "is_correct": false, "explanation": "「故郷との年齢を断ち切る」は意味が通らず、断ち切る対象として不自然。"}, {"text": "天気", "is_correct": false, "explanation": "「故郷との天気を断ち切る」は意味が通らず、断つ対象にならない。"}], "explanations": {"絆": "正解。「故郷との絆を断ち切る」の意味で、人や場所とのつながりを表し文意に合う。", "地図": "「故郷との地図を断ち切る」は意味が通らず、断ち切る対象にならない。", "年齢": "「故郷との年齢を断ち切る」は意味が通らず、断ち切る対象として不自然。", "天気": "「故郷との天気を断ち切る」は意味が通らず、断つ対象にならない。"}, "sentence_index": 6, "correct_answer": "絆"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は難しい試験で、絆に合格した。", "explanation": "絆は人のつながりで、試験のように合格するものではない。"}, {"text": "彼女は大会で、自分の記録を絆で更新した。", "explanation": "絆は数値ではないので、記録のように更新する対象にはならない。"}, {"text": "正月に、子どもたちへ絆をあげた。", "explanation": "絆は人のつながりで、お年玉のようにあげるものではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e589b8e-9cc9-489a-8888-642aa7b09f4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37853, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "幼なじみを絆が、ずっと続いている。", "corrected_sentence": "幼なじみとの絆が、ずっと続いている。", "error_description": "「〜との絆」の形で関係の相手を示すのは「と」。「を」は目的語の印で、ここでは不適。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e589b8e-9cc9-489a-8888-642aa7b09f4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37853, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "長い歳月を経ても、二人の絆は揺るがれなかった。", "corrected_sentence": "長い歳月を経ても、二人の絆は揺るがなかった。", "error_description": "「揺るがない」は「揺るがなかった」と否定形で使う。「揺るがれなかった」という形はなく、活用の誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e589b8e-9cc9-489a-8888-642aa7b09f4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37854, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「語気を」の「を」で、「強める」の対象を表す目的語の助詞。"}, {"text": "が", "is_correct": false, "explanation": "「語気が強めて」は主語を立てる形になり、「強める」の目的語として不自然。"}, {"text": "に", "is_correct": false, "explanation": "「語気に強めて」は対象の示し方として不自然で、「強める」の目的語には合わない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表す「へ」は「語気」を向かう先にできず、「強める」には合わない。"}], "correct_answer": "を", "explanations": {"を": "「語気を」の「を」で、「強める」の対象を表す目的語の助詞。", "が": "「語気が強めて」は主語を立てる形になり、「強める」の目的語として不自然。", "に": "「語気に強めて」は対象の示し方として不自然で、「強める」の目的語には合わない。", "へ": "方向を表す「へ」は「語気」を向かう先にできず、「強める」には合わない。"}, "error_tags": {"が": "主語", "に": "方向・対象", "へ": "方向"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "弱める", "is_correct": true, "explanation": "「強める」の対義語として辞書に挙がり、程度を小さくする意味で反対になる。"}, {"text": "下げる", "is_correct": false, "explanation": "値や温度を低くする意味で、「強める」の対義語ではない。"}, {"text": "歩く", "is_correct": false, "explanation": "移動の動作で、「強める」と対義の関係にはない。"}, {"text": "眠る", "is_correct": false, "explanation": "休む動作で、程度を表す「強める」とは対義にならない。"}], "correct_answer": "弱める", "explanations": {"弱める": "「強める」の対義語として辞書に挙がり、程度を小さくする意味で反対になる。", "下げる": "値や温度を低くする意味で、「強める」の対義語ではない。", "歩く": "移動の動作で、「強める」と対義の関係にはない。", "眠る": "休む動作で、程度を表す「強める」とは対義にならない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25a27df5-4741-4b2c-abc8-2a6286747f67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37854, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「関係を」の「を」で、「強める」の対象を表す目的語の助詞。"}, {"text": "と", "is_correct": false, "explanation": "「関係と強める」は並列の形になり、「強める」の目的語として成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "「関係より強める」は比較の意味になり、対象を示せない。"}, {"text": "の", "is_correct": false, "explanation": "「関係の強める」は名詞句として続かず、文の構造が崩れる。"}], "correct_answer": "を", "explanations": {"を": "「関係を」の「を」で、「強める」の対象を表す目的語の助詞。", "と": "「関係と強める」は並列の形になり、「強める」の目的語として成り立たない。", "より": "「関係より強める」は比較の意味になり、対象を示せない。", "の": "「関係の強める」は名詞句として続かず、文の構造が崩れる。"}, "error_tags": {"と": "並列", "より": "比較", "の": "所属"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "弱める", "is_correct": true, "explanation": "「強める」の対義語として辞書に挙がり、程度を小さくする意味で反対になる。"}, {"text": "冷やす", "is_correct": false, "explanation": "温度を下げる動作で、「強める」の対義語ではない。"}, {"text": "眺める", "is_correct": false, "explanation": "見る動作で、程度を表す「強める」とは対義にならない。"}, {"text": "織る", "is_correct": false, "explanation": "布を作る動作で、「強める」とは対義の関係にない。"}], "correct_answer": "弱める", "explanations": {"弱める": "「強める」の対義語として辞書に挙がり、程度を小さくする意味で反対になる。", "冷やす": "温度を下げる動作で、「強める」の対義語ではない。", "眺める": "見る動作で、程度を表す「強める」とは対義にならない。", "織る": "布を作る動作で、「強める」とは対義の関係にない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25a27df5-4741-4b2c-abc8-2a6286747f67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37854, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "何かを今までよりもっと大きくする。", "primary_collocate": null, "pronunciation": "つよめる", "ipa": "tsɯjomeɾɯ", "syllable_count": 4, "sentences": [{"text": "火を強めると、お湯が早くわきます。", "target_word": "強める", "complexity_tier": "T3", "furigana": "火[ひ]を強[つよ]めると、お湯[ゆ]が早[はや]くわきます。", "sentence_source": "generated"}, {"text": "先生は語気を強めて、大切なところを説明した。", "target_word": "強めて", "complexity_tier": "T3", "furigana": "先生[せんせい]は語気[ごき]を強[つよ]めて、大切[たいせつ]なところを説明[せつめい]した。", "sentence_source": "generated"}, {"text": "警察はこの地域のパトロールを強めている。", "target_word": "強めて", "complexity_tier": "T3", "furigana": "警察[けいさつ]はこの地域[ちいき]のパトロールを強[つよ]めている。", "sentence_source": "generated"}, {"text": "スープの味を強めたくて、塩を少し足した。", "target_word": "強めたくて", "complexity_tier": "T3", "furigana": "スープの味[あじ]を強[つよ]めたくて、塩[しお]を少[すこ]し足[た]した。", "sentence_source": "generated"}, {"text": "暑いので、エアコンの風を強めてください。", "target_word": "強めて", "complexity_tier": "T3", "furigana": "暑[あつ]いので、エアコンの風[かぜ]を強[つよ]めてください。", "sentence_source": "generated"}, {"text": "会社は海外への宣伝を強めることにした。", "target_word": "強める", "complexity_tier": "T3", "furigana": "会社[かいしゃ]は海外[かいがい]への宣伝[せんでん]を強[つよ]めることにした。", "sentence_source": "generated"}, {"text": "母は部屋が暗かったので、電気の明るさを強めた。", "target_word": "強めた", "complexity_tier": "T3", "furigana": "母[はは]は部屋[へや]が暗[くら]かったので、電気[でんき]の明[あか]るさを強[つよ]めた。", "sentence_source": "generated"}, {"text": "友だちとの関係を強めるために、一緒に旅行に行った。", "target_word": "強める", "complexity_tier": "T3", "furigana": "友[とも]だちとの関係[かんけい]を強[つよ]めるために、一緒[いっしょ]に旅行[りょこう]に行[い]った。", "sentence_source": "generated"}, {"text": "彼は注意をうながすため、声を少し強めて話した。", "target_word": "強めて", "complexity_tier": "T3", "furigana": "彼[かれ]は注意[ちゅうい]をうながすため、声[こえ]を少[すこ]し強[つよ]めて話[はな]した。", "sentence_source": "generated"}, {"text": "ヒーターの設定を強めたら、部屋がすぐに暖かくなった。", "target_word": "強めた", "complexity_tier": "T3", "furigana": "ヒーターの設定[せってい]を強[つよ]めたら、部屋[へや]がすぐに暖[あたた]かくなった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "強める", "label": "辞書形"}, {"form": "強めます", "label": "ます形"}, {"form": "強めて", "label": "て形"}, {"form": "強めた", "label": "た形"}, {"form": "強めない", "label": "ない形"}], "register": "neutral", "sense_fingerprint": "火・声・味・風などの程度を今までより大きくする", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '226e73b8-df71-4110-ab40-d23c9c97d88d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37854, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "強める", "is_correct": true, "explanation": "火の勢いを増す動作を表し、お湯が早くわく理由として文が成り立つ。"}, {"text": "読む", "is_correct": false, "explanation": "火は読めないので、「火を読むと」は意味が通らない。"}, {"text": "聞く", "is_correct": false, "explanation": "火を聞くことはできず、火力の調節を表せない。"}, {"text": "眺める", "is_correct": false, "explanation": "火を眺めても、お湯が早くわく原因にはならない。"}], "explanations": {"強める": "火の勢いを増す動作を表し、お湯が早くわく理由として文が成り立つ。", "読む": "火は読めないので、「火を読むと」は意味が通らない。", "聞く": "火を聞くことはできず、火力の調節を表せない。", "眺める": "火を眺めても、お湯が早くわく原因にはならない。"}, "sentence_index": 0, "correct_answer": "強める"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "図書館は新しい本の数を強めた。", "explanation": "ここは〈増やす〉の意味。数を増やすことは「増やす」と言い、「強める」は力や程度を大きくする語なので合わない。"}, {"text": "雨は川の水かさを強めた。", "explanation": "ここは〈増す〉の意味。水かさが多くなるのは「増す」で、「強める」は水の量には使わないので合わない。"}, {"text": "寒いので、スープを強めて飲んだ。", "explanation": "ここは〈温める〉の意味。温度を上げるのは「温める」で、味や程度を大きくする「強める」とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25a27df5-4741-4b2c-abc8-2a6286747f67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37854, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "強めた", "is_correct": true, "explanation": "明るさを大きくした動作の過去形で、部屋が暗かった理由に合う。"}, {"text": "数えた", "is_correct": false, "explanation": "「電気の明るさを数えた」は、明るさを数える動作として意味が成り立たない。"}, {"text": "歌った", "is_correct": false, "explanation": "「電気の明るさを歌った」は意味が通らない。"}, {"text": "眠った", "is_correct": false, "explanation": "「電気の明るさを眠った」は意味が通らず、明るさに合わない。"}], "explanations": {"強めた": "明るさを大きくした動作の過去形で、部屋が暗かった理由に合う。", "数えた": "「電気の明るさを数えた」は、明るさを数える動作として意味が成り立たない。", "歌った": "「電気の明るさを歌った」は意味が通らない。", "眠った": "「電気の明るさを眠った」は意味が通らず、明るさに合わない。"}, "sentence_index": 6, "correct_answer": "強めた"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "会社は製品の品質を強めた。", "explanation": "ここは〈高める〉の意味。品質や水準を上げるのは「高める」で、「強める」は程度を大きくする語なので合わない。"}, {"text": "雨でぬかるんだ道を強めた。", "explanation": "ここは〈固める〉の意味。地面を硬くするのは「固める」で、「強める」は使わない。"}, {"text": "店は売り場を強めた。", "explanation": "ここは〈広げる〉の意味。売り場の範囲を広くするのは「広げる」で、「強める」とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25a27df5-4741-4b2c-abc8-2a6286747f67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37854, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ストーブの火を強めと、部屋がすぐに暖まります。", "corrected_sentence": "ストーブの火を強めると、部屋がすぐに暖まります。", "error_description": "誤りは「強めと」。正しくは「強めると」。「と」は動詞の辞書形につくので、「る」を落とすと形が崩れる。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "強めて", "is_correct": true, "explanation": "て形で、後ろの「説明した」へ続く文の形になる。"}, {"text": "強める", "is_correct": false, "explanation": "辞書形なので、「語気を強める説明した」と続かず文が成り立たない。"}, {"text": "強めた", "is_correct": false, "explanation": "た形は文を終えてしまうため、後ろの「説明した」と続けられない。"}, {"text": "強めない", "is_correct": false, "explanation": "否定の形で、「語気を強めない」は文の流れと合わない。"}], "correct_form": "強めて", "base_form": "強める", "form_label": "て形", "sentence_index": 1, "explanations": {"強めて": "て形で、後ろの「説明した」へ続く文の形になる。", "強める": "辞書形なので、「語気を強める説明した」と続かず文が成り立たない。", "強めた": "た形は文を終えてしまうため、後ろの「説明した」と続けられない。", "強めない": "否定の形で、「語気を強めない」は文の流れと合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25a27df5-4741-4b2c-abc8-2a6286747f67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37854, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "暖房の設定に強めたら、部屋がすぐに暖まった。", "corrected_sentence": "暖房の設定を強めたら、部屋がすぐに暖まった。", "error_description": "誤りは「設定に」。「強める」の対象は「を」で示すので、「に」にすると誤り。正しくは「設定を強めたら」。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "強める", "is_correct": true, "explanation": "辞書形で、「関係を強める」の「強める」として文に合う。"}, {"text": "強めれば", "is_correct": false, "explanation": "仮定の形で、「ために」と続く目的の文の形と合わない。"}, {"text": "強めよう", "is_correct": false, "explanation": "意志の形で、「強めように」と続く文の形として不自然。"}, {"text": "強めて", "is_correct": false, "explanation": "て形は「ために」に直接続かず、文が成り立たない。"}], "correct_form": "強める", "base_form": "強める", "form_label": "辞書形", "sentence_index": 7, "explanations": {"強める": "辞書形で、「関係を強める」の「強める」として文に合う。", "強めれば": "仮定の形で、「ために」と続く目的の文の形と合わない。", "強めよう": "意志の形で、「強めように」と続く文の形として不自然。", "強めて": "て形は「ために」に直接続かず、文が成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25a27df5-4741-4b2c-abc8-2a6286747f67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
