INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37855, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「見回りを」の「を」で、「強めて」の対象を表す目的語の助詞。"}, {"text": "と", "is_correct": false, "explanation": "「見回りと強めて」は並列の形になり、目的語として成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "「見回りより強めて」は比較の意味になり、対象を示せない。"}, {"text": "の", "is_correct": false, "explanation": "「見回りの強めて」は名詞句として続かず、文の構造が崩れる。"}], "correct_answer": "を", "explanations": {"を": "「見回りを」の「を」で、「強めて」の対象を表す目的語の助詞。", "と": "「見回りと強めて」は並列の形になり、目的語として成り立たない。", "より": "「見回りより強めて」は比較の意味になり、対象を示せない。", "の": "「見回りの強めて」は名詞句として続かず、文の構造が崩れる。"}, "error_tags": {"と": "並列", "より": "比較", "の": "所属"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "弱める", "is_correct": true, "explanation": "「強める」の対義語として辞書に挙がり、力や状態を小さくする意味で反対になる。"}, {"text": "冷やす", "is_correct": false, "explanation": "温度を下げる動作で、「強める」の対義語ではない。"}, {"text": "織る", "is_correct": false, "explanation": "布を作る動作で、「強める」とは対義の関係にない。"}, {"text": "眺める", "is_correct": false, "explanation": "見る動作で、程度を表す「強める」とは対義にならない。"}], "correct_answer": "弱める", "explanations": {"弱める": "「強める」の対義語として辞書に挙がり、力や状態を小さくする意味で反対になる。", "冷やす": "温度を下げる動作で、「強める」の対義語ではない。", "織る": "布を作る動作で、「強める」とは対義の関係にない。", "眺める": "見る動作で、程度を表す「強める」とは対義にならない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25a27df5-4741-4b2c-abc8-2a6286747f67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37855, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "ある状態や力を、今よりもっと大きくする。", "primary_collocate": null, "pronunciation": "つよめる", "ipa": "tsɯjomeɾɯ", "syllable_count": 4, "sentences": [{"text": "相手のチームは守りを強めて、点を取らせなかった。", "target_word": "強めて", "complexity_tier": "T3", "furigana": "相手[あいて]のチームは守[まも]りを強[つよ]めて、点[てん]を取[と]らせなかった。", "sentence_source": "generated"}, {"text": "政府は海外との協力を強める方針だ。", "target_word": "強める", "complexity_tier": "T3", "furigana": "政府[せいふ]は海外[かいがい]との協力[きょうりょく]を強[つよ]める方針[ほうしん]だ。", "sentence_source": "generated"}, {"text": "台風が近づいて、警戒を強めるよう呼びかけられた。", "target_word": "強める", "complexity_tier": "T3", "furigana": "台風[たいふう]が近[ちか]づいて、警戒[けいかい]を強[つよ]めるよう呼[よ]びかけられた。", "sentence_source": "generated"}, {"text": "運動で足の筋肉を強めると、けがをしにくくなる。", "target_word": "強める", "complexity_tier": "T3", "furigana": "運動[うんどう]で足[あし]の筋肉[きんにく]を強[つよ]めると、けがをしにくくなる。", "sentence_source": "generated"}, {"text": "会社は安全対策を強めることを発表した。", "target_word": "強める", "complexity_tier": "T3", "furigana": "会社[かいしゃ]は安全対策[あんぜんたいさく]を強[つよ]めることを発表[はっぴょう]した。", "sentence_source": "generated"}, {"text": "彼は反対の気持ちを強めて、計画に最後まで抵抗した。", "target_word": "強めて", "complexity_tier": "T3", "furigana": "彼[かれ]は反対[はんたい]の気持[きも]ちを強[つよ]めて、計画[けいかく]に最後[さいご]まで抵抗[ていこう]した。", "sentence_source": "generated"}, {"text": "この薬は体の抵抗力を強める働きがある。", "target_word": "強める", "complexity_tier": "T3", "furigana": "この薬[くすり]は体[からだ]の抵抗力[ていこうりょく]を強[つよ]める働[はたら]きがある。", "sentence_source": "generated"}, {"text": "市は夜間の見回りを強めて、犯罪を防ごうとしている。", "target_word": "強めて", "complexity_tier": "T3", "furigana": "市[し]は夜間[やかん]の見回[みまわ]りを強[つよ]めて、犯罪[はんざい]を防[ふせ]ごうとしている。", "sentence_source": "generated"}, {"text": "二つの国は経済のつながりを強めてきた。", "target_word": "強めて", "complexity_tier": "T3", "furigana": "二[ふた]つの国[くに]は経済[けいざい]のつながりを強[つよ]めてきた。", "sentence_source": "generated"}, {"text": "彼女は意志を強めて、もう一度試験に挑戦した。", "target_word": "強めて", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は意志[いし]を強[つよ]めて、もう一度[いちど]試験[しけん]に挑戦[ちょうせん]した。", "sentence_source": "generated"}], "morphological_forms": [{"form": "強める", "label": "辞書形"}, {"form": "強めます", "label": "ます形"}, {"form": "強めて", "label": "て形"}, {"form": "強めた", "label": "た形"}, {"form": "強めない", "label": "ない形"}], "register": "neutral", "sense_fingerprint": "警戒・守り・協力・力などの状態や働きを今より大きくする", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '226e73b8-df71-4110-ab40-d23c9c97d88d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37855, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "強めて", "is_correct": true, "explanation": "「守りを強めて」の形で、守りを固めた結果として点を取らせなかった文に合う。"}, {"text": "笑って", "is_correct": false, "explanation": "「守りを笑って」は意味が通らず、守備の状態を表せない。"}, {"text": "食べて", "is_correct": false, "explanation": "「守りを食べて」は意味が成り立たない。"}, {"text": "歌って", "is_correct": false, "explanation": "「守りを歌って」は守備と結びつかず、文の意味が通らない。"}], "explanations": {"強めて": "「守りを強めて」の形で、守りを固めた結果として点を取らせなかった文に合う。", "笑って": "「守りを笑って」は意味が通らず、守備の状態を表せない。", "食べて": "「守りを食べて」は意味が成り立たない。", "歌って": "「守りを歌って」は守備と結びつかず、文の意味が通らない。"}, "sentence_index": 0, "correct_answer": "強めて"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "毎日練習して、技の腕前を強めた。", "explanation": "ここは〈鍛える〉の意味。技術を磨くのは「鍛える」で、「強める」は力や状態を大きくする語なので合わない。"}, {"text": "会社はサービスの評価を強めた。", "explanation": "ここは〈高める〉の意味。評価を上げるのは「高める」で、「強める」とは言わない。"}, {"text": "二人は結婚式の日取りを強めた。", "explanation": "ここは〈決める〉の意味。日取りを決めるのは「決める」で、「強める」とは言わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25a27df5-4741-4b2c-abc8-2a6286747f67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37855, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "強める", "is_correct": true, "explanation": "「抵抗力を強める働き」の形で、薬の効き目を表す文に合う。"}, {"text": "眺める", "is_correct": false, "explanation": "「抵抗力を眺める働き」は意味が通らず、薬の働きを表せない。"}, {"text": "読む", "is_correct": false, "explanation": "「抵抗力を読む働き」は意味が成り立たない。"}, {"text": "聞く", "is_correct": false, "explanation": "「抵抗力を聞く働き」は意味が通らず、体の働きに合わない。"}], "explanations": {"強める": "「抵抗力を強める働き」の形で、薬の効き目を表す文に合う。", "眺める": "「抵抗力を眺める働き」は意味が通らず、薬の働きを表せない。", "読む": "「抵抗力を読む働き」は意味が成り立たない。", "聞く": "「抵抗力を聞く働き」は意味が通らず、体の働きに合わない。"}, "sentence_index": 6, "correct_answer": "強める"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "大学の研究で、専門の知識を強めた。", "explanation": "ここは〈深める〉の意味。知識を深く掘り下げるのは「深める」で、「強める」とは言わない。"}, {"text": "会社は商品の数を強めた。", "explanation": "ここは〈増やす〉の意味。数を多くするのは「増やす」で、「強める」は数には使わない。"}, {"text": "店は売り場を強めた。", "explanation": "ここは〈広げる〉の意味。売り場の範囲を広くするのは「広げる」で、「強める」とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25a27df5-4741-4b2c-abc8-2a6286747f67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37855, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "大雨の予報が出たので、警戒を強めたよう市が呼びかけた。", "corrected_sentence": "大雨の予報が出たので、警戒を強めるよう市が呼びかけた。", "error_description": "誤りは「強めた」。正しくは「強めるよう」。「よう」の前は辞書形を使うので、過去形は続かない。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "強める", "is_correct": true, "explanation": "辞書形で、「方針だ」に続けて「協力を強める方針」となり文に合う。"}, {"text": "強めて", "is_correct": false, "explanation": "て形は「方針だ」で文を終えられず、名詞を修飾する形にならない。"}, {"text": "強めれば", "is_correct": false, "explanation": "仮定の形で、名詞「方針」を修飾できず文が成り立たない。"}, {"text": "強めよう", "is_correct": false, "explanation": "意志の形で、「方針だ」の前に置けず文が成り立たない。"}], "correct_form": "強める", "base_form": "強める", "form_label": "辞書形", "sentence_index": 1, "explanations": {"強める": "辞書形で、「方針だ」に続けて「協力を強める方針」となり文に合う。", "強めて": "て形は「方針だ」で文を終えられず、名詞を修飾する形にならない。", "強めれば": "仮定の形で、名詞「方針」を修飾できず文が成り立たない。", "強めよう": "意志の形で、「方針だ」の前に置けず文が成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25a27df5-4741-4b2c-abc8-2a6286747f67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37855, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この薬は免疫の力を強めるの働きがある。", "corrected_sentence": "この薬は免疫の力を強める働きがある。", "error_description": "誤りは「強めるの」。正しくは「強める働き」。動詞の辞書形に「の」は付けず、そのまま「働き」に続ける。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "強めて", "is_correct": true, "explanation": "て形で、「ことで」と続く文の形として見回りを強める行為を表す。"}, {"text": "強めます", "is_correct": false, "explanation": "ます形で言い切りになり、「、犯罪を…」と続けられず文が成り立たない。"}, {"text": "強めよう", "is_correct": false, "explanation": "意志の形で、「強めよう、犯罪を防ごうとしている」は文の関係が崩れる。"}, {"text": "強めている", "is_correct": false, "explanation": "進行の形で、「強めている、防ごうとしている」は文が重複して不自然。"}], "correct_form": "強めて", "base_form": "強める", "form_label": "て形", "sentence_index": 7, "explanations": {"強めて": "て形で、「ことで」と続く文の形として見回りを強める行為を表す。", "強めます": "ます形で言い切りになり、「、犯罪を…」と続けられず文が成り立たない。", "強めよう": "意志の形で、「強めよう、犯罪を防ごうとしている」は文の関係が崩れる。", "強めている": "進行の形で、「強めている、防ごうとしている」は文が重複して不自然。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25a27df5-4741-4b2c-abc8-2a6286747f67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37856, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「祭りの日」の「の」で、祭りに関わる日を表す連体の助詞。"}, {"text": "が", "is_correct": false, "explanation": "「祭りが日は」は主語を立てる形になり、名詞句として続かない。"}, {"text": "を", "is_correct": false, "explanation": "「祭りを日は」は目的語の形になり、「日」を修飾できない。"}, {"text": "へ", "is_correct": false, "explanation": "方向の「へ」は「祭りへ日は」と続かず、名詞句が成り立たない。"}], "correct_answer": "の", "explanations": {"の": "「祭りの日」の「の」で、祭りに関わる日を表す連体の助詞。", "が": "「祭りが日は」は主語を立てる形になり、名詞句として続かない。", "を": "「祭りを日は」は目的語の形になり、「日」を修飾できない。", "へ": "方向の「へ」は「祭りへ日は」と続かず、名詞句が成り立たない。"}, "error_tags": {"が": "主語", "を": "目的語", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25a27df5-4741-4b2c-abc8-2a6286747f67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37856, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25a27df5-4741-4b2c-abc8-2a6286747f67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37856, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "みんなで楽しむために、特別なことをする日のことです。", "primary_collocate": null, "pronunciation": "まつり", "ipa": "matsɯɾi", "syllable_count": 3, "sentences": [{"text": "町の祭りに、家族みんなで行きました。", "target_word": "祭り", "complexity_tier": "T3", "furigana": "町[まち]の祭[まつ]りに、家族[かぞく]みんなで行[い]きました。", "sentence_source": "generated"}, {"text": "祭りの日は、道にたくさんの屋台が出ます。", "target_word": "祭り", "complexity_tier": "T3", "furigana": "祭[まつ]りの日[ひ]は、道[みち]にたくさんの屋台[やたい]が出[で]ます。", "sentence_source": "generated"}, {"text": "子どもたちは祭りを楽しみにして、早く起きました。", "target_word": "祭り", "complexity_tier": "T3", "furigana": "子[こ]どもたちは祭[まつ]りを楽[たの]しみにして、早[はや]く起[お]きました。", "sentence_source": "generated"}, {"text": "学校の祭りで、わたしはクラスの友だちと歌いました。", "target_word": "祭り", "complexity_tier": "T3", "furigana": "学校[がっこう]の祭[まつ]りで、わたしはクラスの友[とも]だちと歌[うた]いました。", "sentence_source": "generated"}, {"text": "雨が降ったので、今年の祭りは次の日になりました。", "target_word": "祭り", "complexity_tier": "T3", "furigana": "雨[あめ]が降[ふ]ったので、今年[ことし]の祭[まつ]りは次[つぎ]の日[ひ]になりました。", "sentence_source": "generated"}, {"text": "祭りが終わると、町はまた静かになります。", "target_word": "祭り", "complexity_tier": "T3", "furigana": "祭[まつ]りが終[お]わると、町[まち]はまた静[しず]かになります。", "sentence_source": "generated"}, {"text": "祭りのあとで、みんなで広場のごみを拾いました。", "target_word": "祭り", "complexity_tier": "T3", "furigana": "祭[まつ]りのあとで、みんなで広場[ひろば]のごみを拾[ひろ]いました。", "sentence_source": "generated"}, {"text": "祭りには、おじいさんもおばあさんも来て、にぎやかでした。", "target_word": "祭り", "complexity_tier": "T3", "furigana": "祭[まつ]りには、おじいさんもおばあさんも来[き]て、にぎやかでした。", "sentence_source": "generated"}, {"text": "小さな祭りですが、近所の人が集まって毎年開きます。", "target_word": "祭り", "complexity_tier": "T3", "furigana": "小[ちい]さな祭[まつ]りですが、近所[きんじょ]の人[ひと]が集[あつ]まって毎年[まいとし]開[ひら]きます。", "sentence_source": "generated"}, {"text": "祭りの準備は大変でしたが、みんなが手伝ってくれました。", "target_word": "祭り", "complexity_tier": "T3", "furigana": "祭[まつ]りの準備[じゅんび]は大変[たいへん]でしたが、みんなが手伝[てつだ]ってくれました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "祭り", "label": "基本形"}, {"form": "お祭り", "label": "丁寧形"}], "register": "neutral-polite", "sense_fingerprint": "町や学校で、みんなが楽しむための特別な行事の日", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '226e73b8-df71-4110-ab40-d23c9c97d88d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37856, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "祭り", "is_correct": true, "explanation": "町で行われる楽しい行事を表し、家族で行く先として文に合う。"}, {"text": "宿題", "is_correct": false, "explanation": "「町の宿題に行きました」は、行く先として意味が通らない。"}, {"text": "雨", "is_correct": false, "explanation": "「町の雨に行きました」は意味が成り立たない。"}, {"text": "歌", "is_correct": false, "explanation": "「町の歌に行きました」は、行く先として不自然で意味が通らない。"}], "explanations": {"祭り": "町で行われる楽しい行事を表し、家族で行く先として文に合う。", "宿題": "「町の宿題に行きました」は、行く先として意味が通らない。", "雨": "「町の雨に行きました」は意味が成り立たない。", "歌": "「町の歌に行きました」は、行く先として不自然で意味が通らない。"}, "sentence_index": 0, "correct_answer": "祭り"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "年末の大掃除は、家族で行う大切な祭りだ。", "explanation": "ここは〈行事〉の意味。大掃除は家の行事で、楽しみのための祭りとは呼ばないので合わない。"}, {"text": "明日は決勝の祭りがある。", "explanation": "ここは〈試合〉の意味。勝ち負けを争うのは試合で、祭りとは言わない。"}, {"text": "来週、町の祭りで予算を決める。", "explanation": "ここは〈会議〉の意味。予算を話し合って決めるのは会議で、祭りでは決めない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25a27df5-4741-4b2c-abc8-2a6286747f67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37856, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "祭り", "is_correct": true, "explanation": "「祭りのあとで」の形で、祭りの後に広場を掃除する文に合う。"}, {"text": "歯ブラシ", "is_correct": false, "explanation": "「歯ブラシのあとで、ごみを拾いました」は意味が通らない。"}, {"text": "冷蔵庫", "is_correct": false, "explanation": "「冷蔵庫のあとで、ごみを拾いました」は時間の流れとして成り立たない。"}, {"text": "教科書", "is_correct": false, "explanation": "「教科書のあとで、ごみを拾いました」は文脈に合わず、不自然。"}], "explanations": {"祭り": "「祭りのあとで」の形で、祭りの後に広場を掃除する文に合う。", "歯ブラシ": "「歯ブラシのあとで、ごみを拾いました」は意味が通らない。", "冷蔵庫": "「冷蔵庫のあとで、ごみを拾いました」は時間の流れとして成り立たない。", "教科書": "「教科書のあとで、ごみを拾いました」は文脈に合わず、不自然。"}, "sentence_index": 6, "correct_answer": "祭り"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "祖父の祭りは、親戚が集まって行われた。", "explanation": "ここは〈葬式〉の意味。故人を送る儀式は祭りとは言わず、祭りは楽しむための行事に使うので合わない。"}, {"text": "期末試験の祭りを見直した。", "explanation": "ここは〈試験〉の意味。答案などを見直すのは試験に関わる語で、祭りとは言わない。"}, {"text": "来週、取引先との祭りが控えている。", "explanation": "ここは〈仕事〉の意味。取引などの予定は仕事で、祭りとは言わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25a27df5-4741-4b2c-abc8-2a6286747f67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37856, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "週末の祭りを、家族で行きました。", "corrected_sentence": "週末の祭りに、家族で行きました。", "error_description": "誤りは「祭りを」。行く先の場所は「に」で示すので、「を」にすると誤り。正しくは「祭りに」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25a27df5-4741-4b2c-abc8-2a6286747f67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37856, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "毎年この時期に、町で祭りを食べます。", "corrected_sentence": "毎年この時期に、町で祭りを開きます。", "error_description": "誤りは「食べます」。「祭り」と結びつく動詞は「開く」なので、「食べる」にすると誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25a27df5-4741-4b2c-abc8-2a6286747f67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37857, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "「この祭りは」の「は」で、祭りを話題として示す助詞。"}, {"text": "を", "is_correct": false, "explanation": "「この祭りを、千年以上前から毎年続いている」は目的語の形になり、文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「この祭りへ、千年以上前から続いている」は方向の意味になり、文の主語として合わない。"}, {"text": "より", "is_correct": false, "explanation": "「この祭りより、千年以上前から続いている」は比較の意味になり、文の意味が通らない。"}], "correct_answer": "は", "explanations": {"は": "「この祭りは」の「は」で、祭りを話題として示す助詞。", "を": "「この祭りを、千年以上前から毎年続いている」は目的語の形になり、文が成り立たない。", "へ": "「この祭りへ、千年以上前から続いている」は方向の意味になり、文の主語として合わない。", "より": "「この祭りより、千年以上前から続いている」は比較の意味になり、文の意味が通らない。"}, "error_tags": {"を": "目的語", "へ": "方向", "より": "比較"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25a27df5-4741-4b2c-abc8-2a6286747f67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
