INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37857, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "特定の神や仏、または季節の行事を祝うために行われる、楽しい集まりや行事。", "primary_collocate": null, "pronunciation": "まつり", "ipa": "matsɯɾi", "syllable_count": 3, "sentences": [{"text": "神社の祭りでは、みんなで神様に感謝する。", "target_word": "祭り", "complexity_tier": "T3", "furigana": "神社[じんじゃ]の祭[まつ]りでは、みんなで神様[かみさま]に感謝[かんしゃ]する。", "sentence_source": "generated"}, {"text": "この祭りは、千年以上前から毎年続いている。", "target_word": "祭り", "complexity_tier": "T3", "furigana": "この祭[まつ]りは、千年[せんねん]以上[いじょう]前[まえ]から毎年[まいとし]続[つづ]いている。", "sentence_source": "generated"}, {"text": "秋の祭りでは、その年にとれた米を神様に供える。", "target_word": "祭り", "complexity_tier": "T3", "furigana": "秋[あき]の祭[まつ]りでは、その年[とし]にとれた米[こめ]を神様[かみさま]に供[そな]える。", "sentence_source": "generated"}, {"text": "祭りの日、神輿を担いで町を歩く。", "target_word": "祭り", "complexity_tier": "T3", "furigana": "祭[まつ]りの日[ひ]、神輿[みこし]を担[かつ]いで町[まち]を歩[ある]く。", "sentence_source": "generated"}, {"text": "お寺の祭りで、お坊さんがお経を読んだ。", "target_word": "祭り", "complexity_tier": "T3", "furigana": "お寺[てら]の祭[まつ]りで、お坊[ぼう]さんがお経[きょう]を読[よ]んだ。", "sentence_source": "generated"}, {"text": "豊作を祈る祭りが、村で行われた。", "target_word": "祭り", "complexity_tier": "T3", "furigana": "豊作[ほうさく]を祈[いの]る祭[まつ]りが、村[むら]で行[おこな]われた。", "sentence_source": "generated"}, {"text": "祭りの前に、神主が神社をきれいに掃除する。", "target_word": "祭り", "complexity_tier": "T3", "furigana": "祭[まつ]りの前[まえ]に、神主[かんぬし]が神社[じんじゃ]をきれいに掃除[そうじ]する。", "sentence_source": "generated"}, {"text": "春を迎える祭りで、人々は花を飾って歌った。", "target_word": "祭り", "complexity_tier": "T3", "furigana": "春[はる]を迎[むか]える祭[まつ]りで、人々[ひとびと]は花[はな]を飾[かざ]って歌[うた]った。", "sentence_source": "generated"}, {"text": "この地方の祭りは、海の神様に漁の無事を願うものだ。", "target_word": "祭り", "complexity_tier": "T3", "furigana": "この地方[ちほう]の祭[まつ]りは、海[うみ]の神様[かみさま]に漁[りょう]の無事[ぶじ]を願[ねが]うものだ。", "sentence_source": "generated"}, {"text": "祭りの間、村の人たちは仕事を休んで神様を迎える。", "target_word": "祭り", "complexity_tier": "T3", "furigana": "祭[まつ]りの間[あいだ]、村[むら]の人[ひと]たちは仕事[しごと]を休[やす]んで神様[かみさま]を迎[むか]える。", "sentence_source": "generated"}], "morphological_forms": [{"form": "祭り", "label": "基本形"}, {"form": "お祭り", "label": "丁寧形"}], "register": "neutral-plain", "sense_fingerprint": "神や仏、季節を祝うための祭礼・行事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 2 above tier T2: contains vocabulary far above tier T2: 供える (Zipf 2.13)']::text[], '226e73b8-df71-4110-ab40-d23c9c97d88d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37857, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "祭り", "is_correct": true, "explanation": "神社で神様に感謝する行事を表し、「神社の祭りでは」と続く文に合う。"}, {"text": "宿題", "is_correct": false, "explanation": "「神社の宿題では」は意味が通らず、神様への感謝とは結びつかない。"}, {"text": "雨", "is_correct": false, "explanation": "「神社の雨では」は文脈に合わず、意味が成り立たない。"}, {"text": "冷蔵庫", "is_correct": false, "explanation": "「神社の冷蔵庫では」は意味が通らない。"}], "explanations": {"祭り": "神社で神様に感謝する行事を表し、「神社の祭りでは」と続く文に合う。", "宿題": "「神社の宿題では」は意味が通らず、神様への感謝とは結びつかない。", "雨": "「神社の雨では」は文脈に合わず、意味が成り立たない。", "冷蔵庫": "「神社の冷蔵庫では」は意味が通らない。"}, "sentence_index": 0, "correct_answer": "祭り"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "亡くなった祖母の祭りで、親戚が集まってお経を聞いた。", "explanation": "ここは〈法要〉の意味。故人を供養する法事は「祭り」とは言わず、神や季節を祝う行事に使う語なので合わない。"}, {"text": "入学式で、校長が祭りを読んだ。", "explanation": "ここは〈式辞〉の意味。式辞は読むものだが、祭りは読むものではないので合わない。"}, {"text": "家族の誕生日の祭りで、みんなが歌った。", "explanation": "ここは〈お祝い〉の意味。個人の誕生日は神や季節の行事ではないので、「祭り」とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25a27df5-4741-4b2c-abc8-2a6286747f67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37857, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "祭り", "is_correct": true, "explanation": "「祭りの前に」の形で、神社の掃除が行事の前に行われることを表す。"}, {"text": "魚", "is_correct": false, "explanation": "「魚の前に、神主が神社を掃除する」は意味が通らない。"}, {"text": "教科書", "is_correct": false, "explanation": "「教科書の前に」は神社の掃除の時間とは結びつかず、不自然。"}, {"text": "電車", "is_correct": false, "explanation": "「電車の前に」は神社の掃除の時間として意味が通らない。"}], "explanations": {"祭り": "「祭りの前に」の形で、神社の掃除が行事の前に行われることを表す。", "魚": "「魚の前に、神主が神社を掃除する」は意味が通らない。", "教科書": "「教科書の前に」は神社の掃除の時間とは結びつかず、不自然。", "電車": "「電車の前に」は神社の掃除の時間として意味が通らない。"}, "sentence_index": 6, "correct_answer": "祭り"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "市の議会は、夏の祭りで条例を採決した。", "explanation": "ここは〈採決〉の意味。議会が条例を決めるのは採決で、祭りの場で決めるとは言わないので合わない。"}, {"text": "お寺で、お坊さんが修行の祭りを唱えた。", "explanation": "ここは〈読経〉の意味。経文は唱えるものだが、祭りを唱えることはできないので合わない。"}, {"text": "町内会は祭りを集めて、道路を直した。", "explanation": "ここは〈寄付〉の意味。お金や物を集めるのは寄付で、祭りを集めるとは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25a27df5-4741-4b2c-abc8-2a6286747f67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37857, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "山の神社で、秋の祭りを毎年行われる。", "corrected_sentence": "山の神社で、秋の祭りが毎年行われる。", "error_description": "誤りは「祭りを」。「行われる」の主語は「が」で示すので、「を」にすると誤り。正しくは「祭りが」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25a27df5-4741-4b2c-abc8-2a6286747f67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37857, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "毎年夏、町は祭りを飲む。", "corrected_sentence": "毎年夏、町は祭りを開く。", "error_description": "誤りは「飲む」。「祭り」と結びつく動詞は「開く」なので、「飲む」にすると誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25a27df5-4741-4b2c-abc8-2a6286747f67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37858, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「集まりの時間」の「の」。集まりと時間をつなぎ、集まりに関わる時間という意味を作る。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語を示すので、名詞どうしをつなぐここには入らない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は場所や手段を表すので、名詞をつなぐ「集まり〜時間」の形には合わない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表すので、ここでは名詞どうしをつなげない。"}], "correct_answer": "の", "explanations": {"の": "「集まりの時間」の「の」。集まりと時間をつなぎ、集まりに関わる時間という意味を作る。", "を": "「を」は目的語を示すので、名詞どうしをつなぐここには入らない。", "で": "「で」は場所や手段を表すので、名詞をつなぐ「集まり〜時間」の形には合わない。", "へ": "「へ」は方向を表すので、ここでは名詞どうしをつなげない。"}, "error_tags": {"を": "object", "で": "means-location", "へ": "direction"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25a27df5-4741-4b2c-abc8-2a6286747f67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37858, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "集まりを主題として示す「は」。「来週に変わる」の主語になる。"}, {"text": "の", "is_correct": false, "explanation": "「集まりの来週に」と続けると名詞どうしを「の」でつなぐ形になり、「変わる」の文として成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「集まりに来週に」と「に」が二つ続き、主題を示す位置には入らず不自然。"}, {"text": "と", "is_correct": false, "explanation": "「集まりと来週に」は「集まり」と「来週」を並べる意味になり、主題の「は」の代わりにはならない。"}], "correct_answer": "は", "explanations": {"は": "集まりを主題として示す「は」。「来週に変わる」の主語になる。", "の": "「集まりの来週に」と続けると名詞どうしを「の」でつなぐ形になり、「変わる」の文として成り立たない。", "に": "「集まりに来週に」と「に」が二つ続き、主題を示す位置には入らず不自然。", "と": "「集まりと来週に」は「集まり」と「来週」を並べる意味になり、主題の「は」の代わりにはならない。"}, "error_tags": {"の": "genitive-link", "に": "double-ni", "と": "listing"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25a27df5-4741-4b2c-abc8-2a6286747f67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37858, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "たくさんの人が一か所に集まること。", "primary_collocate": null, "pronunciation": "あつまり", "ipa": "atsɯmaɾi", "syllable_count": 4, "sentences": [{"text": "今日は町の集まりに、たくさんの人が来ました。", "target_word": "集まり", "complexity_tier": "T3", "furigana": "今日[きょう]は町[まち]の集[あつ]まりに、たくさんの人[ひと]が来[き]ました。", "sentence_source": "generated"}, {"text": "集まりの時間に遅れて、先生に謝りました。", "target_word": "集まり", "complexity_tier": "T3", "furigana": "集[あつ]まりの時間[じかん]に遅[おく]れて、先生[せんせい]に謝[あやま]りました。", "sentence_source": "generated"}, {"text": "週に一回、近所の集まりがあります。", "target_word": "集まり", "complexity_tier": "T3", "furigana": "週[しゅう]に一回[いっかい]、近所[きんじょ]の集[あつ]まりがあります。", "sentence_source": "generated"}, {"text": "この集まりは、だれでも自由に参加できます。", "target_word": "集まり", "complexity_tier": "T3", "furigana": "この集[あつ]まりは、だれでも自由[じゆう]に参加[さんか]できます。", "sentence_source": "generated"}, {"text": "集まりが悪くて、会議は始まりませんでした。", "target_word": "集まり", "complexity_tier": "T3", "furigana": "集[あつ]まりが悪[わる]くて、会議[かいぎ]は始[はじ]まりませんでした。", "sentence_source": "generated"}, {"text": "友だちの集まりで、ひさしぶりに昔の話をしました。", "target_word": "集まり", "complexity_tier": "T3", "furigana": "友[とも]だちの集[あつ]まりで、ひさしぶりに昔[むかし]の話[はなし]をしました。", "sentence_source": "generated"}, {"text": "集まりのあと、みんなで食事に行きました。", "target_word": "集まり", "complexity_tier": "T3", "furigana": "集[あつ]まりのあと、みんなで食事[しょくじ]に行[い]きました。", "sentence_source": "generated"}, {"text": "雨だったので、集まりは来週に変わりました。", "target_word": "集まり", "complexity_tier": "T3", "furigana": "雨[あめ]だったので、集[あつ]まりは来週[らいしゅう]に変[か]わりました。", "sentence_source": "generated"}, {"text": "学校のそばの公園で、家族の集まりを開きました。", "target_word": "集まり", "complexity_tier": "T3", "furigana": "学校[がっこう]のそばの公園[こうえん]で、家族[かぞく]の集[あつ]まりを開[ひら]きました。", "sentence_source": "generated"}, {"text": "村の集まりで、新しい橋のことを話し合いました。", "target_word": "集まり", "complexity_tier": "T3", "furigana": "村[むら]の集[あつ]まりで、新[あたら]しい橋[はし]のことを話[はな]し合[あ]いました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "集まり", "label": "基本形"}], "register": "neutral-polite", "sense_fingerprint": "gathering or meeting where many people come together in one place", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '226e73b8-df71-4110-ab40-d23c9c97d88d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37858, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "集まり", "is_correct": true, "explanation": "町で人が寄り集まる催しを指し、ここに入る名詞として文の意味が通る。"}, {"text": "病気", "is_correct": false, "explanation": "病気は人が来る催しや場所ではないので、「町の病気に人が来た」は成り立たない。"}, {"text": "切手", "is_correct": false, "explanation": "切手は人が集まって行く場所ではないので、文の意味が合わない。"}, {"text": "落ち葉", "is_correct": false, "explanation": "落ち葉に人が来るという文にはならず、ここに入れると意味が通らない。"}], "explanations": {"集まり": "町で人が寄り集まる催しを指し、ここに入る名詞として文の意味が通る。", "病気": "病気は人が来る催しや場所ではないので、「町の病気に人が来た」は成り立たない。", "切手": "切手は人が集まって行く場所ではないので、文の意味が合わない。", "落ち葉": "落ち葉に人が来るという文にはならず、ここに入れると意味が通らない。"}, "sentence_index": 0, "correct_answer": "集まり"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "わたしは集まりを株式会社として登記した。", "explanation": "〈団体・法人〉の意味で使う語。集まりは人が一か所に寄ることを指すので、登記して法人となる会社の意味にはならない。"}, {"text": "わたしは集まりを一袋百円で売った。", "explanation": "〈商品〉の意味で使う語。集まりは人が寄る催しで、売り買いする品物ではないので誤用。"}, {"text": "わたしは一人の集まりで、毎晩ひとりで静かに本を読む。", "explanation": "〈個人〉の意味で使う語。集まりは複数の人が寄ることを指すので、一人だけの個人には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25a27df5-4741-4b2c-abc8-2a6286747f67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37858, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "集まり", "is_correct": true, "explanation": "食事の前に行われた集まりを指し、「集まりのあと」として文の意味が通る。"}, {"text": "本棚", "is_correct": false, "explanation": "本棚は人が集まる催しではないので、「本棚のあと、食事に行った」は意味が合わない。"}, {"text": "押し入れ", "is_correct": false, "explanation": "押し入れは場所であっても催しではなく、「のあと」の前には入らない。"}, {"text": "眠気", "is_correct": false, "explanation": "眠気は催しではなく、食事に行く流れの前に置くと意味が通らない。"}], "explanations": {"集まり": "食事の前に行われた集まりを指し、「集まりのあと」として文の意味が通る。", "本棚": "本棚は人が集まる催しではないので、「本棚のあと、食事に行った」は意味が合わない。", "押し入れ": "押し入れは場所であっても催しではなく、「のあと」の前には入らない。", "眠気": "眠気は催しではなく、食事に行く流れの前に置くと意味が通らない。"}, "sentence_index": 6, "correct_answer": "集まり"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "集まりは名前を書いて、受付に出した。", "explanation": "〈参加者〉の意味で使う語。集まりは人が寄る場を指し、名前を書いて受付に出す主体にはならない。"}, {"text": "集まりが熱いお湯に溶けて、色が消えた。", "explanation": "溶けて色が消えるのは砂糖などの物質の話。集まりは人や物が寄ることを指し、お湯に溶けるものではないので誤用。"}, {"text": "わたしは集まりを一時間借りて、荷物を置いた。", "explanation": "〈会場〉の意味で使う語。集まりは人が寄ることを指し、場所として借りることはできないので誤用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25a27df5-4741-4b2c-abc8-2a6286747f67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37858, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "今日は町の集まりを、たくさんの人が参加しました。", "corrected_sentence": "今日は町の集まりに、たくさんの人が参加しました。", "error_description": "助詞の誤り：集まりに続けるのは「に」（場所・集合先）。「を」は目的語を示すので、「参加する」の対象として不自然。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25a27df5-4741-4b2c-abc8-2a6286747f67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37858, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "雨が降ったので、集まりを来週に変わりました。", "corrected_sentence": "雨が降ったので、集まりは来週に変わりました。", "error_description": "助詞の誤り：「集まりは来週に変わる」と主題の「は」が正しい。「を」では「変わる」（自動詞）に目的語が続かず不自然。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25a27df5-4741-4b2c-abc8-2a6286747f67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37859, 3, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25a27df5-4741-4b2c-abc8-2a6286747f67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37859, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「島の集まり」の「の」。島と集まりをつなぎ、構成を表す。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語を示すが、ここで名詞どうしをつなぐには合わない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表す「へ」は、「島へ集まり」の形では成り立たない。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を示すので、「島が集まり」と続くと文の構造が崩れる。"}], "correct_answer": "の", "explanations": {"の": "「島の集まり」の「の」。島と集まりをつなぎ、構成を表す。", "を": "「を」は目的語を示すが、ここで名詞どうしをつなぐには合わない。", "へ": "方向を表す「へ」は、「島へ集まり」の形では成り立たない。", "が": "「が」は主語を示すので、「島が集まり」と続くと文の構造が崩れる。"}, "error_tags": {"を": "object", "へ": "direction", "が": "subject"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25a27df5-4741-4b2c-abc8-2a6286747f67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37859, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "人や物が一つの場所に寄り合うこと。また、その集まったもの。", "primary_collocate": null, "pronunciation": "あつまり", "ipa": "atsɯmaɾi", "syllable_count": 4, "sentences": [{"text": "町は小さな店の集まりでできている。", "target_word": "集まり", "complexity_tier": "T3", "furigana": "町[まち]は小[ちい]さな店[みせ]の集[あつ]まりでできている。", "sentence_source": "generated"}, {"text": "雲は小さな水のつぶの集まりだ。", "target_word": "集まり", "complexity_tier": "T3", "furigana": "雲[くも]は小[ちい]さな水[みず]のつぶの集[あつ]まりだ。", "sentence_source": "generated"}, {"text": "この本は短い物語の集まりだ。", "target_word": "集まり", "complexity_tier": "T3", "furigana": "この本[ほん]は短[みじか]い物語[ものがたり]の集[あつ]まりだ。", "sentence_source": "generated"}, {"text": "山の上に古い家の集まりが見える。", "target_word": "集まり", "complexity_tier": "T3", "furigana": "山[やま]の上[うえ]に古[ふる]い家[いえ]の集[あつ]まりが見[み]える。", "sentence_source": "generated"}, {"text": "星の集まりを銀河という。", "target_word": "集まり", "complexity_tier": "T3", "furigana": "星[ほし]の集[あつ]まりを銀河[ぎんが]という。", "sentence_source": "generated"}, {"text": "ここは若い人の集まりなので、いつもにぎやかだ。", "target_word": "集まり", "complexity_tier": "T3", "furigana": "ここは若[わか]い人[ひと]の集[あつ]まりなので、いつもにぎやかだ。", "sentence_source": "generated"}, {"text": "国は人の集まりだと先生は言った。", "target_word": "集まり", "complexity_tier": "T3", "furigana": "国[くに]は人[ひと]の集[あつ]まりだと先生[せんせい]は言[い]った。", "sentence_source": "generated"}, {"text": "小さな島の集まりが海の上に見える。", "target_word": "集まり", "complexity_tier": "T3", "furigana": "小[ちい]さな島[しま]の集[あつ]まりが海[うみ]の上[うえ]に見[み]える。", "sentence_source": "generated"}, {"text": "会社は働く人の集まりだ。", "target_word": "集まり", "complexity_tier": "T3", "furigana": "会社[かいしゃ]は働[はたら]く人[ひと]の集[あつ]まりだ。", "sentence_source": "generated"}, {"text": "小さな部品の集まりが大きな機械になる。", "target_word": "集まり", "complexity_tier": "T3", "furigana": "小[ちい]さな部品[ぶひん]の集[あつ]まりが大[おお]きな機械[きかい]になる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "集まり", "label": "基本形"}], "register": "neutral-plain", "sense_fingerprint": "a collection or aggregate of people or things that have come together", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '226e73b8-df71-4110-ab40-d23c9c97d88d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37859, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "集まり", "is_correct": true, "explanation": "店が寄り集まったものとして町ができている、という意味に合う。"}, {"text": "切手", "is_correct": false, "explanation": "切手は店を構成するものではないので、「店の切手」では意味が通らない。"}, {"text": "落ち葉", "is_correct": false, "explanation": "落ち葉は店を構成するものではなく、「店の落ち葉」は文脈に合わない。"}, {"text": "眠気", "is_correct": false, "explanation": "眠気は店ではなく、「店の眠気でできている」は意味が成り立たない。"}], "explanations": {"集まり": "店が寄り集まったものとして町ができている、という意味に合う。", "切手": "切手は店を構成するものではないので、「店の切手」では意味が通らない。", "落ち葉": "落ち葉は店を構成するものではなく、「店の落ち葉」は文脈に合わない。", "眠気": "眠気は店ではなく、「店の眠気でできている」は意味が成り立たない。"}, "sentence_index": 0, "correct_answer": "集まり"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "一本の鉛筆の集まりを、机の上に置いた。", "explanation": "〈単品〉の意味で使う語。集まりは複数のものが寄った状態を指すので、一本だけの鉛筆には使わない。"}, {"text": "この集まりは、勝った人が賞金をもらう競走だ。", "explanation": "〈競走〉や〈大会〉の意味で使う語ではない。ここは物や人が寄った状態を指すので合わない。"}, {"text": "その集まりは、きのう決めた約束のことだ。", "explanation": "〈約束〉の意味で使う語。集まりは寄り集まったものを指すので、約束そのものを表す語ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25a27df5-4741-4b2c-abc8-2a6286747f67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37859, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "集まり", "is_correct": true, "explanation": "人が寄り集まったものとして国を捉える意味に合う。"}, {"text": "本棚", "is_correct": false, "explanation": "本棚は人の集まりを指さないので、「人の本棚」では意味が通らない。"}, {"text": "押し入れ", "is_correct": false, "explanation": "押し入れは人を構成するものではなく、文が成り立たない。"}, {"text": "大雨", "is_correct": false, "explanation": "大雨は人を構成するものではないので、「人の大雨」は文に合わない。"}], "explanations": {"集まり": "人が寄り集まったものとして国を捉える意味に合う。", "本棚": "本棚は人の集まりを指さないので、「人の本棚」では意味が通らない。", "押し入れ": "押し入れは人を構成するものではなく、文が成り立たない。", "大雨": "大雨は人を構成するものではないので、「人の大雨」は文に合わない。"}, "sentence_index": 6, "correct_answer": "集まり"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "授業中、集まりが切れて、ぼんやり窓の外を見ていた。", "explanation": "〈集中〉の意味で使う語。集まりは物や人が寄ることなので、注意が途切れる意味には合わない。"}, {"text": "集まりを、夏休みの宿題として一人で仕上げた。", "explanation": "仕上げるのは課題や作品。集まりは寄り集まった状態で、作業の対象にはならない。"}, {"text": "わたしは、この集まりで二枚の板をしっかり貼り合わせた。", "explanation": "〈接着剤〉の意味で使う語。集まりは人や物が寄ることを指し、板を貼り合わせる接着剤にはならないので誤用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25a27df5-4741-4b2c-abc8-2a6286747f67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37859, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "雲は小さな水のつぶの集まりに、できている。", "corrected_sentence": "雲は小さな水のつぶの集まりでできている。", "error_description": "助詞の誤り：「〜でできている」の「で」（材料・構成）が正しい。「に」では「できている」と続かず、文が成り立たない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25a27df5-4741-4b2c-abc8-2a6286747f67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37859, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "その村は人の集まりに先生が教えた。", "corrected_sentence": "その村は人の集まりだと先生が教えた。", "error_description": "助詞・述語の誤り：「〜だと教えた」の「だと」（断定＋引用）が正しい。「に」では「教えた」の内容が示せず、文が成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25a27df5-4741-4b2c-abc8-2a6286747f67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37860, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「自体に」の形で、「お金それ自体に、価値はありません」と成り立つ。"}, {"text": "を", "is_correct": false, "explanation": "「お金それ自体を、価値はありません」となり、目的語として文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示すが、「価値はありません」と続く文では不自然。"}, {"text": "と", "is_correct": false, "explanation": "「と」を入れると「お金それ自体と、価値はありません」となり、並列の相手がなく主語と述語が噛み合わないので文が成り立たない。"}], "correct_answer": "に", "explanations": {"に": "「自体に」の形で、「お金それ自体に、価値はありません」と成り立つ。", "を": "「お金それ自体を、価値はありません」となり、目的語として文が成り立たない。", "へ": "方向を示すが、「価値はありません」と続く文では不自然。", "と": "「と」を入れると「お金それ自体と、価値はありません」となり、並列の相手がなく主語と述語が噛み合わないので文が成り立たない。"}, "error_tags": {"を": "対象", "へ": "方向", "と": "並列"}, "sentence_index": 0}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7fa5edfe-0c0f-4bc2-8079-af983ceda906') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37860, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「自体に」の形で、後ろの「は、力があります」と続く。"}, {"text": "が", "is_correct": false, "explanation": "「自体が」の後に「は」が続くと「が＋は」となり、不自然で文が崩れる。"}, {"text": "を", "is_correct": false, "explanation": "「を」を入れると「言葉それ自体をは、力があります」となり、「を」と「は」が重なって成り立たない。"}, {"text": "や", "is_correct": false, "explanation": "「や」を入れると「言葉それ自体やは、力があります」となり、並列の相手が欠けて文が成り立たない。"}], "correct_answer": "に", "explanations": {"に": "「自体に」の形で、後ろの「は、力があります」と続く。", "が": "「自体が」の後に「は」が続くと「が＋は」となり、不自然で文が崩れる。", "を": "「を」を入れると「言葉それ自体をは、力があります」となり、「を」と「は」が重なって成り立たない。", "や": "「や」を入れると「言葉それ自体やは、力があります」となり、並列の相手が欠けて文が成り立たない。"}, "error_tags": {"が": "主語", "を": "対象", "や": "並列"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7fa5edfe-0c0f-4bc2-8079-af983ceda906') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37860, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "「自体」は「そのもの」という意味です。何かを指して、それ以外のものと区別して言います。", "primary_collocate": null, "pronunciation": "じたい", "ipa": "dʑitai", "syllable_count": 3, "sentences": [{"text": "お金それ自体に、価値はありません。", "target_word": "自体", "complexity_tier": "T3", "furigana": "お金[かね]それ自体[じたい]に、価値[かち]はありません。", "sentence_source": "generated"}, {"text": "この問題それ自体は、難しくありません。", "target_word": "自体", "complexity_tier": "T3", "furigana": "この問題[もんだい]それ自体[じたい]は、難[むずか]しくありません。", "sentence_source": "generated"}, {"text": "旅行それ自体より、準備が大変でした。", "target_word": "自体", "complexity_tier": "T3", "furigana": "旅行[りょこう]それ自体[じたい]より、準備[じゅんび]が大変[たいへん]でした。", "sentence_source": "generated"}, {"text": "その考え自体が、間違っていました。", "target_word": "自体", "complexity_tier": "T3", "furigana": "その考[かんが]え自体[じたい]が、間違[まちが]っていました。", "sentence_source": "generated"}, {"text": "ゲームそれ自体は悪くありませんが、遊びすぎは困ります。", "target_word": "自体", "complexity_tier": "T3", "furigana": "ゲームそれ自体[じたい]は悪[わる]くありませんが、遊[あそ]びすぎは困[こま]ります。", "sentence_source": "generated"}, {"text": "病気それ自体より、治すお金が心配です。", "target_word": "自体", "complexity_tier": "T3", "furigana": "病気[びょうき]それ自体[じたい]より、治[なお]すお金[かね]が心配[しんぱい]です。", "sentence_source": "generated"}, {"text": "計画それ自体はいいので、すぐ始めましょう。", "target_word": "自体", "complexity_tier": "T3", "furigana": "計画[けいかく]それ自体[じたい]はいいので、すぐ始[はじ]めましょう。", "sentence_source": "generated"}, {"text": "言葉それ自体には、力があります。", "target_word": "自体", "complexity_tier": "T3", "furigana": "言葉[ことば]それ自体[じたい]には、力[ちから]があります。", "sentence_source": "generated"}, {"text": "パンそれ自体の味が好きで、何もつけません。", "target_word": "自体", "complexity_tier": "T3", "furigana": "パンそれ自体[じたい]の味[あじ]が好[す]きで、何[なに]もつけません。", "sentence_source": "generated"}, {"text": "勝つことそれ自体が、目的ではありません。", "target_word": "自体", "complexity_tier": "T3", "furigana": "勝[か]つことそれ自体[じたい]が、目的[もくてき]ではありません。", "sentence_source": "generated"}], "morphological_forms": [{"form": "自体", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "それ自体・〜それ自体：そのもの、ほかと区別した本体", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1008a082-97df-4e54-bb3b-338a2360e5cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37860, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "自体", "is_correct": true, "explanation": "「そのもの」の意味で、「お金それ自体」の形になり、後ろの「価値はありません」と続く。"}, {"text": "愛情", "is_correct": false, "explanation": "「お金それ愛情」と続けても意味が通らず、文の空欄に入らない。"}, {"text": "天気", "is_correct": false, "explanation": "「お金それ天気」は成り立たず、お金の価値の話と合わない。"}, {"text": "翌日", "is_correct": false, "explanation": "時間の語で、「お金それ翌日」と続かないので文が成り立たない。"}], "explanations": {"自体": "「そのもの」の意味で、「お金それ自体」の形になり、後ろの「価値はありません」と続く。", "愛情": "「お金それ愛情」と続けても意味が通らず、文の空欄に入らない。", "天気": "「お金それ天気」は成り立たず、お金の価値の話と合わない。", "翌日": "時間の語で、「お金それ翌日」と続かないので文が成り立たない。"}, "sentence_index": 0, "correct_answer": "自体"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "その話は自体が一番よく知っています。", "explanation": "ここは〈本人〉の意味。自体は物事を指す語で、知るという動作はできないので合わない。"}, {"text": "事故の自体は、今も入院しています。", "explanation": "ここは〈当人〉の意味。入院するのは人なので、物事を表す「自体」は合わない。"}, {"text": "自体、三時ごろに着きます。", "explanation": "ここは副詞「大体（おおよそ）」の意味。自体は名詞で、副詞として使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7fa5edfe-0c0f-4bc2-8079-af983ceda906') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37860, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "自体", "is_correct": true, "explanation": "「そのもの」の意味で、「計画それ自体はいい」と続き、空欄に入る。"}, {"text": "寝室", "is_correct": false, "explanation": "「計画それ寝室は」と続かず、計画の良し悪しの話に合わない。"}, {"text": "愛想", "is_correct": false, "explanation": "人当たりの態度を表し、「計画それ愛想はいい」は成り立たない。"}, {"text": "休日", "is_correct": false, "explanation": "「計画それ休日」と続かず、計画そのものの評価として不自然。"}], "explanations": {"自体": "「そのもの」の意味で、「計画それ自体はいい」と続き、空欄に入る。", "寝室": "「計画それ寝室は」と続かず、計画の良し悪しの話に合わない。", "愛想": "人当たりの態度を表し、「計画それ愛想はいい」は成り立たない。", "休日": "「計画それ休日」と続かず、計画そのものの評価として不自然。"}, "sentence_index": 6, "correct_answer": "自体"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "友だちに自体を話して、心を落ち着けました。", "explanation": "ここは〈事情〉の意味。「話す」の対象は事情や内容で、「自体」は話す対象として使えないので合わない。"}, {"text": "私の自体を、ていねいに磨きました。", "explanation": "ここは〈自分自身〉の意味。「自体」は物事に使い、自分自身を指す語としては使えないので合わない。"}, {"text": "明日の自体は、晴れるでしょう。", "explanation": "ここは〈天気〉の意味。自体は物事そのものを指す語で、天気の様子は表せない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7fa5edfe-0c0f-4bc2-8079-af983ceda906') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37860, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "その機械自体を、よく動いています。", "corrected_sentence": "その機械自体は、よく動いています。", "error_description": "主題を示すには「は」が正しい。「を」は目的語を示す助詞で、自動詞「動く」と合わないため誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7fa5edfe-0c0f-4bc2-8079-af983ceda906') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37860, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この料理自体を、とても簡単です。", "corrected_sentence": "この料理自体は、とても簡単です。", "error_description": "主題を示すには「は」が正しい。「を」は目的語を示す助詞で、「簡単です」と続かないため誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7fa5edfe-0c0f-4bc2-8079-af983ceda906') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
