INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37861, 3, 'prompt1_core', '{"pos": "接尾辞", "semantic_class": "function", "definition": "「自体」は、名詞に付いて、そのもの自体を強調する語。ほかのものではなく、まさにその対象自身を指す。", "primary_collocate": null, "pronunciation": "じたい", "ipa": "dʑitai", "syllable_count": 3, "sentences": [{"text": "仕事自体は楽しいですが、人間関係が大変です。", "target_word": "自体", "complexity_tier": "T3", "furigana": "仕事[しごと]自体[じたい]は楽[たの]しいですが、人間関係[にんげんかんけい]が大変[たいへん]です。", "sentence_source": "generated"}, {"text": "この映画自体は短いですが、内容は深いです。", "target_word": "自体", "complexity_tier": "T3", "furigana": "この映画[えいが]自体[じたい]は短[みじか]いですが、内容[ないよう]は深[ふか]いです。", "sentence_source": "generated"}, {"text": "日本語自体が好きで、毎日勉強しています。", "target_word": "自体", "complexity_tier": "T3", "furigana": "日本語[にほんご]自体[じたい]が好[す]きで、毎日[まいにち]勉強[べんきょう]しています。", "sentence_source": "generated"}, {"text": "この薬自体には、副作用がほとんどありません。", "target_word": "自体", "complexity_tier": "T3", "furigana": "この薬[くすり]自体[じたい]には、副作用[ふくさよう]がほとんどありません。", "sentence_source": "generated"}, {"text": "スマホ自体が古くなって、動きが遅いです。", "target_word": "自体", "complexity_tier": "T3", "furigana": "スマホ自体[じたい]が古[ふる]くなって、動[うご]きが遅[おそ]いです。", "sentence_source": "generated"}, {"text": "料理自体は簡単ですが、材料を集めるのが大変です。", "target_word": "自体", "complexity_tier": "T3", "furigana": "料理[りょうり]自体[じたい]は簡単[かんたん]ですが、材料[ざいりょう]を集[あつ]めるのが大変[たいへん]です。", "sentence_source": "generated"}, {"text": "学校自体は小さいですが、先生は親切です。", "target_word": "自体", "complexity_tier": "T3", "furigana": "学校[がっこう]自体[じたい]は小[ちい]さいですが、先生[せんせい]は親切[しんせつ]です。", "sentence_source": "generated"}, {"text": "この町自体が、昔の姿を残しています。", "target_word": "自体", "complexity_tier": "T3", "furigana": "この町[まち]自体[じたい]が、昔[むかし]の姿[すがた]を残[のこ]しています。", "sentence_source": "generated"}, {"text": "試験自体より、結果を待つ時間がつらいです。", "target_word": "自体", "complexity_tier": "T3", "furigana": "試験[しけん]自体[じたい]より、結果[けっか]を待[ま]つ時間[じかん]がつらいです。", "sentence_source": "generated"}, {"text": "運動自体は嫌いではありませんが、朝は苦手です。", "target_word": "自体", "complexity_tier": "T3", "furigana": "運動[うんどう]自体[じたい]は嫌[きら]いではありませんが、朝[あさ]は苦手[にがて]です。", "sentence_source": "generated"}], "morphological_forms": [{"form": "自体", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "名詞に付いてその対象自身を強調する（名詞＋自体）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1008a082-97df-4e54-bb3b-338a2360e5cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37861, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "自体", "is_correct": true, "explanation": "名詞の後ろに付いて対象そのものを強調し、「仕事自体は楽しい」と続く。"}, {"text": "深夜", "is_correct": false, "explanation": "時間帯を表す名詞で、「仕事深夜は楽しい」は成り立たない。"}, {"text": "役所", "is_correct": false, "explanation": "役所という場所を表し、「仕事役所は楽しい」と続かない。"}, {"text": "標識", "is_correct": false, "explanation": "道路の目印を表し、「仕事標識は楽しい」は文として成り立たない。"}], "explanations": {"自体": "名詞の後ろに付いて対象そのものを強調し、「仕事自体は楽しい」と続く。", "深夜": "時間帯を表す名詞で、「仕事深夜は楽しい」は成り立たない。", "役所": "役所という場所を表し、「仕事役所は楽しい」と続かない。", "標識": "道路の目印を表し、「仕事標識は楽しい」は文として成り立たない。"}, "sentence_index": 0, "correct_answer": "自体"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は自体が好きで、毎日勉強しています。", "explanation": "ここは〈対象〉の意味。接尾語の「自体」は名詞の後ろに付くもので、「好き」の対象を単独で指す語としては使えないので合わない。"}, {"text": "ここは店の本当の自体で、みんなが集まる場所です。", "explanation": "ここは〈本体・本質〉の意味。「本当の」と組み合わせて店の本質を指す語ではないので合わない。"}, {"text": "店が混むのは、自体のせいです。", "explanation": "ここは〈本体〉の意味。接尾語の「自体」は単独で原因を指す語ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7fa5edfe-0c0f-4bc2-8079-af983ceda906') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37861, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "自体", "is_correct": true, "explanation": "名詞の後ろに付いて学校そのものを強調し、「学校自体は小さい」と続く。"}, {"text": "寝具", "is_correct": false, "explanation": "寝るための道具を表し、「学校寝具は小さい」は成り立たない。"}, {"text": "休憩", "is_correct": false, "explanation": "一時的に休むことで、「学校休憩は小さい」と続かない。"}, {"text": "観光", "is_correct": false, "explanation": "旅行で名所を見ることで、「学校観光は小さい」は文として不自然。"}], "explanations": {"自体": "名詞の後ろに付いて学校そのものを強調し、「学校自体は小さい」と続く。", "寝具": "寝るための道具を表し、「学校寝具は小さい」は成り立たない。", "休憩": "一時的に休むことで、「学校休憩は小さい」と続かない。", "観光": "旅行で名所を見ることで、「学校観光は小さい」は文として不自然。"}, "sentence_index": 6, "correct_answer": "自体"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は一生懸命、自体を勉強しています。", "explanation": "ここは〈内容〉の意味。接尾語の「自体」は名詞の後ろに付くもので、「勉強」の対象を単独で指す語ではないので合わない。"}, {"text": "窓の外の自体で、雨が降ってきました。", "explanation": "ここは〈天気〉の意味。「自体」は物事そのものを指す接尾語で、天気の様子を表す語ではないので合わない。"}, {"text": "会議の自体が、おいしい料理を作りました。", "explanation": "ここは〈料理人〉の意味。会議は料理を作るものではなく、「自体」は人を指す語でもないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7fa5edfe-0c0f-4bc2-8079-af983ceda906') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37861, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この薬自体を、副作用が少ないです。", "corrected_sentence": "この薬自体は、副作用が少ないです。", "error_description": "主題を示すには「は」が正しい。「を」は目的語を示す助詞で、「少ないです」と続かないため誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7fa5edfe-0c0f-4bc2-8079-af983ceda906') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37861, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この学校自体を、古いですが、先生は親切です。", "corrected_sentence": "この学校自体は、古いですが、先生は親切です。", "error_description": "主題を示すには「は」が正しい。「を」は目的語を示す助詞で、「古いです」と続かないため誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7fa5edfe-0c0f-4bc2-8079-af983ceda906') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
