INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37862, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「〜にもとづく」の「に」。事実を基にして書かれたという関係を表す。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語を示すが、「もとづく」は「に」と続くので合わない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表すので、「もとづく」の基準を示せない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段や場所を示すので、「もとづく」の対象にはならない。"}], "correct_answer": "に", "explanations": {"に": "「〜にもとづく」の「に」。事実を基にして書かれたという関係を表す。", "を": "「を」は目的語を示すが、「もとづく」は「に」と続くので合わない。", "へ": "「へ」は方向を表すので、「もとづく」の基準を示せない。", "で": "「で」は手段や場所を示すので、「もとづく」の対象にはならない。"}, "error_tags": {"を": "object", "へ": "direction", "で": "means"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25a27df5-4741-4b2c-abc8-2a6286747f67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37862, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "ほんとうにあったこと。", "primary_collocate": null, "pronunciation": "じじつ", "ipa": "dʑidʑitsɯ", "syllable_count": 3, "sentences": [{"text": "これは作り話ではなく、事実です。", "target_word": "事実", "complexity_tier": "T3", "furigana": "これは作[つく]り話[ばなし]ではなく、事実[じじつ]です。", "sentence_source": "generated"}, {"text": "彼が昨日ここにいたのは事実だ。", "target_word": "事実", "complexity_tier": "T3", "furigana": "彼[かれ]が昨日[きのう]ここにいたのは事実[じじつ]だ。", "sentence_source": "generated"}, {"text": "事実を知って、わたしはとても驚いた。", "target_word": "事実", "complexity_tier": "T3", "furigana": "事実[じじつ]を知[し]って、わたしはとても驚[おどろ]いた。", "sentence_source": "generated"}, {"text": "うわさではなく、事実を話してください。", "target_word": "事実", "complexity_tier": "T3", "furigana": "うわさではなく、事実[じじつ]を話[はな]してください。", "sentence_source": "generated"}, {"text": "事実かどうか、自分の目で確かめたい。", "target_word": "事実", "complexity_tier": "T3", "furigana": "事実[じじつ]かどうか、自分[じぶん]の目[め]で確[たし]かめたい。", "sentence_source": "generated"}, {"text": "彼は事実をかくして、みんなにうそをついた。", "target_word": "事実", "complexity_tier": "T3", "furigana": "彼[かれ]は事実[じじつ]をかくして、みんなにうそをついた。", "sentence_source": "generated"}, {"text": "事実は、ときに物語より不思議なことがある。", "target_word": "事実", "complexity_tier": "T3", "furigana": "事実[じじつ]は、ときに物語[ものがたり]より不思議[ふしぎ]なことがある。", "sentence_source": "generated"}, {"text": "この話は事実にもとづいて書かれた。", "target_word": "事実", "complexity_tier": "T3", "furigana": "この話[はなし]は事実[じじつ]にもとづいて書[か]かれた。", "sentence_source": "generated"}, {"text": "事実と考えを分けて、作文を書きましょう。", "target_word": "事実", "complexity_tier": "T3", "furigana": "事実[じじつ]と考[かんが]えを分[わ]けて、作文[さくぶん]を書[か]きましょう。", "sentence_source": "generated"}, {"text": "記者は、見たことを事実のとおりに伝えた。", "target_word": "事実", "complexity_tier": "T3", "furigana": "記者[きしゃ]は、見[み]たことを事実[じじつ]のとおりに伝[つた]えた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "事実", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "something that really happened, as opposed to a made-up story or rumor", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '226e73b8-df71-4110-ab40-d23c9c97d88d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37862, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "事実", "is_correct": true, "explanation": "作り話と対比して、本当にあったことを表す語。文の意味に合う。"}, {"text": "天気", "is_correct": false, "explanation": "天気は作り話と対比される語ではないので、「天気です」では意味が通らない。"}, {"text": "切手", "is_correct": false, "explanation": "切手は作り話と対比されるものではなく、文の意味が合わない。"}, {"text": "落ち葉", "is_correct": false, "explanation": "落ち葉は作り話と対比されるものではなく、ここには入らない。"}], "explanations": {"事実": "作り話と対比して、本当にあったことを表す語。文の意味に合う。", "天気": "天気は作り話と対比される語ではないので、「天気です」では意味が通らない。", "切手": "切手は作り話と対比されるものではなく、文の意味が合わない。", "落ち葉": "落ち葉は作り話と対比されるものではなく、ここには入らない。"}, "sentence_index": 0, "correct_answer": "事実"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "わたしは来月の旅行の事実を、家族で立てた。", "explanation": "〈計画〉の意味で使う語。事実は既に起きたことを指すので、これから立てる旅行の予定には使わない。"}, {"text": "新しい部長は、チームの事実を部下からまとめて横取りした。", "explanation": "〈手柄〉の意味で使う語。事実は起きたことを指す語で、人の功績を横取りする対象にはならない。"}, {"text": "この宝石は事実だ。", "explanation": "〈本物〉の意味で使う語。事実は出来事や内容が本当であることを指し、物の真偽には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25a27df5-4741-4b2c-abc8-2a6286747f67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37862, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "事実", "is_correct": true, "explanation": "実際にあったことが物語より不思議だ、という文に合う。"}, {"text": "本棚", "is_correct": false, "explanation": "本棚は不思議なことが起きる主体にはならず、文の意味が合わない。"}, {"text": "押し入れ", "is_correct": false, "explanation": "押し入れは不思議なことがある、という文の主語として意味が通らない。"}, {"text": "段差", "is_correct": false, "explanation": "段差は物語と比べる対象にならず、文が成り立たない。"}], "explanations": {"事実": "実際にあったことが物語より不思議だ、という文に合う。", "本棚": "本棚は不思議なことが起きる主体にはならず、文の意味が合わない。", "押し入れ": "押し入れは不思議なことがある、という文の主語として意味が通らない。", "段差": "段差は物語と比べる対象にならず、文が成り立たない。"}, "sentence_index": 6, "correct_answer": "事実"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "今朝、窓から見える事実がとてもきれいだった。", "explanation": "〈景色〉の意味で使う語。事実は起きたことを指すので、窓から見えるながめを表す言葉としては使えない。"}, {"text": "将来の事実を、みんなの前で話した。", "explanation": "〈夢〉の意味で使う語。事実は実際のことを指すので、これから望むことには使わない。"}, {"text": "お皿の上の事実を、みんなで分けて食べた。", "explanation": "〈おやつ〉の意味で使う語。事実は起きたことを指すので、お皿に乗せて分けたり食べたりする食べ物にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25a27df5-4741-4b2c-abc8-2a6286747f67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37862, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "その話は事実に、記録に残っている。", "corrected_sentence": "その話は事実として、記録に残っている。", "error_description": "助詞の誤り：「事実として」の「として」（立場・資格）が正しい。「事実に」では「記録に残る」と続かず不自然。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25a27df5-4741-4b2c-abc8-2a6286747f67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37862, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この記事は事実をもとづいて書かれた。", "corrected_sentence": "この記事は事実にもとづいて書かれた。", "error_description": "助詞の誤り：「〜にもとづく」は「に」で続く。「を」では「もとづいて書かれた」の形が成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25a27df5-4741-4b2c-abc8-2a6286747f67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37863, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "と", "options": [{"text": "と", "is_correct": true, "explanation": "「事実として」の「と」。事実という立場から述べることを示す。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語を示すので、「事実をして」の形では文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表すので、ここでは使えない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段や場所を示すので、「事実でして」の形は合わない。"}], "correct_answer": "と", "explanations": {"と": "「事実として」の「と」。事実という立場から述べることを示す。", "を": "「を」は目的語を示すので、「事実をして」の形では文が成り立たない。", "へ": "「へ」は方向を表すので、ここでは使えない。", "で": "「で」は手段や場所を示すので、「事実でして」の形は合わない。"}, "error_tags": {"を": "object", "へ": "direction", "で": "means"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25a27df5-4741-4b2c-abc8-2a6286747f67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37863, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「事実が明らかにされた」の「が」。「明らかにされた」の主語として事実を示す。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語を示すが、「明らかにされた」は受け身なので事実は主語（が）になる。「事実を明らかにされた」は成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表すので、ここでは使えない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や相手を示すので、「事実と明らかにされた」は意味が通らない。"}], "correct_answer": "が", "explanations": {"が": "「事実が明らかにされた」の「が」。「明らかにされた」の主語として事実を示す。", "を": "「を」は目的語を示すが、「明らかにされた」は受け身なので事実は主語（が）になる。「事実を明らかにされた」は成り立たない。", "へ": "「へ」は方向を表すので、ここでは使えない。", "と": "「と」は並列や相手を示すので、「事実と明らかにされた」は意味が通らない。"}, "error_tags": {"を": "passive-object", "へ": "direction", "と": "comparison"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25a27df5-4741-4b2c-abc8-2a6286747f67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37863, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "実際に起こった事柄や現象。真実であると考えられる内容。", "primary_collocate": null, "pronunciation": "じじつ", "ipa": "dʑidʑitsɯ", "syllable_count": 3, "sentences": [{"text": "調査で、川の水が減っているという事実が分かった。", "target_word": "事実", "complexity_tier": "T3", "furigana": "調査[ちょうさ]で、川[かわ]の水[みず]が減[へ]っているという事実[じじつ]が分[わ]かった。", "sentence_source": "generated"}, {"text": "事実として、売り上げは去年より二割増えている。", "target_word": "事実", "complexity_tier": "T3", "furigana": "事実[じじつ]として、売[う]り上[あ]げは去年[きょねん]より二割[にわり]増[ふ]えている。", "sentence_source": "generated"}, {"text": "警察は、事件の事実を一つずつ調べている。", "target_word": "事実", "complexity_tier": "T3", "furigana": "警察[けいさつ]は、事件[じけん]の事実[じじつ]を一[ひと]つずつ調[しら]べている。", "sentence_source": "generated"}, {"text": "その発表は、事実とは異なる内容を含んでいた。", "target_word": "事実", "complexity_tier": "T3", "furigana": "その発表[はっぴょう]は、事実[じじつ]とは異[こと]なる内容[ないよう]を含[ふく]んでいた。", "sentence_source": "generated"}, {"text": "彼は自分の失敗を事実として受け止めた。", "target_word": "事実", "complexity_tier": "T3", "furigana": "彼[かれ]は自分[じぶん]の失敗[しっぱい]を事実[じじつ]として受[う]け止[と]めた。", "sentence_source": "generated"}, {"text": "科学者は、観察で得た事実から結論を出す。", "target_word": "事実", "complexity_tier": "T3", "furigana": "科学者[かがくしゃ]は、観察[かんさつ]で得[え]た事実[じじつ]から結論[けつろん]を出[だ]す。", "sentence_source": "generated"}, {"text": "目の前の事実から目をそらしてはいけない。", "target_word": "事実", "complexity_tier": "T3", "furigana": "目[め]の前[まえ]の事実[じじつ]から目[め]をそらしてはいけない。", "sentence_source": "generated"}, {"text": "裁判では、証拠によって事実が明らかにされた。", "target_word": "事実", "complexity_tier": "T3", "furigana": "裁判[さいばん]では、証拠[しょうこ]によって事実[じじつ]が明[あき]らかにされた。", "sentence_source": "generated"}, {"text": "この記事は、確かな事実だけを集めて書かれている。", "target_word": "事実", "complexity_tier": "T3", "furigana": "この記事[きじ]は、確[たし]かな事実[じじつ]だけを集[あつ]めて書[か]かれている。", "sentence_source": "generated"}, {"text": "地球が丸いのは、疑いようのない事実である。", "target_word": "事実", "complexity_tier": "T3", "furigana": "地球[ちきゅう]が丸[まる]いのは、疑[うたが]いようのない事実[じじつ]である。", "sentence_source": "generated"}], "morphological_forms": [{"form": "事実", "label": "基本形"}], "register": "formal-written", "sense_fingerprint": "verifiable fact or actual occurrence, backed by evidence or observation", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '226e73b8-df71-4110-ab40-d23c9c97d88d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37863, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "事実", "is_correct": true, "explanation": "調査で分かった内容として、川の水が減っている事柄を指し、文に合う。"}, {"text": "切手", "is_correct": false, "explanation": "切手は分かったという内容にならないので、文の意味が通らない。"}, {"text": "落ち葉", "is_correct": false, "explanation": "落ち葉は調査で分かる内容ではなく、「という落ち葉が分かった」は成り立たない。"}, {"text": "大雨", "is_correct": false, "explanation": "大雨は川の水が減っていることの内容として「分かった」と結び付かず、文の意味が合わない。"}], "explanations": {"事実": "調査で分かった内容として、川の水が減っている事柄を指し、文に合う。", "切手": "切手は分かったという内容にならないので、文の意味が通らない。", "落ち葉": "落ち葉は調査で分かる内容ではなく、「という落ち葉が分かった」は成り立たない。", "大雨": "大雨は川の水が減っていることの内容として「分かった」と結び付かず、文の意味が合わない。"}, "sentence_index": 0, "correct_answer": "事実"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼の事実は、ほぼ当たっていた。", "explanation": "〈推測〉の意味で使う語。事実は起きたことなので、当たるという言い方はしない。"}, {"text": "天気の事実は、夜には外れてしまった。", "explanation": "〈予想〉の意味で使う語。事実は既に起きたことで、当たる・外れるとは言わない。"}, {"text": "寒さの事実が、少しずつ消えていった。", "explanation": "〈感覚〉の意味で使う語。事実は確かな内容を指し、体で感じる感覚には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25a27df5-4741-4b2c-abc8-2a6286747f67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37863, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "事実", "is_correct": true, "explanation": "目の前の対象として、目をそらしてはいけないものを表し、文の意味に合う。"}, {"text": "お茶", "is_correct": false, "explanation": "お茶は目をそらしてはいけない対象とは言えず、「目の前のお茶から目をそらす」は不自然。"}, {"text": "眠気", "is_correct": false, "explanation": "眠気は目の前の対象ではなく、「目の前の眠気から目をそらす」は意味が通らない。"}, {"text": "寒さ", "is_correct": false, "explanation": "寒さは目の前の対象として文に入らず、「目の前の寒さから目をそらす」は不自然。"}], "explanations": {"事実": "目の前の対象として、目をそらしてはいけないものを表し、文の意味に合う。", "お茶": "お茶は目をそらしてはいけない対象とは言えず、「目の前のお茶から目をそらす」は不自然。", "眠気": "眠気は目の前の対象ではなく、「目の前の眠気から目をそらす」は意味が通らない。", "寒さ": "寒さは目の前の対象として文に入らず、「目の前の寒さから目をそらす」は不自然。"}, "sentence_index": 6, "correct_answer": "事実"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "明日は晴れるように、事実を込める。", "explanation": "〈願い〉の意味で使う語。事実は確かな内容を指し、込めたり祈ったりするものではない。"}, {"text": "今日の運勢は、事実で見るとよく分かる。", "explanation": "〈占い〉の意味で使う語。事実は実際の内容を指し、運勢を占う方法としては使えない。"}, {"text": "夕方になると、空の事実が変わった。", "explanation": "〈色〉の意味で使う語。事実は確かな内容を指し、空の色の変化には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25a27df5-4741-4b2c-abc8-2a6286747f67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37863, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "その報告は、事実に新聞に載った。", "corrected_sentence": "その報告は、事実として新聞に載った。", "error_description": "助詞の誤り：「事実として」の「として」（立場・資格）が正しい。「事実に」では「新聞に載る」と続かず不自然。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25a27df5-4741-4b2c-abc8-2a6286747f67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37863, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "裁判では、証拠によって事実を明らかになった。", "corrected_sentence": "裁判では、証拠によって事実が明らかになった。", "error_description": "助詞の誤り：「事実が明らかになる」と主語の「が」が正しい。「を」では「明らかになった」（自動詞）の目的語にならず不自然。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25a27df5-4741-4b2c-abc8-2a6286747f67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37864, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「神話を話す（語る）」の目的語を示す格助詞。"}, {"text": "が", "is_correct": false, "explanation": "「神話が話してくれた」では神話が話し手になり、祖父の行為と噛み合わない。"}, {"text": "に", "is_correct": false, "explanation": "「神話に話してくれた」は話す相手を示す形で、話す内容の神話には使えず不自然。"}, {"text": "へ", "is_correct": false, "explanation": "「神話へ話す」は方向を表すが、話す対象の物語には合わない。"}], "correct_answer": "を", "explanations": {"を": "「神話を話す（語る）」の目的語を示す格助詞。", "が": "「神話が話してくれた」では神話が話し手になり、祖父の行為と噛み合わない。", "に": "「神話に話してくれた」は話す相手を示す形で、話す内容の神話には使えず不自然。", "へ": "「神話へ話す」は方向を表すが、話す対象の物語には合わない。"}, "error_tags": {"が": "主語", "に": "相手", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a7f176f-54da-4761-b24e-95a6f306599d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37864, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a7f176f-54da-4761-b24e-95a6f306599d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37864, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "むかしの人が考えた、たいせつな物語。", "primary_collocate": null, "pronunciation": "しんわ", "ipa": "ɕinwa", "syllable_count": 3, "sentences": [{"text": "むかしの人は、雨や雷の理由を神話で説明しようとした。", "target_word": "神話", "complexity_tier": "T3", "furigana": "むかしの人[ひと]は、雨[あめ]や雷[かみなり]の理由[りゆう]を神話[しんわ]で説明[せつめい]しようとした。", "sentence_source": "generated"}, {"text": "祖父は寝る前に、ギリシャの神話を話してくれた。", "target_word": "神話", "complexity_tier": "T3", "furigana": "祖父[そふ]は寝[ね]る前[まえ]に、ギリシャの神話[しんわ]を話[はな]してくれた。", "sentence_source": "generated"}, {"text": "この神話では、太陽の神が空を毎日歩いて回る。", "target_word": "神話", "complexity_tier": "T3", "furigana": "この神話[しんわ]では、太陽[たいよう]の神[かみ]が空[そら]を毎日[まいにち]歩[ある]いて回[まわ]る。", "sentence_source": "generated"}, {"text": "図書館で神話の本を借りて、週末に読んだ。", "target_word": "神話", "complexity_tier": "T3", "furigana": "図書館[としょかん]で神話[しんわ]の本[ほん]を借[か]りて、週末[しゅうまつ]に読[よ]んだ。", "sentence_source": "generated"}, {"text": "星の動きを不思議に思った人々が、それを神話として語り継いだ。", "target_word": "神話", "complexity_tier": "T3", "furigana": "星[ほし]の動[うご]きを不思議[ふしぎ]に思[おも]った人々[ひとびと]が、それを神話[しんわ]として語[かた]り継[つ]いだ。", "sentence_source": "generated"}, {"text": "この島には、海から生まれた島の神話が伝わっている。", "target_word": "神話", "complexity_tier": "T3", "furigana": "この島[しま]には、海[うみ]から生[う]まれた島[しま]の神話[しんわ]が伝[つた]わっている。", "sentence_source": "generated"}, {"text": "神話に出てくる神様は、人間のように泣いたり笑ったりする。", "target_word": "神話", "complexity_tier": "T3", "furigana": "神話[しんわ]に出[で]てくる神様[かみさま]は、人間[にんげん]のように泣[な]いたり笑[わら]ったりする。", "sentence_source": "generated"}, {"text": "子どものころ、私は神話の絵本が大好きだった。", "target_word": "神話", "complexity_tier": "T3", "furigana": "子[こ]どものころ、私[わたし]は神話[しんわ]の絵本[えほん]が大好[だいす]きだった。", "sentence_source": "generated"}, {"text": "神話は、むかしの人の考え方を知る手がかりになる。", "target_word": "神話", "complexity_tier": "T3", "furigana": "神話[しんわ]は、むかしの人[ひと]の考[かんが]え方[かた]を知[し]る手[て]がかりになる。", "sentence_source": "generated"}, {"text": "先生は、授業で世界のいろいろな神話を紹介した。", "target_word": "神話", "complexity_tier": "T3", "furigana": "先生[せんせい]は、授業[じゅぎょう]で世界[せかい]のいろいろな神話[しんわ]を紹介[しょうかい]した。", "sentence_source": "generated"}], "morphological_forms": [{"form": "神話", "label": "基本形"}], "register": "一般", "sense_fingerprint": "むかしの人が世界や自然を説明するために語った、神様の物語", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98f6d5a5-9f90-4330-858e-b3c0b9ee5e3c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37864, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "神話", "is_correct": true, "explanation": "神々や世界の成り立ちを語る物語は、雨や雷の理由を説明する手段として文の内容に合う。"}, {"text": "靴下", "is_correct": false, "explanation": "靴下で雨や雷の理由を説明することはできず、文の意味が成り立たない。"}, {"text": "駅", "is_correct": false, "explanation": "駅は理由を説明する手段にならず、文脈に合わない。"}, {"text": "体重", "is_correct": false, "explanation": "体重では雨や雷の理由を説明できず、意味が通らない。"}], "explanations": {"神話": "神々や世界の成り立ちを語る物語は、雨や雷の理由を説明する手段として文の内容に合う。", "靴下": "靴下で雨や雷の理由を説明することはできず、文の意味が成り立たない。", "駅": "駅は理由を説明する手段にならず、文脈に合わない。", "体重": "体重では雨や雷の理由を説明できず、意味が通らない。"}, "sentence_index": 0, "correct_answer": "神話"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この神話は、王子とお姫様が結ばれる、子ども向けの楽しいお話だ。", "explanation": "ここは〈童話〉の意味。神話は神々や英雄の古い物語で、王子とお姫様の恋の話には使わない。"}, {"text": "その先生には、生徒を驚かせた神話がたくさんある。", "explanation": "ここは〈逸話〉の意味。神話は神々や英雄の古い物語で、身近な人の小話には使わない。"}, {"text": "この神話は、働き者のアリを褒める短い話で、最後に一文の教訓が添えられている。", "explanation": "ここは〈寓話〉の意味。動物などを登場させ、結びに一文の教訓を添える短い話で、神々の物語である神話とは違う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a7f176f-54da-4761-b24e-95a6f306599d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37864, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "神話", "is_correct": true, "explanation": "「神話に出てくる神様」は神々が登場する物語を指し、文の内容に合う。"}, {"text": "天気", "is_correct": false, "explanation": "天気に神様が出てくる文は意味をなさない。"}, {"text": "電池", "is_correct": false, "explanation": "電池に神様が出てくる文は成り立たない。"}, {"text": "財布", "is_correct": false, "explanation": "財布に神様が出てくるのは不自然で、文脈に合わない。"}], "explanations": {"神話": "「神話に出てくる神様」は神々が登場する物語を指し、文の内容に合う。", "天気": "天気に神様が出てくる文は意味をなさない。", "電池": "電池に神様が出てくる文は成り立たない。", "財布": "財布に神様が出てくるのは不自然で、文脈に合わない。"}, "sentence_index": 6, "correct_answer": "神話"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼の自慢話は、ほとんどが神話だ。", "explanation": "ここは〈作り話〉の意味。神話は多くの人が語り継いだ物語で、個人のうそ話には使わない。"}, {"text": "隣の家の神話が広まって、町中が大騒ぎになった。", "explanation": "ここは〈噂話〉の意味。神話は神々や英雄の物語で、人の噂には使わない。"}, {"text": "彼の計画は、資金も人手もない神話だ。", "explanation": "ここは〈夢物語〉の意味。神話は神々の時代の物語で、実現しない計画には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a7f176f-54da-4761-b24e-95a6f306599d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37864, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "祖父は寝る前に、ギリシャの神話に語ってくれた。", "corrected_sentence": "祖父は寝る前に、ギリシャの神話を語ってくれた。", "error_description": "助詞の誤り。「語る」の目的語は「を」で示すので、「神話に」は「神話を」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a7f176f-54da-4761-b24e-95a6f306599d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37864, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "先生は、授業で世界のいろいろな神話を紹介されている。", "corrected_sentence": "先生は、授業で世界のいろいろな神話を紹介している。", "error_description": "動詞の形の誤り。「紹介する」は神話を目的語にとるので「神話を紹介されている」は誤り。受身にするなら「神話が紹介されている」となる。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a7f176f-54da-4761-b24e-95a6f306599d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37865, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「神話を比べて」の「を」は、比べる対象を示す。"}, {"text": "が", "is_correct": false, "explanation": "「神話が比べて」では神話が比べる主体になり、研究者の行為と噛み合わない。"}, {"text": "へ", "is_correct": false, "explanation": "「神話へ比べて」は方向を示すが、比較の基準・対象の形としては成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "「神話の比べて」は連体の「の」で、動詞「比べて」の目的語にならず非文。"}], "correct_answer": "を", "explanations": {"を": "「神話を比べて」の「を」は、比べる対象を示す。", "が": "「神話が比べて」では神話が比べる主体になり、研究者の行為と噛み合わない。", "へ": "「神話へ比べて」は方向を示すが、比較の基準・対象の形としては成り立たない。", "の": "「神話の比べて」は連体の「の」で、動詞「比べて」の目的語にならず非文。"}, "error_tags": {"が": "主語", "へ": "方向", "の": "連体"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a7f176f-54da-4761-b24e-95a6f306599d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37865, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「神話を題材にした」の「を」は、題材として扱う対象を示す。"}, {"text": "に", "is_correct": false, "explanation": "「神話に題材にした」は神話を位置や相手として示すことになり、題材の対象として合わない。"}, {"text": "へ", "is_correct": false, "explanation": "「神話へ題材にした」は方向を示すが、題材の対象としては成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「神話と題材にした」は並列を示すが、題材の対象を指定する形にはならない。"}], "correct_answer": "を", "explanations": {"を": "「神話を題材にした」の「を」は、題材として扱う対象を示す。", "に": "「神話に題材にした」は神話を位置や相手として示すことになり、題材の対象として合わない。", "へ": "「神話へ題材にした」は方向を示すが、題材の対象としては成り立たない。", "と": "「神話と題材にした」は並列を示すが、題材の対象を指定する形にはならない。"}, "error_tags": {"に": "位置", "へ": "方向", "と": "並列"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a7f176f-54da-4761-b24e-95a6f306599d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37865, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "神や英雄などを中心とした、民族や文化の体系的な物語。伝説や説話と区別され、宗教や世界観と深く結びついている。", "primary_collocate": null, "pronunciation": "しんわ", "ipa": "ɕinwa", "syllable_count": 3, "sentences": [{"text": "神話は、神や英雄の行いを通して、その民族の世界観を表している。", "target_word": "神話", "complexity_tier": "T3", "furigana": "神話[しんわ]は、神[かみ]や英雄[えいゆう]の行[おこな]いを通[とお]して、その民族[みんぞく]の世界観[せかいかん]を表[あらわ]している。", "sentence_source": "generated"}, {"text": "研究者は、各地の神話を比べて、共通する物語の型を探した。", "target_word": "神話", "complexity_tier": "T3", "furigana": "研究者[けんきゅうしゃ]は、各地[かくち]の神話[しんわ]を比[くら]べて、共通[きょうつう]する物語[ものがたり]の型[かた]を探[さが]した。", "sentence_source": "generated"}, {"text": "天地創造を語る神話は、多くの文化に見られる。", "target_word": "神話", "complexity_tier": "T3", "furigana": "天地創造[てんちそうぞう]を語[かた]る神話[しんわ]は、多[おお]くの文化[ぶんか]に見[み]られる。", "sentence_source": "generated"}, {"text": "神話は伝説とは違い、神々の世界と宗教の儀式に結びついている。", "target_word": "神話", "complexity_tier": "T3", "furigana": "神話[しんわ]は伝説[でんせつ]とは違[ちが]い、神々[かみがみ]の世界[せかい]と宗教[しゅうきょう]の儀式[ぎしき]に結[むす]びついている。", "sentence_source": "generated"}, {"text": "ギリシャの神話では、ゼウスが神々の王として描かれる。", "target_word": "神話", "complexity_tier": "T3", "furigana": "ギリシャの神話[しんわ]では、ゼウスが神々[かみがみ]の王[おう]として描[えが]かれる。", "sentence_source": "generated"}, {"text": "この民族の神話には、洪水で世界が滅びる話が含まれている。", "target_word": "神話", "complexity_tier": "T3", "furigana": "この民族[みんぞく]の神話[しんわ]には、洪水[こうずい]で世界[せかい]が滅[ほろ]びる話[はなし]が含[ふく]まれている。", "sentence_source": "generated"}, {"text": "古代の神話は、季節の移り変わりや死の意味を説明していた。", "target_word": "神話", "complexity_tier": "T3", "furigana": "古代[こだい]の神話[しんわ]は、季節[きせつ]の移[うつ]り変[か]わりや死[し]の意味[いみ]を説明[せつめい]していた。", "sentence_source": "generated"}, {"text": "その画家は、北欧の神話を題材にした連作を描いた。", "target_word": "神話", "complexity_tier": "T3", "furigana": "その画家[がか]は、北欧[ほくおう]の神話[しんわ]を題材[だいざい]にした連作[れんさく]を描[えが]いた。", "sentence_source": "generated"}, {"text": "神話を読むと、その社会が何を大切にしていたかが分かる。", "target_word": "神話", "complexity_tier": "T3", "furigana": "神話[しんわ]を読[よ]むと、その社会[しゃかい]が何[なに]を大切[たいせつ]にしていたかが分[わ]かる。", "sentence_source": "generated"}, {"text": "神話は口承で伝えられ、後に文字で記録されたものが多い。", "target_word": "神話", "complexity_tier": "T3", "furigana": "神話[しんわ]は口承[こうしょう]で伝[つた]えられ、後[のち]に文字[もじ]で記録[きろく]されたものが多[おお]い。", "sentence_source": "generated"}], "morphological_forms": [{"form": "神話", "label": "基本形"}], "register": "書き言葉", "sense_fingerprint": "神々や英雄を軸に民族の世界観と宗教を語る、体系的な物語", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 9 above tier T3: contains vocabulary far above tier T3: 口承 (Zipf 1.96)']::text[], '98f6d5a5-9f90-4330-858e-b3c0b9ee5e3c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37865, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "神話", "is_correct": true, "explanation": "神々や英雄を軸に民族の世界観を表すという文の内容に合うのは神話。"}, {"text": "掃除機", "is_correct": false, "explanation": "掃除機が神や英雄の行いを通して世界観を表すのは意味が通らない。"}, {"text": "時計", "is_correct": false, "explanation": "時計は世界観を表す主語として成り立たない。"}, {"text": "座布団", "is_correct": false, "explanation": "座布団は民族の世界観を表すことはできず、文が成り立たない。"}], "explanations": {"神話": "神々や英雄を軸に民族の世界観を表すという文の内容に合うのは神話。", "掃除機": "掃除機が神や英雄の行いを通して世界観を表すのは意味が通らない。", "時計": "時計は世界観を表す主語として成り立たない。", "座布団": "座布団は民族の世界観を表すことはできず、文が成り立たない。"}, "sentence_index": 0, "correct_answer": "神話"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この神話は、貧しい若者が知恵で長者になる、村の民話だ。", "explanation": "ここは〈民話〉の意味。土地に伝わる素朴な話を指し、神々や英雄を中心とした体系的な神話とは区別される。"}, {"text": "この神話は、筆者が若いころの失敗を率直に書いた随筆だ。", "explanation": "ここは〈随筆〉の意味。筆者の体験や考えを綴る文章で、神々の物語である神話とは違う。"}, {"text": "この神話は、池のカエルが仲間を助けて、最後に一文の教訓で結ばれる短い話だ。", "explanation": "ここは〈寓話〉の意味。結びに教訓を添える短い話で、神々や英雄を中心とした体系的な神話とは違う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a7f176f-54da-4761-b24e-95a6f306599d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37865, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "神話", "is_correct": true, "explanation": "神話が季節の移り変わりや死の意味を説明する、という文の内容に合う。"}, {"text": "定規", "is_correct": false, "explanation": "定規は季節や死の意味を説明できず、文として成り立たない。"}, {"text": "体温計", "is_correct": false, "explanation": "体温計が季節の移り変わりを説明するのは意味が通らない。"}, {"text": "冷蔵庫", "is_correct": false, "explanation": "冷蔵庫は季節や死の意味を説明する主語にはならない。"}], "explanations": {"神話": "神話が季節の移り変わりや死の意味を説明する、という文の内容に合う。", "定規": "定規は季節や死の意味を説明できず、文として成り立たない。", "体温計": "体温計が季節の移り変わりを説明するのは意味が通らない。", "冷蔵庫": "冷蔵庫は季節や死の意味を説明する主語にはならない。"}, "sentence_index": 6, "correct_answer": "神話"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この本は、ある実業家が一代で財をなした経緯を、事実に基づいて記した神話だ。", "explanation": "ここは〈伝記〉の意味。実在の人物の生涯を事実に基づいて記すもので、神々や英雄を中心とした神話とは区別される。"}, {"text": "この神話は、現代の若者の恋を描いている。", "explanation": "ここは〈物語〉の意味。神話は神々や英雄を中心とした古い体系的な話で、現代の恋愛を描く作品には合わない。"}, {"text": "その村では、雨乞いの手順を書いた神話を今も代々守っている。", "explanation": "ここは〈手引き〉の意味。手順を示す実用の文書で、神々や英雄の物語である神話とは違う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a7f176f-54da-4761-b24e-95a6f306599d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37865, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "研究者は、各地の神話が比べて、共通する物語の型を分析した。", "corrected_sentence": "研究者は、各地の神話を比べて、共通する物語の型を分析した。", "error_description": "助詞の誤り。「比べる」の目的語は「を」で示す。「神話が」では神話が主語となり、研究者の行為と噛み合わない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a7f176f-54da-4761-b24e-95a6f306599d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37865, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "祖母は、眠る前に神話を食べてくれた。", "corrected_sentence": "祖母は、眠る前に神話を語ってくれた。", "error_description": "動詞の誤り。神話は語られるものなので「食べる」とは結びつかない。物語を伝える「語る」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a7f176f-54da-4761-b24e-95a6f306599d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37866, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「寓話を読んで聞かせた」の「を」は、読む対象を示す。"}, {"text": "が", "is_correct": false, "explanation": "「寓話が聞かせた」では寓話が聞かせる主体になり、先生の行為と噛み合わない。"}, {"text": "に", "is_correct": false, "explanation": "「寓話に読んで聞かせた」は位置や相手を示すが、読む対象を示せない。"}, {"text": "へ", "is_correct": false, "explanation": "「寓話へ読んで聞かせた」は方向を示すが、読む対象としては不自然。"}], "correct_answer": "を", "explanations": {"を": "「寓話を読んで聞かせた」の「を」は、読む対象を示す。", "が": "「寓話が聞かせた」では寓話が聞かせる主体になり、先生の行為と噛み合わない。", "に": "「寓話に読んで聞かせた」は位置や相手を示すが、読む対象を示せない。", "へ": "「寓話へ読んで聞かせた」は方向を示すが、読む対象としては不自然。"}, "error_tags": {"が": "主語", "に": "相手", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a7f176f-54da-4761-b24e-95a6f306599d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37866, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「寓話に出てくる」の「に」は、登場する範囲や場所を示す。"}, {"text": "を", "is_correct": false, "explanation": "「寓話を出てくる」は目的語の「を」では、自動詞の「出てくる」と噛み合わない。"}, {"text": "や", "is_correct": false, "explanation": "「寓話や出てくる」は並列の形で、「出てくる」の範囲を示せず不自然。"}, {"text": "と", "is_correct": false, "explanation": "「寓話と出てくる」は並列を示すが、動物の登場の示し方として不自然。"}], "correct_answer": "に", "explanations": {"に": "「寓話に出てくる」の「に」は、登場する範囲や場所を示す。", "を": "「寓話を出てくる」は目的語の「を」では、自動詞の「出てくる」と噛み合わない。", "や": "「寓話や出てくる」は並列の形で、「出てくる」の範囲を示せず不自然。", "と": "「寓話と出てくる」は並列を示すが、動物の登場の示し方として不自然。"}, "error_tags": {"を": "目的語", "や": "並列", "と": "並列"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a7f176f-54da-4761-b24e-95a6f306599d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37866, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "動物などが出てきて、教えを伝えるお話。", "primary_collocate": null, "pronunciation": "ぐうわ", "ipa": "ɡɯːwa", "syllable_count": 3, "sentences": [{"text": "「アリとキリギリス」は、働くことの大切さを教える寓話だ。", "target_word": "寓話", "complexity_tier": "T3", "furigana": "「アリとキリギリス」は、働[はたら]くことの大切[たいせつ]さを教[おし]える寓話[ぐうわ]だ。", "sentence_source": "generated"}, {"text": "先生は、動物が出てくる寓話を子どもたちに読んで聞かせた。", "target_word": "寓話", "complexity_tier": "T3", "furigana": "先生[せんせい]は、動物[どうぶつ]が出[で]てくる寓話[ぐうわ]を子[こ]どもたちに読[よ]んで聞[き]かせた。", "sentence_source": "generated"}, {"text": "この寓話では、ずるいキツネが最後に失敗する。", "target_word": "寓話", "complexity_tier": "T3", "furigana": "この寓話[ぐうわ]では、ずるいキツネが最後[さいご]に失敗[しっぱい]する。", "sentence_source": "generated"}, {"text": "寓話を読んで、うそをつかない大切さを学んだ。", "target_word": "寓話", "complexity_tier": "T3", "furigana": "寓話[ぐうわ]を読[よ]んで、うそをつかない大切[たいせつ]さを学[まな]んだ。", "sentence_source": "generated"}, {"text": "イソップの寓話は、世界中の子どもに読まれている。", "target_word": "寓話", "complexity_tier": "T3", "furigana": "イソップの寓話[ぐうわ]は、世界中[せかいじゅう]の子[こ]どもに読[よ]まれている。", "sentence_source": "generated"}, {"text": "弟は寓話が好きで、動物の話を何度も読み返す。", "target_word": "寓話", "complexity_tier": "T3", "furigana": "弟[おとうと]は寓話[ぐうわ]が好[す]きで、動物[どうぶつ]の話[はなし]を何度[なんど]も読[よ]み返[かえ]す。", "sentence_source": "generated"}, {"text": "この寓話の教えは、「ゆっくりでも続けることが大切」ということだ。", "target_word": "寓話", "complexity_tier": "T3", "furigana": "この寓話[ぐうわ]の教[おし]えは、「ゆっくりでも続[つづ]けることが大切[たいせつ]」ということだ。", "sentence_source": "generated"}, {"text": "寓話に出てくる動物は、人間のように話す。", "target_word": "寓話", "complexity_tier": "T3", "furigana": "寓話[ぐうわ]に出[で]てくる動物[どうぶつ]は、人間[にんげん]のように話[はな]す。", "sentence_source": "generated"}, {"text": "母は、寓話を使って私に正直であることを教えた。", "target_word": "寓話", "complexity_tier": "T3", "furigana": "母[はは]は、寓話[ぐうわ]を使[つか]って私[わたし]に正直[しょうじき]であることを教[おし]えた。", "sentence_source": "generated"}, {"text": "授業のあとで、寓話から学んだことを作文に書いた。", "target_word": "寓話", "complexity_tier": "T3", "furigana": "授業[じゅぎょう]のあとで、寓話[ぐうわ]から学[まな]んだことを作文[さくぶん]に書[か]いた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "寓話", "label": "基本形"}], "register": "一般", "sense_fingerprint": "動物が登場して大切な教えを伝える短いお話", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98f6d5a5-9f90-4330-858e-b3c0b9ee5e3c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37866, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "寓話", "is_correct": true, "explanation": "「働くことの大切さを教える寓話だ」は、動物などが登場して教えを伝える話という文の内容に合う。"}, {"text": "年表", "is_correct": false, "explanation": "年表は教えを伝える話の種類ではなく、文の内容に合わない。"}, {"text": "洗濯機", "is_correct": false, "explanation": "洗濯機は教えを伝える話ではなく、「教える洗濯機」は文の内容に合わない。"}, {"text": "体温計", "is_correct": false, "explanation": "体温計は教えを伝える話ではなく、「教える体温計」は文の内容に合わない。"}], "explanations": {"寓話": "「働くことの大切さを教える寓話だ」は、動物などが登場して教えを伝える話という文の内容に合う。", "年表": "年表は教えを伝える話の種類ではなく、文の内容に合わない。", "洗濯機": "洗濯機は教えを伝える話ではなく、「教える洗濯機」は文の内容に合わない。", "体温計": "体温計は教えを伝える話ではなく、「教える体温計」は文の内容に合わない。"}, "sentence_index": 0, "correct_answer": "寓話"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "「急がば回れ」は、先人が残した寓話だ。", "explanation": "ここは〈格言〉の意味。動物などが登場する話ではないので、ことわざや格言を寓話とは言わない。"}, {"text": "この寓話は、実際にあった出来事を記した実話だ。", "explanation": "ここは〈実話〉の意味。寓話は作り話で、実際の出来事を語る話には使わない。"}, {"text": "この寓話は、神々が世界を創ったという話だ。", "explanation": "ここは〈神話〉の意味。神々の起源を語る話で、動物が出て教えを伝える寓話とは違う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a7f176f-54da-4761-b24e-95a6f306599d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37866, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "寓話", "is_correct": true, "explanation": "「この寓話の教えは、…ということだ」は、寓話が持つ教えとして文脈に合う。"}, {"text": "辞典", "is_correct": false, "explanation": "辞典は教えを持つ話ではなく、「この辞典の教え」は文脈に合わない。"}, {"text": "時刻表", "is_correct": false, "explanation": "時刻表は教えを持たず、「教え」の説明にならない。"}, {"text": "電卓", "is_correct": false, "explanation": "電卓には教えがなく、「この電卓の教え」は文脈に合わない。"}], "explanations": {"寓話": "「この寓話の教えは、…ということだ」は、寓話が持つ教えとして文脈に合う。", "辞典": "辞典は教えを持つ話ではなく、「この辞典の教え」は文脈に合わない。", "時刻表": "時刻表は教えを持たず、「教え」の説明にならない。", "電卓": "電卓には教えがなく、「この電卓の教え」は文脈に合わない。"}, "sentence_index": 6, "correct_answer": "寓話"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "授業のあとで、先輩の寓話を聞いて、部活の失敗を作文に書いた。", "explanation": "ここは〈体験談〉の意味。寓話は作り話で、実際の失敗を語る話には使わない。"}, {"text": "この寓話は、江戸時代の出来事を記録した歴史書だ。", "explanation": "ここは〈歴史書〉の意味。実際の出来事を記す書物を指し、動物が登場して教えを伝える寓話とは違う。"}, {"text": "この寓話は、村の山に住む龍が川を守ったという伝説だ。", "explanation": "ここは〈伝説〉の意味。土地に結びついた言い伝えを指し、教訓を伝える動物の話の寓話とは違う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a7f176f-54da-4761-b24e-95a6f306599d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37866, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "私は寓話が、ずるいキツネが最後に失敗するという教えを学んだ。", "corrected_sentence": "私は寓話から、ずるいキツネが最後に失敗するという教えを学んだ。", "error_description": "助詞の誤り。「学ぶ」の起点は「から」で示す。「寓話が」では寓話が学ぶ主体になってしまい、文が成り立たない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a7f176f-54da-4761-b24e-95a6f306599d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37866, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "弟は寓話をかじるほど、動物の話が好きだ。", "corrected_sentence": "弟は寓話を読むほど、動物の話が好きだ。", "error_description": "動詞の誤り。寓話は「読む」もので、「かじる」とは結びつかない。「読む」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a7f176f-54da-4761-b24e-95a6f306599d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
