INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37867, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "主題を示す「は」で、文の話題となる寓話を示す。"}, {"text": "を", "is_correct": false, "explanation": "「寓話を翻訳されてきた」は目的語の「を」と受身が噛み合わず、文が成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「寓話に翻訳されてきた」は相手を示すが、翻訳される対象の主語としては不自然。"}, {"text": "と", "is_correct": false, "explanation": "「寓話と翻訳されてきた」は並列を示すが、主語として成り立たない。"}], "correct_answer": "は", "explanations": {"は": "主題を示す「は」で、文の話題となる寓話を示す。", "を": "「寓話を翻訳されてきた」は目的語の「を」と受身が噛み合わず、文が成り立たない。", "に": "「寓話に翻訳されてきた」は相手を示すが、翻訳される対象の主語としては不自然。", "と": "「寓話と翻訳されてきた」は並列を示すが、主語として成り立たない。"}, "error_tags": {"を": "目的語", "に": "相手", "と": "並列"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a7f176f-54da-4761-b24e-95a6f306599d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37867, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "教訓を含んだ短い物語。特に、動物や無生物を擬人化して道徳的な教えを伝える話。", "primary_collocate": null, "pronunciation": "ぐうわ", "ipa": "ɡɯːwa", "syllable_count": 3, "sentences": [{"text": "寓話は、短い物語の中に道徳的な教訓を込めた文学の形式である。", "target_word": "寓話", "complexity_tier": "T3", "furigana": "寓話[ぐうわ]は、短[みじか]い物語[ものがたり]の中[なか]に道徳的[どうとくてき]な教訓[きょうくん]を込[こ]めた文学[ぶんがく]の形式[けいしき]である。", "sentence_source": "generated"}, {"text": "作者は、権力者を批判するために、動物を主人公にした寓話を書いた。", "target_word": "寓話", "complexity_tier": "T3", "furigana": "作者[さくしゃ]は、権力者[けんりょくしゃ]を批判[ひはん]するために、動物[どうぶつ]を主人公[しゅじんこう]にした寓話[ぐうわ]を書[か]いた。", "sentence_source": "generated"}, {"text": "ラ・フォンテーヌの寓話は、風刺と教訓に満ちている。", "target_word": "寓話", "complexity_tier": "T3", "furigana": "ラ・フォンテーヌの寓話[ぐうわ]は、風刺[ふうし]と教訓[きょうくん]に満[み]ちている。", "sentence_source": "generated"}, {"text": "この寓話では、擬人化された風と太陽が力くらべをする。", "target_word": "寓話", "complexity_tier": "T3", "furigana": "この寓話[ぐうわ]では、擬人化[ぎじんか]された風[かぜ]と太陽[たいよう]が力[ちから]くらべをする。", "sentence_source": "generated"}, {"text": "寓話は子ども向けに見えるが、大人にも通じる深い教えを持っている。", "target_word": "寓話", "complexity_tier": "T3", "furigana": "寓話[ぐうわ]は子[こ]ども向[む]けに見[み]えるが、大人[おとな]にも通[つう]じる深[ふか]い教[おし]えを持[も]っている。", "sentence_source": "generated"}, {"text": "彼は会議で、寓話を引いて、協力の大切さを分かりやすく説明した。", "target_word": "寓話", "complexity_tier": "T3", "furigana": "彼[かれ]は会議[かいぎ]で、寓話[ぐうわ]を引[ひ]いて、協力[きょうりょく]の大切[たいせつ]さを分[わ]かりやすく説明[せつめい]した。", "sentence_source": "generated"}, {"text": "寓話の結末には、たいてい一文の教訓が添えられている。", "target_word": "寓話", "complexity_tier": "T3", "furigana": "寓話[ぐうわ]の結末[けつまつ]には、たいてい一文[いちぶん]の教訓[きょうくん]が添[そ]えられている。", "sentence_source": "generated"}, {"text": "古代ギリシャで生まれた寓話は、各国の言葉に翻訳されてきた。", "target_word": "寓話", "complexity_tier": "T3", "furigana": "古代[こだい]ギリシャで生[う]まれた寓話[ぐうわ]は、各国[かっこく]の言葉[ことば]に翻訳[ほんやく]されてきた。", "sentence_source": "generated"}, {"text": "無生物を登場させた寓話は、読者に想像力を求める。", "target_word": "寓話", "complexity_tier": "T3", "furigana": "無生物[むせいぶつ]を登場[とうじょう]させた寓話[ぐうわ]は、読者[どくしゃ]に想像力[そうぞうりょく]を求[もと]める。", "sentence_source": "generated"}, {"text": "この小説は、現代社会を描いた寓話として読むこともできる。", "target_word": "寓話", "complexity_tier": "T3", "furigana": "この小説[しょうせつ]は、現代[げんだい]社会[しゃかい]を描[えが]いた寓話[ぐうわ]として読[よ]むこともできる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "寓話", "label": "基本形"}], "register": "書き言葉", "sense_fingerprint": "動物や無生物を擬人化し、道徳的な教訓を込めた短い文学作品", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 2 above tier T4: contains vocabulary far above tier T4: ラ・フォンテーヌ (Zipf 1.25)']::text[], '98f6d5a5-9f90-4330-858e-b3c0b9ee5e3c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37867, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "寓話", "is_correct": true, "explanation": "「短い物語の中に道徳的な教訓を込めた文学の形式」は寓話の定義に合う。"}, {"text": "地図", "is_correct": false, "explanation": "地図は道徳的な教訓を込める文学の形式ではなく、文が成り立たない。"}, {"text": "時刻表", "is_correct": false, "explanation": "時刻表は文学の形式ではなく、文の主語にならない。"}, {"text": "料理", "is_correct": false, "explanation": "料理は文学の形式ではなく、文の意味に合わない。"}], "explanations": {"寓話": "「短い物語の中に道徳的な教訓を込めた文学の形式」は寓話の定義に合う。", "地図": "地図は道徳的な教訓を込める文学の形式ではなく、文が成り立たない。", "時刻表": "時刻表は文学の形式ではなく、文の主語にならない。", "料理": "料理は文学の形式ではなく、文の意味に合わない。"}, "sentence_index": 0, "correct_answer": "寓話"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この寓話は、一枚の絵で政治家を風刺している。", "explanation": "ここは〈風刺画〉の意味。寓話は文章で教訓を伝える短い物語で、一枚の絵には使わない。"}, {"text": "この寓話では、筆者が自分の体験を率直に述べている。", "explanation": "ここは〈随筆〉の意味。寓話は動物や無生物を擬人化した作り話で、筆者の体験を述べる文章には使わない。"}, {"text": "この寓話では、神々が世界を創る。", "explanation": "ここは〈神話〉の意味。神々の起源を語る話で、道徳的な教訓を込めた寓話とは違う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a7f176f-54da-4761-b24e-95a6f306599d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37867, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "寓話", "is_correct": true, "explanation": "「寓話の結末には、たいてい一文の教訓が添えられている」は、寓話の特徴として文の内容に合う。"}, {"text": "辞書", "is_correct": false, "explanation": "辞書には結末がなく、文の内容に合わない。"}, {"text": "切手", "is_correct": false, "explanation": "切手には結末がなく、教訓が添えられる文脈にならない。"}, {"text": "洗剤", "is_correct": false, "explanation": "洗剤には結末がなく、文が成り立たない。"}], "explanations": {"寓話": "「寓話の結末には、たいてい一文の教訓が添えられている」は、寓話の特徴として文の内容に合う。", "辞書": "辞書には結末がなく、文の内容に合わない。", "切手": "切手には結末がなく、教訓が添えられる文脈にならない。", "洗剤": "洗剤には結末がなく、文が成り立たない。"}, "sentence_index": 6, "correct_answer": "寓話"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この報告書は、現代社会の現状を調べた寓話として提出された。", "explanation": "ここは〈報告書〉の意味。事実を記す文書を指すので、作り話で教訓を伝える寓話とは合わない。"}, {"text": "この寓話は、私が毎日見てきた出来事を書き留めたものだ。", "explanation": "ここは〈日記〉の意味。自分の身の回りの出来事を書き留めるもので、教訓を伝える動物などの話の寓話とは違う。"}, {"text": "この寓話は、偉人の生涯を事実に基づいて記したもので、作り話は一つもない。", "explanation": "ここは〈伝記〉の意味。実在の人物の生涯を事実に基づいて記すもので、作り話で教訓を伝える寓話とは違う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a7f176f-54da-4761-b24e-95a6f306599d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37867, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼は会議で、寓話を飲んで、協力の大切さを分かりやすく説明した。", "corrected_sentence": "彼は会議で、寓話を挙げて、協力の大切さを分かりやすく説明した。", "error_description": "動詞の誤り。寓話は「挙げる（例に出す）」もので、「飲む」は寓話と結びつかない。「挙げて」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a7f176f-54da-4761-b24e-95a6f306599d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37867, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "古代ギリシャで生まれた寓話を、各国の言葉に翻訳されてきた。", "corrected_sentence": "古代ギリシャで生まれた寓話が、各国の言葉に翻訳されてきた。", "error_description": "助詞の誤り。「翻訳される」は受身なので、動作の対象は主語の「が」で示す。「寓話を」では目的語の格が残り、受身と噛み合わない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a7f176f-54da-4761-b24e-95a6f306599d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37868, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「干魃が続く」の主語を示し、文の成り立ちに合う。"}, {"text": "を", "is_correct": false, "explanation": "「続く」は自動詞なので、目的語の「を」は取らない。"}, {"text": "と", "is_correct": false, "explanation": "「干魃と続く」では並列の意味になり、文意に合わない。"}, {"text": "の", "is_correct": false, "explanation": "「干魃の続いて」では連体修飾が続かず、文が成り立たない。"}], "correct_answer": "が", "explanations": {"が": "「干魃が続く」の主語を示し、文の成り立ちに合う。", "を": "「続く」は自動詞なので、目的語の「を」は取らない。", "と": "「干魃と続く」では並列の意味になり、文意に合わない。", "の": "「干魃の続いて」では連体修飾が続かず、文が成り立たない。"}, "error_tags": {"を": "目的語", "と": "並列・相手", "の": "連体修飾"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06e8f94a-57eb-4070-a427-4784d52d32e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37868, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「干魃のとき」の連体修飾になり、正しく続く。"}, {"text": "が", "is_correct": false, "explanation": "「干魃がとき」では主語の「が」が「とき」に続かず、文が成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「干魃にとき」では「とき」と結びつかず、不自然で文意に合わない。"}, {"text": "で", "is_correct": false, "explanation": "「干魃でとき」は手段や場所の意味になり、「とき」の修飾にならない。"}], "correct_answer": "の", "explanations": {"の": "「干魃のとき」の連体修飾になり、正しく続く。", "が": "「干魃がとき」では主語の「が」が「とき」に続かず、文が成り立たない。", "に": "「干魃にとき」では「とき」と結びつかず、不自然で文意に合わない。", "で": "「干魃でとき」は手段や場所の意味になり、「とき」の修飾にならない。"}, "error_tags": {"が": "主語", "に": "時点・相手", "で": "手段・場所"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06e8f94a-57eb-4070-a427-4784d52d32e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37868, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "雨がずっと降らなくて、地面がとても乾いてしまうこと。", "primary_collocate": null, "pronunciation": "かんばつ", "ipa": "kambatsɯ", "syllable_count": 4, "sentences": [{"text": "干魃で、田んぼの土がひびわれてしまった。", "target_word": "干魃", "complexity_tier": "T3", "furigana": "干魃[かんばつ]で、田[た]んぼの土[つち]がひびわれてしまった。", "sentence_source": "generated"}, {"text": "干魃が続いて、川の水がほとんどなくなった。", "target_word": "干魃", "complexity_tier": "T3", "furigana": "干魃[かんばつ]が続[つづ]いて、川[かわ]の水[みず]がほとんどなくなった。", "sentence_source": "generated"}, {"text": "今年は干魃なので、野菜があまり育たない。", "target_word": "干魃", "complexity_tier": "T3", "furigana": "今年[ことし]は干魃[かんばつ]なので、野菜[やさい]があまり育[そだ]たない。", "sentence_source": "generated"}, {"text": "干魃の年は、村の人たちが水を大切に使った。", "target_word": "干魃", "complexity_tier": "T3", "furigana": "干魃[かんばつ]の年[とし]は、村[むら]の人[ひと]たちが水[みず]を大切[たいせつ]に使[つか]った。", "sentence_source": "generated"}, {"text": "夏の干魃のせいで、井戸の水が減った。", "target_word": "干魃", "complexity_tier": "T3", "furigana": "夏の干魃[かんばつ]のせいで、井戸の水が減った。", "sentence_source": "generated"}, {"text": "干魃になると、地面は白くかわいてかたくなる。", "target_word": "干魃", "complexity_tier": "T3", "furigana": "干魃[かんばつ]になると、地面[じめん]は白[しろ]くかわいてかたくなる。", "sentence_source": "generated"}, {"text": "長い干魃のあと、やっと大雨が降った。", "target_word": "干魃", "complexity_tier": "T3", "furigana": "長[なが]い干魃[かんばつ]のあと、やっと大雨[おおあめ]が降[ふ]った。", "sentence_source": "generated"}, {"text": "干魃のとき、牛や馬にも飲む水が足りなかった。", "target_word": "干魃", "complexity_tier": "T3", "furigana": "干魃[かんばつ]のとき、牛[うし]や馬[うま]にも飲[の]む水[みず]が足[た]りなかった。", "sentence_source": "generated"}, {"text": "この国は、毎年のように干魃に苦しんでいる。", "target_word": "干魃", "complexity_tier": "T3", "furigana": "この国[くに]は、毎年[まいとし]のように干魃[かんばつ]に苦[くる]しんでいる。", "sentence_source": "generated"}, {"text": "干魃で草が枯れ、動物たちは水を探して歩いた。", "target_word": "干魃", "complexity_tier": "T3", "furigana": "干魃[かんばつ]で草[くさ]が枯[か]れ、動物[どうぶつ]たちは水[みず]を探[さが]して歩[ある]いた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "干魃", "label": "基本形"}, {"form": "干魃で", "label": "原因"}, {"form": "干魃の", "label": "連体"}], "register": "普通体（日常）", "sense_fingerprint": "雨が長く降らず、土地がからからに乾くこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd744feb5-cce0-45db-a3b7-f31e2c301cc9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37868, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "干魃", "is_correct": true, "explanation": "雨が少なく田んぼの土が乾いた、という原因として合う。"}, {"text": "停電", "is_correct": false, "explanation": "電気が止まる出来事で、田んぼの土がひびわれる原因にはならない。"}, {"text": "雪崩", "is_correct": false, "explanation": "雪が崩れる現象で、田んぼの土をひびわれさせない。"}, {"text": "渋滞", "is_correct": false, "explanation": "車が詰まる状況で、土の状態とは関係がない。"}], "explanations": {"干魃": "雨が少なく田んぼの土が乾いた、という原因として合う。", "停電": "電気が止まる出来事で、田んぼの土がひびわれる原因にはならない。", "雪崩": "雪が崩れる現象で、田んぼの土をひびわれさせない。", "渋滞": "車が詰まる状況で、土の状態とは関係がない。"}, "sentence_index": 0, "correct_answer": "干魃"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "台風で干魃が起き、家が水に浸かった。", "explanation": "ここは〈洪水〉の意味。干魃は雨が降らず乾く現象で、水に浸かる被害には使わない。"}, {"text": "干魃で水道管が凍った。", "explanation": "ここは〈寒波〉の意味。干魃は乾燥による現象で、凍結とは結びつかない。"}, {"text": "干魃で灰が降り積もり、畑が使えなくなった。", "explanation": "ここは〈噴火〉の意味。干魃は雨不足の現象で、火山灰の被害とは結びつかない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06e8f94a-57eb-4070-a427-4784d52d32e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37868, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "干魃", "is_correct": true, "explanation": "長く雨が降らなかったあとに大雨が降った、という流れに合う。"}, {"text": "会議", "is_correct": false, "explanation": "話し合いの場で、雨が降る前の長い期間を表すことはできない。"}, {"text": "腹痛", "is_correct": false, "explanation": "体の不調で、雨が降る流れとは関係がない。"}, {"text": "留守", "is_correct": false, "explanation": "家を空けている状態で、雨の状況には当てはまらない。"}], "explanations": {"干魃": "長く雨が降らなかったあとに大雨が降った、という流れに合う。", "会議": "話し合いの場で、雨が降る前の長い期間を表すことはできない。", "腹痛": "体の不調で、雨が降る流れとは関係がない。", "留守": "家を空けている状態で、雨の状況には当てはまらない。"}, "sentence_index": 6, "correct_answer": "干魃"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "干魃で屋根が飛ばされた。", "explanation": "ここは〈竜巻〉の意味。干魃は雨が降らず乾く現象で、風で屋根が飛ばされる被害とは結びつかない。"}, {"text": "干魃で町が流された。", "explanation": "ここは〈津波〉の意味。干魃は水が押し寄せる現象ではないので、町を押し流す原因とは合わない。"}, {"text": "干魃で道路が閉鎖された。", "explanation": "ここは〈大雪〉の意味。干魃は雨不足の現象で、雪による交通の遮断とは結びつかない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06e8f94a-57eb-4070-a427-4784d52d32e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37868, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "村の田んぼは、干魃を水が足りなくなった。", "corrected_sentence": "村の田んぼは、干魃で水が足りなくなった。", "error_description": "原因を表すのは「で」。「干魃を」の「を」は目的語になり、原因を示せないので誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06e8f94a-57eb-4070-a427-4784d52d32e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37868, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "干魃な年は、井戸の水が早く減ってしまう。", "corrected_sentence": "干魃の年は、井戸の水が早く減ってしまう。", "error_description": "「干魃」は名詞なので、名詞を修飾するときは「の」を使う。「な」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06e8f94a-57eb-4070-a427-4784d52d32e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37869, 3, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06e8f94a-57eb-4070-a427-4784d52d32e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37869, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「干魃のたびに」の連体修飾になり、正しく続く。"}, {"text": "が", "is_correct": false, "explanation": "「干魃がたびに」では「たびに」と結びつかず、文が成り立たない。"}, {"text": "を", "is_correct": false, "explanation": "「干魃をたびに」は目的語として「たびに」を修飾できず、文が成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「干魃にたびに」では「たびに」に続かず、文意に合わない。"}], "correct_answer": "の", "explanations": {"の": "「干魃のたびに」の連体修飾になり、正しく続く。", "が": "「干魃がたびに」では「たびに」と結びつかず、文が成り立たない。", "を": "「干魃をたびに」は目的語として「たびに」を修飾できず、文が成り立たない。", "に": "「干魃にたびに」では「たびに」に続かず、文意に合わない。"}, "error_tags": {"が": "主語", "を": "目的語", "に": "時点・相手"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06e8f94a-57eb-4070-a427-4784d52d32e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37869, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "長期間にわたって雨が降らず、水が不足する状態。農作物や生活に深刻な影響を与える自然現象。", "primary_collocate": null, "pronunciation": "かんばつ", "ipa": "kambatsɯ", "syllable_count": 4, "sentences": [{"text": "干魃により、国内の穀物の収穫量が大きく減った。", "target_word": "干魃", "complexity_tier": "T3", "furigana": "干魃[かんばつ]により、国内[こくない]の穀物[こくもつ]の収穫量[しゅうかくりょう]が大[おお]きく減[へ]った。", "sentence_source": "generated"}, {"text": "数か月続いた干魃は、地域の農業に深刻な被害を与えた。", "target_word": "干魃", "complexity_tier": "T3", "furigana": "数[すう]か月[げつ]続[つづ]いた干魃[かんばつ]は、地域[ちいき]の農業[のうぎょう]に深刻[しんこく]な被害[ひがい]を与[あた]えた。", "sentence_source": "generated"}, {"text": "政府は、干魃に備えて貯水池の整備を進めている。", "target_word": "干魃", "complexity_tier": "T3", "furigana": "政府[せいふ]は、干魃[かんばつ]に備[そな]えて貯水池[ちょすいち]の整備[せいび]を進[すす]めている。", "sentence_source": "generated"}, {"text": "干魃が長引くと、飲み水の確保も難しくなる。", "target_word": "干魃", "complexity_tier": "T3", "furigana": "干魃[かんばつ]が長引[ながび]くと、飲[の]み水[みず]の確保[かくほ]も難[むずか]しくなる。", "sentence_source": "generated"}, {"text": "干魃の影響で、小麦の価格が上がっている。", "target_word": "干魃", "complexity_tier": "T3", "furigana": "干魃[かんばつ]の影響[えいきょう]で、小麦[こむぎ]の価格[かかく]が上[あ]がっている。", "sentence_source": "generated"}, {"text": "気候の変化によって、干魃が起こりやすくなった。", "target_word": "干魃", "complexity_tier": "T3", "furigana": "気候[きこう]の変化[へんか]によって、干魃[かんばつ]が起[お]こりやすくなった。", "sentence_source": "generated"}, {"text": "干魃の被害を受けた農家に、支援金が配られた。", "target_word": "干魃", "complexity_tier": "T3", "furigana": "干魃[かんばつ]の被害[ひがい]を受[う]けた農家[のうか]に、支援金[しえんきん]が配[くば]られた。", "sentence_source": "generated"}, {"text": "この地域では、干魃のたびに食料が不足する。", "target_word": "干魃", "complexity_tier": "T3", "furigana": "この地域[ちいき]では、干魃[かんばつ]のたびに食料[しょくりょう]が不足[ふそく]する。", "sentence_source": "generated"}, {"text": "干魃の対策として、雨水を集める設備が作られた。", "target_word": "干魃", "complexity_tier": "T3", "furigana": "干魃[かんばつ]の対策[たいさく]として、雨水[あまみず]を集[あつ]める設備[せつび]が作[つく]られた。", "sentence_source": "generated"}, {"text": "干魃が広がり、川の流れが細くなって発電量も下がった。", "target_word": "干魃", "complexity_tier": "T3", "furigana": "干魃[かんばつ]が広[ひろ]がり、川[かわ]の流[なが]れが細[ほそ]くなって発電量[はつでんりょう]も下[さ]がった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "干魃", "label": "基本形"}, {"form": "干魃により", "label": "原因"}, {"form": "干魃の", "label": "連体"}], "register": "普通体（書き言葉・報道調）", "sense_fingerprint": "長期の雨不足による水不足で、農業や生活に深刻な被害を出す自然災害", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd744feb5-cce0-45db-a3b7-f31e2c301cc9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37869, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "干魃", "is_correct": true, "explanation": "原因を示す「により」に合い、収穫量が減った理由として自然。"}, {"text": "渋滞", "is_correct": false, "explanation": "交通の混雑で、穀物の収穫量を減らす原因にはならない。"}, {"text": "地価", "is_correct": false, "explanation": "土地の値段を表す語で、収穫量の減少には結びつかない。"}, {"text": "倒産", "is_correct": false, "explanation": "会社が立ち行かなくなることで、収穫量を直接減らす原因とは言えない。"}], "explanations": {"干魃": "原因を示す「により」に合い、収穫量が減った理由として自然。", "渋滞": "交通の混雑で、穀物の収穫量を減らす原因にはならない。", "地価": "土地の値段を表す語で、収穫量の減少には結びつかない。", "倒産": "会社が立ち行かなくなることで、収穫量を直接減らす原因とは言えない。"}, "sentence_index": 0, "correct_answer": "干魃"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "干魃で川の水位が急に上がった。", "explanation": "ここは〈豪雨〉の意味。干魃は雨が降らない現象なので、水位を上げる原因には使わない。"}, {"text": "干魃で建物が倒壊した。", "explanation": "ここは〈地震〉の意味。干魃は揺れを起こさないので、建物を倒す原因にはならない。"}, {"text": "干魃で雪かきが必要になった。", "explanation": "ここは〈大雪〉の意味。干魃は雨が降らず乾く現象なので、雪かきが必要になる原因にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06e8f94a-57eb-4070-a427-4784d52d32e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37869, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "干魃", "is_correct": true, "explanation": "農家が受けた被害の原因として合う。"}, {"text": "卒業", "is_correct": false, "explanation": "学校を終える出来事で、農家の被害の原因にはならない。"}, {"text": "雑談", "is_correct": false, "explanation": "会話を表す語で、農家の被害とは結びつかない。"}, {"text": "読書", "is_correct": false, "explanation": "本を読む行為で、農家の被害の原因として成り立たない。"}], "explanations": {"干魃": "農家が受けた被害の原因として合う。", "卒業": "学校を終える出来事で、農家の被害の原因にはならない。", "雑談": "会話を表す語で、農家の被害とは結びつかない。", "読書": "本を読む行為で、農家の被害の原因として成り立たない。"}, "sentence_index": 6, "correct_answer": "干魃"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "干魃で町の一部が流された。", "explanation": "ここは〈津波〉の意味。干魃は水が押し寄せる現象ではないので、町を押し流す原因とは合わない。"}, {"text": "干魃で火山灰が積もった。", "explanation": "ここは〈噴火〉の意味。干魃は雨不足の現象で、火山灰を降らせる原因にはならない。"}, {"text": "干魃で電柱が倒れた。", "explanation": "ここは〈落雷〉の意味。干魃は雷を伴わないので、電柱を倒す原因にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06e8f94a-57eb-4070-a427-4784d52d32e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37869, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "干魃を、今年の小麦の収穫が大きく落ち込んだ。", "corrected_sentence": "干魃により、今年の小麦の収穫が大きく落ち込んだ。", "error_description": "原因を表すのは「により」。「干魃を」の「を」は目的語になり、原因を示せないので誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06e8f94a-57eb-4070-a427-4784d52d32e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37869, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "干魃な被害で、地域の農業は大きな打撃を受けた。", "corrected_sentence": "干魃の被害で、地域の農業は大きな打撃を受けた。", "error_description": "「干魃」は名詞なので、名詞を修飾するときは「の」を使う。「な」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06e8f94a-57eb-4070-a427-4784d52d32e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37870, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「洪水のせいで」の「の」は、洪水を名詞「せい」に結びつける。"}, {"text": "が", "is_correct": false, "explanation": "「洪水がせいで」は主語の「が」だが、名詞「せい」を修飾する形として不自然で、原因を示せない。"}, {"text": "を", "is_correct": false, "explanation": "「洪水をせいで」は目的語の「を」で、名詞「せい」を修飾する形にならない。"}, {"text": "に", "is_correct": false, "explanation": "「洪水にせいで」は場所や相手を示し、原因の名詞「せい」と結びつかない。"}], "correct_answer": "の", "explanations": {"の": "「洪水のせいで」の「の」は、洪水を名詞「せい」に結びつける。", "が": "「洪水がせいで」は主語の「が」だが、名詞「せい」を修飾する形として不自然で、原因を示せない。", "を": "「洪水をせいで」は目的語の「を」で、名詞「せい」を修飾する形にならない。", "に": "「洪水にせいで」は場所や相手を示し、原因の名詞「せい」と結びつかない。"}, "error_tags": {"が": "主語を示すが、「せいで」の前に続かない", "を": "目的語を示すので、「洪水を」は「せいで」とつながらない", "に": "場所や相手を示し、「洪水に」は「せいで」と続かない"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a7f176f-54da-4761-b24e-95a6f306599d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
