INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37870, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "水がたくさん出て、町や田んぼを水でいっぱいにしてしまうこと。", "primary_collocate": null, "pronunciation": "こうずい", "ipa": "koːzɯi", "syllable_count": 4, "sentences": [{"text": "大雨で川があふれて、洪水が町をのみこんだ。", "target_word": "洪水", "complexity_tier": "T3", "furigana": "大雨[おおあめ]で川[かわ]があふれて、洪水[こうずい]が町[まち]をのみこんだ。", "sentence_source": "generated"}, {"text": "洪水のせいで、田んぼが水の底に沈んでしまった。", "target_word": "洪水", "complexity_tier": "T3", "furigana": "洪水[こうずい]のせいで、田[た]んぼが水[みず]の底[そこ]に沈[しず]んでしまった。", "sentence_source": "generated"}, {"text": "洪水が起きたので、村の人たちは高い所へにげた。", "target_word": "洪水", "complexity_tier": "T3", "furigana": "洪水[こうずい]が起[お]きたので、村[むら]の人[ひと]たちは高[たか]い所[ところ]へにげた。", "sentence_source": "generated"}, {"text": "去年の夏、この町では洪水で道が使えなくなった。", "target_word": "洪水", "complexity_tier": "T3", "furigana": "去年[きょねん]の夏[なつ]、この町[まち]では洪水[こうずい]で道[みち]が使[つか]えなくなった。", "sentence_source": "generated"}, {"text": "洪水のあと、家の中はどろだらけになっていた。", "target_word": "洪水", "complexity_tier": "T3", "furigana": "洪水[こうずい]のあと、家[いえ]の中[なか]はどろだらけになっていた。", "sentence_source": "generated"}, {"text": "洪水が来る前に、みんなで大切な物を二階に運んだ。", "target_word": "洪水", "complexity_tier": "T3", "furigana": "洪水[こうずい]が来[く]る前[まえ]に、みんなで大切[たいせつ]な物[もの]を二階[にかい]に運[はこ]んだ。", "sentence_source": "generated"}, {"text": "山の木を切りすぎると、洪水が起こりやすくなる。", "target_word": "洪水", "complexity_tier": "T3", "furigana": "山[やま]の木[き]を切[き]りすぎると、洪水[こうずい]が起[お]こりやすくなる。", "sentence_source": "generated"}, {"text": "洪水のニュースを見て、祖母は田んぼのことを心配した。", "target_word": "洪水", "complexity_tier": "T3", "furigana": "洪水[こうずい]のニュースを見[み]て、祖母[そぼ]は田[た]んぼのことを心配[しんぱい]した。", "sentence_source": "generated"}, {"text": "洪水で水につかった畑では、今年は野菜が育たなかった。", "target_word": "洪水", "complexity_tier": "T3", "furigana": "洪水[こうずい]で水[みず]につかった畑[はたけ]では、今年[ことし]は野菜[やさい]が育[そだ]たなかった。", "sentence_source": "generated"}, {"text": "洪水にそなえて、町では川の岸を高くした。", "target_word": "洪水", "complexity_tier": "T3", "furigana": "洪水[こうずい]にそなえて、町[まち]では川[かわ]の岸[きし]を高[たか]くした。", "sentence_source": "generated"}], "morphological_forms": [{"form": "洪水", "label": "基本形"}], "register": "一般", "sense_fingerprint": "大水が出て町や田んぼが水でいっぱいになること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T3: contains vocabulary far above tier T3: のみこん (Zipf 1.6)']::text[], '98f6d5a5-9f90-4330-858e-b3c0b9ee5e3c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37870, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "洪水", "is_correct": true, "explanation": "水があふれて町を覆う出来事で、ここにぴったり入る。"}, {"text": "雷", "is_correct": false, "explanation": "光と音をともなう現象で、町を水のようにのみこむことはない。"}, {"text": "干ばつ", "is_correct": false, "explanation": "雨が長く降らない状態で、川があふれる文脈とは逆になる。"}, {"text": "停電", "is_correct": false, "explanation": "電気が止まることで、町を水のようにのみこむ主語にはならない。"}], "explanations": {"洪水": "水があふれて町を覆う出来事で、ここにぴったり入る。", "雷": "光と音をともなう現象で、町を水のようにのみこむことはない。", "干ばつ": "雨が長く降らない状態で、川があふれる文脈とは逆になる。", "停電": "電気が止まることで、町を水のようにのみこむ主語にはならない。"}, "sentence_index": 0, "correct_answer": "洪水"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "雨がまったく降らない夏、畑は洪水に苦しんだ。", "explanation": "ここは〈干ばつ〉の意味。雨が降らない被害を指すのに、水があふれる〈洪水〉を使うのは合わない。"}, {"text": "地震のあと、洪水が港の防波堤を越えた。", "explanation": "ここは〈津波〉の意味。海から押し寄せる波を指す語で、川の増水や大雨による洪水とは合わない。"}, {"text": "強い風が吹いて、洪水が倉庫の屋根を吹き飛ばした。", "explanation": "ここは〈竜巻〉の意味。風で物を吹き飛ばす現象で、水で町を覆う洪水とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a7f176f-54da-4761-b24e-95a6f306599d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37870, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "洪水", "is_correct": true, "explanation": "山の木を切ると起こりやすくなる水害そのもので、ここに入る。"}, {"text": "土壌", "is_correct": false, "explanation": "土の性質を指し、起こる出来事ではないので合わない。"}, {"text": "保水力", "is_correct": false, "explanation": "水を蓄える力で、起きる現象ではないので合わない。"}, {"text": "水源", "is_correct": false, "explanation": "水の出どころで、起こりやすくなる対象ではない。"}], "explanations": {"洪水": "山の木を切ると起こりやすくなる水害そのもので、ここに入る。", "土壌": "土の性質を指し、起こる出来事ではないので合わない。", "保水力": "水を蓄える力で、起きる現象ではないので合わない。", "水源": "水の出どころで、起こりやすくなる対象ではない。"}, "sentence_index": 6, "correct_answer": "洪水"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "雪山で洪水が起き、登山者が巻き込まれた。", "explanation": "ここは〈雪崩〉の意味。雪が斜面を一気に落ちる現象で、川の増水による洪水とは合わない。"}, {"text": "大雨で山の斜面が崩れ、洪水が住宅を押しつぶした。", "explanation": "ここは〈土砂崩れ〉の意味。斜面の土が崩れ落ちる現象で、水があふれる洪水とは違う。"}, {"text": "ポンプで洪水を送り込み、井戸の水位を上げた。", "explanation": "ここは〈注水〉の意味。決まった量の水を入れる作業を指し、水があふれて町を覆う洪水とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a7f176f-54da-4761-b24e-95a6f306599d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37870, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "大雨で川が増水し、洪水を町を襲った。", "corrected_sentence": "大雨で川が増水し、洪水が町を襲った。", "error_description": "「洪水」は主語なので「が」が正しい。「を」を付けると目的語になり、「町を」と二重になって誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a7f176f-54da-4761-b24e-95a6f306599d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37870, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "木を切りすぎた山では、洪水を起こりやすくなる。", "corrected_sentence": "木を切りすぎた山では、洪水が起こりやすくなる。", "error_description": "「起こりやすい」の主語は「洪水が」。「洪水を」は目的語を示すので誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a7f176f-54da-4761-b24e-95a6f306599d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
