INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37871, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「洪水が引いた」の「が」は、水が引く動作の主語を示す。"}, {"text": "に", "is_correct": false, "explanation": "「洪水に引いたあと」は場所や相手を示し、水が引く動作の主語にならない。"}, {"text": "と", "is_correct": false, "explanation": "「洪水と引いたあと」は並列や相手を示し、主語にならず文が成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "「洪水より引いたあと」は比較を示し、ここでは主語として成り立たない。"}], "correct_answer": "が", "explanations": {"が": "「洪水が引いた」の「が」は、水が引く動作の主語を示す。", "に": "「洪水に引いたあと」は場所や相手を示し、水が引く動作の主語にならない。", "と": "「洪水と引いたあと」は並列や相手を示し、主語にならず文が成り立たない。", "より": "「洪水より引いたあと」は比較を示し、ここでは主語として成り立たない。"}, "error_tags": {"に": "場所や相手を示し、「洪水に引いた」は動詞「引く」とつながらない", "と": "並列や相手を示し、「洪水と引いた」は成り立たない", "より": "比較を示し、ここでは文が成り立たない"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a7f176f-54da-4761-b24e-95a6f306599d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37871, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "大雨や川の氾濫などによって、土地や建物が水に浸かる自然現象。", "primary_collocate": null, "pronunciation": "こうずい", "ipa": "koːzɯi", "syllable_count": 4, "sentences": [{"text": "台風による大雨で河川が氾濫し、広い地域で洪水が発生した。", "target_word": "洪水", "complexity_tier": "T3", "furigana": "台風[たいふう]による大雨[おおあめ]で河川[かせん]が氾濫[はんらん]し、広[ひろ]い地域[ちいき]で洪水[こうずい]が発生[はっせい]した。", "sentence_source": "generated"}, {"text": "洪水の危険がある地域では、ハザードマップが配られている。", "target_word": "洪水", "complexity_tier": "T3", "furigana": "洪水[こうずい]の危険[きけん]がある地域[ちいき]では、ハザードマップが配[くば]られている。", "sentence_source": "generated"}, {"text": "洪水により、多くの建物が浸水する被害が出た。", "target_word": "洪水", "complexity_tier": "T3", "furigana": "洪水[こうずい]により、多[おお]くの建物[たてもの]が浸水[しんすい]する被害[ひがい]が出[で]た。", "sentence_source": "generated"}, {"text": "気候変動の影響で、洪水の回数が増えていると言われる。", "target_word": "洪水", "complexity_tier": "T3", "furigana": "気候変動[きこうへんどう]の影響[えいきょう]で、洪水[こうずい]の回数[かいすう]が増[ふ]えていると言[い]われる。", "sentence_source": "generated"}, {"text": "川の上流にダムを造ったのは、洪水を防ぐためである。", "target_word": "洪水", "complexity_tier": "T3", "furigana": "川[かわ]の上流[じょうりゅう]にダムを造[つく]ったのは、洪水[こうずい]を防[ふせ]ぐためである。", "sentence_source": "generated"}, {"text": "洪水の際は、早めに避難することが命を守る。", "target_word": "洪水", "complexity_tier": "T3", "furigana": "洪水[こうずい]の際[さい]は、早[はや]めに避難[ひなん]することが命[いのち]を守[まも]る。", "sentence_source": "generated"}, {"text": "専門家は、洪水の原因として、短時間の記録的な大雨を挙げた。", "target_word": "洪水", "complexity_tier": "T3", "furigana": "専門家[せんもんか]は、洪水[こうずい]の原因[げんいん]として、短時間[たんじかん]の記録的[きろくてき]な大雨[おおあめ]を挙[あ]げた。", "sentence_source": "generated"}, {"text": "洪水が引いたあとも、道路には泥が厚く残っていた。", "target_word": "洪水", "complexity_tier": "T3", "furigana": "洪水[こうずい]が引[ひ]いたあとも、道路[どうろ]には泥[どろ]が厚[あつ]く残[のこ]っていた。", "sentence_source": "generated"}, {"text": "この平野は、昔から洪水が繰り返し起きてきた土地だ。", "target_word": "洪水", "complexity_tier": "T3", "furigana": "この平野[へいや]は、昔[むかし]から洪水[こうずい]が繰[く]り返[かえ]し起[お]きてきた土地[とち]だ。", "sentence_source": "generated"}, {"text": "洪水への備えとして、自治体は堤防を整備している。", "target_word": "洪水", "complexity_tier": "T3", "furigana": "洪水[こうずい]への備[そな]えとして、自治体[じちたい]は堤防[ていぼう]を整備[せいび]している。", "sentence_source": "generated"}], "morphological_forms": [{"form": "洪水", "label": "基本形"}], "register": "書き言葉", "sense_fingerprint": "大雨や河川の氾濫で土地や建物が浸水する自然災害", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98f6d5a5-9f90-4330-858e-b3c0b9ee5e3c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37871, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "洪水", "is_correct": true, "explanation": "広い地域で水が浸かる現象で、発生する主語として入る。"}, {"text": "警報", "is_correct": false, "explanation": "発令されるもので、発生する現象ではないので合わない。"}, {"text": "雨量", "is_correct": false, "explanation": "雨の量を測る数値で、発生する出来事ではない。"}, {"text": "震度", "is_correct": false, "explanation": "地震の揺れの強さを表す数値で、水害の発生には合わない。"}], "explanations": {"洪水": "広い地域で水が浸かる現象で、発生する主語として入る。", "警報": "発令されるもので、発生する現象ではないので合わない。", "雨量": "雨の量を測る数値で、発生する出来事ではない。", "震度": "地震の揺れの強さを表す数値で、水害の発生には合わない。"}, "sentence_index": 0, "correct_answer": "洪水"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "一か月まったく雨が降らず、農家は洪水の被害に悩まされた。", "explanation": "ここは〈干ばつ〉の意味。雨が降らない被害を指すので、水があふれる〈洪水〉の意味では合わない。"}, {"text": "台風の夜、海の水が吹き寄せられ、洪水が防波堤を越えた。", "explanation": "ここは〈高潮〉の意味。台風で海水が吹き寄せられる現象で、川の増水を指す洪水とは違う。"}, {"text": "雨で斜面の土が崩れ、洪水が民家を押しつぶした。", "explanation": "ここは〈土砂崩れ〉の意味。斜面の土が崩れ落ちる現象で、水があふれる洪水とは違う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a7f176f-54da-4761-b24e-95a6f306599d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37871, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "洪水", "is_correct": true, "explanation": "大雨や川の氾濫による水害で、原因として挙げられるものになる。"}, {"text": "避難所", "is_correct": false, "explanation": "避難する場所で、大雨の原因にはならない。"}, {"text": "防災無線", "is_correct": false, "explanation": "情報を伝える設備で、大雨の原因にはならない。"}, {"text": "土嚢", "is_correct": false, "explanation": "水を防ぐための袋で、大雨の原因にはならない。"}], "explanations": {"洪水": "大雨や川の氾濫による水害で、原因として挙げられるものになる。", "避難所": "避難する場所で、大雨の原因にはならない。", "防災無線": "情報を伝える設備で、大雨の原因にはならない。", "土嚢": "水を防ぐための袋で、大雨の原因にはならない。"}, "sentence_index": 6, "correct_answer": "洪水"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "冬の山で洪水が起き、登山者が雪に埋まった。", "explanation": "ここは〈雪崩〉の意味。雪が斜面を一気に落ちる現象で、川の増水による洪水とは合わない。"}, {"text": "台風の強風で、洪水が看板を吹き飛ばした。", "explanation": "ここは〈竜巻〉の意味。風で物を吹き飛ばす現象で、水かさが増える洪水とは合わない。"}, {"text": "ポンプで洪水を流し込み、タンクの水位を上げた。", "explanation": "ここは〈注水〉の意味。タンクに水を入れる作業を指し、水があふれて土地を覆う洪水とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a7f176f-54da-4761-b24e-95a6f306599d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37871, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "大雨で川が氾濫し、低い地域で洪水を発生した。", "corrected_sentence": "大雨で川が氾濫し、低い地域で洪水が発生した。", "error_description": "「発生する」は自動詞なので、主語は「洪水が」。「洪水を」は目的語の誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a7f176f-54da-4761-b24e-95a6f306599d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37871, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "専門家は、洪水に原因は記録的な大雨だと指摘した。", "corrected_sentence": "専門家は、洪水の原因は記録的な大雨だと指摘した。", "error_description": "「洪水の原因」と名詞を修飾するには「の」が必要。「洪水に原因」は誤りで、「洪水の原因」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a7f176f-54da-4761-b24e-95a6f306599d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37872, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "正解。「写っている」の主語は人物なので、「人物が写っています」と「が」で続く。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語を示す。「写る」は目的語をとらないので合わない。"}, {"text": "に", "is_correct": false, "explanation": "「に」は場所や相手を示す。「人物に写っています」では主語の位置に合わない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は場所や手段を示す。「人物で写っています」では主語の役割が果たせない。"}], "correct_answer": "が", "explanations": {"が": "正解。「写っている」の主語は人物なので、「人物が写っています」と「が」で続く。", "を": "「を」は目的語を示す。「写る」は目的語をとらないので合わない。", "に": "「に」は場所や相手を示す。「人物に写っています」では主語の位置に合わない。", "で": "「で」は場所や手段を示す。「人物で写っています」では主語の役割が果たせない。"}, "error_tags": {"を": "目的語", "に": "場所・相手", "で": "場所・手段"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8dac1717-7ccc-4ac9-ab72-65c612654a43') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37872, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8dac1717-7ccc-4ac9-ab72-65c612654a43') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37872, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "人のこと。", "primary_collocate": null, "pronunciation": "じんぶつ", "ipa": "dʑimbɯtsɯ", "syllable_count": 4, "sentences": [{"text": "この小説には、おもしろい人物がたくさん出てきます。", "target_word": "人物", "complexity_tier": "T3", "furigana": "この小説(しょうせつ)には、おもしろい人物(じんぶつ)がたくさん出(で)てきます。", "sentence_source": "generated"}, {"text": "写真には三人の人物が写っています。", "target_word": "人物", "complexity_tier": "T3", "furigana": "写真(しゃしん)には三人(さんにん)の人物(じんぶつ)が写(うつ)っています。", "sentence_source": "generated"}, {"text": "絵の中央に立っている人物は、王様です。", "target_word": "人物", "complexity_tier": "T3", "furigana": "絵(え)の中央(ちゅうおう)に立(た)っている人物(じんぶつ)は、王様(おうさま)です。", "sentence_source": "generated"}, {"text": "事件の現場から、あやしい人物が走って逃げました。", "target_word": "人物", "complexity_tier": "T3", "furigana": "事件(じけん)の現場(げんば)から、あやしい人物(じんぶつ)が走(はし)って逃(に)げました。", "sentence_source": "generated"}, {"text": "物語に出てくる人物の名前を、ノートに書きました。", "target_word": "人物", "complexity_tier": "T3", "furigana": "物語[ものがたり]に出[で]てくる人物[じんぶつ]の名前[なまえ]を、ノートに書[か]きました。", "sentence_source": "generated"}, {"text": "窓の外に、黒い服を着た人物が立っていました。", "target_word": "人物", "complexity_tier": "T3", "furigana": "窓(まど)の外(そと)に、黒(くろ)い服(ふく)を着(き)た人物(じんぶつ)が立(た)っていました。", "sentence_source": "generated"}, {"text": "この映画の主な人物は、医者と教師の二人です。", "target_word": "人物", "complexity_tier": "T3", "furigana": "この映画(えいが)の主(おも)な人物(じんぶつ)は、医者(いしゃ)と教師(きょうし)の二人(ふたり)です。", "sentence_source": "generated"}, {"text": "歴史の授業で、江戸時代の人物について調べました。", "target_word": "人物", "complexity_tier": "T3", "furigana": "歴史(れきし)の授業(じゅぎょう)で、江戸時代(えどじだい)の人物(じんぶつ)について調(しら)べました。", "sentence_source": "generated"}, {"text": "絵の左に描かれた人物がだれなのか、だれも知りません。", "target_word": "人物", "complexity_tier": "T3", "furigana": "絵(え)の左(ひだり)に描(えが)かれた人物(じんぶつ)がだれなのか、だれも知(し)りません。", "sentence_source": "generated"}, {"text": "暗くてよく見えませんでしたが、ドアの向こうに人物の姿がありました。", "target_word": "人物", "complexity_tier": "T3", "furigana": "暗[くら]くてよく見[み]えませんでしたが、ドアの向[む]こうに人物[じんぶつ]の姿[すがた]がありました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "人物", "label": "基本形"}, {"form": "人物が", "label": "が格"}, {"form": "人物の", "label": "の格"}], "register": "標準（丁寧体）", "sense_fingerprint": "物語・絵・写真・現場などに現れる、ある人（登場人物・写っている人物）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7187a5e-8c4c-4216-b62d-4b95debbe3a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37872, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "人物", "is_correct": true, "explanation": "正解。小説に登場する人を指し、「おもしろい人物がたくさん出てきます」と自然に続く。"}, {"text": "天気", "is_correct": false, "explanation": "空の様子のこと。小説に出てくる人の代わりにはならない。"}, {"text": "鉛筆", "is_correct": false, "explanation": "文房具。小説の中に出てくる「おもしろい鉛筆」は文の意味が通らない。"}, {"text": "窓", "is_correct": false, "explanation": "建物の部分。「おもしろい窓がたくさん出てきます」は意味が通らない。"}], "explanations": {"人物": "正解。小説に登場する人を指し、「おもしろい人物がたくさん出てきます」と自然に続く。", "天気": "空の様子のこと。小説に出てくる人の代わりにはならない。", "鉛筆": "文房具。小説の中に出てくる「おもしろい鉛筆」は文の意味が通らない。", "窓": "建物の部分。「おもしろい窓がたくさん出てきます」は意味が通らない。"}, "sentence_index": 0, "correct_answer": "人物"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "町の人物は、およそ十万人です。", "explanation": "ここは〈人口〉の意味。人物は一人の人を指すので、町の総人数には使わない。"}, {"text": "人物は、ほかの動物と違って言葉を使います。", "explanation": "ここは〈人間〉の意味。人物は特定の一人を指すので、人類全体を表す文には使えない。"}, {"text": "会社の人物を増やしました。", "explanation": "ここは〈人員〉の意味。人物は一人の人を指すので、働く人の数を増やす話には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8dac1717-7ccc-4ac9-ab72-65c612654a43') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37872, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "人物", "is_correct": true, "explanation": "正解。映画に出てくる特定の人を指し、「主な人物は医者と教師の二人です」と自然に続く。"}, {"text": "音楽", "is_correct": false, "explanation": "映画の要素のひとつ。「主な音楽は医者と教師の二人です」では意味が通らない。"}, {"text": "季節", "is_correct": false, "explanation": "時期を表す語。人数を示す「二人」とは続かない。"}, {"text": "料金", "is_correct": false, "explanation": "支払う金額のこと。医者と教師の二人とは対応しない。"}], "explanations": {"人物": "正解。映画に出てくる特定の人を指し、「主な人物は医者と教師の二人です」と自然に続く。", "音楽": "映画の要素のひとつ。「主な音楽は医者と教師の二人です」では意味が通らない。", "季節": "時期を表す語。人数を示す「二人」とは続かない。", "料金": "支払う金額のこと。医者と教師の二人とは対応しない。"}, "sentence_index": 6, "correct_answer": "人物"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "子どもたちは、棚に人物を並べて遊びました。", "explanation": "ここは〈人形〉の意味。人物は人を指すので、おもちゃの人形を並べる文には使わない。"}, {"text": "夕食のあと、人物を三枚洗いました。", "explanation": "ここは〈皿〉の意味。人物は人を指すので、洗う食器の数え方には使わない。"}, {"text": "この池には、さまざまな人物が泳いでいます。", "explanation": "ここは〈魚〉の意味。人物は人を指すので、池で泳ぐ生きものには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8dac1717-7ccc-4ac9-ab72-65c612654a43') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37872, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "その絵の人物に、こちらを見ています。", "corrected_sentence": "その絵の人物が、こちらを見ています。", "error_description": "「見ている」動作の主体は「が」。「に」を使うと主語の役割が果たせず、「人物が見ています」と直す。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8dac1717-7ccc-4ac9-ab72-65c612654a43') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37872, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "駅の前で、帽子をかぶった人物を手を振っています。", "corrected_sentence": "駅の前で、帽子をかぶった人物が手を振っています。", "error_description": "「手を振る」動作の主語は「が」。「人物を」は目的語の形で誤りで、「人物が」と直す。", "correct_sentence_indices": [6, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8dac1717-7ccc-4ac9-ab72-65c612654a43') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
