INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37873, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "特定の個人、人。", "primary_collocate": null, "pronunciation": "じんぶつ", "ipa": "dʑimbɯtsɯ", "syllable_count": 4, "sentences": [{"text": "田中さんは、みんなから信頼されている人物です。", "target_word": "人物", "complexity_tier": "T3", "furigana": "田中(たなか)さんは、みんなから信頼(しんらい)されている人物(じんぶつ)です。", "sentence_source": "generated"}, {"text": "彼はこの町の歴史を変えた重要な人物です。", "target_word": "人物", "complexity_tier": "T3", "furigana": "彼(かれ)はこの町(まち)の歴史(れきし)を変(か)えた重要(じゅうよう)な人物(じんぶつ)です。", "sentence_source": "generated"}, {"text": "面接では、会社に合う人物かどうかが見られます。", "target_word": "人物", "complexity_tier": "T3", "furigana": "面接(めんせつ)では、会社(かいしゃ)に合(あ)う人物(じんぶつ)かどうかが見(み)られます。", "sentence_source": "generated"}, {"text": "紙幣に描かれている人物は、有名な作家です。", "target_word": "人物", "complexity_tier": "T3", "furigana": "紙幣(しへい)に描(えが)かれている人物(じんぶつ)は、有名(ゆうめい)な作家(さっか)です。", "sentence_source": "generated"}, {"text": "この会社の社長は、とても心が広い人物だと言われています。", "target_word": "人物", "complexity_tier": "T3", "furigana": "この会社(かいしゃ)の社長(しゃちょう)は、とても心(こころ)が広(ひろ)い人物(じんぶつ)だと言(い)われています。", "sentence_source": "generated"}, {"text": "中学校の先生は、尊敬できる人物でした。", "target_word": "人物", "complexity_tier": "T3", "furigana": "中学校(ちゅうがっこう)の先生(せんせい)は、尊敬(そんけい)できる人物(じんぶつ)でした。", "sentence_source": "generated"}, {"text": "手紙を書いた人物は、まだわかっていません。", "target_word": "人物", "complexity_tier": "T3", "furigana": "手紙(てがみ)を書(か)いた人物(じんぶつ)は、まだわかっていません。", "sentence_source": "generated"}, {"text": "この科学者は、世界中で知られる偉大な人物です。", "target_word": "人物", "complexity_tier": "T3", "furigana": "この科学者(かがくしゃ)は、世界中(せかいじゅう)で知(し)られる偉大(いだい)な人物(じんぶつ)です。", "sentence_source": "generated"}, {"text": "新しい委員長には、責任感のある人物を選びたいです。", "target_word": "人物", "complexity_tier": "T3", "furigana": "新(あたら)しい委員長(いいんちょう)には、責任感(せきにんかん)のある人物(じんぶつ)を選(えら)びたいです。", "sentence_source": "generated"}, {"text": "彼は約束を守る人物なので、お金を貸しても心配ありません。", "target_word": "人物", "complexity_tier": "T3", "furigana": "彼(かれ)は約束(やくそく)を守(まも)る人物(じんぶつ)なので、お金(かね)を貸(か)しても心配(しんぱい)ありません。", "sentence_source": "generated"}], "morphological_forms": [{"form": "人物", "label": "基本形"}, {"form": "人物が", "label": "が格"}, {"form": "人物を", "label": "を格"}], "register": "標準（丁寧体）", "sense_fingerprint": "人柄や立場で評価される特定の個人（信頼できる人物・重要な人物）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7187a5e-8c4c-4216-b62d-4b95debbe3a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37873, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "人物", "is_correct": true, "explanation": "正解。人柄や立場で評価される特定の人を指し、「信頼されている人物です」と自然に続く。"}, {"text": "天気", "is_correct": false, "explanation": "空の様子のこと。信頼される対象にはならない。"}, {"text": "鉛筆", "is_correct": false, "explanation": "文房具。人として信頼されるものではない。"}, {"text": "季節", "is_correct": false, "explanation": "時期を表す語。「信頼されている季節です」では文が成り立たない。"}], "explanations": {"人物": "正解。人柄や立場で評価される特定の人を指し、「信頼されている人物です」と自然に続く。", "天気": "空の様子のこと。信頼される対象にはならない。", "鉛筆": "文房具。人として信頼されるものではない。", "季節": "時期を表す語。「信頼されている季節です」では文が成り立たない。"}, "sentence_index": 0, "correct_answer": "人物"}, "level_6": {"correct_sentence_index": 4, "wrong_sentences": [{"text": "今日のパーティーで、人物を十本開けました。", "explanation": "ここは〈飲み物〉の意味。人物は人を指すので、瓶の飲み物を開ける数には使わない。"}, {"text": "スーパーで、人物を三つ買いました。", "explanation": "ここは〈食材〉の意味。人物は人を指すので、店で買う食べ物には使わない。"}, {"text": "新しい機械のために、人物を三つ注文しました。", "explanation": "ここは〈部品〉の意味。人物は人を指すので、機械の部品の注文には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8dac1717-7ccc-4ac9-ab72-65c612654a43') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37873, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "人物", "is_correct": true, "explanation": "正解。手紙を書いた特定の人を指し、「わかっていません」と自然に続く。"}, {"text": "切手", "is_correct": false, "explanation": "郵便料金を示す小さな紙。手紙を書いた主体にはならない。"}, {"text": "座布団", "is_correct": false, "explanation": "座る時に敷く布。手紙を書いた主体として文が成り立たない。"}, {"text": "教科書", "is_correct": false, "explanation": "学ぶための本。手紙を書いたのが誰かという文には合わない。"}], "explanations": {"人物": "正解。手紙を書いた特定の人を指し、「わかっていません」と自然に続く。", "切手": "郵便料金を示す小さな紙。手紙を書いた主体にはならない。", "座布団": "座る時に敷く布。手紙を書いた主体として文が成り立たない。", "教科書": "学ぶための本。手紙を書いたのが誰かという文には合わない。"}, "sentence_index": 6, "correct_answer": "人物"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "祭りの日は、人物が多くて道がこみました。", "explanation": "ここは〈人出〉の意味。人物は一人の人を指すので、大勢の人の集まりには使えない。"}, {"text": "人物は、道具を使う動物です。", "explanation": "ここは〈人間〉の意味。人物は特定の一人を指すので、人類全体を表す文には使わない。"}, {"text": "妹は、ぬいぐるみと人物を並べて遊びました。", "explanation": "ここは〈人形〉の意味。人物は人を指すので、ぬいぐるみと並べて遊ぶ人形の代わりにはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8dac1717-7ccc-4ac9-ab72-65c612654a43') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37873, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼は、将来、立派な人物をなりたいと言いました。", "corrected_sentence": "彼は、将来、立派な人物になりたいと言いました。", "error_description": "「なる」（変化）の相手を示すのは「に」。「人物を」は目的語の形で誤りで、「人物に」と直す。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8dac1717-7ccc-4ac9-ab72-65c612654a43') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37873, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼は、信頼される人物に目指して努力しています。", "corrected_sentence": "彼は、信頼される人物を目指して努力しています。", "error_description": "「目指す」（目標）を示すのは「を」。「に」は誤りで、「人物を目指す」と直す。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8dac1717-7ccc-4ac9-ab72-65c612654a43') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37874, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「インパクトがある」の主語を示す格助詞で、ここに入る。"}, {"text": "を", "is_correct": false, "explanation": "「ある」は目的語を取らない動詞なので、「インパクトをあって」は文として成り立たない。"}, {"text": "まで", "is_correct": false, "explanation": "「まで」は到達点を示すので、「インパクトまであって」では主語を示せず文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すので、「インパクトへあって」は存在の主語として不自然になる。"}], "correct_answer": "が", "explanations": {"が": "「インパクトがある」の主語を示す格助詞で、ここに入る。", "を": "「ある」は目的語を取らない動詞なので、「インパクトをあって」は文として成り立たない。", "まで": "「まで」は到達点を示すので、「インパクトまであって」では主語を示せず文が成り立たない。", "へ": "「へ」は方向を示すので、「インパクトへあって」は存在の主語として不自然になる。"}, "error_tags": {"を": "目的語", "まで": "到達点", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c351e7f7-2503-47aa-b52f-e3dd26b94bb2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37874, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "だけ", "options": [{"text": "だけ", "is_correct": true, "explanation": "「〜だけでなく」の形で、インパクトを限定する副助詞として入る。"}, {"text": "が", "is_correct": false, "explanation": "「インパクトがでなく」は成り立たず、後ろの「でなく」と続かない。"}, {"text": "と", "is_correct": false, "explanation": "「インパクトとでなく」は文法的に不自然で、「だけでなく」の形にならない。"}, {"text": "より", "is_correct": false, "explanation": "「インパクトよりでなく」は意味が通らず、「だけでなく」の限定の意味を表せない。"}], "correct_answer": "だけ", "explanations": {"だけ": "「〜だけでなく」の形で、インパクトを限定する副助詞として入る。", "が": "「インパクトがでなく」は成り立たず、後ろの「でなく」と続かない。", "と": "「インパクトとでなく」は文法的に不自然で、「だけでなく」の形にならない。", "より": "「インパクトよりでなく」は意味が通らず、「だけでなく」の限定の意味を表せない。"}, "error_tags": {"が": "主語", "と": "並列", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c351e7f7-2503-47aa-b52f-e3dd26b94bb2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37874, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "人の心に強く残る力のこと。", "primary_collocate": null, "pronunciation": "いんぱくと", "ipa": "impakɯto", "syllable_count": 5, "sentences": [{"text": "あの映画の最後の場面は、インパクトが強くて忘れられない。", "target_word": "インパクト", "complexity_tier": "T3", "furigana": "あの映画[えいが]の最後[さいご]の場面[ばめん]は、インパクトが強[つよ]くて忘[わす]れられない。", "sentence_source": "generated"}, {"text": "彼の自己紹介はインパクトがあって、みんなの記憶に残った。", "target_word": "インパクト", "complexity_tier": "T3", "furigana": "彼[かれ]の自己紹介[じこしょうかい]はインパクトがあって、みんなの記憶[きおく]に残[のこ]った。", "sentence_source": "generated"}, {"text": "このポスターは色が派手で、インパクトのあるデザインだ。", "target_word": "インパクト", "complexity_tier": "T3", "furigana": "このポスターは色[いろ]が派手[はで]で、インパクトのあるデザインだ。", "sentence_source": "generated"}, {"text": "初めて見た富士山のインパクトは、今も心に残っている。", "target_word": "インパクト", "complexity_tier": "T3", "furigana": "初[はじ]めて見[み]た富士山[ふじさん]のインパクトは、今[いま]も心[こころ]に残[のこ]っている。", "sentence_source": "generated"}, {"text": "面接では、名前を覚えてもらうために、インパクトのある話をした。", "target_word": "インパクト", "complexity_tier": "T3", "furigana": "面接[めんせつ]では、名前[なまえ]を覚[おぼ]えてもらうために、インパクトのある話[はなし]をした。", "sentence_source": "generated"}, {"text": "話の内容はよかったが、インパクトが足りなくて印象に残らなかった。", "target_word": "インパクト", "complexity_tier": "T3", "furigana": "話[はなし]の内容[ないよう]はよかったが、インパクトが足[た]りなくて印象[いんしょう]に残[のこ]らなかった。", "sentence_source": "generated"}, {"text": "先生の最初の一言には、生徒たちの心に残るインパクトがあった。", "target_word": "インパクト", "complexity_tier": "T3", "furigana": "先生[せんせい]の最初[さいしょ]の一言[ひとこと]には、生徒[せいと]たちの心[こころ]に残[のこ]るインパクトがあった。", "sentence_source": "generated"}, {"text": "見た目のインパクトだけでなく、味も本当においしい料理だった。", "target_word": "インパクト", "complexity_tier": "T3", "furigana": "見[み]た目[め]のインパクトだけでなく、味[あじ]も本当[ほんとう]においしい料理[りょうり]だった。", "sentence_source": "generated"}, {"text": "新商品の名前は、インパクトがあって一度で覚えられる。", "target_word": "インパクト", "complexity_tier": "T3", "furigana": "新商品[しんしょうひん]の名前[なまえ]は、インパクトがあって一度[いちど]で覚[おぼ]えられる。", "sentence_source": "generated"}, {"text": "その絵は大きさだけでもインパクトがあった。", "target_word": "インパクト", "complexity_tier": "T3", "furigana": "その絵[え]は大[おお]きさだけでもインパクトがあった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "インパクト", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "見た人・聞いた人の記憶に強く残る力や印象の強さ", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e61789a-9eca-468c-8b66-53ec4aea85ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37874, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "インパクト", "is_correct": true, "explanation": "映画の場面が心に強く残る力を指す語で、「〜が強くて忘れられない」に入る。"}, {"text": "予算", "is_correct": false, "explanation": "予算は使える金額の計画で、記憶に残る力の強さを表さないので「予算が強い」は成り立たない。"}, {"text": "日程", "is_correct": false, "explanation": "日程は予定の並びを表す語で、「強くて」と組み合わせると意味が通らない。"}, {"text": "配達", "is_correct": false, "explanation": "配達は荷物を届ける行為で、「配達が強くて忘れられない」は意味をなさない。"}], "explanations": {"インパクト": "映画の場面が心に強く残る力を指す語で、「〜が強くて忘れられない」に入る。", "予算": "予算は使える金額の計画で、記憶に残る力の強さを表さないので「予算が強い」は成り立たない。", "日程": "日程は予定の並びを表す語で、「強くて」と組み合わせると意味が通らない。", "配達": "配達は荷物を届ける行為で、「配達が強くて忘れられない」は意味をなさない。"}, "sentence_index": 0, "correct_answer": "インパクト"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "その騒音は、近所にインパクトをかけた。", "explanation": "ここは〈迷惑〉の意味。迷惑は『かける』と言うが、インパクトを人に『かける』とは言わないので合わない。"}, {"text": "その景色を見て、彼は深いインパクトにふけった。", "explanation": "ここは〈感慨〉の意味。感慨は『にふける』と言うが、インパクトに『ふける』とは言わないので合わない。"}, {"text": "彼はインパクトに駆られて、店を飛び出した。", "explanation": "ここは〈衝動〉の意味。衝動は『に駆られる』と言うが、インパクトは駆られるものではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c351e7f7-2503-47aa-b52f-e3dd26b94bb2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37874, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "インパクト", "is_correct": true, "explanation": "生徒たちの心に強く残る力を指す語で、「心に残る〜があった」に入る。"}, {"text": "駐車場", "is_correct": false, "explanation": "駐車場は車を止める場所で、心に残るものとしては意味をなさない。"}, {"text": "紙袋", "is_correct": false, "explanation": "紙袋は物の名前で、心に残る力の強さを表さないので文として不自然になる。"}, {"text": "郵便", "is_correct": false, "explanation": "郵便は手紙などを届ける仕組みで、「心に残る郵便があった」は意味が通らない。"}], "explanations": {"インパクト": "生徒たちの心に強く残る力を指す語で、「心に残る〜があった」に入る。", "駐車場": "駐車場は車を止める場所で、心に残るものとしては意味をなさない。", "紙袋": "紙袋は物の名前で、心に残る力の強さを表さないので文として不自然になる。", "郵便": "郵便は手紙などを届ける仕組みで、「心に残る郵便があった」は意味が通らない。"}, "sentence_index": 6, "correct_answer": "インパクト"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は毎日の練習にインパクトを注いだ。", "explanation": "ここは〈熱意〉の意味。熱意は『注ぐ』と言うが、インパクトは注ぐものではないので合わない。"}, {"text": "その説明で、みんなのインパクトを解いた。", "explanation": "ここは〈疑問〉の意味。疑問は『解く』と言うが、インパクトは解くものではないので合わない。"}, {"text": "彼は走った後、インパクトを流した。", "explanation": "ここは〈汗〉の意味。汗は『流す』と言うが、インパクトは流せないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c351e7f7-2503-47aa-b52f-e3dd26b94bb2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37874, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "その曲の最後のインパクトを強くて、ずっと耳に残る。", "corrected_sentence": "その曲の最後のインパクトが強くて、ずっと耳に残る。", "error_description": "「強い」の主語はインパクト。「を」は誤りで、正しくは「が」（インパクトが強くて）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c351e7f7-2503-47aa-b52f-e3dd26b94bb2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37874, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "その映像は見る人の記憶に強いインパクトを残しる。", "corrected_sentence": "その映像は見る人の記憶に強いインパクトを残す。", "error_description": "「残す」の活用を誤って「残しる」とした。文末の終止形なので正しくは基本形の「残す」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c351e7f7-2503-47aa-b52f-e3dd26b94bb2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37875, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "「インパクトは、とても大きい」で、話題を示す係助詞として入る。"}, {"text": "を", "is_correct": false, "explanation": "「インパクトを、とても大きい」では目的語の後に述語がなく、文が成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「インパクトに、とても大きい」では、「に」が形容詞の主語にならず不自然になる。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すので、「インパクトへ、とても大きい」は話題として成り立たない。"}], "correct_answer": "は", "explanations": {"は": "「インパクトは、とても大きい」で、話題を示す係助詞として入る。", "を": "「インパクトを、とても大きい」では目的語の後に述語がなく、文が成り立たない。", "に": "「インパクトに、とても大きい」では、「に」が形容詞の主語にならず不自然になる。", "へ": "「へ」は方向を示すので、「インパクトへ、とても大きい」は話題として成り立たない。"}, "error_tags": {"を": "目的語", "に": "位置・相手", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c351e7f7-2503-47aa-b52f-e3dd26b94bb2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37875, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "「インパクトは、予想よりも深刻だった」で、話題を示す係助詞として入る。"}, {"text": "の", "is_correct": false, "explanation": "「インパクトの、予想よりも深刻だった」では名詞を修飾する先がなく、文が成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "「インパクトより」は比較の基準として不自然で、直後の「予想よりも」と重なって意味が通らない。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を示すので、「インパクトから、予想よりも深刻だった」では話題として成り立たない。"}], "correct_answer": "は", "explanations": {"は": "「インパクトは、予想よりも深刻だった」で、話題を示す係助詞として入る。", "の": "「インパクトの、予想よりも深刻だった」では名詞を修飾する先がなく、文が成り立たない。", "より": "「インパクトより」は比較の基準として不自然で、直後の「予想よりも」と重なって意味が通らない。", "から": "「から」は起点を示すので、「インパクトから、予想よりも深刻だった」では話題として成り立たない。"}, "error_tags": {"の": "連体修飾", "より": "比較", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c351e7f7-2503-47aa-b52f-e3dd26b94bb2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37875, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "人に強い印象や影響を与えること。また、その力。", "primary_collocate": null, "pronunciation": "いんぱくと", "ipa": "impakɯto", "syllable_count": 5, "sentences": [{"text": "新しい法律は、町の暮らしに大きなインパクトを与えた。", "target_word": "インパクト", "complexity_tier": "T3", "furigana": "新[あたら]しい法律[ほうりつ]は、町[まち]の暮[く]らしに大[おお]きなインパクトを与[あた]えた。", "sentence_source": "generated"}, {"text": "この発明が社会に与えるインパクトは、とても大きい。", "target_word": "インパクト", "complexity_tier": "T3", "furigana": "この発明[はつめい]が社会[しゃかい]に与[あた]えるインパクトは、とても大[おお]きい。", "sentence_source": "generated"}, {"text": "値上げが家計に与えるインパクトを、専門家が計算した。", "target_word": "インパクト", "complexity_tier": "T3", "furigana": "値上[ねあ]げが家計[かけい]に与[あた]えるインパクトを、専門家[せんもんか]が計算[けいさん]した。", "sentence_source": "generated"}, {"text": "彼の一言は、チームに強いインパクトを与えた。", "target_word": "インパクト", "complexity_tier": "T3", "furigana": "彼[かれ]の一言[ひとこと]は、チームに強[つよ]いインパクトを与[あた]えた。", "sentence_source": "generated"}, {"text": "新しい店ができても、客の数へのインパクトは小さかった。", "target_word": "インパクト", "complexity_tier": "T3", "furigana": "新[あたら]しい店[みせ]ができても、客[きゃく]の数[かず]へのインパクトは小[ちい]さかった。", "sentence_source": "generated"}, {"text": "広告は消費者にインパクトを与えられなければ、意味がない。", "target_word": "インパクト", "complexity_tier": "T3", "furigana": "広告[こうこく]は消費者[しょうひしゃ]にインパクトを与[あた]えられなければ、意味[いみ]がない。", "sentence_source": "generated"}, {"text": "先輩の努力は、後輩たちに大きなインパクトを与えている。", "target_word": "インパクト", "complexity_tier": "T3", "furigana": "先輩[せんぱい]の努力[どりょく]は、後輩[こうはい]たちに大[おお]きなインパクトを与[あた]えている。", "sentence_source": "generated"}, {"text": "台風が農業に与えたインパクトは、予想よりも深刻だった。", "target_word": "インパクト", "complexity_tier": "T3", "furigana": "台風[たいふう]が農業[のうぎょう]に与[あた]えたインパクトは、予想[よそう]よりも深刻[しんこく]だった。", "sentence_source": "generated"}, {"text": "会社は、この決定が社員にどんなインパクトを与えるかを心配している。", "target_word": "インパクト", "complexity_tier": "T3", "furigana": "会社[かいしゃ]は、この決定[けってい]が社員[しゃいん]にどんなインパクトを与[あた]えるかを心配[しんぱい]している。", "sentence_source": "generated"}, {"text": "その事件は、国の政治に長く続くインパクトを残した。", "target_word": "インパクト", "complexity_tier": "T3", "furigana": "その事件[じけん]は、国[くに]の政治[せいじ]に長[なが]く続[つづ]くインパクトを残[のこ]した。", "sentence_source": "generated"}], "morphological_forms": [{"form": "インパクト", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "人や社会・物事に強い影響や変化を与えること、またその影響力", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e61789a-9eca-468c-8b66-53ec4aea85ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37875, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "インパクト", "is_correct": true, "explanation": "法律が町の暮らしに与える強い影響を指す語で、「大きな〜を与えた」に入る。"}, {"text": "挨拶", "is_correct": false, "explanation": "挨拶は人に対する言葉のやりとりで、「大きな挨拶を与える」は成り立たない。"}, {"text": "住所", "is_correct": false, "explanation": "住所は場所を示す情報で、暮らしに与えるものとしては意味をなさない。"}, {"text": "紅茶", "is_correct": false, "explanation": "紅茶は飲み物の名前で、町の暮らしに与える対象にはならない。"}], "explanations": {"インパクト": "法律が町の暮らしに与える強い影響を指す語で、「大きな〜を与えた」に入る。", "挨拶": "挨拶は人に対する言葉のやりとりで、「大きな挨拶を与える」は成り立たない。", "住所": "住所は場所を示す情報で、暮らしに与えるものとしては意味をなさない。", "紅茶": "紅茶は飲み物の名前で、町の暮らしに与える対象にはならない。"}, "sentence_index": 0, "correct_answer": "インパクト"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "その制度のインパクトにあずかり、多くの家庭が助かった。", "explanation": "ここは〈恩恵〉の意味。恩恵は『あずかる』と言うが、インパクトはあずかるものではないので合わない。"}, {"text": "その発言は、多くの人のインパクトを買った。", "explanation": "ここは〈反感〉の意味。反感は『買う』と言うが、インパクトは買うものではないので合わない。"}, {"text": "彼はこの一年で、インパクトを積んで昇進した。", "explanation": "ここは〈実績〉の意味。実績は『積む』と言うが、インパクトは積むものではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c351e7f7-2503-47aa-b52f-e3dd26b94bb2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37875, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "インパクト", "is_correct": true, "explanation": "先輩の努力が後輩に与える強い影響を指す語で、「大きな〜を与えている」に入る。"}, {"text": "湯呑み", "is_correct": false, "explanation": "湯呑みは飲み物を入れる器で、努力が後輩に与える対象としては意味をなさない。"}, {"text": "名刺", "is_correct": false, "explanation": "名刺は身分を示す紙片で、努力が後輩に与えるものとしては不自然になる。"}, {"text": "電池", "is_correct": false, "explanation": "電池は電力を供給する部品で、努力の結果として「大きな電池を与える」とは言えない。"}], "explanations": {"インパクト": "先輩の努力が後輩に与える強い影響を指す語で、「大きな〜を与えている」に入る。", "湯呑み": "湯呑みは飲み物を入れる器で、努力が後輩に与える対象としては意味をなさない。", "名刺": "名刺は身分を示す紙片で、努力が後輩に与えるものとしては不自然になる。", "電池": "電池は電力を供給する部品で、努力の結果として「大きな電池を与える」とは言えない。"}, "sentence_index": 6, "correct_answer": "インパクト"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "多くの人が彼にインパクトを寄せた。", "explanation": "ここは〈信頼〉の意味。信頼は『寄せる』と言うが、インパクトは寄せるものではないので合わない。"}, {"text": "運転手は、前方にインパクトを払った。", "explanation": "ここは〈注意〉の意味。注意は『払う』と言うが、インパクトは払うものではないので合わない。"}, {"text": "彼はそのミスのインパクトを負った。", "explanation": "ここは〈責任〉の意味。責任は『負う』と言うが、インパクトは負うものではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c351e7f7-2503-47aa-b52f-e3dd26b94bb2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37875, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "その改革は、社員の働き方に大きなインパクトが与えた。", "corrected_sentence": "その改革は、社員の働き方に大きなインパクトを与えた。", "error_description": "「与える」の目的語は「インパクトを」。「が」を使うのは誤りで、正しくは「を」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c351e7f7-2503-47aa-b52f-e3dd26b94bb2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37875, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "その改革は、社会に長く続くインパクトを残しった。", "corrected_sentence": "その改革は、社会に長く続くインパクトを残した。", "error_description": "「残す」の過去形は「残した」。「残しった」は誤った活用で、正しくは「残した」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c351e7f7-2503-47aa-b52f-e3dd26b94bb2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37876, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「町の歴史が」の「が」。受身の「刻まれている」の主語を示し、文が成り立つ。"}, {"text": "を", "is_correct": false, "explanation": "目的語を示すので、受身の主語にはならない。"}, {"text": "で", "is_correct": false, "explanation": "手段や場所を示し、「歴史で刻まれている」は成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "連体修飾で、受身の文の主語にはならない。"}], "correct_answer": "が", "explanations": {"が": "「町の歴史が」の「が」。受身の「刻まれている」の主語を示し、文が成り立つ。", "を": "目的語を示すので、受身の主語にはならない。", "で": "手段や場所を示し、「歴史で刻まれている」は成り立たない。", "の": "連体修飾で、受身の文の主語にはならない。"}, "error_tags": {"を": "目的語を示すので、受身の主語にはならない", "で": "手段や場所を示し、「歴史で刻まれている」は成り立たない", "の": "連体修飾で、受身の文の主語にはならない"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a7f176f-54da-4761-b24e-95a6f306599d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37876, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「日が」の「が」。受身の「刻まれている」の主語を示し、文が成り立つ。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示し、「日へ刻まれている」は受身の文と合わない。"}, {"text": "と", "is_correct": false, "explanation": "並列や相手を示し、主語にはならない。"}, {"text": "より", "is_correct": false, "explanation": "比較を示し、主語にはならない。"}], "correct_answer": "が", "explanations": {"が": "「日が」の「が」。受身の「刻まれている」の主語を示し、文が成り立つ。", "へ": "方向を示し、「日へ刻まれている」は受身の文と合わない。", "と": "並列や相手を示し、主語にはならない。", "より": "比較を示し、主語にはならない。"}, "error_tags": {"へ": "方向を示し、「日へ刻まれている」は受身の文と合わない", "と": "並列や相手を示し、主語にはならない", "より": "比較を示し、主語にはならない"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a7f176f-54da-4761-b24e-95a6f306599d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37876, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "何かを道具で切って、形を付けること。例えば、木に文字を書くように、強く深く跡を残すこと。", "primary_collocate": null, "pronunciation": "きざむ", "ipa": "kizamɯ", "syllable_count": 3, "sentences": [{"text": "祖父は小さな木の板に、孫の名前を刻んだ。", "target_word": "刻んだ", "complexity_tier": "T3", "furigana": "祖父[そふ]は小[ちい]さな木[き]の板[いた]に、孫[まご]の名前[なまえ]を刻[きざ]んだ。", "sentence_source": "generated"}, {"text": "石碑には、町の歴史が深く刻まれている。", "target_word": "刻まれている", "complexity_tier": "T3", "furigana": "石碑[せきひ]には、町[まち]の歴史[れきし]が深[ふか]く刻[きざ]まれている。", "sentence_source": "generated"}, {"text": "先生の言葉を胸に刻んで、毎日練習を続けている。", "target_word": "刻んで", "complexity_tier": "T3", "furigana": "先生[せんせい]の言葉[ことば]を胸[むね]に刻[きざ]んで、毎日[まいにち]練習[れんしゅう]を続[つづ]けている。", "sentence_source": "generated"}, {"text": "職人はナイフで丸太に模様を刻み、美しい置物を作った。", "target_word": "刻み", "complexity_tier": "T3", "furigana": "職人[しょくにん]はナイフで丸太[まるた]に模様[もよう]を刻[きざ]み、美[うつく]しい置物[おきもの]を作[つく]った。", "sentence_source": "generated"}, {"text": "木の幹に刻まれた古い傷は、何十年も消えなかった。", "target_word": "刻まれた", "complexity_tier": "T3", "furigana": "木[き]の幹[みき]に刻[きざ]まれた古[ふる]い傷[きず]は、何十年[なんじゅうねん]も消[き]えなかった。", "sentence_source": "generated"}, {"text": "彫刻家は固い石に細かい線を刻んで、鳥の羽を表現した。", "target_word": "刻んで", "complexity_tier": "T3", "furigana": "彫刻家[ちょうこくか]は固[かた]い石[いし]に細[こま]かい線[せん]を刻[きざ]んで、鳥[とり]の羽[はね]を表現[ひょうげん]した。", "sentence_source": "generated"}, {"text": "この事故の悲しい記憶を、私たちは決して忘れず、心に刻むべきだ。", "target_word": "刻む", "complexity_tier": "T3", "furigana": "この事故[じこ]の悲[かな]しい記憶[きおく]を、私[わたし]たちは決[けっ]して忘[わす]れず、心[こころ]に刻[きざ]むべきだ。", "sentence_source": "generated"}, {"text": "指輪の内側には、二人の結婚した日が刻まれている。", "target_word": "刻まれている", "complexity_tier": "T3", "furigana": "指輪[ゆびわ]の内側[うちがわ]には、二人[ふたり]の結婚[けっこん]した日[ひ]が刻[きざ]まれている。", "sentence_source": "generated"}, {"text": "母の顔に刻まれたしわは、長い苦労を物語っていた。", "target_word": "刻まれた", "complexity_tier": "T3", "furigana": "母[はは]の顔[かお]に刻[きざ]まれたしわは、長[なが]い苦労[くろう]を物語[ものがた]っていた。", "sentence_source": "generated"}, {"text": "彼は銅の板に文字を刻むために、小さな彫刻刀を使った。", "target_word": "刻む", "complexity_tier": "T3", "furigana": "彼[かれ]は銅[どう]の板[いた]に文字[もじ]を刻[きざ]むために、小[ちい]さな彫刻刀[ちょうこくとう]を使[つか]った。", "sentence_source": "generated"}], "morphological_forms": [{"form": "刻む", "label": "辞書形"}, {"form": "刻み", "label": "連用形"}, {"form": "刻まない", "label": "否定形"}, {"form": "刻んで", "label": "て形"}, {"form": "刻んだ", "label": "過去形"}, {"form": "刻める", "label": "可能形"}, {"form": "刻まれる", "label": "受身形"}], "register": "中立", "sense_fingerprint": "道具で木や石に文字や模様を彫る。また、記憶や跡を深く残す。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98f6d5a5-9f90-4330-858e-b3c0b9ee5e3c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37876, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "刻んだ", "is_correct": true, "explanation": "道具で板に跡を残す動作で、名前を板に刻むことになる。"}, {"text": "眺めた", "is_correct": false, "explanation": "見つめる動作で、名前を板に残す文には合わない。"}, {"text": "運んだ", "is_correct": false, "explanation": "物を移す動作で、名前を板に残す文には合わない。"}, {"text": "折った", "is_correct": false, "explanation": "曲げて切る動作で、「名前を折った」は文として成り立たない。"}], "explanations": {"刻んだ": "道具で板に跡を残す動作で、名前を板に刻むことになる。", "眺めた": "見つめる動作で、名前を板に残す文には合わない。", "運んだ": "物を移す動作で、名前を板に残す文には合わない。", "折った": "曲げて切る動作で、「名前を折った」は文として成り立たない。"}, "sentence_index": 0, "correct_answer": "刻んだ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "庭に穴を刻んで、木を植えた。", "explanation": "ここは〈掘る〉の意味。土を掘る動作で、硬いものに跡を彫る「刻む」とは合わない。"}, {"text": "壁に白いペンキを刻んだ。", "explanation": "ここは〈塗る〉の意味。液体の塗料を広げる動作で、彫って跡を残す「刻む」は使わない。"}, {"text": "祖父は手紙の裏に、住所を刻んだ。", "explanation": "ここは〈書く〉の意味。ペンで紙に文字を書く動作を指す。彫って跡を残す〈刻む〉では、紙の上の文字には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a7f176f-54da-4761-b24e-95a6f306599d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37876, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "刻む", "is_correct": true, "explanation": "心に強く跡を残す意味で、ここに入る。"}, {"text": "歩く", "is_correct": false, "explanation": "移動する動作で、心に残すという文には使わない。"}, {"text": "跳ねる", "is_correct": false, "explanation": "飛び上がる動作で、心に残す文には合わない。"}, {"text": "撮る", "is_correct": false, "explanation": "写真を写す動作で、心に残す文には合わない。"}], "explanations": {"刻む": "心に強く跡を残す意味で、ここに入る。", "歩く": "移動する動作で、心に残すという文には使わない。", "跳ねる": "飛び上がる動作で、心に残す文には合わない。", "撮る": "写真を写す動作で、心に残す文には合わない。"}, "sentence_index": 6, "correct_answer": "刻む"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "画用紙に大きな花の絵を刻んだ。", "explanation": "ここは〈描く〉の意味。色で絵を描く動作で、硬いものに彫る「刻む」とは合わない。"}, {"text": "黒板の文字を刻んだ。", "explanation": "ここは〈消す〉の意味。文字を消す動作で、跡を残す「刻む」とは反対の働きになる。"}, {"text": "窓ガラスを刻んで、きれいにした。", "explanation": "ここは〈洗う〉の意味。汚れを落とす動作で、彫って跡を残す「刻む」は使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a7f176f-54da-4761-b24e-95a6f306599d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37876, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この石碑には、昔の出来事が深く刻んでいる。", "corrected_sentence": "この石碑には、昔の出来事が深く刻まれている。", "error_description": "「出来事」は刻まれる側なので、受身の「刻まれている」が正しい。能動の「刻んでいる」は、石碑に刻む主体がなく誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "刻まれている", "is_correct": true, "explanation": "受身に「ている」が付き、跡が残っている状態を表す。"}, {"text": "刻まれて", "is_correct": false, "explanation": "て形で文が終わり、述語として成り立たない。"}, {"text": "刻んでいる", "is_correct": false, "explanation": "能動の進行形で、誰かが刻んでいる意味になり、受身の文と合わない。"}, {"text": "刻まない", "is_correct": false, "explanation": "否定形で、跡が残っている事実と合わない。"}], "correct_form": "刻まれている", "base_form": "刻む", "form_label": "受身＋ている（状態）", "sentence_index": 1, "explanations": {"刻まれている": "受身に「ている」が付き、跡が残っている状態を表す。", "刻まれて": "て形で文が終わり、述語として成り立たない。", "刻んでいる": "能動の進行形で、誰かが刻んでいる意味になり、受身の文と合わない。", "刻まない": "否定形で、跡が残っている事実と合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a7f176f-54da-4761-b24e-95a6f306599d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37876, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "このつらい出来事を、心を刻むべきだ。", "corrected_sentence": "このつらい出来事を、心に刻むべきだ。", "error_description": "「刻む」の場所を示すのは「に」。「心を刻む」は誤りで、「心に刻む」が正しい。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "刻まれている", "is_correct": true, "explanation": "受身＋ている。日付が今も残っている状態を表す。"}, {"text": "刻まれて", "is_correct": false, "explanation": "て形で文が終わり、述語として成り立たない。"}, {"text": "刻めない", "is_correct": false, "explanation": "可能の否定で、跡が残っている状態とは合わない。"}, {"text": "刻んだ", "is_correct": false, "explanation": "能動の過去で、誰かが刻んだ動作を表し、残る状態を示さない。"}], "correct_form": "刻まれている", "base_form": "刻む", "form_label": "受身＋ている（結果の状態）", "sentence_index": 7, "explanations": {"刻まれている": "受身＋ている。日付が今も残っている状態を表す。", "刻まれて": "て形で文が終わり、述語として成り立たない。", "刻めない": "可能の否定で、跡が残っている状態とは合わない。", "刻んだ": "能動の過去で、誰かが刻んだ動作を表し、残る状態を示さない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a7f176f-54da-4761-b24e-95a6f306599d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37878, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「伝承によれば」の「に」。「〜によれば」は情報源を示す形で、ここに入る。"}, {"text": "が", "is_correct": false, "explanation": "主語を示すが、「よれば」の前に続かない。"}, {"text": "で", "is_correct": false, "explanation": "手段や場所を示し、「伝承でよれば」は成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "連体修飾で、「伝承のよれば」は文として続かない。"}], "correct_answer": "に", "explanations": {"に": "「伝承によれば」の「に」。「〜によれば」は情報源を示す形で、ここに入る。", "が": "主語を示すが、「よれば」の前に続かない。", "で": "手段や場所を示し、「伝承でよれば」は成り立たない。", "の": "連体修飾で、「伝承のよれば」は文として続かない。"}, "error_tags": {"が": "主語を示すが、「よれば」の前に続かない", "で": "手段や場所を示し、「伝承でよれば」は成り立たない", "の": "連体修飾で、「伝承のよれば」は文として続かない"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a7f176f-54da-4761-b24e-95a6f306599d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
