INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37878, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "昔から言い伝えられてきた話やこと。", "primary_collocate": null, "pronunciation": "でんしょう", "ipa": "deɴɕoː", "syllable_count": 4, "sentences": [{"text": "この村には、山の神が人を助けたという伝承がある。", "target_word": "伝承", "complexity_tier": "T3", "furigana": "この村[むら]には、山[やま]の神[かみ]が人[ひと]を助[たす]けたという伝承[でんしょう]がある。", "sentence_source": "generated"}, {"text": "古い伝承によれば、この池の底には大きな龍が眠っている。", "target_word": "伝承", "complexity_tier": "T3", "furigana": "古[ふる]い伝承[でんしょう]によれば、この池[いけ]の底[そこ]には大[おお]きな龍[りゅう]が眠[ねむ]っている。", "sentence_source": "generated"}, {"text": "祖母から聞いた伝承を、絵本にして子どもたちに伝えたい。", "target_word": "伝承", "complexity_tier": "T3", "furigana": "祖母[そぼ]から聞[き]いた伝承[でんしょう]を、絵本[えほん]にして子[こ]どもたちに伝[つた]えたい。", "sentence_source": "generated"}, {"text": "その島の伝承では、海の向こうから神様が来たとされている。", "target_word": "伝承", "complexity_tier": "T3", "furigana": "その島[しま]の伝承[でんしょう]では、海[うみ]の向[む]こうから神様[かみさま]が来[き]たとされている。", "sentence_source": "generated"}, {"text": "伝承は事実とは違うことも多いが、人々の思いが込められている。", "target_word": "伝承", "complexity_tier": "T3", "furigana": "伝承[でんしょう]は事実[じじつ]とは違[ちが]うことも多[おお]いが、人々[ひとびと]の思[おも]いが込[こ]められている。", "sentence_source": "generated"}, {"text": "町の図書館で、地元に残る伝承を集めた本を借りた。", "target_word": "伝承", "complexity_tier": "T3", "furigana": "町[まち]の図書館[としょかん]で、地元[じもと]に残[のこ]る伝承[でんしょう]を集[あつ]めた本[ほん]を借[か]りた。", "sentence_source": "generated"}, {"text": "夜に口笛を吹くと蛇が来るという伝承を、今も信じる人がいる。", "target_word": "伝承", "complexity_tier": "T3", "furigana": "夜[よる]に口笛[くちぶえ]を吹[ふ]くと蛇[へび]が来[く]るという伝承[でんしょう]を、今[いま]も信[しん]じる人[ひと]がいる。", "sentence_source": "generated"}, {"text": "研究者は、各地の伝承を比べて、物語の元の形を探している。", "target_word": "伝承", "complexity_tier": "T3", "furigana": "研究者[けんきゅうしゃ]は、各地[かくち]の伝承[でんしょう]を比[くら]べて、物語[ものがたり]の元[もと]の形[かたち]を探[さが]している。", "sentence_source": "generated"}, {"text": "この伝承は、千年も前から、語り手が変わりながら続いてきた。", "target_word": "伝承", "complexity_tier": "T3", "furigana": "この伝承[でんしょう]は、千年[せんねん]も前[まえ]から、語[かた]り手[て]が変[か]わりながら続[つづ]いてきた。", "sentence_source": "generated"}, {"text": "川の名前の由来は、洪水を防いだ僧の伝承にある。", "target_word": "伝承", "complexity_tier": "T3", "furigana": "川[かわ]の名前[なまえ]の由来[ゆらい]は、洪水[こうずい]を防[ふせ]いだ僧[そう]の伝承[でんしょう]にある。", "sentence_source": "generated"}], "morphological_forms": [{"form": "伝承", "label": "基本形"}, {"form": "伝承する", "label": "動詞形"}, {"form": "伝承される", "label": "受身形"}], "register": "やや硬い（書き言葉寄り）", "sense_fingerprint": "地域や家に昔から言い伝えられてきた話・言い伝えそのもの。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98f6d5a5-9f90-4330-858e-b3c0b9ee5e3c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37878, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "伝承", "is_correct": true, "explanation": "昔から言い伝えられた話で、人を助けた話として入る。"}, {"text": "反省", "is_correct": false, "explanation": "自分の行いを振り返る気持ちで、話としては入らない。"}, {"text": "不安", "is_correct": false, "explanation": "心配する気持ちで、話としては入らない。"}, {"text": "後悔", "is_correct": false, "explanation": "悔やむ気持ちで、話としては入らない。"}], "explanations": {"伝承": "昔から言い伝えられた話で、人を助けた話として入る。", "反省": "自分の行いを振り返る気持ちで、話としては入らない。", "不安": "心配する気持ちで、話としては入らない。", "後悔": "悔やむ気持ちで、話としては入らない。"}, "sentence_index": 0, "correct_answer": "伝承"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "裁判では、この伝承が決定的な証拠として採用された。", "explanation": "ここは〈証拠〉の意味。事実を裏づける材料を指し、昔から語り継がれた話の伝承とは合わない。"}, {"text": "彼は三十年の伝承を持つベテランだ。", "explanation": "ここは〈経験〉の意味。仕事を重ねた年数や実績を指し、語り継がれた話の伝承とは合わない。"}, {"text": "最近、社長が辞めるという伝承が社内に広がっている。", "explanation": "ここは〈噂〉の意味。最近の話題を指すので、昔から言い伝えられてきたという定義と合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a7f176f-54da-4761-b24e-95a6f306599d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37878, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "伝承", "is_correct": true, "explanation": "昔から信じられてきた言い伝えで、信じる対象として入る。"}, {"text": "感想", "is_correct": false, "explanation": "感じたことを述べたもので、信じる対象とは言えない。"}, {"text": "手紙", "is_correct": false, "explanation": "書いて送るもので、信じる対象ではない。"}, {"text": "悪夢", "is_correct": false, "explanation": "眠っている間の怖い夢で、信じる対象ではない。"}], "explanations": {"伝承": "昔から信じられてきた言い伝えで、信じる対象として入る。", "感想": "感じたことを述べたもので、信じる対象とは言えない。", "手紙": "書いて送るもので、信じる対象ではない。", "悪夢": "眠っている間の怖い夢で、信じる対象ではない。"}, "sentence_index": 6, "correct_answer": "伝承"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "昨日、町の広場で大きな伝承が起きた。", "explanation": "ここは〈事件・出来事〉の意味。昨日の出来事には使わず、昔から語り継がれた話の伝承とは違う。"}, {"text": "研究者は、川の流れの変化を伝承として報告した。", "explanation": "ここは〈報告〉の意味。調べて分かった事実を述べることで、言い伝えの伝承とは違う。"}, {"text": "伝承によると、去年の雨は少なかった。", "explanation": "ここは〈統計・記録〉の意味。去年の観測を示すので、昔から言い伝えられてきた話の定義とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a7f176f-54da-4761-b24e-95a6f306599d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37878, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "祖父から伝承が聞いた子どもたちは、山の神を信じた。", "corrected_sentence": "祖父から伝承を聞いた子どもたちは、山の神を信じた。", "error_description": "「聞く」の目的語は「伝承を」。「伝承が」は主語を示すので誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a7f176f-54da-4761-b24e-95a6f306599d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37878, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "祖母は、町に残る伝承が絵本にまとめた。", "corrected_sentence": "祖母は、町に残る伝承を絵本にまとめた。", "error_description": "「まとめる」の目的語は「伝承を」。「伝承が」は主語を示すので誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a7f176f-54da-4761-b24e-95a6f306599d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37879, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「若い人に伝承する」で、伝える相手（受け手）を示す。文の意味に合う。"}, {"text": "を", "is_correct": false, "explanation": "「を」は伝承の対象を示すので、人を対象にした「若い人を伝承する」は意味が通らない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は場所や手段を表すため、受け手の人には付かない。「若い人で伝承する」は不自然。"}, {"text": "の", "is_correct": false, "explanation": "「の」は名詞どうしをつなぐ助詞なので、「若い人の伝承するため」は文として成り立たない。"}], "correct_answer": "に", "explanations": {"に": "「若い人に伝承する」で、伝える相手（受け手）を示す。文の意味に合う。", "を": "「を」は伝承の対象を示すので、人を対象にした「若い人を伝承する」は意味が通らない。", "で": "「で」は場所や手段を表すため、受け手の人には付かない。「若い人で伝承する」は不自然。", "の": "「の」は名詞どうしをつなぐ助詞なので、「若い人の伝承するため」は文として成り立たない。"}, "error_tags": {"に": "受け手・帰着点", "を": "目的語（対象）", "で": "場所・手段", "の": "連体修飾・所属"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a7f176f-54da-4761-b24e-95a6f306599d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37879, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a7f176f-54da-4761-b24e-95a6f306599d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37879, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "昔から人から人へと語り継がれてきた、物事や習慣、話。", "primary_collocate": null, "pronunciation": "でんしょう", "ipa": "deɴɕoː", "syllable_count": 4, "sentences": [{"text": "この地域では、祭りの踊りを親から子へ伝承してきた。", "target_word": "伝承", "complexity_tier": "T3", "furigana": "この地域[ちいき]では、祭[まつ]りの踊[おど]りを親[おや]から子[こ]へ伝承[でんしょう]してきた。", "sentence_source": "generated"}, {"text": "職人の技を若い人に伝承するため、工房で教室を開いている。", "target_word": "伝承", "complexity_tier": "T3", "furigana": "職人[しょくにん]の技[わざ]を若[わか]い人[ひと]に伝承[でんしょう]するため、工房[こうぼう]で教室[きょうしつ]を開[ひら]いている。", "sentence_source": "generated"}, {"text": "正月に餅をつく習慣は、家族の中で代々伝承されている。", "target_word": "伝承", "complexity_tier": "T3", "furigana": "正月[しょうがつ]に餅[もち]をつく習慣[しゅうかん]は、家族[かぞく]の中[なか]で代々[だいだい]伝承[でんしょう]されている。", "sentence_source": "generated"}, {"text": "伝承されてきた料理の作り方は、レシピに書かれていない。", "target_word": "伝承", "complexity_tier": "T3", "furigana": "伝承[でんしょう]されてきた料理[りょうり]の作[つく]り方[かた]は、レシピに書[か]かれていない。", "sentence_source": "generated"}, {"text": "祖父は、村に伝わる歌を、口で教える形で伝承している。", "target_word": "伝承", "complexity_tier": "T3", "furigana": "祖父[そふ]は、村[むら]に伝[つた]わる歌[うた]を、口[くち]で教[おし]える形[かたち]で伝承[でんしょう]している。", "sentence_source": "generated"}, {"text": "文字を使わずに伝承された知恵は、語る人が減ると消えてしまう。", "target_word": "伝承", "complexity_tier": "T3", "furigana": "文字[もじ]を使[つか]わずに伝承[でんしょう]された知恵[ちえ]は、語[かた]る人[ひと]が減[へ]ると消[き]えてしまう。", "sentence_source": "generated"}, {"text": "昔ながらの染めの技術の伝承が、後継者不足で難しくなっている。", "target_word": "伝承", "complexity_tier": "T3", "furigana": "昔[むかし]ながらの染[そ]めの技術[ぎじゅつ]の伝承[でんしょう]が、後継者[こうけいしゃ]不足[ぶそく]で難[むずか]しくなっている。", "sentence_source": "generated"}, {"text": "村の人々は、田植えの前に祈る風習を、今も大切に伝承している。", "target_word": "伝承", "complexity_tier": "T3", "furigana": "村[むら]の人々[ひとびと]は、田植[たう]えの前[まえ]に祈[いの]る風習[ふうしゅう]を、今[いま]も大切[たいせつ]に伝承[でんしょう]している。", "sentence_source": "generated"}, {"text": "文字のない社会では、歴史は歌や語りによる伝承で残された。", "target_word": "伝承", "complexity_tier": "T3", "furigana": "文字[もじ]のない社会[しゃかい]では、歴史[れきし]は歌[うた]や語[かた]りによる伝承[でんしょう]で残[のこ]された。", "sentence_source": "generated"}, {"text": "若者が減って、地域の行事の伝承が途切れそうだ。", "target_word": "伝承", "complexity_tier": "T3", "furigana": "若者[わかもの]が減[へ]って、地域[ちいき]の行事[ぎょうじ]の伝承[でんしょう]が途切[とぎ]れそうだ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "伝承", "label": "基本形"}, {"form": "伝承する", "label": "動詞形"}, {"form": "伝承される", "label": "受身形"}], "register": "やや硬い（書き言葉寄り）", "sense_fingerprint": "技や習慣、行事などを人から人へ受け渡して残していくこと、またその受け継がれた物事。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98f6d5a5-9f90-4330-858e-b3c0b9ee5e3c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37879, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "伝承", "is_correct": true, "explanation": "「〜してきた」に続く動作を表す名詞で、受け継いできたという文脈に合う。"}, {"text": "伝統", "is_correct": false, "explanation": "「伝統してきた」は動詞として成り立たず、「踊りを親から子へ」の後に続けられない。"}, {"text": "伝説", "is_correct": false, "explanation": "語り継がれた話そのものを指す名詞で、「〜してきた」という動作の形にならない。"}, {"text": "伝記", "is_correct": false, "explanation": "人物の生涯を記した本を指す名詞で、「伝記してきた」は文として不自然になる。"}], "explanations": {"伝承": "「〜してきた」に続く動作を表す名詞で、受け継いできたという文脈に合う。", "伝統": "「伝統してきた」は動詞として成り立たず、「踊りを親から子へ」の後に続けられない。", "伝説": "語り継がれた話そのものを指す名詞で、「〜してきた」という動作の形にならない。", "伝記": "人物の生涯を記した本を指す名詞で、「伝記してきた」は文として不自然になる。"}, "sentence_index": 0, "correct_answer": "伝承"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "父の会社を伝承して、若くして社長になった。", "explanation": "会社の地位や財産を引き継ぐのは〈継承〉。伝承は技や習慣を語り継ぐ意味で、会社の地位には使わない。"}, {"text": "先方の返事を伝承しておきました。", "explanation": "相手に情報を知らせるのは〈伝達〉。伝承は昔から受け継がれた物事を次の世代へ渡すことに使う。"}, {"text": "電圧が配線を伝承して、機器が動いた。", "explanation": "熱や電気が物質の中を伝わるのは〈伝導〉。伝承は人から人へ語り継ぐことに限られる。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a7f176f-54da-4761-b24e-95a6f306599d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37879, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "伝承", "is_correct": true, "explanation": "「技術の〜が難しくなっている」で、技や習慣を次の世代へ受け継ぐ意味に合う。"}, {"text": "伝記", "is_correct": false, "explanation": "人物の生涯を記した本を指すため、「染めの技術の伝記」は意味が通らない。"}, {"text": "伝言", "is_correct": false, "explanation": "人づてに言葉を伝えることで、技術を受け継ぐという文脈には合わない。"}, {"text": "伝令", "is_correct": false, "explanation": "命令や連絡を伝える役目や連絡を指し、技術には使えない。"}], "explanations": {"伝承": "「技術の〜が難しくなっている」で、技や習慣を次の世代へ受け継ぐ意味に合う。", "伝記": "人物の生涯を記した本を指すため、「染めの技術の伝記」は意味が通らない。", "伝言": "人づてに言葉を伝えることで、技術を受け継ぐという文脈には合わない。", "伝令": "命令や連絡を伝える役目や連絡を指し、技術には使えない。"}, "sentence_index": 6, "correct_answer": "伝承"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "古い写真は、防湿庫に入れて伝承してある。", "explanation": "物を傷めないように守るのは〈保存〉。伝承は技・習慣・話を受け渡す意味で、写真には使わない。"}, {"text": "風邪が家族に伝承して、全員が寝込んだ。", "explanation": "病気がうつって広がるのは〈伝染〉。伝承は人から人へ語り継ぐ意味で、病気には使わない。"}, {"text": "音が壁を伝承して、隣の部屋まで聞こえた。", "explanation": "音や波が広がって届くのは〈伝播〉。伝承は技・習慣・話を受け渡す意味で、音には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a7f176f-54da-4761-b24e-95a6f306599d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37879, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この村では、田楽の舞を親から子で伝承してきた。", "corrected_sentence": "この村では、田楽の舞を親から子へ伝承してきた。", "error_description": "「伝承」の直前の助詞が誤り。「子で」は手段や場所を表すが、受け手を示すには方向・相手の「へ」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a7f176f-54da-4761-b24e-95a6f306599d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37879, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "祖母は、この歌を孫に伝承されている。", "corrected_sentence": "祖母は、この歌を孫に伝承している。", "error_description": "「伝承」に付く「されている」が誤り。祖母が伝える側の能動文なので、能動の「伝承している」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a7f176f-54da-4761-b24e-95a6f306599d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
