INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37880, 3, 'prompt1_core', '{"pos": "代名詞", "semantic_class": "function", "definition": "素性や正体の分からない人について、どんな人かを問う語。", "primary_collocate": null, "pronunciation": "なにもの", "ipa": "nanimono", "syllable_count": 4, "sentences": [{"text": "隣に引っ越してきた男が何者なのか、町の誰も知らなかった。", "target_word": "何者", "complexity_tier": "T3", "furigana": "隣[となり]に引[ひ]っ越[こ]してきた男[おとこ]が何者[なにもの]なのか、町[まち]の誰[だれ]も知[し]らなかった。", "sentence_source": "generated"}, {"text": "彼女が何者であろうと、私は友達として付き合いたい。", "target_word": "何者", "complexity_tier": "T3", "furigana": "彼女[かのじょ]が何者[なにもの]であろうと、私[わたし]は友達[ともだち]として付[つ]き合[あ]いたい。", "sentence_source": "generated"}, {"text": "夜中に家の前に立っていたのは、何者だったのだろう。", "target_word": "何者", "complexity_tier": "T3", "furigana": "夜中[よなか]に家[いえ]の前[まえ]に立[た]っていたのは、何者[なにもの]だったのだろう。", "sentence_source": "generated"}, {"text": "彼の過去を調べても、何者なのか分からなかった。", "target_word": "何者", "complexity_tier": "T3", "furigana": "彼[かれ]の過去[かこ]を調[しら]べても、何者[なにもの]なのか分[わ]からなかった。", "sentence_source": "generated"}, {"text": "この手紙を書いたのは何者ですか。", "target_word": "何者", "complexity_tier": "T3", "furigana": "この手紙[てがみ]を書[か]いたのは何者[なにもの]ですか。", "sentence_source": "generated"}, {"text": "あの人が何者かを知れば、きっとみんな驚くだろう。", "target_word": "何者", "complexity_tier": "T3", "furigana": "あの人[ひと]が何者[なにもの]かを知[し]れば、きっとみんな驚[おどろ]くだろう。", "sentence_source": "generated"}, {"text": "「そこにいるのは何者ですか」と、警備員が声をかけた。", "target_word": "何者", "complexity_tier": "T3", "furigana": "「そこにいるのは何者[なにもの]ですか」と、警備員[けいびいん]が声[こえ]をかけた。", "sentence_source": "generated"}, {"text": "見知らぬ旅人に、村人たちは「あなたは何者ですか」とたずねた。", "target_word": "何者", "complexity_tier": "T3", "furigana": "見知[みし]らぬ旅人[たびびと]に、村人[むらびと]たちは「あなたは何者[なにもの]ですか」とたずねた。", "sentence_source": "generated"}, {"text": "彼が何者であるかは、本人が話すまで秘密だ。", "target_word": "何者", "complexity_tier": "T3", "furigana": "彼[かれ]が何者[なにもの]であるかは、本人[ほんにん]が話[はな]すまで秘密[ひみつ]だ。", "sentence_source": "generated"}, {"text": "王様は、城に入ってきた若者が何者か、すぐに調べさせた。", "target_word": "何者", "complexity_tier": "T3", "furigana": "王様[おうさま]は、城[しろ]に入[はい]ってきた若者[わかもの]が何者[なにもの]か、すぐに調[しら]べさせた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "何者", "label": "基本形"}, {"form": "何者か", "label": "疑問の形"}, {"form": "何者だ", "label": "断定形"}, {"form": "何者ですか", "label": "丁寧な疑問形"}], "register": "やや硬い（書き言葉寄り）", "sense_fingerprint": "素性の分からない相手について「どんな人か」を表す語。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98f6d5a5-9f90-4330-858e-b3c0b9ee5e3c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37880, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "何者", "is_correct": true, "explanation": "人の正体を問う語で、「いったい何者なのか」という文脈に合う。"}, {"text": "何事", "is_correct": false, "explanation": "出来事や騒ぎを問う語で、人の正体を問う文には使えない。"}, {"text": "何時", "is_correct": false, "explanation": "時刻を問う語で、「男が何時なのか」は意味が通らない。"}, {"text": "何番", "is_correct": false, "explanation": "番号を問う語で、人の正体には合わない。"}], "explanations": {"何者": "人の正体を問う語で、「いったい何者なのか」という文脈に合う。", "何事": "出来事や騒ぎを問う語で、人の正体を問う文には使えない。", "何時": "時刻を問う語で、「男が何時なのか」は意味が通らない。", "何番": "番号を問う語で、人の正体には合わない。"}, "sentence_index": 0, "correct_answer": "何者"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "机の上の箱は何者なのか、まだ誰も知らない。", "explanation": "物の正体を問うのは〈何〉。〈何者〉は人について使うので、箱には合わない。"}, {"text": "この騒ぎは何者だったのか、誰も説明できなかった。", "explanation": "騒ぎの原因や出来事を問うのは〈何事〉。〈何者〉は人の正体を問うので、騒ぎには使えない。"}, {"text": "受付で何者の名前を確認すればいいか分からない。", "explanation": "名前や人物を特定するのは〈誰〉。〈何者〉は正体や人柄を問うので、名前の確認には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a7f176f-54da-4761-b24e-95a6f306599d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37880, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "何者", "is_correct": true, "explanation": "「そこにいるのは何者ですか」で、相手の正体を問う。"}, {"text": "何色", "is_correct": false, "explanation": "色を問う語で、人の正体を問う文には使えない。"}, {"text": "何語", "is_correct": false, "explanation": "言語を問う語で、人の正体を問う文には合わない。"}, {"text": "何階", "is_correct": false, "explanation": "階数を問う語で、人には使えない。"}], "explanations": {"何者": "「そこにいるのは何者ですか」で、相手の正体を問う。", "何色": "色を問う語で、人の正体を問う文には使えない。", "何語": "言語を問う語で、人の正体を問う文には合わない。", "何階": "階数を問う語で、人には使えない。"}, "sentence_index": 6, "correct_answer": "何者"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "門番は若者を見下し、「お前は何者のつもりだ」と言った。", "explanation": "「〜のつもり」と相手を見下す言い回しは〈何様〉。〈何者〉はこの形では使わないので不自然。"}, {"text": "城で見つかった鍵は何者か、すぐに調べさせた。", "explanation": "物の正体を問うのは〈何物〉。〈何者〉は人について使うので、鍵には合わない。"}, {"text": "次の駅は何者ですか。", "explanation": "場所を尋ねるのは〈何処〉。〈何者〉は人の正体を問うので、駅には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a7f176f-54da-4761-b24e-95a6f306599d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37880, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "私は、相手を何者か分からないまま、会う約束をした。", "corrected_sentence": "私は、相手が何者か分からないまま、会う約束をした。", "error_description": "「何者」の直前の助詞が誤り。「相手が何者か分からない」と、主語の相手を示す「が」が必要。「を」は目的語を示すため不自然。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a7f176f-54da-4761-b24e-95a6f306599d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37880, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "その方は何者だですか。", "corrected_sentence": "その方は何者ですか。", "error_description": "「何者」の後の「だ」が誤り。丁寧な疑問は「何者ですか」で、「だ」と「ですか」は併用しない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a7f176f-54da-4761-b24e-95a6f306599d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37882, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「子どもの問いに」の「に」は、問いに対して母が困った、という関係を示し、ここで合う。"}, {"text": "を", "is_correct": false, "explanation": "「問いを」だと問いが目的語になるが、続く「困った顔をした」とつながらず不自然。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す「へ」では、問いに対する反応という関係を導けないので合わない。"}, {"text": "の", "is_correct": false, "explanation": "「の」は名詞をつなぐ助詞で、文の動詞「困った」「した」の対象にはならない。"}], "correct_answer": "に", "explanations": {"に": "「子どもの問いに」の「に」は、問いに対して母が困った、という関係を示し、ここで合う。", "を": "「問いを」だと問いが目的語になるが、続く「困った顔をした」とつながらず不自然。", "へ": "方向を示す「へ」では、問いに対する反応という関係を導けないので合わない。", "の": "「の」は名詞をつなぐ助詞で、文の動詞「困った」「した」の対象にはならない。"}, "error_tags": {"を": "目的語（困るとつながらない）", "へ": "方向", "の": "連体・所有"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '616496e4-4d0a-47ad-b093-14a19d5697f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37882, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「問いの意味」で、問いと意味をつなぐ「の」。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段・場所を示し、「問いで意味がわからず」とは続かないので合わない。"}, {"text": "に", "is_correct": false, "explanation": "「に」は対象や場所を示すが、「問いに意味」は続かない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を示すが、ここでは比較の文脈がない。"}], "correct_answer": "の", "explanations": {"の": "「問いの意味」で、問いと意味をつなぐ「の」。", "で": "「で」は手段・場所を示し、「問いで意味がわからず」とは続かないので合わない。", "に": "「に」は対象や場所を示すが、「問いに意味」は続かない。", "より": "「より」は比較を示すが、ここでは比較の文脈がない。"}, "error_tags": {"に": "対象・場所", "より": "比較", "で": "手段・場所"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '616496e4-4d0a-47ad-b093-14a19d5697f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37882, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "わからないことを、たずねること。", "primary_collocate": null, "pronunciation": "とい", "ipa": "toi", "syllable_count": 2, "sentences": [{"text": "先生は生徒の問いに、やさしく答えた。", "target_word": "問い", "complexity_tier": "T3", "furigana": "先生[せんせい]は生徒[せいと]の問[と]いに、やさしく答[こた]えた。", "sentence_source": "generated"}, {"text": "子どもの問いに、母は少し困った顔をした。", "target_word": "問い", "complexity_tier": "T3", "furigana": "子[こ]どもの問[と]いに、母[はは]は少[すこ]し困[こま]った顔[かお]をした。", "sentence_source": "generated"}, {"text": "何度も同じ問いをくり返されて、彼は黙ってしまった。", "target_word": "問い", "complexity_tier": "T3", "furigana": "何度[なんど]も同[おな]じ問[と]いをくり返[かえ]されて、彼[かれ]は黙[だま]ってしまった。", "sentence_source": "generated"}, {"text": "旅人の問いに、村の人は道を教えてくれた。", "target_word": "問い", "complexity_tier": "T3", "furigana": "旅人[たびびと]の問[と]いに、村[むら]の人[ひと]は道[みち]を教[おし]えてくれた。", "sentence_source": "generated"}, {"text": "弟の素直な問いに、兄は一つ一つ丁寧に答えた。", "target_word": "問い", "complexity_tier": "T3", "furigana": "弟[おとうと]の素直[すなお]な問[と]いに、兄[あに]は一つ一つ丁寧[ていねい]に答[こた]えた。", "sentence_source": "generated"}, {"text": "突然の問いだったので、すぐには返事ができなかった。", "target_word": "問い", "complexity_tier": "T3", "furigana": "突然[とつぜん]の問[と]いだったので、すぐには返事[へんじ]ができなかった。", "sentence_source": "generated"}, {"text": "会議で社長に問いを向けられ、部長は言葉につまった。", "target_word": "問い", "complexity_tier": "T3", "furigana": "会議[かいぎ]で社長[しゃちょう]に問[と]いを向[む]けられ、部長[ぶちょう]は言葉[ことば]につまった。", "sentence_source": "generated"}, {"text": "その問いの意味がわからず、私は聞き返した。", "target_word": "問い", "complexity_tier": "T3", "furigana": "その問[と]いの意味[いみ]がわからず、私[わたし]は聞[き]き返[かえ]した。", "sentence_source": "generated"}, {"text": "子どもらしい問いに、会場の大人たちが笑った。", "target_word": "問い", "complexity_tier": "T3", "furigana": "子[こ]どもらしい問[と]いに、会場[かいじょう]の大人[おとな]たちが笑[わら]った。", "sentence_source": "generated"}, {"text": "先生は問いを受けたあとで、ゆっくり説明を始めた。", "target_word": "問い", "complexity_tier": "T3", "furigana": "先生[せんせい]は問[と]いを受[う]けたあとで、ゆっくり説明[せつめい]を始[はじ]めた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "問い", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "問い: the act of asking about something one does not know; a question put to someone (人の問いに答える)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e19b2205-6e13-41a2-a86e-2a42bff0feea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37882, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "問い", "is_correct": true, "explanation": "「生徒の問い」は生徒がたずねた内容で、やさしく答えた対象として合う。"}, {"text": "黒板", "is_correct": false, "explanation": "黒板は物で、答える対象にはならないので合わない。"}, {"text": "教科書", "is_correct": false, "explanation": "教科書は本で、人のたずねたことに答える対象にはならない。"}, {"text": "窓", "is_correct": false, "explanation": "窓は物で、答える相手にならないので合わない。"}], "explanations": {"問い": "「生徒の問い」は生徒がたずねた内容で、やさしく答えた対象として合う。", "黒板": "黒板は物で、答える対象にはならないので合わない。", "教科書": "教科書は本で、人のたずねたことに答える対象にはならない。", "窓": "窓は物で、答える相手にならないので合わない。"}, "sentence_index": 0, "correct_answer": "問い"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は新しい問いを買って、部屋に飾った。", "explanation": "ここは〈品物〉の意味（買う）。〈たずねること〉の問いは品物ではないので、買うとは言えない。"}, {"text": "数学の問いが合っていて、ほっとした。", "explanation": "ここは〈答え〉の意味。「合う」のは答えの方で、たずねることの問いが合うとは言わない。"}, {"text": "試験の日が近づき、問いを感じてよく眠れなかった。", "explanation": "ここは〈不安〉の意味。「感じる」のは不安で、たずねることの問いは感じるものではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '616496e4-4d0a-47ad-b093-14a19d5697f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37882, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "問い", "is_correct": true, "explanation": "社長から向けられるのは問いで、「問いを向ける」と合う。"}, {"text": "資料", "is_correct": false, "explanation": "資料は向けられるものではなく、ここでは合わない。"}, {"text": "机", "is_correct": false, "explanation": "机は物で、向けられる対象にならない。"}, {"text": "時計", "is_correct": false, "explanation": "時計は向けられるものではないので合わない。"}], "explanations": {"問い": "社長から向けられるのは問いで、「問いを向ける」と合う。", "資料": "資料は向けられるものではなく、ここでは合わない。", "机": "机は物で、向けられる対象にならない。", "時計": "時計は向けられるものではないので合わない。"}, "sentence_index": 6, "correct_answer": "問い"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼女は亡くなった母のために、静かに問いを捧げた。", "explanation": "ここは〈祈り〉の意味（祈りを捧げる）。〈たずねること〉の問いは捧げるものではないので合わない。"}, {"text": "彼は涙の代わりに、問いを拭った。", "explanation": "ここは〈涙〉の意味（涙を拭う）。〈たずねること〉の問いは拭えないので合わない。"}, {"text": "友人との別れを前に、彼は問いを祝った。", "explanation": "ここは〈祝い〉の意味（祝う）。〈たずねること〉の問いは祝うものではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '616496e4-4d0a-47ad-b093-14a19d5697f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37882, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "先生は生徒の問いを答えた。", "corrected_sentence": "先生は生徒の問いに答えた。", "error_description": "「答える」の対象は「に」で示す。「問いを答えた」は「を」が誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '616496e4-4d0a-47ad-b093-14a19d5697f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37882, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "先生は問いを受けてあとで、すぐに説明を始めた。", "corrected_sentence": "先生は問いを受けたあとで、すぐに説明を始めた。", "error_description": "「受けた」は過去形。「受けてあとで」は文法が誤りで、「受けたあとで」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '616496e4-4d0a-47ad-b093-14a19d5697f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37883, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「この問いの答え」で、問いと答えをつなぐ「の」。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語で、「問いを答え」は成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向で、ここでは答えとの関係にならない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段・場所を示し、「この問いで答えは」と続かないので合わない。"}], "correct_answer": "の", "explanations": {"の": "「この問いの答え」で、問いと答えをつなぐ「の」。", "を": "「を」は目的語で、「問いを答え」は成り立たない。", "へ": "「へ」は方向で、ここでは答えとの関係にならない。", "で": "「で」は手段・場所を示し、「この問いで答えは」と続かないので合わない。"}, "error_tags": {"を": "目的語", "へ": "方向", "で": "手段・場所"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '616496e4-4d0a-47ad-b093-14a19d5697f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37883, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "黒板に書く対象は「問い」で、目的語の「を」が正しい。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段・場所で、「問いで書いて」は意味が合わない。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を示すが、「問いが書いて」では書く動作の主語にも目的語にもならず成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "「の」は名詞をつなぐ助詞で、「問いの書いて」は文が成り立たない。"}], "correct_answer": "を", "explanations": {"を": "黒板に書く対象は「問い」で、目的語の「を」が正しい。", "で": "「で」は手段・場所で、「問いで書いて」は意味が合わない。", "が": "「が」は主語を示すが、「問いが書いて」では書く動作の主語にも目的語にもならず成り立たない。", "の": "「の」は名詞をつなぐ助詞で、「問いの書いて」は文が成り立たない。"}, "error_tags": {"で": "手段・場所", "の": "連体", "が": "主語"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '616496e4-4d0a-47ad-b093-14a19d5697f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37883, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "疑問や問題として提示される、説明や答えを求める言葉や文章。", "primary_collocate": null, "pronunciation": "とい", "ipa": "toi", "syllable_count": 2, "sentences": [{"text": "試験の問いが難しくて、最後まで解けなかった。", "target_word": "問い", "complexity_tier": "T3", "furigana": "試験[しけん]の問[と]いが難[むずか]しくて、最後[さいご]まで解[と]けなかった。", "sentence_source": "generated"}, {"text": "この問いの答えは、本文の三行目に書いてある。", "target_word": "問い", "complexity_tier": "T3", "furigana": "この問[と]いの答[こた]えは、本文[ほんぶん]の三行目[さんぎょうめ]に書[か]いてある。", "sentence_source": "generated"}, {"text": "問いをよく読まなかったので、答えを間違えた。", "target_word": "問い", "complexity_tier": "T3", "furigana": "問[と]いをよく読[よ]まなかったので、答[こた]えを間違[まちが]えた。", "sentence_source": "generated"}, {"text": "哲学者は「人はなぜ生きるのか」という問いを一生考え続けた。", "target_word": "問い", "complexity_tier": "T3", "furigana": "哲学者[てつがくしゃ]は「人[ひと]はなぜ生[い]きるのか」という問[と]いを一生[いっしょう]考[かんが]え続[つづ]けた。", "sentence_source": "generated"}, {"text": "数学の問いは、図を描くと解きやすくなる。", "target_word": "問い", "complexity_tier": "T3", "furigana": "数学[すうがく]の問[と]いは、図[ず]を描[か]くと解[と]きやすくなる。", "sentence_source": "generated"}, {"text": "作文のテストでは、問いの意図をつかむことが大切だ。", "target_word": "問い", "complexity_tier": "T3", "furigana": "作文[さくぶん]のテストでは、問[と]いの意図[いと]をつかむことが大切[たいせつ]だ。", "sentence_source": "generated"}, {"text": "答えは見つかったが、問いそのものが間違っていた。", "target_word": "問い", "complexity_tier": "T3", "furigana": "答[こた]えは見[み]つかったが、問[と]いそのものが間違[まちが]っていた。", "sentence_source": "generated"}, {"text": "先生は黒板に問いを書いて、生徒に考えさせた。", "target_word": "問い", "complexity_tier": "T3", "furigana": "先生[せんせい]は黒板[こくばん]に問[と]いを書[か]いて、生徒[せいと]に考[かんが]えさせた。", "sentence_source": "generated"}, {"text": "長い問いだったので、まず要点に線を引いた。", "target_word": "問い", "complexity_tier": "T3", "furigana": "長[なが]い問[と]いだったので、まず要点[ようてん]に線[せん]を引[ひ]いた。", "sentence_source": "generated"}, {"text": "最後の問いだけは、だれも正解できなかった。", "target_word": "問い", "complexity_tier": "T3", "furigana": "最後[さいご]の問[と]いだけは、だれも正解[せいかい]できなかった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "問い", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "問い: a question or problem set out in words or text that demands an answer (試験の問い、哲学的な問い)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e19b2205-6e13-41a2-a86e-2a42bff0feea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37883, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "問い", "is_correct": true, "explanation": "試験の問いは解くべき問題で、「問いが難しい」と合う。"}, {"text": "色", "is_correct": false, "explanation": "色は試験の難しさの主語にならないので合わない。"}, {"text": "天気", "is_correct": false, "explanation": "天気は試験の難しさを表さないので合わない。"}, {"text": "時計", "is_correct": false, "explanation": "時計は道具で、難しさの主語にならないので合わない。"}], "explanations": {"問い": "試験の問いは解くべき問題で、「問いが難しい」と合う。", "色": "色は試験の難しさの主語にならないので合わない。", "天気": "天気は試験の難しさを表さないので合わない。", "時計": "時計は道具で、難しさの主語にならないので合わない。"}, "sentence_index": 0, "correct_answer": "問い"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "計算の問いが合っていて、ほっとした。", "explanation": "ここは〈答え〉の意味。「合う」のは答えの方で、問いが合うとは言わない。"}, {"text": "彼女は夜、大きな問いを見て目を覚ました。", "explanation": "ここは〈夢〉の意味。「見る」のは夢で、解くべき問題の問いは見るものではない。"}, {"text": "彼は白紙に問いを描き、友達に見せた。", "explanation": "ここは〈絵〉の意味。「描く」のは絵で、問題としての問いは描くものではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '616496e4-4d0a-47ad-b093-14a19d5697f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37883, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "問い", "is_correct": true, "explanation": "答えの対になる問いそのものが間違っていた、と合う。"}, {"text": "窓", "is_correct": false, "explanation": "窓は間違いの対象にならないので合わない。"}, {"text": "椅子", "is_correct": false, "explanation": "椅子は問題の対象ではないので合わない。"}, {"text": "鉛筆", "is_correct": false, "explanation": "鉛筆は問題そのものではないので合わない。"}], "explanations": {"問い": "答えの対になる問いそのものが間違っていた、と合う。", "窓": "窓は間違いの対象にならないので合わない。", "椅子": "椅子は問題の対象ではないので合わない。", "鉛筆": "鉛筆は問題そのものではないので合わない。"}, "sentence_index": 6, "correct_answer": "問い"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "父は重い問いをひいて、会社を休んだ。", "explanation": "ここは〈風邪〉の意味（風邪をひく）。「ひく」は病気に使い、問いには使わない。"}, {"text": "彼は先生の前で大きな問いをつき、宿題を免れた。", "explanation": "ここは〈嘘〉の意味（嘘をつく）。「つく」は嘘に使い、問いには使わない。"}, {"text": "彼は白い紙に問いを塗って、先生に出した。", "explanation": "ここは〈色〉の意味。「塗る」は色を対象にするので、問いには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '616496e4-4d0a-47ad-b093-14a19d5697f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37883, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "試験の問いを答えて、最後まで悩んだ。", "corrected_sentence": "試験の問いに答えて、最後まで悩んだ。", "error_description": "「答える」の対象は「に」で示す。「問いを答えて」は「を」が誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '616496e4-4d0a-47ad-b093-14a19d5697f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37883, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "先生は黒板に問いを書いたして、生徒に長く考えさせた。", "corrected_sentence": "先生は黒板に問いを書いて、生徒に長く考えさせた。", "error_description": "「書いて」は接続形。「書いたして」は文法が誤りで、「書いて」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '616496e4-4d0a-47ad-b093-14a19d5697f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37884, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "問う", "is_correct": true, "explanation": "答えるが応じる相手となる、質問を投げかける行為。答えるの対義語として辞書に挙がる。"}, {"text": "忘れる", "is_correct": false, "explanation": "忘れるは記憶を失うことで、答えるの対義語ではない。"}, {"text": "歌う", "is_correct": false, "explanation": "歌うは声を出して旋律を表すことで、答えるとは対になる関係にない。"}, {"text": "開く", "is_correct": false, "explanation": "開くは閉じたものを広げることで、答えるとは関係がない。"}], "correct_answer": "問う", "explanations": {"問う": "答えるが応じる相手となる、質問を投げかける行為。答えるの対義語として辞書に挙がる。", "忘れる": "忘れるは記憶を失うことで、答えるの対義語ではない。", "歌う": "歌うは声を出して旋律を表すことで、答えるとは対になる関係にない。", "開く": "開くは閉じたものを広げることで、答えるとは関係がない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d48e443-0dbf-4466-acec-a3edef6548fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37884, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "問う", "is_correct": true, "explanation": "答えるが応じる相手となる、問いを投げかける行為。答えるの対義語として辞書に挙がる。"}, {"text": "眠る", "is_correct": false, "explanation": "眠るは休息の状態を表し、答えるとは対になる関係にない。"}, {"text": "届ける", "is_correct": false, "explanation": "届けるは物を相手のところへ運ぶことで、答えるの対義語ではない。"}, {"text": "掘る", "is_correct": false, "explanation": "掘るは地面に穴をあける動作で、答えるとは関係がない。"}], "correct_answer": "問う", "explanations": {"問う": "答えるが応じる相手となる、問いを投げかける行為。答えるの対義語として辞書に挙がる。", "眠る": "眠るは休息の状態を表し、答えるとは対になる関係にない。", "届ける": "届けるは物を相手のところへ運ぶことで、答えるの対義語ではない。", "掘る": "掘るは地面に穴をあける動作で、答えるとは関係がない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d48e443-0dbf-4466-acec-a3edef6548fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37884, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "質問や問題に、ことばや行動で返すこと。", "primary_collocate": null, "pronunciation": "こたえる", "ipa": "kotaeɾɯ", "syllable_count": 4, "sentences": [{"text": "先生の質問に、私は大きな声で答えました。", "target_word": "答えました", "complexity_tier": "T3", "furigana": "先生[せんせい]の質問[しつもん]に、私[わたし]は大[おお]きな声[こえ]で答[こた]えました。", "sentence_source": "generated"}, {"text": "彼は何も言わず、うなずいて答えた。", "target_word": "答えた", "complexity_tier": "T3", "furigana": "彼[かれ]は何[なに]も言[い]わず、うなずいて答[こた]えた。", "sentence_source": "generated"}, {"text": "試験の問題に答える前に、全体を読んでください。", "target_word": "答える", "complexity_tier": "T3", "furigana": "試験[しけん]の問題[もんだい]に答[こた]える前[まえ]に、全体[ぜんたい]を読[よ]んでください。", "sentence_source": "generated"}, {"text": "名前を呼ばれたら、手を挙げて答えてください。", "target_word": "答えて", "complexity_tier": "T3", "furigana": "名前[なまえ]を呼[よ]ばれたら、手[て]を挙[あ]げて答[こた]えてください。", "sentence_source": "generated"}, {"text": "記者の質問に、社長は落ち着いて答えていた。", "target_word": "答えていた", "complexity_tier": "T3", "furigana": "記者[きしゃ]の質問[しつもん]に、社長[しゃちょう]は落[お]ち着[つ]いて答[こた]えていた。", "sentence_source": "generated"}, {"text": "難しい質問だったので、すぐには答えられなかった。", "target_word": "答えられなかった", "complexity_tier": "T3", "furigana": "難[むずか]しい質問[しつもん]だったので、すぐには答[こた]えられなかった。", "sentence_source": "generated"}, {"text": "聞かれたことに答えないと、話が進みません。", "target_word": "答えない", "complexity_tier": "T3", "furigana": "聞[き]かれたことに答[こた]えないと、話[はなし]が進[すす]みません。", "sentence_source": "generated"}, {"text": "メールで質問したら、担当者がていねいに答えてくれた。", "target_word": "答えてくれた", "complexity_tier": "T3", "furigana": "メールで質問[しつもん]したら、担当者[たんとうしゃ]がていねいに答[こた]えてくれた。", "sentence_source": "generated"}, {"text": "クイズの問題に、チームで相談して答えた。", "target_word": "答えた", "complexity_tier": "T3", "furigana": "クイズの問題[もんだい]に、チームで相談[そうだん]して答[こた]えた。", "sentence_source": "generated"}, {"text": "質問が多すぎて、全部には答えきれなかった。", "target_word": "答えきれなかった", "complexity_tier": "T3", "furigana": "質問[しつもん]が多[おお]すぎて、全部[ぜんぶ]には答[こた]えきれなかった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "答える", "label": "辞書形"}, {"form": "答えます", "label": "丁寧形"}, {"form": "答えた", "label": "過去形"}, {"form": "答えない", "label": "否定形"}, {"form": "答えて", "label": "て形"}, {"form": "答えれば", "label": "仮定形"}, {"form": "答えられる", "label": "可能形"}, {"form": "答えよう", "label": "意志形"}], "register": "neutral", "sense_fingerprint": "質問や問題に対して、ことばや身ぶりで返す", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28474861-32e1-4bed-92ca-a633d6cda916') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37884, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "答えました", "is_correct": true, "explanation": "「大きな声で答える」は自然で、先生の質問に返した行為として文に合う。"}, {"text": "眠りました", "is_correct": false, "explanation": "眠る（寝る）は質問への応答ではなく、「大きな声で」とも結びつかない。"}, {"text": "磨きました", "is_correct": false, "explanation": "磨く（みがく）は物を対象にする動詞で、「質問に」と組み合わせると文が成り立たない。"}, {"text": "凍りました", "is_correct": false, "explanation": "凍る（こおる）は自動詞で、「質問に」「大きな声で」と結びつく文にならない。"}], "explanations": {"答えました": "「大きな声で答える」は自然で、先生の質問に返した行為として文に合う。", "眠りました": "眠る（寝る）は質問への応答ではなく、「大きな声で」とも結びつかない。", "磨きました": "磨く（みがく）は物を対象にする動詞で、「質問に」と組み合わせると文が成り立たない。", "凍りました": "凍る（こおる）は自動詞で、「質問に」「大きな声で」と結びつく文にならない。"}, "sentence_index": 0, "correct_answer": "答えました"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "借りたお金を、彼は週末に答えた。", "explanation": "ここは〈返す〉の意味との混同。答えるは問いへの返事を指すので、借りた物を返す場面には使えない。"}, {"text": "先生は難しい理論を、黒板を使って答えた。", "explanation": "ここは〈説明する〉の意味との混同。答えるは問いに返す行為で、理論を順序立てて解き明かす場面には使わない。"}, {"text": "この曲で、彼は感動を答えた。", "explanation": "ここは〈伝える〉の意味。答えるは問いへの返事を指し、感情を相手に届ける場面では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d48e443-0dbf-4466-acec-a3edef6548fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37884, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "答えない", "is_correct": true, "explanation": "否定形。「聞かれたことに答えないと、話が進まない」と文意が通る。"}, {"text": "洗わない", "is_correct": false, "explanation": "洗う（洗浄する）は「聞かれたこと」を対象にできず、文が成り立たない。"}, {"text": "踊らない", "is_correct": false, "explanation": "踊る（おどる）は「聞かれたことに」と結びつかず、話が進まない理由にならない。"}, {"text": "削らない", "is_correct": false, "explanation": "削る（けずる）は物を対象にする動詞で、「聞かれたことに」と組み合わせると不自然。"}], "explanations": {"答えない": "否定形。「聞かれたことに答えないと、話が進まない」と文意が通る。", "洗わない": "洗う（洗浄する）は「聞かれたこと」を対象にできず、文が成り立たない。", "踊らない": "踊る（おどる）は「聞かれたことに」と結びつかず、話が進まない理由にならない。", "削らない": "削る（けずる）は物を対象にする動詞で、「聞かれたことに」と組み合わせると不自然。"}, "sentence_index": 6, "correct_answer": "答えない"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は友人に、本当の気持ちを答えた。", "explanation": "ここは〈打ち明ける〉の意味。答えるは問いに返す行為で、自分の気持ちを明かす場面には合わない。"}, {"text": "彼は反対する人を、丁寧に答えた。", "explanation": "ここは〈説得する〉の意味との混同。答えるは返事をする意味で、相手を説き伏せる文には使えない。"}, {"text": "落とした鍵を、彼は急いで答えた。", "explanation": "ここは〈拾う〉の意味。答えるは問いや問題に返すことで、落ちた物を拾う場面では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d48e443-0dbf-4466-acec-a3edef6548fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37884, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "先生の質問を、彼はすぐに答えた。", "corrected_sentence": "先生の質問に、彼はすぐに答えた。", "error_description": "誤: 質問を答えた → 正: 質問に答えた。答えるは「〜に答える」の形で、応答の相手や対象に「に」を付ける。「を」では不自然な文になる。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "答えた", "is_correct": true, "explanation": "過去形。うなずいて応じた動作が完了したことを示す。"}, {"text": "答えない", "is_correct": false, "explanation": "否定形。答えたという事実を打ち消してしまい、文の意味に合わない。"}, {"text": "答えられる", "is_correct": false, "explanation": "可能形。能力や可能性を表し、実際に行った動作を述べる文には合わない。"}, {"text": "答えよう", "is_correct": false, "explanation": "意志形。これからの意向を表すので、過去の出来事には使えない。"}], "correct_form": "答えた", "base_form": "答える", "form_label": "過去形", "sentence_index": 1, "explanations": {"答えた": "過去形。うなずいて応じた動作が完了したことを示す。", "答えない": "否定形。答えたという事実を打ち消してしまい、文の意味に合わない。", "答えられる": "可能形。能力や可能性を表し、実際に行った動作を述べる文には合わない。", "答えよう": "意志形。これからの意向を表すので、過去の出来事には使えない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d48e443-0dbf-4466-acec-a3edef6548fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37884, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "質問の数が多くて、全部には答えきれられなかった。", "corrected_sentence": "質問の数が多くて、全部には答えきれなかった。", "error_description": "誤: 答えきれられなかった（可能の意味を二重に重ねた形）→ 正: 答えきれなかった。「〜きれる」が既に「全部〜できる」の意味を持つので、可能形の「られ」を重ねてはいけない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "答えてくれた", "is_correct": true, "explanation": "〜てくれた形。相手が自分のために答えてくれたという授受の意味を表す。"}, {"text": "答えてくれなかった", "is_correct": false, "explanation": "否定形。「ていねいに」と矛盾し、答えてもらった事実を打ち消す。"}, {"text": "答えて", "is_correct": false, "explanation": "て形。時系列や理由を続ける形で、過去の授受の文を完結させられない。"}, {"text": "答えられる", "is_correct": false, "explanation": "可能形。できることを表し、実際に答えてもらった出来事には合わない。"}], "correct_form": "答えてくれた", "base_form": "答える", "form_label": "てくれた形", "sentence_index": 7, "explanations": {"答えてくれた": "〜てくれた形。相手が自分のために答えてくれたという授受の意味を表す。", "答えてくれなかった": "否定形。「ていねいに」と矛盾し、答えてもらった事実を打ち消す。", "答えて": "て形。時系列や理由を続ける形で、過去の授受の文を完結させられない。", "答えられる": "可能形。できることを表し、実際に答えてもらった出来事には合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d48e443-0dbf-4466-acec-a3edef6548fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37885, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "問う", "is_correct": true, "explanation": "答えるが応じる相手となる、問いを投げかける行為。答えるの対義語として辞書に挙がる。"}, {"text": "泳ぐ", "is_correct": false, "explanation": "泳ぐは水中を移動する動作で、答えるとは対になる関係にない。"}, {"text": "隠す", "is_correct": false, "explanation": "隠すは物を見えないようにする動作で、答えるの対義語ではない。"}, {"text": "乗る", "is_correct": false, "explanation": "乗るは物の上に移ることで、答えるとは関係がない。"}], "correct_answer": "問う", "explanations": {"問う": "答えるが応じる相手となる、問いを投げかける行為。答えるの対義語として辞書に挙がる。", "泳ぐ": "泳ぐは水中を移動する動作で、答えるとは対になる関係にない。", "隠す": "隠すは物を見えないようにする動作で、答えるの対義語ではない。", "乗る": "乗るは物の上に移ることで、答えるとは関係がない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d48e443-0dbf-4466-acec-a3edef6548fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37885, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "問う", "is_correct": true, "explanation": "答えるが応じる相手となる、問いを投げかける行為。答えるの対義語として辞書に挙がる。"}, {"text": "数える", "is_correct": false, "explanation": "数えるは数量を確かめる動作で、答えるの対義語ではない。"}, {"text": "寝る", "is_correct": false, "explanation": "寝るは睡眠をとる動作で、答えるとは対になる関係にない。"}, {"text": "織る", "is_correct": false, "explanation": "織るは糸で布を作る動作で、答えるとは関係がない。"}], "correct_answer": "問う", "explanations": {"問う": "答えるが応じる相手となる、問いを投げかける行為。答えるの対義語として辞書に挙がる。", "数える": "数えるは数量を確かめる動作で、答えるの対義語ではない。", "寝る": "寝るは睡眠をとる動作で、答えるとは対になる関係にない。", "織る": "織るは糸で布を作る動作で、答えるとは関係がない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d48e443-0dbf-4466-acec-a3edef6548fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37885, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "問いかけや要求に対して、答えや返事をすること。また、その答えを述べる。", "primary_collocate": null, "pronunciation": "こたえる", "ipa": "kotaeɾɯ", "syllable_count": 4, "sentences": [{"text": "「行きますか」と聞くと、彼は「はい」と答えた。", "target_word": "答えた", "complexity_tier": "T3", "furigana": "「行[い]きますか」と聞[き]くと、彼[かれ]は「はい」と答[こた]えた。", "sentence_source": "generated"}, {"text": "名前を聞かれて、彼女は小さな声で「田中です」と答えた。", "target_word": "答えた", "complexity_tier": "T3", "furigana": "名前[なまえ]を聞[き]かれて、彼女[かのじょ]は小[ちい]さな声[こえ]で「田中[たなか]です」と答[こた]えた。", "sentence_source": "generated"}, {"text": "年齢を聞かれたが、彼は答えたくなさそうだった。", "target_word": "答えたく", "complexity_tier": "T3", "furigana": "年齢[ねんれい]を聞[き]かれたが、彼[かれ]は答[こた]えたくなさそうだった。", "sentence_source": "generated"}, {"text": "アンケートに答える人には、小さな贈り物があります。", "target_word": "答える", "complexity_tier": "T3", "furigana": "アンケートに答[こた]える人[ひと]には、小[ちい]さな贈[おく]り物[もの]があります。", "sentence_source": "generated"}, {"text": "どうして遅れたのかと聞かれ、正直に答えました。", "target_word": "答えました", "complexity_tier": "T3", "furigana": "どうして遅[おく]れたのかと聞[き]かれ、正直[しょうじき]に答[こた]えました。", "sentence_source": "generated"}, {"text": "答えがわからなくて、「わかりません」と答えるしかなかった。", "target_word": "答える", "complexity_tier": "T3", "furigana": "答[こた]えがわからなくて、「わかりません」と答[こた]えるしかなかった。", "sentence_source": "generated"}, {"text": "「明日は来られますか」と聞かれ、彼女はすぐに答えた。", "target_word": "答えた", "complexity_tier": "T3", "furigana": "「明日[あした]は来[こ]られますか」と聞[き]かれ、彼女[かのじょ]はすぐに答[こた]えた。", "sentence_source": "generated"}, {"text": "「いいえ」と答えた人は、次の問いに進まなくてよい。", "target_word": "答えた", "complexity_tier": "T3", "furigana": "「いいえ」と答[こた]えた人[ひと]は、次[つぎ]の問[と]いに進[すす]まなくてよい。", "sentence_source": "generated"}, {"text": "先生に聞かれたら、思ったとおりに答えればいいよ。", "target_word": "答えれば", "complexity_tier": "T3", "furigana": "先生[せんせい]に聞[き]かれたら、思[おも]ったとおりに答[こた]えればいいよ。", "sentence_source": "generated"}, {"text": "面接で志望理由を聞かれ、はっきりと答えられた。", "target_word": "答えられた", "complexity_tier": "T3", "furigana": "面接[めんせつ]で志望[しぼう]理由[りゆう]を聞[き]かれ、はっきりと答[こた]えられた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "答える", "label": "辞書形"}, {"form": "答えます", "label": "丁寧形"}, {"form": "答えた", "label": "過去形"}, {"form": "答えない", "label": "否定形"}, {"form": "答えて", "label": "て形"}, {"form": "答えれば", "label": "仮定形"}, {"form": "答えられる", "label": "可能形"}, {"form": "答えよう", "label": "意志形"}], "register": "neutral", "sense_fingerprint": "問われたことに対する返事や答えの内容を述べる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28474861-32e1-4bed-92ca-a633d6cda916') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37885, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "答えた", "is_correct": true, "explanation": "「はい」と返事をしたという意味で、「と答えた」の形として文に合う。"}, {"text": "踊った", "is_correct": false, "explanation": "踊る（おどる）は「「はい」と」と結びつかず、聞かれた後の返事として成り立たない。"}, {"text": "掘った", "is_correct": false, "explanation": "掘る（ほる）は地面などを対象にする動詞で、返事の文には入らない。"}, {"text": "洗った", "is_correct": false, "explanation": "洗う（あらう）は物を対象にする動詞で、「「はい」と洗った」は意味をなさない。"}], "explanations": {"答えた": "「はい」と返事をしたという意味で、「と答えた」の形として文に合う。", "踊った": "踊る（おどる）は「「はい」と」と結びつかず、聞かれた後の返事として成り立たない。", "掘った": "掘る（ほる）は地面などを対象にする動詞で、返事の文には入らない。", "洗った": "洗う（あらう）は物を対象にする動詞で、「「はい」と洗った」は意味をなさない。"}, "sentence_index": 0, "correct_answer": "答えた"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "アンケートの参加者に、小さな贈り物を答えた。", "explanation": "ここは〈贈る〉の意味。答えるは問いに返す行為で、物を相手に渡す場面では使わない。"}, {"text": "大事な会議の資料を、彼は一晩で答えた。", "explanation": "ここは〈作る〉の意味。答えるは問いへの返事で、資料を作る場面には合わない。"}, {"text": "会議で、チームは新しいプランを答えた。", "explanation": "ここは〈提示する〉の意味との混同。答えるは問いへの返事を指すので、計画を示す場面には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d48e443-0dbf-4466-acec-a3edef6548fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37885, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "答えた", "is_correct": true, "explanation": "「すぐに答えた」は自然で、聞かれた後の返答として文に合う。"}, {"text": "磨いた", "is_correct": false, "explanation": "磨く（みがく）は物を対象にする動詞で、「すぐに磨いた」は返答の文として成り立たない。"}, {"text": "凍った", "is_correct": false, "explanation": "凍る（こおる）は自動詞で、「すぐに凍った」は聞かれた人の行動として文に合わない。"}, {"text": "織った", "is_correct": false, "explanation": "織る（おる）は布などを作る動詞で、返答の文には入らない。"}], "explanations": {"答えた": "「すぐに答えた」は自然で、聞かれた後の返答として文に合う。", "磨いた": "磨く（みがく）は物を対象にする動詞で、「すぐに磨いた」は返答の文として成り立たない。", "凍った": "凍る（こおる）は自動詞で、「すぐに凍った」は聞かれた人の行動として文に合わない。", "織った": "織る（おる）は布などを作る動詞で、返答の文には入らない。"}, "sentence_index": 6, "correct_answer": "答えた"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "手紙を、彼は遠い町の友人に答えた。", "explanation": "ここは〈届ける〉の意味。答えるは問いへの返事で、物を相手のもとへ運ぶ場面では使わない。"}, {"text": "贈り物を、彼女は笑顔で答えた。", "explanation": "ここは〈受け取る〉の意味。答えるは相手に返す行為で、贈られた物を受け取る場面では使わない。"}, {"text": "担当者は新しい制度を、丁寧に答えた。", "explanation": "ここは〈説明する〉の意味との混同。答えるは問いへの返事で、制度の仕組みを述べる場面には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d48e443-0dbf-4466-acec-a3edef6548fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37885, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "先生の問いに、正直に答えるた。", "corrected_sentence": "先生の問いに、正直に答えた。", "error_description": "誤: 答えるた → 正: 答えた。答えるは一段動詞なので、過去形は「答え」に「た」を付ける。辞書形の「答える」に「た」を重ねてはいけない。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "答えた", "is_correct": true, "explanation": "過去形。「はい」「田中です」と返した動作が完了したことを示す。"}, {"text": "答えます", "is_correct": false, "explanation": "丁寧形。非過去の丁寧な表現で、過去の出来事を述べる文には合わない。"}, {"text": "答えない", "is_correct": false, "explanation": "否定形。返答したという事実を打ち消し、文の意味に合わない。"}, {"text": "答えられる", "is_correct": false, "explanation": "可能形。できることを表し、実際に答えた出来事を述べる文には合わない。"}], "correct_form": "答えた", "base_form": "答える", "form_label": "過去形", "sentence_index": 1, "explanations": {"答えた": "過去形。「はい」「田中です」と返した動作が完了したことを示す。", "答えます": "丁寧形。非過去の丁寧な表現で、過去の出来事を述べる文には合わない。", "答えない": "否定形。返答したという事実を打ち消し、文の意味に合わない。", "答えられる": "可能形。できることを表し、実際に答えた出来事を述べる文には合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d48e443-0dbf-4466-acec-a3edef6548fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37885, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "「はい」を答えた人は、そのまま次へ進んでください。", "corrected_sentence": "「はい」と答えた人は、そのまま次へ進んでください。", "error_description": "誤: 「はい」を答えた → 正: 「はい」と答えた。答えるは返答の内容を「と」で受ける動詞で、「を」は取らない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "答えた", "is_correct": true, "explanation": "過去形の連体修飾。「「いいえ」と答えた人」のように、答えた動作を持つ人を修飾している。"}, {"text": "答えたら", "is_correct": false, "explanation": "たら形。条件を表すので、名詞「人」を修飾する文にならない。"}, {"text": "答えて", "is_correct": false, "explanation": "て形。修飾の形として成り立たず、人を修飾する文にならない。"}, {"text": "答えよう", "is_correct": false, "explanation": "意志形。これからの意向を表すので、既に答えた人を修飾する文には使えない。"}], "correct_form": "答えた", "base_form": "答える", "form_label": "過去形（連体修飾）", "sentence_index": 7, "explanations": {"答えた": "過去形の連体修飾。「「いいえ」と答えた人」のように、答えた動作を持つ人を修飾している。", "答えたら": "たら形。条件を表すので、名詞「人」を修飾する文にならない。", "答えて": "て形。修飾の形として成り立たず、人を修飾する文にならない。", "答えよう": "意志形。これからの意向を表すので、既に答えた人を修飾する文には使えない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d48e443-0dbf-4466-acec-a3edef6548fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37886, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "基準を示す「〜に照らして」の「に」。道徳を基準に判断した文脈に合う。"}, {"text": "の", "is_correct": false, "explanation": "連体修飾の「の」。「私の道徳の照らして」では「道徳の」が動詞に結びつかず、文が成り立たない。"}, {"text": "が", "is_correct": false, "explanation": "主格の「が」。「道徳が照らして」では主語が立たず、「許せなかった」の文意と合わない。"}, {"text": "へ", "is_correct": false, "explanation": "方向の「へ」。「道徳へ照らして」では光を向ける先の意味になり、基準を示す文脈に合わない。"}], "correct_answer": "に", "explanations": {"に": "基準を示す「〜に照らして」の「に」。道徳を基準に判断した文脈に合う。", "の": "連体修飾の「の」。「私の道徳の照らして」では「道徳の」が動詞に結びつかず、文が成り立たない。", "が": "主格の「が」。「道徳が照らして」では主語が立たず、「許せなかった」の文意と合わない。", "へ": "方向の「へ」。「道徳へ照らして」では光を向ける先の意味になり、基準を示す文脈に合わない。"}, "error_tags": {"の": "連体修飾", "が": "主格", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25c1e5d6-c0e8-4304-9fb4-e18af266873f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37886, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "主格の「が」。「道徳がある」で存在するものを示し、理由の「から」につながる。"}, {"text": "と", "is_correct": false, "explanation": "並列・共同の「と」。「道徳とあるから」では並べる相手がなく、意味が通らない。"}, {"text": "の", "is_correct": false, "explanation": "連体修飾の「の」。「道徳の」で止まると「ある」の主語が立たず、文が成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "比較の「より」。「道徳よりある」では比べる対象がなく、存在の主語を示せない。"}], "correct_answer": "が", "explanations": {"が": "主格の「が」。「道徳がある」で存在するものを示し、理由の「から」につながる。", "と": "並列・共同の「と」。「道徳とあるから」では並べる相手がなく、意味が通らない。", "の": "連体修飾の「の」。「道徳の」で止まると「ある」の主語が立たず、文が成り立たない。", "より": "比較の「より」。「道徳よりある」では比べる対象がなく、存在の主語を示せない。"}, "error_tags": {"と": "並列・共同", "の": "連体修飾", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25c1e5d6-c0e8-4304-9fb4-e18af266873f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37886, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "人が正しいことと悪いことを考えるときの、心の中の決まりです。", "primary_collocate": null, "pronunciation": "どうとく", "ipa": "doːtoku", "syllable_count": 4, "sentences": [{"text": "人をだますのは、道徳に反する行いだ。", "target_word": "道徳", "complexity_tier": "T3", "furigana": "人[ひと]をだますのは、道徳[どうとく]に反[はん]する行[おこな]いだ。", "sentence_source": "generated"}, {"text": "そのやり方は、私の道徳に照らして許せなかった。", "target_word": "道徳", "complexity_tier": "T3", "furigana": "そのやり方[やりかた]は、私[わたし]の道徳[どうとく]に照[て]らして許[ゆる]せなかった。", "sentence_source": "generated"}, {"text": "彼は道徳を大切にして、うそをつかない。", "target_word": "道徳", "complexity_tier": "T3", "furigana": "彼[かれ]は道徳[どうとく]を大切[たいせつ]にして、うそをつかない。", "sentence_source": "generated"}, {"text": "道徳を守る人は、ごみを道に捨てない。", "target_word": "道徳", "complexity_tier": "T3", "furigana": "道徳[どうとく]を守[まも]る人[ひと]は、ごみを道[みち]に捨[す]てない。", "sentence_source": "generated"}, {"text": "落とし物を届けるのは、道徳として当たり前だ。", "target_word": "道徳", "complexity_tier": "T3", "furigana": "落[お]とし物[もの]を届[とど]けるのは、道徳[どうとく]として当[あ]たり前[まえ]だ。", "sentence_source": "generated"}, {"text": "子どもに道徳を教えるのは、家庭の大切な役目だ。", "target_word": "道徳", "complexity_tier": "T3", "furigana": "子[こ]どもに道徳[どうとく]を教[おし]えるのは、家庭[かてい]の大切[たいせつ]な役目[やくめ]だ。", "sentence_source": "generated"}, {"text": "お年寄りに席をゆずる心は、道徳の基本だ。", "target_word": "道徳", "complexity_tier": "T3", "furigana": "お年寄[としよ]りに席[せき]をゆずる心[こころ]は、道徳[どうとく]の基本[きほん]だ。", "sentence_source": "generated"}, {"text": "道徳があるから、人は人を傷つけてはいけないと考える。", "target_word": "道徳", "complexity_tier": "T3", "furigana": "道徳[どうとく]があるから、人[ひと]は人[ひと]を傷[きず]つけてはいけないと考[かんが]える。", "sentence_source": "generated"}, {"text": "父は、うそをつかないことを自分の道徳として守っている。", "target_word": "道徳", "complexity_tier": "T3", "furigana": "父[ちち]は、うそをつかないことを自分[じぶん]の道徳[どうとく]として守[まも]っている。", "sentence_source": "generated"}, {"text": "道徳の心がない人は、ほかの人の気持ちを考えない。", "target_word": "道徳", "complexity_tier": "T3", "furigana": "道徳[どうとく]の心[こころ]がない人[ひと]は、ほかの人[ひと]の気持[きも]ちを考[かんが]えない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "道徳", "label": "基本形"}], "register": "標準", "sense_fingerprint": "善悪を考えるときの心の中の決まり", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a04de0b4-b7c5-4a40-b388-094939d08f82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37886, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "道徳", "is_correct": true, "explanation": "心の中で善悪を判断する決まりを表し、「〜に反する行い」に入って文意が通る。"}, {"text": "距離", "is_correct": false, "explanation": "長さを表す語で、「〜に反する」と結べず空所に入らない。"}, {"text": "季節", "is_correct": false, "explanation": "時期を表す語で、規範に反する行いという文には入らない。"}, {"text": "天気", "is_correct": false, "explanation": "天候の意味で、規範に反する行いとは結びつかない。"}], "explanations": {"道徳": "心の中で善悪を判断する決まりを表し、「〜に反する行い」に入って文意が通る。", "距離": "長さを表す語で、「〜に反する」と結べず空所に入らない。", "季節": "時期を表す語で、規範に反する行いという文には入らない。", "天気": "天候の意味で、規範に反する行いとは結びつかない。"}, "sentence_index": 0, "correct_answer": "道徳"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この箱の道徳は、五キロもある。", "explanation": "ここは〈重さ〉の意味。道徳は心の中の決まりで、物の重さを表す語ではない。"}, {"text": "彼は道徳が豊富で、歴史の質問に何でも答える。", "explanation": "ここは〈知識〉の意味。道徳は善悪を考える決まりで、知っている事柄の量を表さない。"}, {"text": "彼は道徳が強く、一日中走り続けられる。", "explanation": "ここは〈体力〉の意味。道徳は心の中の決まりで、身体の強さを表す語ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25c1e5d6-c0e8-4304-9fb4-e18af266873f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37886, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "道徳", "is_correct": true, "explanation": "お年寄りに席をゆずるような心の土台となる規範を指し、「〜の基本だ」に入って文意が通る。"}, {"text": "手紙", "is_correct": false, "explanation": "文書の意味で、心の基本として成り立たない。"}, {"text": "切符", "is_correct": false, "explanation": "乗車券の意味で、心の基本にはならない。"}, {"text": "窓", "is_correct": false, "explanation": "建物の開口部の意味で、心の基本として文が通らない。"}], "explanations": {"道徳": "お年寄りに席をゆずるような心の土台となる規範を指し、「〜の基本だ」に入って文意が通る。", "手紙": "文書の意味で、心の基本として成り立たない。", "切符": "乗車券の意味で、心の基本にはならない。", "窓": "建物の開口部の意味で、心の基本として文が通らない。"}, "sentence_index": 6, "correct_answer": "道徳"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この煮物は道徳が濃くて、少し塩辛い。", "explanation": "ここは〈味〉の意味。道徳は行いの善悪を考える決まりで、料理の味の濃さには使わない。"}, {"text": "新幹線の道徳は、時速三百キロを超える。", "explanation": "ここは〈速さ〉の意味。道徳は善悪の判断の基準で、速度を表す語ではない。"}, {"text": "明日の道徳は、晴れるらしい。", "explanation": "ここは〈天気〉の意味。道徳は心の中の決まりで、天候の予報には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25c1e5d6-c0e8-4304-9fb4-e18af266873f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37886, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "人を傷つけるのは、道徳が反する行いだ。", "corrected_sentence": "人を傷つけるのは、道徳に反する行いだ。", "error_description": "「反する」は「〜に反する」と「に」を取る。「が」にすると「反する」と結びつかず、文が成り立たない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25c1e5d6-c0e8-4304-9fb4-e18af266873f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37886, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "赤ちゃんに優しくする心は、道徳を基本だ。", "corrected_sentence": "赤ちゃんに優しくする心は、道徳の基本だ。", "error_description": "「道徳の基本」と「の」で結ぶ。「を」にすると「基本だ」と結びつかず、文が成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25c1e5d6-c0e8-4304-9fb4-e18af266873f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37887, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "連体修飾の「の」。「道徳の基準」で基準の所属先を示し、「基準も変わる」につながる。"}, {"text": "を", "is_correct": false, "explanation": "目的語の「を」。「道徳を基準も変わる」では目的語が立たず、文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "方向の「へ」。「道徳へ基準も」では向かう先にならず、基準の所属を示せない。"}, {"text": "が", "is_correct": false, "explanation": "主格の「が」。「道徳が基準も変わる」では主語が二つ並んで文が崩れる。"}], "correct_answer": "の", "explanations": {"の": "連体修飾の「の」。「道徳の基準」で基準の所属先を示し、「基準も変わる」につながる。", "を": "目的語の「を」。「道徳を基準も変わる」では目的語が立たず、文が成り立たない。", "へ": "方向の「へ」。「道徳へ基準も」では向かう先にならず、基準の所属を示せない。", "が": "主格の「が」。「道徳が基準も変わる」では主語が二つ並んで文が崩れる。"}, "error_tags": {"を": "目的語", "へ": "方向", "が": "主格"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25c1e5d6-c0e8-4304-9fb4-e18af266873f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37887, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "場面・範囲を示す「で」。「昔の道徳では」で、その時代の基準の範囲を示す。"}, {"text": "の", "is_correct": false, "explanation": "連体修飾の「の」。「昔の道徳のは」では名詞に「の」が続き、主題を示せず文が成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "並列・共同の「と」。「道徳と」では並べる相手がなく、文が成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "比較の「より」。「道徳より」では比べる対象がなく、主題を示せない。"}], "correct_answer": "で", "explanations": {"で": "場面・範囲を示す「で」。「昔の道徳では」で、その時代の基準の範囲を示す。", "の": "連体修飾の「の」。「昔の道徳のは」では名詞に「の」が続き、主題を示せず文が成り立たない。", "と": "並列・共同の「と」。「道徳と」では並べる相手がなく、文が成り立たない。", "より": "比較の「より」。「道徳より」では比べる対象がなく、主題を示せない。"}, "error_tags": {"の": "連体修飾", "と": "並列・共同", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25c1e5d6-c0e8-4304-9fb4-e18af266873f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37887, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "社会で良いとされる行動や考え方の基準。善悪を判断するための規範。", "primary_collocate": null, "pronunciation": "どうとく", "ipa": "doːtoku", "syllable_count": 4, "sentences": [{"text": "社会の道徳に反する行動は、非難される。", "target_word": "道徳", "complexity_tier": "T3", "furigana": "社会[しゃかい]の道徳[どうとく]に反[はん]する行動[こうどう]は、非難[ひなん]される。", "sentence_source": "generated"}, {"text": "時代が変わると、道徳の基準も変わることがある。", "target_word": "道徳", "complexity_tier": "T3", "furigana": "時代[じだい]が変[か]わると、道徳[どうとく]の基準[きじゅん]も変[か]わることがある。", "sentence_source": "generated"}, {"text": "国によって、道徳の考え方はちがう。", "target_word": "道徳", "complexity_tier": "T3", "furigana": "国[くに]によって、道徳[どうとく]の考[かんが]え方[かた]はちがう。", "sentence_source": "generated"}, {"text": "その広告は、公共の道徳に合わないとして中止された。", "target_word": "道徳", "complexity_tier": "T3", "furigana": "その広告[こうこく]は、公共[こうきょう]の道徳[どうとく]に合[あ]わないとして中止[ちゅうし]された。", "sentence_source": "generated"}, {"text": "法律では禁じられていないが、道徳の面では問題がある。", "target_word": "道徳", "complexity_tier": "T3", "furigana": "法律[ほうりつ]では禁[きん]じられていないが、道徳[どうとく]の面[めん]では問題[もんだい]がある。", "sentence_source": "generated"}, {"text": "道徳は、善悪を判断するときのよりどころになる。", "target_word": "道徳", "complexity_tier": "T3", "furigana": "道徳[どうとく]は、善悪[ぜんあく]を判断[はんだん]するときのよりどころになる。", "sentence_source": "generated"}, {"text": "社会の道徳として、順番を守ることが求められる。", "target_word": "道徳", "complexity_tier": "T3", "furigana": "社会[しゃかい]の道徳[どうとく]として、順番[じゅんばん]を守[まも]ることが求[もと]められる。", "sentence_source": "generated"}, {"text": "昔の道徳では、親に逆らうことは許されなかった。", "target_word": "道徳", "complexity_tier": "T3", "furigana": "昔[むかし]の道徳[どうとく]では、親[おや]に逆[さか]らうことは許[ゆる]されなかった。", "sentence_source": "generated"}, {"text": "政治家には、法律だけでなく道徳も求められる。", "target_word": "道徳", "complexity_tier": "T3", "furigana": "政治家[せいじか]には、法律[ほうりつ]だけでなく道徳[どうとく]も求[もと]められる。", "sentence_source": "generated"}, {"text": "道徳と法律は似ているが、同じものではない。", "target_word": "道徳", "complexity_tier": "T3", "furigana": "道徳[どうとく]と法律[ほうりつ]は似[に]ているが、同[おな]じものではない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "道徳", "label": "基本形"}], "register": "標準", "sense_fingerprint": "社会が善悪を判断するときの規範や基準", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a04de0b4-b7c5-4a40-b388-094939d08f82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37887, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "道徳", "is_correct": true, "explanation": "社会で良いとされる行動の基準を表し、「社会の〜に反する行動」に入って文意が通る。"}, {"text": "料理", "is_correct": false, "explanation": "食べ物の意味で、社会の基準に反する行動とは結びつかない。"}, {"text": "天気", "is_correct": false, "explanation": "天候の意味で、社会の基準を表す語として入らない。"}, {"text": "距離", "is_correct": false, "explanation": "長さを表す語で、「〜に反する行動」とは成り立たない。"}], "explanations": {"道徳": "社会で良いとされる行動の基準を表し、「社会の〜に反する行動」に入って文意が通る。", "料理": "食べ物の意味で、社会の基準に反する行動とは結びつかない。", "天気": "天候の意味で、社会の基準を表す語として入らない。", "距離": "長さを表す語で、「〜に反する行動」とは成り立たない。"}, "sentence_index": 0, "correct_answer": "道徳"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この煮物の道徳は、少し塩辛い。", "explanation": "ここは〈味〉の意味。道徳は社会の善悪の基準で、料理の塩辛さを表す語ではない。"}, {"text": "マラソン選手は道徳が強く、どんなに長く走っても疲れない。", "explanation": "ここは〈体力〉の意味。道徳は社会の善悪の基準で、身体の強さには使わない。"}, {"text": "電車の道徳は、時速百キロを超える。", "explanation": "ここは〈速さ〉の意味。道徳は善悪の基準で、速度を表す語ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25c1e5d6-c0e8-4304-9fb4-e18af266873f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37887, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "道徳", "is_correct": true, "explanation": "社会の行動規範を指し、「社会の〜として求められる」に入って文意が通る。"}, {"text": "手紙", "is_correct": false, "explanation": "文書の意味で、社会の規範の形としては成り立たない。"}, {"text": "窓", "is_correct": false, "explanation": "建物の開口部の意味で、「社会の〜として」には入らない。"}, {"text": "切符", "is_correct": false, "explanation": "乗車券の意味で、社会の規範として文が通らない。"}], "explanations": {"道徳": "社会の行動規範を指し、「社会の〜として求められる」に入って文意が通る。", "手紙": "文書の意味で、社会の規範の形としては成り立たない。", "窓": "建物の開口部の意味で、「社会の〜として」には入らない。", "切符": "乗車券の意味で、社会の規範として文が通らない。"}, "sentence_index": 6, "correct_answer": "道徳"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この壁の道徳は、明るい黄色だ。", "explanation": "ここは〈色〉の意味。道徳は社会の善悪の基準で、壁の色を表す語ではない。"}, {"text": "この先生は道徳が豊富で、年号を全部覚えている。", "explanation": "ここは〈知識〉の意味。道徳は社会の規範で、学んだ知識の量を表さない。"}, {"text": "明日の道徳は、晴れて暖かいらしい。", "explanation": "ここは〈天気〉の意味。道徳は善悪の基準で、天候の予報には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25c1e5d6-c0e8-4304-9fb4-e18af266873f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37887, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ルールを破るのは、社会の道徳が反する行動だ。", "corrected_sentence": "ルールを破るのは、社会の道徳に反する行動だ。", "error_description": "「反する」は「に」を取る。「が」は誤りで、「に反する」と結びつけなければならない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25c1e5d6-c0e8-4304-9fb4-e18af266873f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37887, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "社会の道徳を、ごみを分けることが求められる。", "corrected_sentence": "社会の道徳として、ごみを分けることが求められる。", "error_description": "「社会の道徳として」の形が正しい。「を」では目的語にならず、「求められる」の文の主題と結びつかない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25c1e5d6-c0e8-4304-9fb4-e18af266873f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
