INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37888, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "得るは目的語を「を」で取る。「教訓を得た」は経験から教えを得たという自然な文になる。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を表すため、「教訓が得た」では得る行為の対象が立たない。"}, {"text": "に", "is_correct": false, "explanation": "「に」は着点や相手を表すため、「教訓に得た」は得る対象として成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表すため、「教訓へ得た」は文として意味をなさない。"}], "correct_answer": "を", "explanations": {"を": "得るは目的語を「を」で取る。「教訓を得た」は経験から教えを得たという自然な文になる。", "が": "「が」は主語を表すため、「教訓が得た」では得る行為の対象が立たない。", "に": "「に」は着点や相手を表すため、「教訓に得た」は得る対象として成り立たない。", "へ": "「へ」は方向を表すため、「教訓へ得た」は文として意味をなさない。"}, "error_tags": {"が": "主語を表す格", "に": "着点や相手を表す格", "へ": "方向を表す格"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d48e443-0dbf-4466-acec-a3edef6548fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37888, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "学んだこと。", "primary_collocate": null, "pronunciation": "きょうくん", "ipa": "kʲoːkɯɴ", "syllable_count": 4, "sentences": [{"text": "失敗から学んだ教訓を、ノートに書いておきました。", "target_word": "教訓", "complexity_tier": "T3", "furigana": "失敗[しっぱい]から学[まな]んだ教訓[きょうくん]を、ノートに書[か]いておきました。", "sentence_source": "generated"}, {"text": "この旅行で得た教訓は、早めに準備することだ。", "target_word": "教訓", "complexity_tier": "T3", "furigana": "この旅行[りょこう]で得[え]た教訓[きょうくん]は、早[はや]めに準備[じゅんび]することだ。", "sentence_source": "generated"}, {"text": "忘れ物をした日の教訓は、前の晩に確認することです。", "target_word": "教訓", "complexity_tier": "T3", "furigana": "忘[わす]れ物[もの]をした日[ひ]の教訓[きょうくん]は、前[まえ]の晩[ばん]に確認[かくにん]することです。", "sentence_source": "generated"}, {"text": "彼は試合に負けて、大切な教訓を学んだ。", "target_word": "教訓", "complexity_tier": "T3", "furigana": "彼[かれ]は試合[しあい]に負[ま]けて、大切[たいせつ]な教訓[きょうくん]を学[まな]んだ。", "sentence_source": "generated"}, {"text": "先輩は自分の失敗を教訓として話してくれた。", "target_word": "教訓", "complexity_tier": "T3", "furigana": "先輩[せんぱい]は自分[じぶん]の失敗[しっぱい]を教訓[きょうくん]として話[はな]してくれた。", "sentence_source": "generated"}, {"text": "今回の教訓を、次の計画に生かしたい。", "target_word": "教訓", "complexity_tier": "T3", "furigana": "今回[こんかい]の教訓[きょうくん]を、次[つぎ]の計画[けいかく]に生[い]かしたい。", "sentence_source": "generated"}, {"text": "道に迷った経験が、私にはいい教訓になった。", "target_word": "教訓", "complexity_tier": "T3", "furigana": "道[みち]に迷[まよ]った経験[けいけん]が、私[わたし]にはいい教訓[きょうくん]になった。", "sentence_source": "generated"}, {"text": "教訓を得たので、同じ間違いは二度としない。", "target_word": "教訓", "complexity_tier": "T3", "furigana": "教訓[きょうくん]を得[え]たので、同じ[おなじ]間違[まちが]いは二度[にど]としない。", "sentence_source": "generated"}, {"text": "この話の教訓は何だと思いますか。", "target_word": "教訓", "complexity_tier": "T3", "furigana": "この話[はなし]の教訓[きょうくん]は何[なん]だと思[おも]いますか。", "sentence_source": "generated"}, {"text": "祖母から聞いた昔話の教訓を、今でも覚えている。", "target_word": "教訓", "complexity_tier": "T3", "furigana": "祖母[そぼ]から聞[き]いた昔話[むかしばなし]の教訓[きょうくん]を、今[いま]でも覚[おぼ]えている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "教訓", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "出来事や失敗から学び取ったこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28474861-32e1-4bed-92ca-a633d6cda916') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37888, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "教訓", "is_correct": true, "explanation": "失敗から学んだ教えを指し、ノートに書くものとして文に合う。"}, {"text": "体温", "is_correct": false, "explanation": "体温は体の温度で、「学んだ体温」「書いておいた体温」は意味をなさない。"}, {"text": "空腹", "is_correct": false, "explanation": "空腹は腹が空いた状態で、学んだものとして書き留める対象にはならない。"}, {"text": "疲労", "is_correct": false, "explanation": "疲労は体の疲れで、「失敗から学んだ疲労」は文として成り立たない。"}], "explanations": {"教訓": "失敗から学んだ教えを指し、ノートに書くものとして文に合う。", "体温": "体温は体の温度で、「学んだ体温」「書いておいた体温」は意味をなさない。", "空腹": "空腹は腹が空いた状態で、学んだものとして書き留める対象にはならない。", "疲労": "疲労は体の疲れで、「失敗から学んだ疲労」は文として成り立たない。"}, "sentence_index": 0, "correct_answer": "教訓"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "寒かったので、教訓を閉めた。", "explanation": "ここは〈ドアを閉める〉の意味。教訓は閉めるものではなく、物として扱えない。"}, {"text": "難しい問題に、彼は教訓を絞って挑んだ。", "explanation": "ここは〈知恵を絞る〉の意味との混同。教訓は経験から得た教えで、絞り出すものではない。"}, {"text": "駅の窓口で、教訓を買った。", "explanation": "ここは〈切符を買う〉の意味。教訓は買えるものではなく、学んだことを指す。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d48e443-0dbf-4466-acec-a3edef6548fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37888, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "教訓", "is_correct": true, "explanation": "経験から得た教えを指し、「いい教訓になった」と文に合う。"}, {"text": "病気", "is_correct": false, "explanation": "病気は体の不調で、「いい病気になった」は意味をなさない。"}, {"text": "騒音", "is_correct": false, "explanation": "騒音は不快な音で、「いい騒音になった」とは言えない。"}, {"text": "雷", "is_correct": false, "explanation": "雷は気象現象で、「いい雷になった」は経験の結果として成り立たない。"}], "explanations": {"教訓": "経験から得た教えを指し、「いい教訓になった」と文に合う。", "病気": "病気は体の不調で、「いい病気になった」は意味をなさない。", "騒音": "騒音は不快な音で、「いい騒音になった」とは言えない。", "雷": "雷は気象現象で、「いい雷になった」は経験の結果として成り立たない。"}, "sentence_index": 6, "correct_answer": "教訓"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "旅行で撮った教訓を、今も大切に持っている。", "explanation": "ここは〈写真〉の意味との混同。教訓は撮るものではなく、学んだことを指す。"}, {"text": "換気のため、教訓を開けた。", "explanation": "ここは〈窓を開ける〉の意味。教訓は開けられるものではない。"}, {"text": "用件が終わったので、教訓を切った。", "explanation": "ここは〈電話を切る〉の意味。教訓は切れるものではなく、この文では使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d48e443-0dbf-4466-acec-a3edef6548fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37888, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "失敗から教訓が得て、次は慎重に進めた。", "corrected_sentence": "失敗から教訓を得て、次は慎重に進めた。", "error_description": "誤: 教訓が得て → 正: 教訓を得て。得るは目的語を「を」で取る動詞なので、「が」では不自然な文になる。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d48e443-0dbf-4466-acec-a3edef6548fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37888, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "教訓を得たた人は、同じ失敗を繰り返さない。", "corrected_sentence": "教訓を得た人は、同じ失敗を繰り返さない。", "error_description": "誤: 得たた → 正: 得た。「得た」で既に過去形なので、「た」を重ねてはいけない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d48e443-0dbf-4466-acec-a3edef6548fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
