INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37889, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "経験から得た、これからの行動の指針となる教えや学び。", "primary_collocate": null, "pronunciation": "きょうくん", "ipa": "kʲoːkɯɴ", "syllable_count": 4, "sentences": [{"text": "過去の事故の教訓を、安全の決まりに取り入れた。", "target_word": "教訓", "complexity_tier": "T3", "furigana": "過去[かこ]の事故[じこ]の教訓[きょうくん]を、安全[あんぜん]の決[き]まりに取[と]り入[い]れた。", "sentence_source": "generated"}, {"text": "歴史の教訓に学ぶことは、国にとって大切だ。", "target_word": "教訓", "complexity_tier": "T3", "furigana": "歴史[れきし]の教訓[きょうくん]に学[まな]ぶことは、国[くに]にとって大切[たいせつ]だ。", "sentence_source": "generated"}, {"text": "失敗を教訓にして、会社は新しい仕組みを作った。", "target_word": "教訓", "complexity_tier": "T3", "furigana": "失敗[しっぱい]を教訓[きょうくん]にして、会社[かいしゃ]は新[あたら]しい仕組[しく]みを作[つく]った。", "sentence_source": "generated"}, {"text": "地震の教訓から、学校は避難訓練を増やした。", "target_word": "教訓", "complexity_tier": "T3", "furigana": "地震[じしん]の教訓[きょうくん]から、学校[がっこう]は避難[ひなん]訓練[くんれん]を増[ふ]やした。", "sentence_source": "generated"}, {"text": "「急がば回れ」という教訓を、祖父はよく口にした。", "target_word": "教訓", "complexity_tier": "T3", "furigana": "「急[いそ]がば回[まわ]れ」という教訓[きょうくん]を、祖父[そふ]はよく口[くち]にした。", "sentence_source": "generated"}, {"text": "この事件の教訓を、次の世代に伝えなければならない。", "target_word": "教訓", "complexity_tier": "T3", "furigana": "この事件[じけん]の教訓[きょうくん]を、次[つぎ]の世代[せだい]に伝[つた]えなければならない。", "sentence_source": "generated"}, {"text": "彼は苦い経験を教訓に、毎月貯金を始めた。", "target_word": "教訓", "complexity_tier": "T3", "furigana": "彼[かれ]は苦[にが]い経験[けいけん]を教訓[きょうくん]に、毎月[まいつき]貯金[ちょきん]を始[はじ]めた。", "sentence_source": "generated"}, {"text": "前回の教訓が生かされず、同じ問題がまた起きた。", "target_word": "教訓", "complexity_tier": "T3", "furigana": "前回[ぜんかい]の教訓[きょうくん]が生[い]かされず、同[おな]じ問題[もんだい]がまた起[お]きた。", "sentence_source": "generated"}, {"text": "災害の教訓を忘れないために、記念館が建てられた。", "target_word": "教訓", "complexity_tier": "T3", "furigana": "災害[さいがい]の教訓[きょうくん]を忘[わす]れないために、記念館[きねんかん]が建[た]てられた。", "sentence_source": "generated"}, {"text": "失敗から得た教訓は、お金には替えられない財産だ。", "target_word": "教訓", "complexity_tier": "T3", "furigana": "失敗[しっぱい]から得[え]た教訓[きょうくん]は、お金[かね]には替[か]えられない財産[ざいさん]だ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "教訓", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "経験から得て今後の行動の指針にする教え", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28474861-32e1-4bed-92ca-a633d6cda916') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37889, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "教訓", "is_correct": true, "explanation": "事故から得た教えを指し、「安全の決まりに取り入れた」と文に合う。"}, {"text": "体温", "is_correct": false, "explanation": "体温は体の温度で、「安全の決まりに取り入れた体温」は意味をなさない。"}, {"text": "空腹", "is_correct": false, "explanation": "空腹は腹が空いた状態で、決まりに取り入れる対象にはならない。"}, {"text": "天気", "is_correct": false, "explanation": "天気は気象の状態で、安全の決まりに取り入れるものではない。"}], "explanations": {"教訓": "事故から得た教えを指し、「安全の決まりに取り入れた」と文に合う。", "体温": "体温は体の温度で、「安全の決まりに取り入れた体温」は意味をなさない。", "空腹": "空腹は腹が空いた状態で、決まりに取り入れる対象にはならない。", "天気": "天気は気象の状態で、安全の決まりに取り入れるものではない。"}, "sentence_index": 0, "correct_answer": "教訓"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "雨が降ってきたので、教訓を閉めた。", "explanation": "ここは〈ドアを閉める〉の意味。教訓は閉めるものではなく、物として扱えない。"}, {"text": "のどが渇いて、教訓を飲んだ。", "explanation": "ここは〈水を飲む〉の意味。教訓は飲めるものではなく、学んだ教えを指す。"}, {"text": "日差しが強いので、教訓をかぶった。", "explanation": "ここは〈帽子をかぶる〉の意味。教訓は身につけるものではなく、この文では使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d48e443-0dbf-4466-acec-a3edef6548fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37889, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "教訓", "is_correct": true, "explanation": "苦い経験から得た教えを指し、「教訓に、貯金を始めた」と文に合う。"}, {"text": "病気", "is_correct": false, "explanation": "病気は体の不調で、「苦い経験を病気に」は意味をなさない。"}, {"text": "騒音", "is_correct": false, "explanation": "騒音は不快な音で、「苦い経験を騒音に」と言い換える文にはならない。"}, {"text": "雷", "is_correct": false, "explanation": "雷は気象現象で、「苦い経験を雷に」は文として成り立たない。"}], "explanations": {"教訓": "苦い経験から得た教えを指し、「教訓に、貯金を始めた」と文に合う。", "病気": "病気は体の不調で、「苦い経験を病気に」は意味をなさない。", "騒音": "騒音は不快な音で、「苦い経験を騒音に」と言い換える文にはならない。", "雷": "雷は気象現象で、「苦い経験を雷に」は文として成り立たない。"}, "sentence_index": 6, "correct_answer": "教訓"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "靴をはいて、教訓を履いた。", "explanation": "ここは〈履き物〉の意味との混同。教訓は身につけて使う物ではなく、学んだ教えを指すので履くものとしては合わない。"}, {"text": "花に水をやって、教訓に水をやった。", "explanation": "ここは〈庭木を育てる〉の意味との混同。教訓は学んだ教えで、水をやって育てる対象ではないので合わない。"}, {"text": "用件が終わったので、教訓の電源を切った。", "explanation": "ここは〈電源を切る〉の意味との混同。教訓は電気機器のように切るものではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d48e443-0dbf-4466-acec-a3edef6548fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37889, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "過去の事故の教訓が、防災の手引きに取り入れた。", "corrected_sentence": "過去の事故の教訓を、防災の手引きに取り入れた。", "error_description": "誤: 教訓が → 正: 教訓を。取り入れるは目的語を「を」で取る動詞で、「が」では取り入れた動作の対象がなくなる。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d48e443-0dbf-4466-acec-a3edef6548fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37889, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "前回の教訓を生かしず、今回は同じ失敗を防げた。", "corrected_sentence": "前回の教訓を生かして、今回は同じ失敗を防げた。", "error_description": "誤: 生かしず → 正: 生かして。生かすは五段動詞で、て形は「生かして」。「生かしず」は存在しない誤った活用形。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d48e443-0dbf-4466-acec-a3edef6548fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
