INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37890, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "言いたいことを相手にわかるように話すこと。", "primary_collocate": null, "pronunciation": "とく", "ipa": "tokɯ", "syllable_count": 2, "sentences": [{"text": "先生は生徒に、毎日勉強する大切さを説いた。", "target_word": "説いた", "complexity_tier": "T3", "furigana": "先生[せんせい]は生徒[せいと]に、毎日[まいにち]勉強[べんきょう]する大切[たいせつ]さを説[と]いた。", "sentence_source": "generated"}, {"text": "彼は仲間に、計画に参加するよう熱心に説いていた。", "target_word": "説いていた", "complexity_tier": "T3", "furigana": "彼[かれ]は仲間[なかま]に、計画[けいかく]に参加[さんか]するよう熱心[ねっしん]に説[と]いていた。", "sentence_source": "generated"}, {"text": "母は私に、約束を守ることの大切さを説いてくれた。", "target_word": "説いてくれた", "complexity_tier": "T3", "furigana": "母[はは]は私[わたし]に、約束[やくそく]を守[まも]ることの大切[たいせつ]さを説[と]いてくれた。", "sentence_source": "generated"}, {"text": "医者は患者に、運動を続けるよう優しく説いた。", "target_word": "説いた", "complexity_tier": "T3", "furigana": "医者[いしゃ]は患者[かんじゃ]に、運動[うんどう]を続[つづ]けるよう優[やさ]しく説[と]いた。", "sentence_source": "generated"}, {"text": "社長は社員を集めて、新しい方針の必要を説いた。", "target_word": "説いた", "complexity_tier": "T3", "furigana": "社長[しゃちょう]は社員[しゃいん]を集[あつ]めて、新[あたら]しい方針[ほうしん]の必要[ひつよう]を説[と]いた。", "sentence_source": "generated"}, {"text": "父は兄に、進学したほうがいいと何度も説いた。", "target_word": "説いた", "complexity_tier": "T3", "furigana": "父[ちち]は兄[あに]に、進学[しんがく]したほうがいいと何度[なんど]も説[と]いた。", "sentence_source": "generated"}, {"text": "彼女は反対する人たちに、じっくり理由を説いて回った。", "target_word": "説いて", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は反対[はんたい]する人[ひと]たちに、じっくり理由[りゆう]を説[と]いて回[まわ]った。", "sentence_source": "generated"}, {"text": "説いても聞かない相手には、時間を置くしかない。", "target_word": "説いても", "complexity_tier": "T3", "furigana": "説[と]いても聞[き]かない相手[あいて]には、時間[じかん]を置[お]くしかない。", "sentence_source": "generated"}, {"text": "友人に、遠慮せず相談するよう説かれて、私は決心した。", "target_word": "説かれて", "complexity_tier": "T3", "furigana": "友人[ゆうじん]に、遠慮[えんりょ]せず相談[そうだん]するよう説[と]かれて、私[わたし]は決心[けっしん]した。", "sentence_source": "generated"}, {"text": "先輩は新人に、あいさつの大切さを説いている。", "target_word": "説いている", "complexity_tier": "T3", "furigana": "先輩[せんぱい]は新人[しんじん]に、あいさつの大切[たいせつ]さを説[と]いている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "説く", "label": "辞書形"}, {"form": "説きます", "label": "丁寧形"}, {"form": "説いた", "label": "過去形"}, {"form": "説かない", "label": "否定形"}, {"form": "説いて", "label": "て形"}, {"form": "説けば", "label": "仮定形"}, {"form": "説かれる", "label": "受身形"}, {"form": "説こう", "label": "意志形"}], "register": "neutral", "sense_fingerprint": "相手に納得してもらえるよう、考えや主張を話して聞かせる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28474861-32e1-4bed-92ca-a633d6cda916') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37890, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "説いた", "is_correct": true, "explanation": "「大切さを説く」は、道理を相手にわかるように話して納得させる意味。ここに入る。"}, {"text": "叱った", "is_correct": false, "explanation": "叱るは相手の言動を責める動作。「大切さを叱った」とは言えず、内容を伝える文に合わない。"}, {"text": "怒った", "is_correct": false, "explanation": "怒るは感情を表す動詞で、「大切さを怒った」とは言わない。"}, {"text": "謝った", "is_correct": false, "explanation": "謝るは詫びる動作で、目的語に「大切さ」は取れない。文が成り立たない。"}], "explanations": {"説いた": "「大切さを説く」は、道理を相手にわかるように話して納得させる意味。ここに入る。", "叱った": "叱るは相手の言動を責める動作。「大切さを叱った」とは言えず、内容を伝える文に合わない。", "怒った": "怒るは感情を表す動詞で、「大切さを怒った」とは言わない。", "謝った": "謝るは詫びる動作で、目的語に「大切さ」は取れない。文が成り立たない。"}, "sentence_index": 0, "correct_answer": "説いた"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は固く結ばれたひもを説いた。", "explanation": "ここは〈解く〉の意味。説くは道理や考えを話して相手に理解させることで、結び目をほどく動作には使わない。"}, {"text": "彼は子どもの頃の思い出を説いた。", "explanation": "ここは〈語る〉の意味。説くは意味や道理を相手に納得させる働きで、思い出を話す場面には使わない。"}, {"text": "彼は友人に秘密を説いた。", "explanation": "ここは〈打ち明ける〉の意味。説くは理屈で納得させることで、秘密を明かす場面では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d48e443-0dbf-4466-acec-a3edef6548fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37890, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "説いて", "is_correct": true, "explanation": "「理由を説いて回る」は、理由を話して納得させて回ること。ここに入る。"}, {"text": "責めて", "is_correct": false, "explanation": "責めるは非難する動作。「理由を責めて回る」とは言わず、内容を伝える文に合わない。"}, {"text": "詫びて", "is_correct": false, "explanation": "詫びるは謝る動作。「理由を詫びて回る」は成り立たない。"}, {"text": "怒鳴って", "is_correct": false, "explanation": "怒鳴るは大声を出す動作。「理由を怒鳴る」は目的語として不自然で、文が成り立たない。"}], "explanations": {"説いて": "「理由を説いて回る」は、理由を話して納得させて回ること。ここに入る。", "責めて": "責めるは非難する動作。「理由を責めて回る」とは言わず、内容を伝える文に合わない。", "詫びて": "詫びるは謝る動作。「理由を詫びて回る」は成り立たない。", "怒鳴って": "怒鳴るは大声を出す動作。「理由を怒鳴る」は目的語として不自然で、文が成り立たない。"}, "sentence_index": 6, "correct_answer": "説いて"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "先輩は新人に、夕飯を説いた。", "explanation": "ここは〈作る〉の意味。説くは意味や道理を言葉で伝える行為で、料理をする場面には使わない。"}, {"text": "新人がコップを説いた。", "explanation": "ここは〈壊す〉の意味。説くは話を通じて理解させる行為で、物を壊す意味はない。"}, {"text": "先輩は新人の努力を説いた。", "explanation": "ここは〈褒める〉の意味。説くは道理を伝える行為で、努力を評価する意味では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d48e443-0dbf-4466-acec-a3edef6548fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37890, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "部長は部下で、報告を毎日出す大切さを説いた。", "corrected_sentence": "部長は部下に、報告を毎日出す大切さを説いた。", "error_description": "説く相手は「に」で示す。「部下で」は場所・手段を表し、説く相手として成り立たない。正しくは「部下に」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "説いていた", "is_correct": true, "explanation": "「〜ていた」は過去の継続を表す。「熱心に説いていた」の形で、文の流れに合う。"}, {"text": "説かない", "is_correct": false, "explanation": "否定形で、説いたこと自体を打ち消す意味になり、文の内容と合わない。"}, {"text": "説きます", "is_correct": false, "explanation": "丁寧形の非過去で、過去の継続を述べる文脈に合わない。"}, {"text": "説けば", "is_correct": false, "explanation": "仮定形で、「〜ば」の条件節になる。文末の過去の出来事として成り立たない。"}], "correct_form": "説いていた", "base_form": "説く", "form_label": "〜ていた（過去の継続）", "sentence_index": 1, "explanations": {"説いていた": "「〜ていた」は過去の継続を表す。「熱心に説いていた」の形で、文の流れに合う。", "説かない": "否定形で、説いたこと自体を打ち消す意味になり、文の内容と合わない。", "説きます": "丁寧形の非過去で、過去の継続を述べる文脈に合わない。", "説けば": "仮定形で、「〜ば」の条件節になる。文末の過去の出来事として成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d48e443-0dbf-4466-acec-a3edef6548fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37890, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "会長は株主に、新しい計画の利点を説きた。", "corrected_sentence": "会長は株主に、新しい計画の利点を説いた。", "error_description": "過去形の誤り。五段活用の「説く」の過去形は「説いた」（イ音便）。「説きた」は正しい活用形ではない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "説いても", "is_correct": true, "explanation": "「〜ても」は逆接の形。「説いても聞かない相手」の文脈に合う。"}, {"text": "説いた", "is_correct": false, "explanation": "過去形で「〜ても」とつながらない。「説いた聞かない相手」は成り立たない。"}, {"text": "説こう", "is_correct": false, "explanation": "意志形で、「〜ても」とつながらない。「説こう聞かない相手」は成り立たない。"}, {"text": "説く", "is_correct": false, "explanation": "辞書形で「〜ても」とつながらない。「説く聞かない相手」は文が成り立たない。"}], "correct_form": "説いても", "base_form": "説く", "form_label": "〜ても（逆接）", "sentence_index": 7, "explanations": {"説いても": "「〜ても」は逆接の形。「説いても聞かない相手」の文脈に合う。", "説いた": "過去形で「〜ても」とつながらない。「説いた聞かない相手」は成り立たない。", "説こう": "意志形で、「〜ても」とつながらない。「説こう聞かない相手」は成り立たない。", "説く": "辞書形で「〜ても」とつながらない。「説く聞かない相手」は文が成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d48e443-0dbf-4466-acec-a3edef6548fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
