INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37891, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "物事の意味や道理などを、相手に理解できるように説明する。", "primary_collocate": null, "pronunciation": "とく", "ipa": "tokɯ", "syllable_count": 2, "sentences": [{"text": "僧は村人に、仏の教えの意味をやさしく説いた。", "target_word": "説いた", "complexity_tier": "T3", "furigana": "僧[そう]は村人[むらびと]に、仏[ほとけ]の教[おし]えの意味[いみ]をやさしく説[と]いた。", "sentence_source": "generated"}, {"text": "先生は黒板を使って、この法則の仕組みを説いた。", "target_word": "説いた", "complexity_tier": "T3", "furigana": "先生[せんせい]は黒板[こくばん]を使[つか]って、この法則[ほうそく]の仕組[しく]みを説[と]いた。", "sentence_source": "generated"}, {"text": "その本は、人が生きる道理を短い話で説いている。", "target_word": "説いている", "complexity_tier": "T3", "furigana": "その本[ほん]は、人[ひと]が生[い]きる道理[どうり]を短[みじか]い話[はなし]で説[と]いている。", "sentence_source": "generated"}, {"text": "彼は経済の考え方を、例を挙げてわかりやすく説いた。", "target_word": "説いた", "complexity_tier": "T3", "furigana": "彼[かれ]は経済[けいざい]の考[かんが]え方[かた]を、例[れい]を挙[あ]げてわかりやすく説[と]いた。", "sentence_source": "generated"}, {"text": "哲学者は、正しい行いとは何かを弟子に説いた。", "target_word": "説いた", "complexity_tier": "T3", "furigana": "哲学者[てつがくしゃ]は、正[ただ]しい行[おこな]いとは何[なに]かを弟子[でし]に説[と]いた。", "sentence_source": "generated"}, {"text": "講師は、健康の基本となる理屈を図で説いていた。", "target_word": "説いていた", "complexity_tier": "T3", "furigana": "講師[こうし]は、健康[けんこう]の基本[きほん]となる理屈[りくつ]を図[ず]で説[と]いていた。", "sentence_source": "generated"}, {"text": "孔子は人の守るべき道を説いたと言われる。", "target_word": "説いた", "complexity_tier": "T3", "furigana": "孔子[こうし]は人[ひと]の守[まも]るべき道[みち]を説[と]いたと言[い]われる。", "sentence_source": "generated"}, {"text": "彼は環境を守る理由を、数字を使って説いた。", "target_word": "説いた", "complexity_tier": "T3", "furigana": "彼[かれ]は環境[かんきょう]を守[まも]る理由[りゆう]を、数字[すうじ]を使[つか]って説[と]いた。", "sentence_source": "generated"}, {"text": "教授は法律の考え方を、学生に順序立てて説いた。", "target_word": "説いた", "complexity_tier": "T3", "furigana": "教授[きょうじゅ]は法律[ほうりつ]の考[かんが]え方[かた]を、学生[がくせい]に順序立[じゅんじょだ]てて説[と]いた。", "sentence_source": "generated"}, {"text": "この物語は、助け合うことの意味を説いている。", "target_word": "説いている", "complexity_tier": "T3", "furigana": "この物語[ものがたり]は、助[たす]け合[あ]うことの意味[いみ]を説[と]いている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "説く", "label": "辞書形"}, {"form": "説きます", "label": "丁寧形"}, {"form": "説いた", "label": "過去形"}, {"form": "説かない", "label": "否定形"}, {"form": "説いて", "label": "て形"}, {"form": "説けば", "label": "仮定形"}, {"form": "説かれる", "label": "受身形"}, {"form": "説こう", "label": "意志形"}], "register": "neutral", "sense_fingerprint": "物事の意味や道理を、理解できるよう順を追って説明する", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28474861-32e1-4bed-92ca-a633d6cda916') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37891, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "説いた", "is_correct": true, "explanation": "「教えの意味を説く」は、物事の意味を相手に理解できるよう説明する意味。ここに入る。"}, {"text": "叱った", "is_correct": false, "explanation": "叱るは相手を責める動作。「意味を叱った」とは言えず、説明の文脈に合わない。"}, {"text": "怒った", "is_correct": false, "explanation": "怒るは感情を表す。「教えの意味を怒った」は成り立たない。"}, {"text": "謝った", "is_correct": false, "explanation": "謝るは詫びる動作で、「意味を謝った」とは言えない。"}], "explanations": {"説いた": "「教えの意味を説く」は、物事の意味を相手に理解できるよう説明する意味。ここに入る。", "叱った": "叱るは相手を責める動作。「意味を叱った」とは言えず、説明の文脈に合わない。", "怒った": "怒るは感情を表す。「教えの意味を怒った」は成り立たない。", "謝った": "謝るは詫びる動作で、「意味を謝った」とは言えない。"}, "sentence_index": 0, "correct_answer": "説いた"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は絡まった糸を説いた。", "explanation": "ここは〈解く〉の意味。説くは意味を言葉で伝える行為で、絡まった糸をほどく動作には使わない。"}, {"text": "彼は風景を説いた。", "explanation": "ここは〈描く〉の意味。説くは言葉で意味を伝える行為で、景色を絵や文章で描く場面では使わない。"}, {"text": "彼は子守歌を説いた。", "explanation": "ここは〈歌う〉の意味。説くは道理や意味を伝えることで、歌を歌う行為には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d48e443-0dbf-4466-acec-a3edef6548fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37891, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "説いた", "is_correct": true, "explanation": "「道を説いた」は、道理を人に説明した意味。ここに入る。"}, {"text": "責めた", "is_correct": false, "explanation": "責めるは相手を非難する動作。「人の道を責めた」は意味が通らない。"}, {"text": "詫びた", "is_correct": false, "explanation": "詫びるは謝る動作で、「道を詫びた」は成り立たない。"}, {"text": "怒鳴った", "is_correct": false, "explanation": "怒鳴るは大声を出す動作で、「道を怒鳴った」とは言えない。"}], "explanations": {"説いた": "「道を説いた」は、道理を人に説明した意味。ここに入る。", "責めた": "責めるは相手を非難する動作。「人の道を責めた」は意味が通らない。", "詫びた": "詫びるは謝る動作で、「道を詫びた」は成り立たない。", "怒鳴った": "怒鳴るは大声を出す動作で、「道を怒鳴った」とは言えない。"}, "sentence_index": 6, "correct_answer": "説いた"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼女はギターを説いている。", "explanation": "ここは〈弾く〉の意味。説くは意味や道理を言葉で伝えることで、楽器を演奏する場面には使わない。"}, {"text": "母は野菜を説いた。", "explanation": "ここは〈切る〉の意味。説くは言葉で意味を伝える行為で、野菜を切る動作には使わない。"}, {"text": "友人は財布を説いた。", "explanation": "ここは〈落とす〉の意味。説くは道理を説明する行為で、物をなくす意味では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d48e443-0dbf-4466-acec-a3edef6548fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37891, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "祖父は孫に、昔の遊びの意味に説いた。", "corrected_sentence": "祖父は孫に、昔の遊びの意味を説いた。", "error_description": "説く内容（目的語）は「を」で示す。正しくは「意味を説いた」。「意味に説いた」では説明の内容を示せず、不自然になる。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "説いた", "is_correct": true, "explanation": "過去形で、「黒板を使って説いた」という完了した説明行為を表す。"}, {"text": "説けば", "is_correct": false, "explanation": "仮定形で、「〜ば」の条件節になる。文末の完了した行為として成り立たない。"}, {"text": "説かれた", "is_correct": false, "explanation": "受身形。「仕組みを説かれた」では目的語と受身が合わず、文が成り立たない。"}, {"text": "説こう", "is_correct": false, "explanation": "意志形で、これから説明するという意図を表す。完了した過去の出来事にならない。"}], "correct_form": "説いた", "base_form": "説く", "form_label": "過去形（〜た）", "sentence_index": 1, "explanations": {"説いた": "過去形で、「黒板を使って説いた」という完了した説明行為を表す。", "説けば": "仮定形で、「〜ば」の条件節になる。文末の完了した行為として成り立たない。", "説かれた": "受身形。「仕組みを説かれた」では目的語と受身が合わず、文が成り立たない。", "説こう": "意志形で、これから説明するという意図を表す。完了した過去の出来事にならない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d48e443-0dbf-4466-acec-a3edef6548fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37891, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "学者は学生を、研究の成果を図で説いた。", "corrected_sentence": "学者は学生に、研究の成果を図で説いた。", "error_description": "説く相手（受け手）は「に」で示す。正しくは「学生に」。「学生を」だと学生を目的語として扱い、文の関係が成り立たない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "説いた", "is_correct": true, "explanation": "過去形で、「環境を守る理由を数字で説いた」という完了した説明行為を表す。"}, {"text": "説きます", "is_correct": false, "explanation": "丁寧形の非過去で、完了した過去の説明を述べる文に合わない。"}, {"text": "説かない", "is_correct": false, "explanation": "否定形で、説明したことを否定する意味になり、文の内容と合わない。"}, {"text": "説け", "is_correct": false, "explanation": "命令形で、文末の過去の説明行為を述べる文として成り立たない。"}], "correct_form": "説いた", "base_form": "説く", "form_label": "過去形（〜た）", "sentence_index": 7, "explanations": {"説いた": "過去形で、「環境を守る理由を数字で説いた」という完了した説明行為を表す。", "説きます": "丁寧形の非過去で、完了した過去の説明を述べる文に合わない。", "説かない": "否定形で、説明したことを否定する意味になり、文の内容と合わない。", "説け": "命令形で、文末の過去の説明行為を述べる文として成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d48e443-0dbf-4466-acec-a3edef6548fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37892, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「話の帰結」と名詞を修飾する。"}, {"text": "を", "is_correct": false, "explanation": "「話を帰結です」とは言えない。"}, {"text": "に", "is_correct": false, "explanation": "「話に帰結です」とは言えない。"}, {"text": "へ", "is_correct": false, "explanation": "「話へ帰結です」とは言えない。"}], "correct_answer": "の", "explanations": {"の": "「話の帰結」と名詞を修飾する。", "を": "「話を帰結です」とは言えない。", "に": "「話に帰結です」とは言えない。", "へ": "「話へ帰結です」とは言えない。"}, "error_tags": {"を": "対象の誤り", "に": "連体の誤り", "へ": "方向の誤り"}, "sentence_index": 0}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "発端", "is_correct": true, "explanation": "最後の結果である帰結に対し、発端は物事の始まりである。"}, {"text": "結果", "is_correct": false, "explanation": "帰結とほぼ同じ意味の類義語である。"}, {"text": "結末", "is_correct": false, "explanation": "話の最後を表す類義語である。"}, {"text": "結論", "is_correct": false, "explanation": "最終的な判断を表し、類義に近い。"}], "correct_answer": "発端", "explanations": {"発端": "最後の結果である帰結に対し、発端は物事の始まりである。", "結果": "帰結とほぼ同じ意味の類義語である。", "結末": "話の最後を表す類義語である。", "結論": "最終的な判断を表し、類義に近い。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '870ad63f-8afb-4149-b424-d3e31c170903') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37892, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「人生の帰結をつくる」と対象を表す。"}, {"text": "に", "is_correct": false, "explanation": "「帰結につくる」とは言えない。"}, {"text": "へ", "is_correct": false, "explanation": "「帰結へつくる」とは言えない。"}, {"text": "と", "is_correct": false, "explanation": "「帰結とつくる」とは言えない。"}], "correct_answer": "を", "explanations": {"を": "「人生の帰結をつくる」と対象を表す。", "に": "「帰結につくる」とは言えない。", "へ": "「帰結へつくる」とは言えない。", "と": "「帰結とつくる」とは言えない。"}, "error_tags": {"に": "対象の誤り", "へ": "方向の誤り", "と": "共同の誤り"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "原因", "is_correct": true, "explanation": "最後に生じる結果である帰結に対し、原因はそれを引き起こす始まりの側である。"}, {"text": "結果", "is_correct": false, "explanation": "帰結とほぼ同じ意味の類義語である。"}, {"text": "結末", "is_correct": false, "explanation": "最後の状態を表す類義語である。"}, {"text": "結論", "is_correct": false, "explanation": "最終的な判断を表し、類義に近い。"}], "correct_answer": "原因", "explanations": {"原因": "最後に生じる結果である帰結に対し、原因はそれを引き起こす始まりの側である。", "結果": "帰結とほぼ同じ意味の類義語である。", "結末": "最後の状態を表す類義語である。", "結論": "最終的な判断を表し、類義に近い。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '870ad63f-8afb-4149-b424-d3e31c170903') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37892, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "何かをしたあとに、最後にどうなるかという結果のこと。", "primary_collocate": null, "pronunciation": "きけつ", "ipa": "kiketsɯ", "syllable_count": 3, "sentences": [{"text": "それが話の帰結です。", "target_word": "帰結", "complexity_tier": "T2", "furigana": "それがはなしのきけつです。", "sentence_source": "generated"}, {"text": "帰結は、まだ分からない。", "target_word": "帰結", "complexity_tier": "T2", "furigana": "きけつは、まだわからない。", "sentence_source": "generated"}, {"text": "長い話の帰結を聞きたい。", "target_word": "帰結", "complexity_tier": "T2", "furigana": "ながいはなしのきけつをききたい。", "sentence_source": "generated"}, {"text": "議論の帰結は、意外なものだった。", "target_word": "帰結", "complexity_tier": "T2", "furigana": "ぎろんのきけつは、いがいなものだった。", "sentence_source": "generated"}, {"text": "準備をしないと、悪い帰結を招く。", "target_word": "帰結", "complexity_tier": "T3", "furigana": "じゅんびをしないと、わるいきけつをまねく。", "sentence_source": "generated"}, {"text": "話し合いは、その案に帰結した。", "target_word": "帰結した", "complexity_tier": "T3", "furigana": "はなしあいは、そのあんにきけつした。", "sentence_source": "generated"}, {"text": "彼らの争いは、思わぬ形で帰結した。", "target_word": "帰結した", "complexity_tier": "T3", "furigana": "かれらのあらそいは、おもわぬかたちできけつした。", "sentence_source": "generated"}, {"text": "毎日の小さな選択が、人生の帰結をつくる。", "target_word": "帰結", "complexity_tier": "T3", "furigana": "まいにちのちいさなせんたくが、じんせいのきけつをつくる。", "sentence_source": "generated"}, {"text": "帰結を考えずに行動すると、後で困ることになる。", "target_word": "帰結", "complexity_tier": "T4", "furigana": "きけつをかんがえずにこうどうすると、あとでこまることになる。", "sentence_source": "generated"}, {"text": "この話の帰結を、子どもにも分かる言葉で説明した。", "target_word": "帰結", "complexity_tier": "T4", "furigana": "このはなしのきけつを、こどもにもわかることばでせつめいした。", "sentence_source": "generated"}], "morphological_forms": [{"form": "帰結する", "label": "活用"}, {"form": "帰結した", "label": "活用"}, {"form": "帰結して", "label": "活用"}], "register": "formal", "sense_fingerprint": "名詞 | 最後にどうなるかという結果", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc96f6e4-9414-4db2-8218-4b424363511e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37892, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "帰結", "is_correct": true, "explanation": "「きけつ」で、見出し語そのものの音である。"}, {"text": "危険", "is_correct": false, "explanation": "「きけん」で、最後の音が違う。"}, {"text": "季節", "is_correct": false, "explanation": "「きせつ」で、二つ目の音が違う。"}, {"text": "議決", "is_correct": false, "explanation": "「ぎけつ」で、最初の音が濁音になる。"}], "explanations": {"帰結": "「きけつ」で、見出し語そのものの音である。", "危険": "「きけん」で、最後の音が違う。", "季節": "「きせつ」で、二つ目の音が違う。", "議決": "「ぎけつ」で、最初の音が濁音になる。"}, "sentence_index": null, "correct_answer": "帰結"}, "level_3": {"options": [{"text": "帰結", "is_correct": true, "explanation": "話の最後の結果という意味で合う。"}, {"text": "帽子", "is_correct": false, "explanation": "形は合うが、「話の帽子」では意味が合わない。"}, {"text": "椅子", "is_correct": false, "explanation": "形は合うが、「話の椅子」では意味が通らない。"}, {"text": "湿度", "is_correct": false, "explanation": "形は合うが、「話の湿度」では意味が合わない。"}], "explanations": {"帰結": "話の最後の結果という意味で合う。", "帽子": "形は合うが、「話の帽子」では意味が合わない。", "椅子": "形は合うが、「話の椅子」では意味が通らない。", "湿度": "形は合うが、「話の湿度」では意味が合わない。"}, "sentence_index": 0, "correct_answer": "帰結"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "帰結をお湯で洗ってから使う。", "explanation": "「帰結」は結果を表す抽象名詞で、洗える物ではない。"}, {"text": "彼は帰結を持って駅まで走った。", "explanation": "「帰結」は手に持てる物ではなく、語義の誤用である。"}, {"text": "今朝は帰結が高くて、窓を開けた。", "explanation": "「帰結」は気温や湿度のような状態を表さない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '870ad63f-8afb-4149-b424-d3e31c170903') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37892, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "帰結", "is_correct": true, "explanation": "「きけつ」で、見出し語そのものの音である。"}, {"text": "否決", "is_correct": false, "explanation": "「ひけつ」で、最初の音が違う。"}, {"text": "止血", "is_correct": false, "explanation": "「しけつ」で、最初の音が違う。"}, {"text": "気骨", "is_correct": false, "explanation": "「きこつ」で、二つ目の音が違う。"}], "explanations": {"帰結": "「きけつ」で、見出し語そのものの音である。", "否決": "「ひけつ」で、最初の音が違う。", "止血": "「しけつ」で、最初の音が違う。", "気骨": "「きこつ」で、二つ目の音が違う。"}, "sentence_index": null, "correct_answer": "帰結"}, "level_3": {"options": [{"text": "帰結した", "is_correct": true, "explanation": "争いが思わぬ形で最終的に行き着いたという意味で合う。"}, {"text": "出発した", "is_correct": false, "explanation": "形は合うが、「争いが出発した」では意味が合わない。"}, {"text": "乾燥した", "is_correct": false, "explanation": "形は合うが、「争いが乾燥した」では意味が通らない。"}, {"text": "散歩した", "is_correct": false, "explanation": "形は合うが、「争いが散歩した」では意味が合わない。"}], "explanations": {"帰結した": "争いが思わぬ形で最終的に行き着いたという意味で合う。", "出発した": "形は合うが、「争いが出発した」では意味が合わない。", "乾燥した": "形は合うが、「争いが乾燥した」では意味が通らない。", "散歩した": "形は合うが、「争いが散歩した」では意味が合わない。"}, "sentence_index": 6, "correct_answer": "帰結した"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "母は帰結を台所で切って料理した。", "explanation": "「帰結」は結果を表す抽象名詞で、食材ではない。"}, {"text": "帰結は大きな声で歌を歌った。", "explanation": "「帰結」は人ではなく、歌う主語にはなれない。"}, {"text": "帰結がとても長くて、足が痛くなった。", "explanation": "「帰結」は物理的な長さを持たず、語義の誤用である。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '870ad63f-8afb-4149-b424-d3e31c170903') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
