INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37892, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼の計画は、失敗が帰結した。", "corrected_sentence": "彼の計画は、失敗に帰結した。", "error_description": "「帰結する」の行き着く先は「が」ではなく「に」で示す。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '870ad63f-8afb-4149-b424-d3e31c170903') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37893, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「当然の帰結」と名詞を修飾する。"}, {"text": "を", "is_correct": false, "explanation": "「当然を帰結」では名詞を結べない。"}, {"text": "に", "is_correct": false, "explanation": "「当然に帰結だ」とは言えない。"}, {"text": "と", "is_correct": false, "explanation": "「当然と帰結だ」とは言えない。"}], "correct_answer": "の", "explanations": {"の": "「当然の帰結」と名詞を修飾する。", "を": "「当然を帰結」では名詞を結べない。", "に": "「当然に帰結だ」とは言えない。", "と": "「当然と帰結だ」とは言えない。"}, "error_tags": {"を": "対象の誤り", "に": "連体の誤り", "と": "並列の誤り"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "原因", "is_correct": true, "explanation": "結果として生じる帰結に対し、原因は始まりの側にある。"}, {"text": "結果", "is_correct": false, "explanation": "帰結とほぼ同じ意味の類義語である。"}, {"text": "結末", "is_correct": false, "explanation": "最終的な行き着く先を表す類義語である。"}, {"text": "成果", "is_correct": false, "explanation": "努力の結果を表し、反対の関係ではない。"}], "correct_answer": "原因", "explanations": {"原因": "結果として生じる帰結に対し、原因は始まりの側にある。", "結果": "帰結とほぼ同じ意味の類義語である。", "結末": "最終的な行き着く先を表す類義語である。", "成果": "努力の結果を表し、反対の関係ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '870ad63f-8afb-4149-b424-d3e31c170903') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37893, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「どこに帰結する」と行き着く先を表す。"}, {"text": "を", "is_correct": false, "explanation": "「どこを帰結する」とは言えない。"}, {"text": "と", "is_correct": false, "explanation": "「どこと帰結する」とは言えない。"}, {"text": "の", "is_correct": false, "explanation": "「どこの帰結する」では動詞につながらない。"}], "correct_answer": "に", "explanations": {"に": "「どこに帰結する」と行き着く先を表す。", "を": "「どこを帰結する」とは言えない。", "と": "「どこと帰結する」とは言えない。", "の": "「どこの帰結する」では動詞につながらない。"}, "error_tags": {"を": "対象の誤り", "と": "共同の誤り", "の": "連体の誤り"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "前提", "is_correct": true, "explanation": "帰結が行き着く先なら、前提は議論の出発点であり反対の関係にある。"}, {"text": "結論", "is_correct": false, "explanation": "帰結に近い類義語である。"}, {"text": "終結", "is_correct": false, "explanation": "物事が終わることを表し、類義に近い。"}, {"text": "末路", "is_correct": false, "explanation": "行き着いた最後の状態を表し、類義に近い。"}], "correct_answer": "前提", "explanations": {"前提": "帰結が行き着く先なら、前提は議論の出発点であり反対の関係にある。", "結論": "帰結に近い類義語である。", "終結": "物事が終わることを表し、類義に近い。", "末路": "行き着いた最後の状態を表し、類義に近い。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '870ad63f-8afb-4149-b424-d3e31c170903') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37893, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "ある行動や出来事の結果として最終的に生じる状態や事柄。", "primary_collocate": null, "pronunciation": "きけつ", "ipa": "kiketsɯ", "syllable_count": 3, "sentences": [{"text": "さらに、こうした非伝統的な金融政策がインフレ期待のアンカーとして機能し得る一方で、過剰な流動性が実体経済における物価上昇圧力と相乗効果を生み、予期せぬスタグフレーションや財政主導のシナリオへと帰結するリスクを常に内包していることを、我々は冷徹に認識する責務を負っている。", "target_word": "帰結する", "complexity_tier": "T6", "furigana": "さらに、こうしたひでんとうてきなきんゆうせいさくがインフレきたいのアンカーとしてきのうしえるいっぽうで、かじょうなりゅうどうせいがじったいけいざいにおけるぶっかじょうしょうあつりょくとそうじょうこうかをうみ、よきせぬスタグフレーションやざいせいしゅどうのシナリオへときけつするリスクをつねにないほうしていることを、われわれはれいてつににんしきするせきむをおっている。", "sentence_source": "mined"}, {"text": "この結果は当然の帰結だ。", "target_word": "帰結", "complexity_tier": "T2", "furigana": "このけっかはとうぜんのきけつだ。", "sentence_source": "generated"}, {"text": "長い議論の帰結として、新しい規則ができた。", "target_word": "帰結", "complexity_tier": "T3", "furigana": "ながいぎろんのきけつとして、あたらしいきそくができた。", "sentence_source": "generated"}, {"text": "努力の帰結が、ようやく見えてきました。", "target_word": "帰結", "complexity_tier": "T3", "furigana": "どりょくのきけつが、ようやくみえてきました。", "sentence_source": "generated"}, {"text": "その決定は、どんな帰結をもたらすのだろうか。", "target_word": "帰結", "complexity_tier": "T3", "furigana": "そのけっていは、どんなきけつをもたらすのだろうか。", "sentence_source": "generated"}, {"text": "論理的に考えれば、この帰結は避けられない。", "target_word": "帰結", "complexity_tier": "T4", "furigana": "ろんりてきにかんがえれば、このきけつはさけられない。", "sentence_source": "generated"}, {"text": "彼の失敗は、準備不足の当然の帰結である。", "target_word": "帰結", "complexity_tier": "T4", "furigana": "かれのしっぱいは、じゅんびぶそくのとうぜんのきけつである。", "sentence_source": "generated"}, {"text": "この議論は、結局どこに帰結するのだろうか。", "target_word": "帰結する", "complexity_tier": "T4", "furigana": "このぎろんは、けっきょくどこにきけつするのだろうか。", "sentence_source": "generated"}, {"text": "環境破壊の帰結を、私たちは真剣に考えなければならない。", "target_word": "帰結", "complexity_tier": "T4", "furigana": "かんきょうはかいのきけつを、わたしたちはしんけんにかんがえなければならない。", "sentence_source": "generated"}, {"text": "小さな嘘が大きな問題へと帰結することは、決して珍しくない。", "target_word": "帰結する", "complexity_tier": "T5", "furigana": "ちいさなうそがおおきなもんだいへときけつすることは、けっしてめずらしくない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "帰結する", "label": "活用"}, {"form": "帰結した", "label": "活用"}, {"form": "帰結して", "label": "活用"}], "register": "formal", "sense_fingerprint": "名詞 | 行動の結果として最終的に生じる事柄", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc96f6e4-9414-4db2-8218-4b424363511e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37893, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "帰結", "is_correct": true, "explanation": "「きけつ」で、見出し語そのものの音である。"}, {"text": "危険", "is_correct": false, "explanation": "「きけん」で、最後の音が違う。"}, {"text": "季節", "is_correct": false, "explanation": "「きせつ」で、二つ目の音が違う。"}, {"text": "議決", "is_correct": false, "explanation": "「ぎけつ」で、最初の音が濁音になる。"}], "explanations": {"帰結": "「きけつ」で、見出し語そのものの音である。", "危険": "「きけん」で、最後の音が違う。", "季節": "「きせつ」で、二つ目の音が違う。", "議決": "「ぎけつ」で、最初の音が濁音になる。"}, "sentence_index": null, "correct_answer": "帰結"}, "level_3": {"options": [{"text": "帰結する", "is_correct": true, "explanation": "「シナリオへと最終的に行き着く」という意味で合う。"}, {"text": "出発する", "is_correct": false, "explanation": "形は合うが、「シナリオへと出発する」では意味が合わない。"}, {"text": "洗濯する", "is_correct": false, "explanation": "形は合うが、「シナリオへと洗濯する」では意味が通らない。"}, {"text": "乾燥する", "is_correct": false, "explanation": "形は合うが、「シナリオへと乾燥する」では意味が通らない。"}], "explanations": {"帰結する": "「シナリオへと最終的に行き着く」という意味で合う。", "出発する": "形は合うが、「シナリオへと出発する」では意味が合わない。", "洗濯する": "形は合うが、「シナリオへと洗濯する」では意味が通らない。", "乾燥する": "形は合うが、「シナリオへと乾燥する」では意味が通らない。"}, "sentence_index": 0, "correct_answer": "帰結する"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "毎朝、帰結を食べてから学校へ行く。", "explanation": "「帰結」は結果を表す抽象名詞で、食べ物ではない。"}, {"text": "駅の帰結で友達と待ち合わせた。", "explanation": "「帰結」は場所を表さず、出口などと取り違えている。"}, {"text": "彼は帰結をかぶって出かけた。", "explanation": "「帰結」は身につける物ではなく、語義の誤用である。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '870ad63f-8afb-4149-b424-d3e31c170903') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37893, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "帰結", "is_correct": true, "explanation": "「きけつ」で、見出し語そのものの音である。"}, {"text": "否決", "is_correct": false, "explanation": "「ひけつ」で、最初の音が違う。"}, {"text": "止血", "is_correct": false, "explanation": "「しけつ」で、最初の音が違う。"}, {"text": "気骨", "is_correct": false, "explanation": "「きこつ」で、二つ目の音が違う。"}], "explanations": {"帰結": "「きけつ」で、見出し語そのものの音である。", "否決": "「ひけつ」で、最初の音が違う。", "止血": "「しけつ」で、最初の音が違う。", "気骨": "「きこつ」で、二つ目の音が違う。"}, "sentence_index": null, "correct_answer": "帰結"}, "level_3": {"options": [{"text": "帰結", "is_correct": true, "explanation": "準備不足から生じた結果という意味で合う。"}, {"text": "帽子", "is_correct": false, "explanation": "形は合うが、「準備不足の当然の帽子」では意味が合わない。"}, {"text": "椅子", "is_correct": false, "explanation": "形は合うが、失敗を説明する意味にならない。"}, {"text": "天井", "is_correct": false, "explanation": "形は合うが、「準備不足の当然の天井」では意味が通らない。"}], "explanations": {"帰結": "準備不足から生じた結果という意味で合う。", "帽子": "形は合うが、「準備不足の当然の帽子」では意味が合わない。", "椅子": "形は合うが、失敗を説明する意味にならない。", "天井": "形は合うが、「準備不足の当然の天井」では意味が通らない。"}, "sentence_index": 6, "correct_answer": "帰結"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "電車が駅に帰結して、乗客が降りた。", "explanation": "「帰結する」は物事の最終的な結果を表し、到着の意味では使えない。"}, {"text": "私は毎晩、十時に家へ帰結する。", "explanation": "「帰結する」は帰宅の意味ではなく、帰ることと取り違えている。"}, {"text": "彼は散歩の途中で帰結して水を飲んだ。", "explanation": "「帰結する」は一時的に立ち止まる意味では使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '870ad63f-8afb-4149-b424-d3e31c170903') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37893, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼の勝利は努力に当然の帰結だ。", "corrected_sentence": "彼の勝利は努力の当然の帰結だ。", "error_description": "「帰結」の原因を結ぶ助詞は「に」ではなく「の」である。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '870ad63f-8afb-4149-b424-d3e31c170903') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37893, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この政策は、やがて混乱を帰結するだろう。", "corrected_sentence": "この政策は、やがて混乱に帰結するだろう。", "error_description": "「帰結する」の行き着く先は「を」ではなく「に」で示す。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '870ad63f-8afb-4149-b424-d3e31c170903') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37894, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「聞き手の顔」の所有を示す「の」。聞き手に属する顔を表す。"}, {"text": "に", "is_correct": false, "explanation": "方向・対象の「に」。「聞き手に顔を見ながら」は意味が通らない。"}, {"text": "で", "is_correct": false, "explanation": "場所・手段の「で」。「聞き手で顔」は成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "方向の「へ」。「聞き手へ顔」は不自然で、顔との関係を表せない。"}], "correct_answer": "の", "explanations": {"の": "「聞き手の顔」の所有を示す「の」。聞き手に属する顔を表す。", "に": "方向・対象の「に」。「聞き手に顔を見ながら」は意味が通らない。", "で": "場所・手段の「で」。「聞き手で顔」は成り立たない。", "へ": "方向の「へ」。「聞き手へ顔」は不自然で、顔との関係を表せない。"}, "error_tags": {"に": "方向・対象", "で": "場所・手段", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d48e443-0dbf-4466-acec-a3edef6548fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37894, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「聞き手の気持ち」の所有を示す「の」。聞き手に属する気持ちを表す。"}, {"text": "を", "is_correct": false, "explanation": "目的語の「を」。「聞き手を気持ち」では気持ちとつながらず、文が成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "共同の「と」。「聞き手と気持ち」は成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "起点の「から」。「聞き手から気持ち」は成り立たない。"}], "correct_answer": "の", "explanations": {"の": "「聞き手の気持ち」の所有を示す「の」。聞き手に属する気持ちを表す。", "を": "目的語の「を」。「聞き手を気持ち」では気持ちとつながらず、文が成り立たない。", "と": "共同の「と」。「聞き手と気持ち」は成り立たない。", "から": "起点の「から」。「聞き手から気持ち」は成り立たない。"}, "error_tags": {"を": "目的語", "と": "共同", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d48e443-0dbf-4466-acec-a3edef6548fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37894, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "話を聞く人のこと。", "primary_collocate": null, "pronunciation": "ききて", "ipa": "kikite", "syllable_count": 3, "sentences": [{"text": "話し手が早口だと、聞き手は内容についていけません。", "target_word": "聞き手", "complexity_tier": "T3", "furigana": "話[はな]し手[て]が早口[はやくち]だと、聞[き]き手[て]は内容[ないよう]についていけません。", "sentence_source": "generated"}, {"text": "上手な話し手は、聞き手の顔を見ながら話します。", "target_word": "聞き手", "complexity_tier": "T3", "furigana": "上手[じょうず]な話[はな]し手[て]は、聞[き]き手[て]の顔[かお]を見[み]ながら話[はな]します。", "sentence_source": "generated"}, {"text": "聞き手が笑ってくれたので、私は安心して話を続けました。", "target_word": "聞き手", "complexity_tier": "T3", "furigana": "聞[き]き手[て]が笑[わら]ってくれたので、私[わたし]は安心[あんしん]して話[はなし]を続[つづ]けました。", "sentence_source": "generated"}, {"text": "この先生は、聞き手を飽きさせない話し方をします。", "target_word": "聞き手", "complexity_tier": "T3", "furigana": "この先生[せんせい]は、聞[き]き手[て]を飽[あ]きさせない話[はな]し方[かた]をします。", "sentence_source": "generated"}, {"text": "兄は話すより聞くほうが得意で、いつも良い聞き手です。", "target_word": "聞き手", "complexity_tier": "T3", "furigana": "兄[あに]は話[はな]すより聞[き]くほうが得意[とくい]で、いつも良[よ]い聞[き]き手[て]です。", "sentence_source": "generated"}, {"text": "聞き手が子どもなので、難しい言葉は使わないでください。", "target_word": "聞き手", "complexity_tier": "T3", "furigana": "聞[き]き手[て]が子[こ]どもなので、難[むずか]しい言葉[ことば]は使[つか]わないでください。", "sentence_source": "generated"}, {"text": "会場の聞き手は、みんな静かにメモを取っていました。", "target_word": "聞き手", "complexity_tier": "T3", "furigana": "会場[かいじょう]の聞[き]き手[て]は、みんな静[しず]かにメモを取[と]っていました。", "sentence_source": "generated"}, {"text": "彼は話し上手だが、聞き手の気持ちを考えないところがある。", "target_word": "聞き手", "complexity_tier": "T3", "furigana": "彼[かれ]は話[はなし]上手[じょうず]だが、聞[き]き手[て]の気持[きも]ちを考[かんが]えないところがある。", "sentence_source": "generated"}, {"text": "友達の相談では、私はいつも聞き手になります。", "target_word": "聞き手", "complexity_tier": "T3", "furigana": "友達[ともだち]の相談[そうだん]では、私[わたし]はいつも聞[き]き手[て]になります。", "sentence_source": "generated"}, {"text": "聞き手がうなずくと、話し手も話しやすくなります。", "target_word": "聞き手", "complexity_tier": "T3", "furigana": "聞[き]き手[て]がうなずくと、話[はな]し手[て]も話[はな]しやすくなります。", "sentence_source": "generated"}], "morphological_forms": [{"form": "聞き手", "label": "基本形"}, {"form": "聞き手が", "label": "主格"}, {"form": "聞き手を", "label": "目的格"}], "register": "neutral", "sense_fingerprint": "話し手の話を聞く側の人。聞く人一般を指す。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28474861-32e1-4bed-92ca-a633d6cda916') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37894, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "聞き手", "is_correct": true, "explanation": "話を聞く側の人を指す。「話し手が早口だと、聞き手は内容についていけない」に合う。"}, {"text": "天気", "is_correct": false, "explanation": "自然現象の名詞。「天気は内容についていけません」は主語として意味が通らない。"}, {"text": "消しゴム", "is_correct": false, "explanation": "物の名詞。「消しゴムは内容についていけません」は主語として成り立たない。"}, {"text": "黒板", "is_correct": false, "explanation": "物の名詞。「黒板は内容についていけない」は意味が通らない。"}], "explanations": {"聞き手": "話を聞く側の人を指す。「話し手が早口だと、聞き手は内容についていけない」に合う。", "天気": "自然現象の名詞。「天気は内容についていけません」は主語として意味が通らない。", "消しゴム": "物の名詞。「消しゴムは内容についていけません」は主語として成り立たない。", "黒板": "物の名詞。「黒板は内容についていけない」は意味が通らない。"}, "sentence_index": 0, "correct_answer": "聞き手"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "映画の聞き手は、最後の場面で大きく笑った。", "explanation": "ここは〈観客〉の意味。聞き手は話を聞く人で、映画を見て楽しむ人には使わない。"}, {"text": "彼は毎日、将棋の聞き手と対局している。", "explanation": "ここは〈対局の相手〉の意味。聞き手は話を聞く人で、一緒に指す相手には使わない。"}, {"text": "この小説の聞き手は、若い作家だ。", "explanation": "ここは〈作者〉の意味。聞き手は話を聞く人で、書いた人には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d48e443-0dbf-4466-acec-a3edef6548fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37894, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "聞き手", "is_correct": true, "explanation": "会場で話を聞いている人を指す。「会場の聞き手は静かにメモを取っていた」に合う。"}, {"text": "出口", "is_correct": false, "explanation": "場所の名詞。「出口はメモを取っていた」は主語として成り立たない。"}, {"text": "照明", "is_correct": false, "explanation": "物の名詞。照明が人のようにメモを取る文は成り立たない。"}, {"text": "天井", "is_correct": false, "explanation": "場所の名詞。「天井はメモを取っていた」は意味が通らない。"}], "explanations": {"聞き手": "会場で話を聞いている人を指す。「会場の聞き手は静かにメモを取っていた」に合う。", "出口": "場所の名詞。「出口はメモを取っていた」は主語として成り立たない。", "照明": "物の名詞。照明が人のようにメモを取る文は成り立たない。", "天井": "場所の名詞。「天井はメモを取っていた」は意味が通らない。"}, "sentence_index": 6, "correct_answer": "聞き手"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この雑誌の聞き手は、主に若い女性です。", "explanation": "ここは〈読者〉の意味。聞き手は話を聞く人で、雑誌を読む人には使わない。"}, {"text": "彼は工場で、機械を操作する聞き手を担当している。", "explanation": "ここは〈操作者〉の意味。聞き手は話を聞く人で、機械を動かす人には使わない。"}, {"text": "彼女は学校の聞き手として、毎朝教室を掃除する。", "explanation": "ここは〈掃除係〉の意味。聞き手は話を聞く人で、掃除をする役割には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d48e443-0dbf-4466-acec-a3edef6548fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37894, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "会議では、聞き手を質問に答えられる人が必要だ。", "corrected_sentence": "会議では、聞き手の質問に答えられる人が必要だ。", "error_description": "「聞き手の質問」が正しい。「聞き手を質問」では聞き手を目的語にしてしまい、質問との関係が成り立たない。「の」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d48e443-0dbf-4466-acec-a3edef6548fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37894, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この番組の聞き手として、彼女は毎週ゲストの話を聞き手する。", "corrected_sentence": "この番組の聞き手として、彼女は毎週ゲストの話を聞く。", "error_description": "「聞き手する」は名詞の「聞き手」を動詞化した誤り。動作は動詞「聞く」で表すので、「話を聞く」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d48e443-0dbf-4466-acec-a3edef6548fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37895, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「聞き手の反応」の所有を示す「の」。聞き手に属する反応を表す。"}, {"text": "から", "is_correct": false, "explanation": "起点の「から」。「聞き手から反応を見て」は反応を見る起点として成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "場所・手段の「で」。「聞き手で反応」は成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "方向の「へ」。「聞き手へ反応」は不自然で、反応との関係を表せない。"}], "correct_answer": "の", "explanations": {"の": "「聞き手の反応」の所有を示す「の」。聞き手に属する反応を表す。", "から": "起点の「から」。「聞き手から反応を見て」は反応を見る起点として成り立たない。", "で": "場所・手段の「で」。「聞き手で反応」は成り立たない。", "へ": "方向の「へ」。「聞き手へ反応」は不自然で、反応との関係を表せない。"}, "error_tags": {"で": "場所・手段", "へ": "方向", "から": "起点"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d48e443-0dbf-4466-acec-a3edef6548fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37895, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "使役の対象（笑わせる相手）を示す「を」。「聞き手を笑わせる」の形になる。"}, {"text": "が", "is_correct": false, "explanation": "主語の「が」。「聞き手が笑わせる」は笑わせる相手を示せず、文が成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "比較の「より」。「聞き手より笑わせる」は成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "起点の「から」。「聞き手から笑わせる」は不自然で、笑わせる相手を示せない。"}], "correct_answer": "を", "explanations": {"を": "使役の対象（笑わせる相手）を示す「を」。「聞き手を笑わせる」の形になる。", "が": "主語の「が」。「聞き手が笑わせる」は笑わせる相手を示せず、文が成り立たない。", "より": "比較の「より」。「聞き手より笑わせる」は成り立たない。", "から": "起点の「から」。「聞き手から笑わせる」は不自然で、笑わせる相手を示せない。"}, "error_tags": {"が": "主語", "より": "比較", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d48e443-0dbf-4466-acec-a3edef6548fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37895, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "話し手の言葉を聞いている人。会話や講演などで、話を聞く側の立場の人。", "primary_collocate": null, "pronunciation": "ききて", "ipa": "kikite", "syllable_count": 3, "sentences": [{"text": "講演では、話し手と聞き手の間に信頼が必要だ。", "target_word": "聞き手", "complexity_tier": "T3", "furigana": "講演[こうえん]では、話[はな]し手[て]と聞[き]き手[て]の間[あいだ]に信頼[しんらい]が必要[ひつよう]だ。", "sentence_source": "generated"}, {"text": "聞き手の反応を見て、話す速さを変えました。", "target_word": "聞き手", "complexity_tier": "T3", "furigana": "聞[き]き手[て]の反応[はんのう]を見[み]て、話[はな]す速[はや]さを変[か]えました。", "sentence_source": "generated"}, {"text": "インタビューでは、聞き手が上手に質問すると話が広がります。", "target_word": "聞き手", "complexity_tier": "T3", "furigana": "インタビューでは、聞[き]き手[て]が上手[じょうず]に質問[しつもん]すると話[はなし]が広[ひろ]がります。", "sentence_source": "generated"}, {"text": "聞き手が理解できるように、例を挙げて説明した。", "target_word": "聞き手", "complexity_tier": "T3", "furigana": "聞[き]き手[て]が理解[りかい]できるように、例[れい]を挙[あ]げて説明[せつめい]した。", "sentence_source": "generated"}, {"text": "会話では、話し手だけでなく聞き手の努力も大切です。", "target_word": "聞き手", "complexity_tier": "T3", "furigana": "会話[かいわ]では、話[はな]し手[て]だけでなく聞[き]き手[て]の努力[どりょく]も大切[たいせつ]です。", "sentence_source": "generated"}, {"text": "聞き手が十人しかいない小さな会場でも、彼女は全力で話した。", "target_word": "聞き手", "complexity_tier": "T4", "furigana": "聞[き]き手[て]が十人[じゅうにん]しかいない小[ちい]さな会場[かいじょう]でも、彼女[かのじょ]は全力[ぜんりょく]で話[はな]した。", "sentence_source": "generated"}, {"text": "長い講義になると、聞き手の集中力が続かなくなります。", "target_word": "聞き手", "complexity_tier": "T3", "furigana": "長[なが]い講義[こうぎ]になると、聞[き]き手[て]の集中力[しゅうちゅうりょく]が続[つづ]かなくなります。", "sentence_source": "generated"}, {"text": "落語家は、聞き手を笑わせるために間を大切にします。", "target_word": "聞き手", "complexity_tier": "T3", "furigana": "落語家[らくごか]は、聞[き]き手[て]を笑[わら]わせるために間[ま]を大切[たいせつ]にします。", "sentence_source": "generated"}, {"text": "聞き手の年齢に合わせて、話の内容を選ぶ。", "target_word": "聞き手", "complexity_tier": "T3", "furigana": "聞[き]き手[て]の年齢[ねんれい]に合[あ]わせて、話[はなし]の内容[ないよう]を選[えら]ぶ。", "sentence_source": "generated"}, {"text": "電話では顔が見えないので、聞き手は声だけで相手の気持ちを知ろうとする。", "target_word": "聞き手", "complexity_tier": "T4", "furigana": "電話[でんわ]では顔[かお]が見[み]えないので、聞[き]き手[て]は声[こえ]だけで相手[あいて]の気持[きも]ちを知[し]ろうとする。", "sentence_source": "generated"}], "morphological_forms": [{"form": "聞き手", "label": "基本形"}, {"form": "聞き手の", "label": "連体形"}, {"form": "聞き手を", "label": "目的格"}], "register": "neutral", "sense_fingerprint": "会話・講演・インタビューなどで、話し手に対する聞く側の立場の人。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28474861-32e1-4bed-92ca-a633d6cda916') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37895, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "聞き手", "is_correct": true, "explanation": "講演で話を聞く側の立場の人を指す。「話し手と聞き手の間に信頼が必要」に合う。"}, {"text": "演台", "is_correct": false, "explanation": "物の名詞。話し手と演台の間の信頼という関係は成り立たない。"}, {"text": "照明", "is_correct": false, "explanation": "物の名詞。照明との間に信頼が必要という文は意味が通らない。"}, {"text": "扉", "is_correct": false, "explanation": "物の名詞。扉との間に信頼が必要という文は成り立たない。"}], "explanations": {"聞き手": "講演で話を聞く側の立場の人を指す。「話し手と聞き手の間に信頼が必要」に合う。", "演台": "物の名詞。話し手と演台の間の信頼という関係は成り立たない。", "照明": "物の名詞。照明との間に信頼が必要という文は意味が通らない。", "扉": "物の名詞。扉との間に信頼が必要という文は成り立たない。"}, "sentence_index": 0, "correct_answer": "聞き手"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この大会の聞き手は、作品に点数をつけた。", "explanation": "ここは〈審査員〉の意味。聞き手は話を聞く側で、評価を下す立場ではない。"}, {"text": "この曲の聞き手は、新しいメロディーを作った。", "explanation": "ここは〈作曲家〉の意味。聞き手は話を聞く人で、曲を作る人には使わない。"}, {"text": "この劇の聞き手は、主役を演じた。", "explanation": "ここは〈役者〉の意味。聞き手は話を聞く側の人で、劇で役を演じる立場には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d48e443-0dbf-4466-acec-a3edef6548fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37895, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "聞き手", "is_correct": true, "explanation": "長い講義で話を聞いている人々を指す。「聞き手の集中力」に合う。"}, {"text": "窓", "is_correct": false, "explanation": "物の名詞。「窓の集中力」は意味が通らない。"}, {"text": "黒板", "is_correct": false, "explanation": "物の名詞。「黒板の集中力が続かなくなる」は成り立たない。"}, {"text": "出口", "is_correct": false, "explanation": "場所の名詞。「出口の集中力」は意味が通らない。"}], "explanations": {"聞き手": "長い講義で話を聞いている人々を指す。「聞き手の集中力」に合う。", "窓": "物の名詞。「窓の集中力」は意味が通らない。", "黒板": "物の名詞。「黒板の集中力が続かなくなる」は成り立たない。", "出口": "場所の名詞。「出口の集中力」は意味が通らない。"}, "sentence_index": 6, "correct_answer": "聞き手"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この店の聞き手が、お客に商品を勧めた。", "explanation": "ここは〈店員〉の意味。聞き手は話を聞く人で、店で商品を売る人には使わない。"}, {"text": "聞き手が小説を訳した。", "explanation": "ここは〈翻訳家〉の意味。聞き手は話を聞く人で、文章を別の言語に訳す人には使わない。"}, {"text": "彼はオーケストラの聞き手として、舞台で指揮を振った。", "explanation": "ここは〈指揮者〉の意味。聞き手は話を聞く人で、演奏を指揮する役割には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d48e443-0dbf-4466-acec-a3edef6548fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37895, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼は聞き手を、毎回熱心に話を聞いている。", "corrected_sentence": "彼は聞き手として、毎回熱心に話を聞いている。", "error_description": "立場を表すには「聞き手として」が必要。「聞き手を」では聞き手を目的語にしてしまい、文の形が成り立たない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d48e443-0dbf-4466-acec-a3edef6548fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37895, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "アナウンサーは聞き手を質問し、番組を進めた。", "corrected_sentence": "アナウンサーは聞き手に質問し、番組を進めた。", "error_description": "質問の相手は「に」で示す。正しくは「聞き手に質問し」。「聞き手を質問し」では聞き手を質問の対象にしてしまい、不自然になる。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d48e443-0dbf-4466-acec-a3edef6548fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37896, 3, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d48e443-0dbf-4466-acec-a3edef6548fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37896, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「判断に」で「その判断を受けて」の意味になり、文脈に合う。"}, {"text": "を", "is_correct": false, "explanation": "「判断を」は後ろの「言わなかった」の目的語にならず（言うのは文句）、文の筋が通らない。"}, {"text": "へ", "is_correct": false, "explanation": "向かう先を示すが、判断に対する反応の意味では不自然。"}, {"text": "と", "is_correct": false, "explanation": "並列を表すが、対になる語がなく文が不完全になる。"}], "correct_answer": "に", "explanations": {"に": "「判断に」で「その判断を受けて」の意味になり、文脈に合う。", "を": "「判断を」は後ろの「言わなかった」の目的語にならず（言うのは文句）、文の筋が通らない。", "へ": "向かう先を示すが、判断に対する反応の意味では不自然。", "と": "並列を表すが、対になる語がなく文が不完全になる。"}, "error_tags": {"を": "対象", "へ": "方向", "と": "並列"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d48e443-0dbf-4466-acec-a3edef6548fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37896, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "何かを正しいか、悪いかを決めること。", "primary_collocate": null, "pronunciation": "はんだん", "ipa": "handaɴ", "syllable_count": 4, "sentences": [{"text": "正しいかどうか、自分で判断してください。", "target_word": "判断", "complexity_tier": "T3", "furigana": "正[ただ]しいかどうか、自分[じぶん]で判断[はんだん]してください。", "sentence_source": "generated"}, {"text": "この情報が本当かどうか、私には判断できません。", "target_word": "判断", "complexity_tier": "T3", "furigana": "この情報[じょうほう]が本当[ほんとう]かどうか、私[わたし]には判断[はんだん]できません。", "sentence_source": "generated"}, {"text": "医者は検査の結果を見て、病気かどうかを判断した。", "target_word": "判断", "complexity_tier": "T3", "furigana": "医者[いしゃ]は検査[けんさ]の結果[けっか]を見[み]て、病気[びょうき]かどうかを判断[はんだん]した。", "sentence_source": "generated"}, {"text": "写真だけでは、味が良いか悪いか判断できない。", "target_word": "判断", "complexity_tier": "T3", "furigana": "写真[しゃしん]だけでは、味[あじ]が良[よ]いか悪[わる]いか判断[はんだん]できない。", "sentence_source": "generated"}, {"text": "先生は、答えが正しいか間違いかを判断して丸をつけた。", "target_word": "判断", "complexity_tier": "T3", "furigana": "先生[せんせい]は、答[こた]えが正[ただ]しいか間違[まちが]いかを判断[はんだん]して丸[まる]をつけた。", "sentence_source": "generated"}, {"text": "雨が強くなったので、試合は中止だと判断された。", "target_word": "判断", "complexity_tier": "T3", "furigana": "雨[あめ]が強[つよ]くなったので、試合[しあい]は中止[ちゅうし]だと判断[はんだん]された。", "sentence_source": "generated"}, {"text": "急いでいたため、悪いかどうか判断する時間がなかった。", "target_word": "判断", "complexity_tier": "T3", "furigana": "急[いそ]いでいたため、悪[わる]いかどうか判断[はんだん]する時間[じかん]がなかった。", "sentence_source": "generated"}, {"text": "審判の判断に、選手たちは文句を言わなかった。", "target_word": "判断", "complexity_tier": "T3", "furigana": "審判[しんぱん]の判断[はんだん]に、選手[せんしゅ]たちは文句[もんく]を言[い]わなかった。", "sentence_source": "generated"}, {"text": "見た目だけで人を判断するのはよくない。", "target_word": "判断", "complexity_tier": "T3", "furigana": "見[み]た目[め]だけで人[ひと]を判断[はんだん]するのはよくない。", "sentence_source": "generated"}, {"text": "安全かどうかは、専門家が判断します。", "target_word": "判断", "complexity_tier": "T3", "furigana": "安全[あんぜん]かどうかは、専門家[せんもんか]が判断[はんだん]します。", "sentence_source": "generated"}], "morphological_forms": [{"form": "判断", "label": "基本形"}, {"form": "判断する", "label": "サ変動詞・終止形"}, {"form": "判断した", "label": "サ変動詞・過去形"}, {"form": "判断できない", "label": "可能否定形"}], "register": "neutral", "sense_fingerprint": "物事が正しいか誤りか、良いか悪いかを見きわめて決めること。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28474861-32e1-4bed-92ca-a633d6cda916') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37896, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "出発", "is_correct": false, "explanation": "その場所を出て行く意味。正誤を決める文脈と結びつかない。"}, {"text": "判断", "is_correct": true, "explanation": "「正しいかどうか」を自分で見きわめて決める意味で、文脈に合う。"}, {"text": "就寝", "is_correct": false, "explanation": "寝ること。正しいかどうかを決める場面とは無関係。"}, {"text": "入浴", "is_correct": false, "explanation": "風呂に入ること。空欄に入れても文の意味が通らない。"}], "explanations": {"出発": "その場所を出て行く意味。正誤を決める文脈と結びつかない。", "判断": "「正しいかどうか」を自分で見きわめて決める意味で、文脈に合う。", "就寝": "寝ること。正しいかどうかを決める場面とは無関係。", "入浴": "風呂に入ること。空欄に入れても文の意味が通らない。"}, "sentence_index": 0, "correct_answer": "判断"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "看護師は患者の体温を判断した。", "explanation": "ここは〈測定〉の意味。判断は善し悪しや正誤を見きわめることで、数値を計る意味では使わない。"}, {"text": "彼女の悲しみを判断した。", "explanation": "ここは〈感じ取る〉の意味。判断は理屈で評価することで、相手の気持ちを感じ取る意味では使わない。"}, {"text": "彼は英単語を一晩で判断した。", "explanation": "ここは〈暗記〉の意味。判断は見きわめて決めることで、覚えて頭に入れる意味では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d48e443-0dbf-4466-acec-a3edef6548fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37896, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "判断", "is_correct": true, "explanation": "「悪いかどうか」を見きわめて決める意味で、文脈に合う。"}, {"text": "散歩", "is_correct": false, "explanation": "ぶらぶら歩くこと。悪いかどうかを決める文とは結びつかない。"}, {"text": "購入", "is_correct": false, "explanation": "買うこと。「悪いかどうか」の見きわめとは無関係。"}, {"text": "洗濯", "is_correct": false, "explanation": "衣類を洗うこと。文の意味が成り立たない。"}], "explanations": {"判断": "「悪いかどうか」を見きわめて決める意味で、文脈に合う。", "散歩": "ぶらぶら歩くこと。悪いかどうかを決める文とは結びつかない。", "購入": "買うこと。「悪いかどうか」の見きわめとは無関係。", "洗濯": "衣類を洗うこと。文の意味が成り立たない。"}, "sentence_index": 6, "correct_answer": "判断"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "会場に集まった人数を判断した。", "explanation": "ここは〈数える〉の意味。判断は善し悪しや正誤を見きわめることで、数量を数える意味では使わない。"}, {"text": "明日の席を判断しておいた。", "explanation": "ここは〈予約〉の意味。判断は見きわめて決めることで、席を取っておく意味では使わない。"}, {"text": "申込用紙に住所を判断して書いた。", "explanation": "ここは〈記入〉の意味。判断は評価して決めることで、用紙に書き込む意味では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d48e443-0dbf-4466-acec-a3edef6548fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37896, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼女はその判断が満足している。", "corrected_sentence": "彼女はその判断に満足している。", "error_description": "「満足する」は「に」を取る。「判断が」は誤りで、正しくは「判断に」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d48e443-0dbf-4466-acec-a3edef6548fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37896, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "急いで判断に誤ると、後で大きな問題になる。", "corrected_sentence": "急いで判断を誤ると、後で大きな問題になる。", "error_description": "「誤る」は「を」を取る。「判断に」は誤りで、正しくは「判断を」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d48e443-0dbf-4466-acec-a3edef6548fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
