INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37897, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「判断がつく」は「判断ができる」という決まった言い方で、「が」は主語を示す。"}, {"text": "を", "is_correct": false, "explanation": "「判断をつく」は成り立たない。「つく」は「判断が」と結びつく。"}, {"text": "に", "is_correct": false, "explanation": "「判断につく」は不自然で、文の意味が通らない。"}, {"text": "で", "is_correct": false, "explanation": "「判断でつく」は手段の意味になり、「つく」と結びつかない。"}], "correct_answer": "が", "explanations": {"が": "「判断がつく」は「判断ができる」という決まった言い方で、「が」は主語を示す。", "を": "「判断をつく」は成り立たない。「つく」は「判断が」と結びつく。", "に": "「判断につく」は不自然で、文の意味が通らない。", "で": "「判断でつく」は手段の意味になり、「つく」と結びつかない。"}, "error_tags": {"を": "対象", "に": "着点", "で": "手段"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d48e443-0dbf-4466-acec-a3edef6548fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37897, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "物事の善悪や価値について、自分の考えを決めること。", "primary_collocate": null, "pronunciation": "はんだん", "ipa": "handaɴ", "syllable_count": 4, "sentences": [{"text": "本の価値は、読んだ人が自分で判断するものだ。", "target_word": "判断", "complexity_tier": "T3", "furigana": "本[ほん]の価値[かち]は、読[よ]んだ人[ひと]が自分[じぶん]で判断[はんだん]するものだ。", "sentence_source": "generated"}, {"text": "彼の行動が良いか悪いかは、私には判断しにくい。", "target_word": "判断", "complexity_tier": "T3", "furigana": "彼[かれ]の行動[こうどう]が良[よ]いか悪[わる]いかは、私[わたし]には判断[はんだん]しにくい。", "sentence_source": "generated"}, {"text": "歴史上の人物は、時代の背景も考えて判断すべきだ。", "target_word": "判断", "complexity_tier": "T4", "furigana": "歴史上[れきしじょう]の人物[じんぶつ]は、時代[じだい]の背景[はいけい]も考[かんが]えて判断[はんだん]すべきだ。", "sentence_source": "generated"}, {"text": "結果を見てから、この計画に価値があったかどうか判断しよう。", "target_word": "判断", "complexity_tier": "T3", "furigana": "結果[けっか]を見[み]てから、この計画[けいかく]に価値[かち]があったかどうか判断[はんだん]しよう。", "sentence_source": "generated"}, {"text": "友達の言葉を聞いても、最後は自分で判断する。", "target_word": "判断", "complexity_tier": "T3", "furigana": "友達[ともだち]の言葉[ことば]を聞[き]いても、最後[さいご]は自分[じぶん]で判断[はんだん]する。", "sentence_source": "generated"}, {"text": "映画の良し悪しの判断は、人によって違う。", "target_word": "判断", "complexity_tier": "T3", "furigana": "映画[えいが]の良[よ]し悪[あ]しの判断[はんだん]は、人[ひと]によって違[ちが]う。", "sentence_source": "generated"}, {"text": "他人の意見だけで判断せず、自分の考えを持ちたい。", "target_word": "判断", "complexity_tier": "T3", "furigana": "他人[たにん]の意見[いけん]だけで判断[はんだん]せず、自分[じぶん]の考[かんが]えを持[も]ちたい。", "sentence_source": "generated"}, {"text": "善悪の判断がつく年齢になれば、責任も生まれる。", "target_word": "判断", "complexity_tier": "T4", "furigana": "善悪[ぜんあく]の判断[はんだん]がつく年齢[ねんれい]になれば、責任[せきにん]も生[う]まれる。", "sentence_source": "generated"}, {"text": "この絵に価値があるかどうか、あなたはどう判断しますか。", "target_word": "判断", "complexity_tier": "T3", "furigana": "この絵[え]に価値[かち]があるかどうか、あなたはどう判断[はんだん]しますか。", "sentence_source": "generated"}, {"text": "彼女の判断は、いつも公平で納得できる。", "target_word": "判断", "complexity_tier": "T3", "furigana": "彼女[かのじょ]の判断[はんだん]は、いつも公平[こうへい]で納得[なっとく]できる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "判断", "label": "基本形"}, {"form": "判断する", "label": "サ変動詞・終止形"}, {"form": "判断せず", "label": "サ変動詞・否定連用形"}, {"form": "判断しよう", "label": "意志形"}], "register": "neutral", "sense_fingerprint": "物事の善悪や価値について、自分の考えや意見を決めること。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28474861-32e1-4bed-92ca-a633d6cda916') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37897, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "洗車", "is_correct": false, "explanation": "車を洗うこと。価値を見きわめる文脈には合わない。"}, {"text": "判断", "is_correct": true, "explanation": "価値を自分で見きわめて決める意味で、文脈に合う。"}, {"text": "散髪", "is_correct": false, "explanation": "髪を切ること。ここでは意味が通らない。"}, {"text": "乾杯", "is_correct": false, "explanation": "杯を上げて祝うこと。価値の見きわめとは無関係。"}], "explanations": {"洗車": "車を洗うこと。価値を見きわめる文脈には合わない。", "判断": "価値を自分で見きわめて決める意味で、文脈に合う。", "散髪": "髪を切ること。ここでは意味が通らない。", "乾杯": "杯を上げて祝うこと。価値の見きわめとは無関係。"}, "sentence_index": 0, "correct_answer": "判断"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "保健室で体重を判断した。", "explanation": "ここは〈測定〉の意味。判断は見きわめて決めることで、重さを量る意味では使わない。"}, {"text": "相手の緊張を判断した。", "explanation": "ここは〈感じ取る〉の意味。判断は理屈で評価することで、相手の緊張を感じ取る意味では使わない。"}, {"text": "彼は年表を一晩で判断した。", "explanation": "ここは〈暗記〉の意味。判断は見きわめて決めることで、年表を覚え込む意味では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d48e443-0dbf-4466-acec-a3edef6548fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37897, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "作曲", "is_correct": false, "explanation": "曲を作ること。意見の扱いを述べる文とは無関係。"}, {"text": "判断", "is_correct": true, "explanation": "他人に任せず自分で見きわめる意味で、文脈に合う。"}, {"text": "出張", "is_correct": false, "explanation": "仕事で他の場所へ行くこと。文が成り立たない。"}, {"text": "清掃", "is_correct": false, "explanation": "掃除すること。意見の扱いとは結びつかない。"}], "explanations": {"作曲": "曲を作ること。意見の扱いを述べる文とは無関係。", "判断": "他人に任せず自分で見きわめる意味で、文脈に合う。", "出張": "仕事で他の場所へ行くこと。文が成り立たない。", "清掃": "掃除すること。意見の扱いとは結びつかない。"}, "sentence_index": 6, "correct_answer": "判断"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "教室に来た生徒の数を判断した。", "explanation": "ここは〈数える〉の意味。判断は善し悪しや正誤を見きわめることで、数量を数える意味では使わない。"}, {"text": "ホテルの部屋を判断しておいた。", "explanation": "ここは〈予約〉の意味。判断は見きわめて決めることで、部屋を取っておく意味では使わない。"}, {"text": "申込書の氏名を判断して書いた。", "explanation": "ここは〈記入〉の意味。判断は評価して決めることで、書き込む意味では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d48e443-0dbf-4466-acec-a3edef6548fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37897, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼は判断を速い。", "corrected_sentence": "彼は判断が速い。", "error_description": "「速い」は「が」で主語を示す形容詞。「判断を」は誤りで、正しくは「判断が」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d48e443-0dbf-4466-acec-a3edef6548fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37897, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "私は彼の判断が納得した。", "corrected_sentence": "私は彼の判断に納得した。", "error_description": "「納得する」は「に」を取る。「判断が」は誤りで、正しくは「判断に」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d48e443-0dbf-4466-acec-a3edef6548fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37898, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "「人の内面は、外から見ただけでは」と主題を示す。「わからない」に続く自然な形。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表すので、「人の内面へ」は意味が通らない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は場所や手段を表すため、「人の内面で」は意味が通らない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列を表すので、「人の内面と、外から見ただけ」は文の構造に合わない。"}], "correct_answer": "は", "explanations": {"は": "「人の内面は、外から見ただけでは」と主題を示す。「わからない」に続く自然な形。", "へ": "「へ」は方向を表すので、「人の内面へ」は意味が通らない。", "で": "「で」は場所や手段を表すため、「人の内面で」は意味が通らない。", "と": "「と」は並列を表すので、「人の内面と、外から見ただけ」は文の構造に合わない。"}, "error_tags": {"で": "手段・場所", "と": "並列・共同", "へ": "方向"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "外面", "is_correct": true, "explanation": "「外面」は外から見える表面を指し、心の奥の「内面」と対義関係にある。"}, {"text": "天気", "is_correct": false, "explanation": "天気は空模様を表し、内面の対義語にはならない。"}, {"text": "窓", "is_correct": false, "explanation": "窓は建具の名前で、内面と対になる語ではない。"}, {"text": "切手", "is_correct": false, "explanation": "切手は郵便に使う紙片で、内面とは対義関係にない。"}], "correct_answer": "外面", "explanations": {"外面": "「外面」は外から見える表面を指し、心の奥の「内面」と対義関係にある。", "天気": "天気は空模様を表し、内面の対義語にはならない。", "窓": "窓は建具の名前で、内面と対になる語ではない。", "切手": "切手は郵便に使う紙片で、内面とは対義関係にない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c533aa2e-e72a-4880-bd9a-6c2afcc806d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37898, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「彼の内面の優しさ」の「の」。「内面」が「優しさ」を修飾する連体修飾の形。"}, {"text": "が", "is_correct": false, "explanation": "「彼の内面が優しさがよく伝わってきた」は主語が重なり、不自然になる。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を表すので、「彼の内面より優しさ」は文の構造に合わない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表すので、「彼の内面へ優しさ」は意味が通らない。"}], "correct_answer": "の", "explanations": {"の": "「彼の内面の優しさ」の「の」。「内面」が「優しさ」を修飾する連体修飾の形。", "が": "「彼の内面が優しさがよく伝わってきた」は主語が重なり、不自然になる。", "より": "「より」は比較を表すので、「彼の内面より優しさ」は文の構造に合わない。", "へ": "「へ」は方向を表すので、「彼の内面へ優しさ」は意味が通らない。"}, "error_tags": {"が": "主語", "より": "比較", "へ": "方向"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "外面", "is_correct": true, "explanation": "「外面」は外から見える表面を指し、傷つきやすい心の奥の「内面」と対義関係にある。"}, {"text": "花瓶", "is_correct": false, "explanation": "花瓶は花を生ける器で、内面の対義語にはならない。"}, {"text": "靴", "is_correct": false, "explanation": "靴は履物の名前で、内面と対になる語ではない。"}, {"text": "鍋", "is_correct": false, "explanation": "鍋は調理器具の名前で、内面とは対義関係にない。"}], "correct_answer": "外面", "explanations": {"外面": "「外面」は外から見える表面を指し、傷つきやすい心の奥の「内面」と対義関係にある。", "花瓶": "花瓶は花を生ける器で、内面の対義語にはならない。", "靴": "靴は履物の名前で、内面と対になる語ではない。", "鍋": "鍋は調理器具の名前で、内面とは対義関係にない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c533aa2e-e72a-4880-bd9a-6c2afcc806d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37898, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "人の心の中にある考えや気持ちのこと。目に見えない。", "primary_collocate": null, "pronunciation": "ないめん", "ipa": "naimeɴ", "syllable_count": 4, "sentences": [{"text": "彼は明るく見えるが、内面ではいつも不安を抱えている。", "target_word": "内面", "complexity_tier": "T3", "furigana": "彼[かれ]は明[あか]るく見[み]えるが、内面[ないめん]ではいつも不安[ふあん]を抱[かか]えている。", "sentence_source": "generated"}, {"text": "人の内面は、外から見ただけではわからない。", "target_word": "内面", "complexity_tier": "T3", "furigana": "人[ひと]の内面[ないめん]は、外[そと]から見[み]ただけではわからない。", "sentence_source": "generated"}, {"text": "外見ばかり気にして、内面を磨くことを忘れてはいけない。", "target_word": "内面", "complexity_tier": "T3", "furigana": "外見[がいけん]ばかり気[き]にして、内面[ないめん]を磨[みが]くことを忘[わす]れてはいけない。", "sentence_source": "generated"}, {"text": "この小説は、主人公の内面を丁寧に描いている。", "target_word": "内面", "complexity_tier": "T3", "furigana": "この小説[しょうせつ]は、主人公[しゅじんこう]の内面[ないめん]を丁寧[ていねい]に描[えが]いている。", "sentence_source": "generated"}, {"text": "彼女は自分の内面と向き合うために、毎日日記を書いている。", "target_word": "内面", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は自分[じぶん]の内面[ないめん]と向[む]き合[あ]うために、毎日[まいにち]日記[にっき]を書[か]いている。", "sentence_source": "generated"}, {"text": "笑顔の裏にある内面を、友人だけが見抜いていた。", "target_word": "内面", "complexity_tier": "T3", "furigana": "笑顔[えがお]の裏[うら]にある内面[ないめん]を、友人[ゆうじん]だけが見抜[みぬ]いていた。", "sentence_source": "generated"}, {"text": "怒りを表に出さなくても、内面では強く傷ついていた。", "target_word": "内面", "complexity_tier": "T3", "furigana": "怒[いか]りを表[おもて]に出[だ]さなくても、内面[ないめん]では強[つよ]く傷[きず]ついていた。", "sentence_source": "generated"}, {"text": "話してみると、彼の内面の優しさがよく伝わってきた。", "target_word": "内面", "complexity_tier": "T3", "furigana": "話[はな]してみると、彼[かれ]の内面[ないめん]の優[やさ]しさがよく伝[つた]わってきた。", "sentence_source": "generated"}, {"text": "子どもの内面の成長は、数字では測れない。", "target_word": "内面", "complexity_tier": "T3", "furigana": "子[こ]どもの内面[ないめん]の成長[せいちょう]は、数字[すうじ]では測[はか]れない。", "sentence_source": "generated"}, {"text": "役者は役の内面を理解して、はじめて自然な演技ができる。", "target_word": "内面", "complexity_tier": "T3", "furigana": "役者[やくしゃ]は役[やく]の内面[ないめん]を理解[りかい]して、はじめて自然[しぜん]な演技[えんぎ]ができる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "内面", "label": "基本形"}], "register": "標準", "sense_fingerprint": "人の外から見えない心の中の考えや気持ち", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a8c3c963-2a95-475a-8066-2eceb2411f9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37898, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "内面", "is_correct": true, "explanation": "「明るく見えるが、内面では不安を抱えている」の形。外見と対比して心の中を表す。"}, {"text": "靴", "is_correct": false, "explanation": "靴は履物で、「ではいつも不安を抱えている」の場所としては成り立たない。"}, {"text": "写真", "is_correct": false, "explanation": "写真は画像を指す語で、不安を抱える場所としては合わない。"}, {"text": "鍋", "is_correct": false, "explanation": "鍋は調理器具で、人の心の状態を表す文脈には合わない。"}], "explanations": {"内面": "「明るく見えるが、内面では不安を抱えている」の形。外見と対比して心の中を表す。", "靴": "靴は履物で、「ではいつも不安を抱えている」の場所としては成り立たない。", "写真": "写真は画像を指す語で、不安を抱える場所としては合わない。", "鍋": "鍋は調理器具で、人の心の状態を表す文脈には合わない。"}, "sentence_index": 0, "correct_answer": "内面"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は内面を厚く着込んで、寒い冬の外へ出た。", "explanation": "ここは〈服装〉の意味。服を重ねて着る意味では「着込む」を使い、心の中を指す内面とは言わない。"}, {"text": "この箱の内面には、古い手紙が入っていた。", "explanation": "ここは〈中身〉の意味。内面は物の内側の表面や心を指し、中に入っている物には使わない。"}, {"text": "この煮物は内面がよく染みていて、ごはんが進む。", "explanation": "ここは〈味〉の意味。味が染みる様子は「味」や「染みる」で表し、心の中を指す内面とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c533aa2e-e72a-4880-bd9a-6c2afcc806d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37898, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "内面", "is_correct": true, "explanation": "「怒りを表に出さなくても、内面では強く傷ついていた」の形。心の中を表し、表に出さない気持ちと合う。"}, {"text": "机", "is_correct": false, "explanation": "机は家具で、「では強く傷ついていた」の場所としては成り立たない。"}, {"text": "時計", "is_correct": false, "explanation": "時計は時刻を示す道具で、傷ついている場所としては合わない。"}, {"text": "海", "is_correct": false, "explanation": "海は自然の場所で、心の中の状態を表す文脈には合わない。"}], "explanations": {"内面": "「怒りを表に出さなくても、内面では強く傷ついていた」の形。心の中を表し、表に出さない気持ちと合う。", "机": "机は家具で、「では強く傷ついていた」の場所としては成り立たない。", "時計": "時計は時刻を示す道具で、傷ついている場所としては合わない。", "海": "海は自然の場所で、心の中の状態を表す文脈には合わない。"}, "sentence_index": 6, "correct_answer": "内面"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "明日の内面は、朝から雨が降るらしい。", "explanation": "ここは〈天気〉の意味。天気の予報は「天気」や「空模様」で表し、心の中を指す内面とは言わない。"}, {"text": "このビルの内面は、年々値段が上がっている。", "explanation": "ここは〈値段〉の意味。値段が上がる意味では「値段」や「価格」を使い、内面とは言わない。"}, {"text": "町の内面を調べたところ、古い神社があった。", "explanation": "ここは〈内部の様子〉の意味。町の内部を指す語としては、内面は使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c533aa2e-e72a-4880-bd9a-6c2afcc806d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37898, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼は怒りを心の内面をしまい込んだ。", "corrected_sentence": "彼は怒りを心の内面にしまい込んだ。", "error_description": "「しまい込む」は場所を「に」で表す。「を」を重ねると目的語が二つになり誤り。正しくは「内面に」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c533aa2e-e72a-4880-bd9a-6c2afcc806d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37898, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼は喜びを内面を秘めて、静かに笑った。", "corrected_sentence": "彼は喜びを内面に秘めて、静かに笑った。", "error_description": "「秘める」は場所を「に」で表す。「を」を重ねると目的語が二つになり誤り。正しくは「内面に」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c533aa2e-e72a-4880-bd9a-6c2afcc806d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37899, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "「内面では」の「では」。場面や範囲を表し、「心の中では」の意味になる。"}, {"text": "を", "is_correct": false, "explanation": "「内面を大きな不安を抱えている」は目的語が重なり、文が成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列を表すため、「内面と大きな不安を抱えている」は意味が通らない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表すので、「内面へ不安を抱えている」は不自然。"}], "correct_answer": "で", "explanations": {"で": "「内面では」の「では」。場面や範囲を表し、「心の中では」の意味になる。", "を": "「内面を大きな不安を抱えている」は目的語が重なり、文が成り立たない。", "と": "「と」は並列を表すため、「内面と大きな不安を抱えている」は意味が通らない。", "へ": "「へ」は方向を表すので、「内面へ不安を抱えている」は不自然。"}, "error_tags": {"を": "目的語", "と": "並列・共同", "へ": "方向"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "外面", "is_correct": true, "explanation": "「外面」は外から見える表面や見た目を指し、心の奥の「内面」と対になる語。"}, {"text": "教室", "is_correct": false, "explanation": "教室は場所を表す語で、内面の対義語にはならない。"}, {"text": "駅", "is_correct": false, "explanation": "駅は場所を表す語で、内面とは対義関係にない。"}, {"text": "机", "is_correct": false, "explanation": "机は家具の名前で、内面と対になる語ではない。"}], "correct_answer": "外面", "explanations": {"外面": "「外面」は外から見える表面や見た目を指し、心の奥の「内面」と対になる語。", "教室": "教室は場所を表す語で、内面の対義語にはならない。", "駅": "駅は場所を表す語で、内面とは対義関係にない。", "机": "机は家具の名前で、内面と対になる語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c533aa2e-e72a-4880-bd9a-6c2afcc806d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37899, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「内面が大きく成長した」の「が」。成長する主体を表す。"}, {"text": "の", "is_correct": false, "explanation": "「の」は名詞を修飾するため、「内面の大きく成長した」は文の構造に合わない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を表すので、ここでは成長する主体を示せない。"}, {"text": "を", "is_correct": false, "explanation": "「内面を大きく成長した」は成長の対象を取らず、目的語の「を」が不自然。"}], "correct_answer": "が", "explanations": {"が": "「内面が大きく成長した」の「が」。成長する主体を表す。", "の": "「の」は名詞を修飾するため、「内面の大きく成長した」は文の構造に合わない。", "より": "「より」は比較を表すので、ここでは成長する主体を示せない。", "を": "「内面を大きく成長した」は成長の対象を取らず、目的語の「を」が不自然。"}, "error_tags": {"の": "連体修飾", "より": "比較", "を": "目的語"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "外面", "is_correct": true, "explanation": "「外面」は外から見える表面を指し、心の奥の「内面」と対義関係にある。"}, {"text": "機械", "is_correct": false, "explanation": "機械は道具の一種で、内面と対義関係にはならない。"}, {"text": "時計", "is_correct": false, "explanation": "時計は時刻を示す道具で、内面の対義語にはならない。"}, {"text": "花瓶", "is_correct": false, "explanation": "花瓶は花を生ける器で、内面と対になる語ではない。"}], "correct_answer": "外面", "explanations": {"外面": "「外面」は外から見える表面を指し、心の奥の「内面」と対義関係にある。", "機械": "機械は道具の一種で、内面と対義関係にはならない。", "時計": "時計は時刻を示す道具で、内面の対義語にはならない。", "花瓶": "花瓶は花を生ける器で、内面と対になる語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c533aa2e-e72a-4880-bd9a-6c2afcc806d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37899, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "心の奥底にある、外からは見えない精神的な部分。感情や考え方。", "primary_collocate": null, "pronunciation": "ないめん", "ipa": "naimeɴ", "syllable_count": 4, "sentences": [{"text": "私の内面に潜む不安を、誰にも話せずにいた。", "target_word": "内面", "complexity_tier": "T3", "furigana": "私[わたし]の内面[ないめん]に潜[ひそ]む不安[ふあん]を、誰[だれ]にも話[はな]せずにいた。", "sentence_source": "generated"}, {"text": "彼は明るく見えるが、内面では大きな不安を抱えている。", "target_word": "内面", "complexity_tier": "T3", "furigana": "彼[かれ]は明[あか]るく見[み]えるが、内面[ないめん]では大[おお]きな不安[ふあん]を抱[かか]えている。", "sentence_source": "generated"}, {"text": "人の価値は外見だけでなく、内面にも表れる。", "target_word": "内面", "complexity_tier": "T3", "furigana": "人[ひと]の価値[かち]は外見[がいけん]だけでなく、内面[ないめん]にも表[あらわ]れる。", "sentence_source": "generated"}, {"text": "日記を書くことで、自分の内面と向き合う時間ができた。", "target_word": "内面", "complexity_tier": "T3", "furigana": "日記[にっき]を書[か]くことで、自分[じぶん]の内面[ないめん]と向[む]き合[あ]う時間[じかん]ができた。", "sentence_source": "generated"}, {"text": "この小説は、主人公の内面の変化を丁寧に描いている。", "target_word": "内面", "complexity_tier": "T3", "furigana": "この小説[しょうせつ]は、主人公[しゅじんこう]の内面[ないめん]の変化[へんか]を丁寧[ていねい]に描[えが]いている。", "sentence_source": "generated"}, {"text": "彼女は穏やかな笑顔の裏に、強い内面を持っている。", "target_word": "内面", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は穏[おだ]やかな笑顔[えがお]の裏[うら]に、強[つよ]い内面[ないめん]を持[も]っている。", "sentence_source": "generated"}, {"text": "内面を言葉にするのが苦手で、いつも友だちに誤解される。", "target_word": "内面", "complexity_tier": "T3", "furigana": "内面[ないめん]を言葉[ことば]にするのが苦手[にがて]で、いつも友[とも]だちに誤解[ごかい]される。", "sentence_source": "generated"}, {"text": "長い旅を終えて、内面が大きく成長したように感じる。", "target_word": "内面", "complexity_tier": "T3", "furigana": "長[なが]い旅[たび]を終[お]えて、内面[ないめん]が大[おお]きく成長[せいちょう]したように感[かん]じる。", "sentence_source": "generated"}, {"text": "俳優は役の内面を理解してはじめて、自然な演技ができる。", "target_word": "内面", "complexity_tier": "T3", "furigana": "俳優[はいゆう]は役[やく]の内面[ないめん]を理解[りかい]してはじめて、自然[しぜん]な演技[えんぎ]ができる。", "sentence_source": "generated"}, {"text": "彼の冷たい態度は、傷つきやすい内面を隠すためのものだった。", "target_word": "内面", "complexity_tier": "T3", "furigana": "彼[かれ]の冷[つめ]たい態度[たいど]は、傷[きず]つきやすい内面[ないめん]を隠[かく]すためのものだった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "内面", "label": "基本形"}, {"form": "内面的", "label": "形状詞形（的）"}], "register": "標準（書き言葉）", "sense_fingerprint": "人の心の奥にある、外から見えない感情や考え方の部分。外見・外面と対になる。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a8c3c963-2a95-475a-8066-2eceb2411f9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37899, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "内面", "is_correct": true, "explanation": "「私の内面に潜む不安」の形。心の奥底を指す語で、文の意味に合う。"}, {"text": "天気", "is_correct": false, "explanation": "天気は空模様を表し、感情が潜む場所としては成り立たない。"}, {"text": "窓", "is_correct": false, "explanation": "窓は建具で、情動が潜む場所を表すには合わない。"}, {"text": "冷蔵庫", "is_correct": false, "explanation": "冷蔵庫は家電で、「私の」に続いて情動が潜む場所にはならない。"}], "explanations": {"内面": "「私の内面に潜む不安」の形。心の奥底を指す語で、文の意味に合う。", "天気": "天気は空模様を表し、感情が潜む場所としては成り立たない。", "窓": "窓は建具で、情動が潜む場所を表すには合わない。", "冷蔵庫": "冷蔵庫は家電で、「私の」に続いて情動が潜む場所にはならない。"}, "sentence_index": 0, "correct_answer": "内面"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "このスープは内面が濃くて、味がはっきりしている。", "explanation": "ここは〈味〉の意味。味の濃さは「味」や「濃さ」で表し、心の奥を指す内面とは言わない。"}, {"text": "この封筒の内面には、古い写真が入っていた。", "explanation": "ここは〈中身〉の意味。内面は物の内側の表面や心を指し、中に入っている物には使わない。"}, {"text": "森の内面に、小さな池があった。", "explanation": "ここは〈奥〉の意味。場所の奥を言う時は「奥」や「中」を使い、内面とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c533aa2e-e72a-4880-bd9a-6c2afcc806d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37899, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "内面", "is_correct": true, "explanation": "「内面を言葉にするのが苦手」の形。心の中の考えや気持ちを指し、文に合う。"}, {"text": "海", "is_correct": false, "explanation": "海は自然の場所で、「を言葉にする」の対象にはならない。"}, {"text": "切手", "is_correct": false, "explanation": "切手は郵便に使う紙片で、言葉にする対象としては成り立たない。"}, {"text": "部屋", "is_correct": false, "explanation": "部屋は空間を表し、「を言葉にする」とは続かない。"}], "explanations": {"内面": "「内面を言葉にするのが苦手」の形。心の中の考えや気持ちを指し、文に合う。", "海": "海は自然の場所で、「を言葉にする」の対象にはならない。", "切手": "切手は郵便に使う紙片で、言葉にする対象としては成り立たない。", "部屋": "部屋は空間を表し、「を言葉にする」とは続かない。"}, "sentence_index": 6, "correct_answer": "内面"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼女は内面がとても若く見えるので、年下に間違えられる。", "explanation": "ここは〈見た目の若さ〉の意味。見た目は「外見」や「見た目」で表し、心の奥を指す内面とは言わない。"}, {"text": "この店の内面は、ずいぶん高くなった。", "explanation": "ここは〈値段〉の意味。店の値段は「値段」や「価格」で表し、内面とは言わない。"}, {"text": "その部屋の内面は、とても広い。", "explanation": "ここは〈空間の内側〉の意味。部屋の広さを言う時は「内側」や「中」を使い、内面とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c533aa2e-e72a-4880-bd9a-6c2afcc806d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37899, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼女は自分の内面に見つめ直した。", "corrected_sentence": "彼女は自分の内面を見つめ直した。", "error_description": "「見つめ直す」は見る対象を「を」で表す。「に」は誤り。正しくは「内面を」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c533aa2e-e72a-4880-bd9a-6c2afcc806d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37899, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "その出来事で、彼女の内面を大きく変わった。", "corrected_sentence": "その出来事で、彼女の内面は大きく変わった。", "error_description": "「変わる」は自動詞なので、変化する主体は「は」や「が」で示す。「を」は誤り。正しくは「内面は」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c533aa2e-e72a-4880-bd9a-6c2afcc806d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37900, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「権力を使う」の目的語で、「権力を使って」と続けて文の意味が成り立つ。"}, {"text": "に", "is_correct": false, "explanation": "「権力に使う」は「使う」の相手として不自然。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示すが、「使う」と結びつかない。"}, {"text": "と", "is_correct": false, "explanation": "並列を表すが、「使う」とは合わない。"}], "correct_answer": "を", "explanations": {"を": "「権力を使う」の目的語で、「権力を使って」と続けて文の意味が成り立つ。", "に": "「権力に使う」は「使う」の相手として不自然。", "へ": "方向を示すが、「使う」と結びつかない。", "と": "並列を表すが、「使う」とは合わない。"}, "error_tags": {"に": "相手", "へ": "方向", "と": "並列"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d48e443-0dbf-4466-acec-a3edef6548fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37900, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「権力が強すぎる」の主語を示し、「強すぎると」に続いて文が成り立つ。"}, {"text": "を", "is_correct": false, "explanation": "「権力を強すぎる」は形容詞の前に目的語を取れず不自然。"}, {"text": "で", "is_correct": false, "explanation": "「権力で強すぎる」は手段の意味になり、不自然。"}, {"text": "の", "is_correct": false, "explanation": "「権力の強すぎる」は名詞を修飾し、「強すぎると」の述語と合わない。"}], "correct_answer": "が", "explanations": {"が": "「権力が強すぎる」の主語を示し、「強すぎると」に続いて文が成り立つ。", "を": "「権力を強すぎる」は形容詞の前に目的語を取れず不自然。", "で": "「権力で強すぎる」は手段の意味になり、不自然。", "の": "「権力の強すぎる」は名詞を修飾し、「強すぎると」の述語と合わない。"}, "error_tags": {"を": "対象", "で": "手段", "の": "連体"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d48e443-0dbf-4466-acec-a3edef6548fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37900, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "人を指図したり、自由をうばったりする力のこと。", "primary_collocate": null, "pronunciation": "けんりょく", "ipa": "keɴɾʲokɯ", "syllable_count": 4, "sentences": [{"text": "王は大きな権力を持ち、人々に命令した。", "target_word": "権力", "complexity_tier": "T3", "furigana": "王[おう]は大[おお]きな権力[けんりょく]を持[も]ち、人々[ひとびと]に命令[めいれい]した。", "sentence_source": "generated"}, {"text": "権力を使って人の自由を奪うことは許されない。", "target_word": "権力", "complexity_tier": "T3", "furigana": "権力[けんりょく]を使[つか]って人[ひと]の自由[じゆう]を奪[うば]うことは許[ゆる]されない。", "sentence_source": "generated"}, {"text": "独裁者は権力を握ると、国民の言論を禁じた。", "target_word": "権力", "complexity_tier": "T4", "furigana": "独裁者[どくさいしゃ]は権力[けんりょく]を握[にぎ]ると、国民[こくみん]の言論[げんろん]を禁[きん]じた。", "sentence_source": "generated"}, {"text": "権力に逆らった人は、仕事を失ってしまった。", "target_word": "権力", "complexity_tier": "T3", "furigana": "権力[けんりょく]に逆[さか]らった人[ひと]は、仕事[しごと]を失[うしな]ってしまった。", "sentence_source": "generated"}, {"text": "昔の領主は権力が強く、農民は逆らえなかった。", "target_word": "権力", "complexity_tier": "T3", "furigana": "昔[むかし]の領主[りょうしゅ]は権力[けんりょく]が強[つよ]く、農民[のうみん]は逆[さか]らえなかった。", "sentence_source": "generated"}, {"text": "権力を持つと、人は周りの意見を聞かなくなることがある。", "target_word": "権力", "complexity_tier": "T3", "furigana": "権力[けんりょく]を持[も]つと、人[ひと]は周[まわ]りの意見[いけん]を聞[き]かなくなることがある。", "sentence_source": "generated"}, {"text": "彼は権力で部下を従わせようとして、嫌われた。", "target_word": "権力", "complexity_tier": "T3", "furigana": "彼[かれ]は権力[けんりょく]で部下[ぶか]を従[したが]わせようとして、嫌[きら]われた。", "sentence_source": "generated"}, {"text": "政府の権力が強すぎると、市民の自由が減る。", "target_word": "権力", "complexity_tier": "T3", "furigana": "政府[せいふ]の権力[けんりょく]が強[つよ]すぎると、市民[しみん]の自由[じゆう]が減[へ]る。", "sentence_source": "generated"}, {"text": "その小説は、権力と戦う少年の物語だ。", "target_word": "権力", "complexity_tier": "T3", "furigana": "その小説[しょうせつ]は、権力[けんりょく]と戦[たたか]う少年[しょうねん]の物語[ものがたり]だ。", "sentence_source": "generated"}, {"text": "権力を手に入れた男は、仲間さえ信じなくなった。", "target_word": "権力", "complexity_tier": "T3", "furigana": "権力[けんりょく]を手[て]に入[い]れた男[おとこ]は、仲間[なかま]さえ信[しん]じなくなった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "権力", "label": "基本形"}, {"form": "権力が", "label": "主格"}, {"form": "権力を", "label": "目的格"}, {"form": "権力に", "label": "与格"}], "register": "neutral", "sense_fingerprint": "人に命令したり、人の自由をおさえたりできる強い力。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28474861-32e1-4bed-92ca-a633d6cda916') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37900, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "感謝", "is_correct": false, "explanation": "恩に感じて礼を言うこと。「持ち」と「命令した」の文脈に合わない。"}, {"text": "権力", "is_correct": true, "explanation": "人々に命令できる力のことで、「持ち、命令した」の文脈に合う。"}, {"text": "寿命", "is_correct": false, "explanation": "生き続ける期間。命令する行為とは結びつかない。"}, {"text": "食欲", "is_correct": false, "explanation": "食べたい気持ち。命令した理由にならない。"}], "explanations": {"感謝": "恩に感じて礼を言うこと。「持ち」と「命令した」の文脈に合わない。", "権力": "人々に命令できる力のことで、「持ち、命令した」の文脈に合う。", "寿命": "生き続ける期間。命令する行為とは結びつかない。", "食欲": "食べたい気持ち。命令した理由にならない。"}, "sentence_index": 0, "correct_answer": "権力"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は権力があり、山登りで誰よりも先に頂上へ着いた。", "explanation": "ここは〈体力〉の意味。権力は他人を支配する力なので、体の強さを表す文では使わない。"}, {"text": "彼女は権力が高く、難しい数学の問題をすぐ解いた。", "explanation": "ここは〈知力〉の意味。権力は人を従わせる力で、頭の働きを表す文では使わない。"}, {"text": "夜道でも権力が良く、遠くの看板がはっきり見えた。", "explanation": "ここは〈視力〉の意味。権力は人を支配する力で、目の働きを表す文には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d48e443-0dbf-4466-acec-a3edef6548fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37900, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "悲しみ", "is_correct": false, "explanation": "悲しい気持ち。部下を従わせる手段として結びつかない。"}, {"text": "権力", "is_correct": true, "explanation": "人を従わせる力のことで、「彼は〜で部下を従わせようとして」に合う。"}, {"text": "記憶", "is_correct": false, "explanation": "覚えていること。従わせる手段として文が成り立たない。"}, {"text": "遠慮", "is_correct": false, "explanation": "控えめに振る舞うこと。従わせる手段にならない。"}], "explanations": {"悲しみ": "悲しい気持ち。部下を従わせる手段として結びつかない。", "権力": "人を従わせる力のことで、「彼は〜で部下を従わせようとして」に合う。", "記憶": "覚えていること。従わせる手段として文が成り立たない。", "遠慮": "控えめに振る舞うこと。従わせる手段にならない。"}, "sentence_index": 6, "correct_answer": "権力"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "毎朝走って、脚の権力を鍛えている。", "explanation": "ここは〈筋力〉の意味。権力は人を支配する力で、筋肉の強さには使わない。"}, {"text": "彼は権力が鋭く、ボールに素早く届いた。", "explanation": "ここは〈瞬発力〉の意味。権力は人を動かす力で、一瞬の反応の速さには使わない。"}, {"text": "犬は権力が優れていて、落とした財布をすぐ見つけた。", "explanation": "ここは〈嗅覚〉の意味。権力は人を支配する力で、においを感じ取る能力には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d48e443-0dbf-4466-acec-a3edef6548fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37900, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼は権力に使って人を従わせた。", "corrected_sentence": "彼は権力を使って人を従わせた。", "error_description": "「使う」は「を」を取る。「権力に」は誤りで、正しくは「権力を」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d48e443-0dbf-4466-acec-a3edef6548fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37900, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "一人への権力を集中は、国を危うくする。", "corrected_sentence": "一人への権力の集中は、国を危うくする。", "error_description": "「集中」は「権力の集中」と「の」で結ぶ名詞。「権力を集中」は「を」で誤り。正しくは「権力の集中」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d48e443-0dbf-4466-acec-a3edef6548fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37901, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「権力が集まる」の主語を示し、「一人に集まる」と続けて文が成り立つ。"}, {"text": "を", "is_correct": false, "explanation": "「権力を集まる」は自動詞の「集まる」に目的語が合わず不自然。"}, {"text": "に", "is_correct": false, "explanation": "「権力に集まる」は不自然で、文の意味が通らない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示すが、「一人に集まる」と重なって文が成り立たない。"}], "correct_answer": "が", "explanations": {"が": "「権力が集まる」の主語を示し、「一人に集まる」と続けて文が成り立つ。", "を": "「権力を集まる」は自動詞の「集まる」に目的語が合わず不自然。", "に": "「権力に集まる」は不自然で、文の意味が通らない。", "へ": "方向を示すが、「一人に集まる」と重なって文が成り立たない。"}, "error_tags": {"を": "対象", "に": "相手", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d48e443-0dbf-4466-acec-a3edef6548fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37901, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「権力に興味がない」の「に」で、興味の対象を示して文が成り立つ。"}, {"text": "が", "is_correct": false, "explanation": "「権力が興味がない」は主語にならず不自然。"}, {"text": "で", "is_correct": false, "explanation": "「権力で興味がない」は手段の意味になり不自然。"}, {"text": "を", "is_correct": false, "explanation": "「権力を」は「興味がない」と結びつかず、文が成り立たない。"}], "correct_answer": "に", "explanations": {"に": "「権力に興味がない」の「に」で、興味の対象を示して文が成り立つ。", "が": "「権力が興味がない」は主語にならず不自然。", "で": "「権力で興味がない」は手段の意味になり不自然。", "を": "「権力を」は「興味がない」と結びつかず、文が成り立たない。"}, "error_tags": {"が": "主語", "で": "手段", "を": "対象"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d48e443-0dbf-4466-acec-a3edef6548fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37901, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "他者や組織を支配し、自分の思い通りに動かすことのできる力や影響力。", "primary_collocate": null, "pronunciation": "けんりょく", "ipa": "keɴɾʲokɯ", "syllable_count": 4, "sentences": [{"text": "社長は会社の中で大きな権力を持っている。", "target_word": "権力", "complexity_tier": "T3", "furigana": "社長[しゃちょう]は会社[かいしゃ]の中[なか]で大[おお]きな権力[けんりょく]を持[も]っている。", "sentence_source": "generated"}, {"text": "権力が一人に集まると、組織は間違いを正せなくなる。", "target_word": "権力", "complexity_tier": "T4", "furigana": "権力[けんりょく]が一人[ひとり]に集[あつ]まると、組織[そしき]は間違[まちが]いを正[ただ]せなくなる。", "sentence_source": "generated"}, {"text": "彼は権力を利用して、取引先を思い通りに動かした。", "target_word": "権力", "complexity_tier": "T3", "furigana": "彼[かれ]は権力[けんりょく]を利用[りよう]して、取引先[とりひきさき]を思[おも]い通[どお]りに動[うご]かした。", "sentence_source": "generated"}, {"text": "政治家の権力は、国民の信頼に支えられている。", "target_word": "権力", "complexity_tier": "T3", "furigana": "政治家[せいじか]の権力[けんりょく]は、国民[こくみん]の信頼[しんらい]に支[ささ]えられている。", "sentence_source": "generated"}, {"text": "新しい部長は権力を振りかざさず、部下の意見を聞いた。", "target_word": "権力", "complexity_tier": "T4", "furigana": "新[あたら]しい部長[ぶちょう]は権力[けんりょく]を振[ふ]りかざさず、部下[ぶか]の意見[いけん]を聞[き]いた。", "sentence_source": "generated"}, {"text": "権力の座を争う二つの派閥が、会議で対立した。", "target_word": "権力", "complexity_tier": "T4", "furigana": "権力[けんりょく]の座[ざ]を争[あらそ]う二[ふた]つの派閥[はばつ]が、会議[かいぎ]で対立[たいりつ]した。", "sentence_source": "generated"}, {"text": "権力を分けることで、国は一人の暴走を防いでいる。", "target_word": "権力", "complexity_tier": "T4", "furigana": "権力[けんりょく]を分[わ]けることで、国[くに]は一人[ひとり]の暴走[ぼうそう]を防[ふせ]いでいる。", "sentence_source": "generated"}, {"text": "彼女は権力に興味がなく、研究だけを続けた。", "target_word": "権力", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は権力[けんりょく]に興味[きょうみ]がなく、研究[けんきゅう]だけを続[つづ]けた。", "sentence_source": "generated"}, {"text": "大きな権力には、それにふさわしい責任が伴う。", "target_word": "権力", "complexity_tier": "T4", "furigana": "大[おお]きな権力[けんりょく]には、それにふさわしい責任[せきにん]が伴[ともな]う。", "sentence_source": "generated"}, {"text": "裏で権力を握る人物が、市の計画を決めていた。", "target_word": "権力", "complexity_tier": "T4", "furigana": "裏[うら]で権力[けんりょく]を握[にぎ]る人物[じんぶつ]が、市[し]の計画[けいかく]を決[き]めていた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "権力", "label": "基本形"}, {"form": "権力の", "label": "連体形"}, {"form": "権力を", "label": "目的格"}, {"form": "権力に", "label": "与格"}], "register": "neutral", "sense_fingerprint": "他者や組織を支配し、思い通りに動かせる力や影響力。政治・組織の力関係で使う。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 1 above tier T2: contains vocabulary far above tier T2: 正せ (Zipf 2.39)','sentence 4 above tier T2: contains vocabulary far above tier T2: 振りかざさ (Zipf 1.3)']::text[], '28474861-32e1-4bed-92ca-a633d6cda916') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37901, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "休暇", "is_correct": false, "explanation": "仕事を休むこと。「大きな〜を持っている」に合わない。"}, {"text": "権力", "is_correct": true, "explanation": "他者を支配する力のことで、「大きな〜を持っている」に合う。"}, {"text": "好物", "is_correct": false, "explanation": "特に好きな食べ物。文脈に合わない。"}, {"text": "眠気", "is_correct": false, "explanation": "眠くなる感覚。「持っている」と結びつかない。"}], "explanations": {"休暇": "仕事を休むこと。「大きな〜を持っている」に合わない。", "権力": "他者を支配する力のことで、「大きな〜を持っている」に合う。", "好物": "特に好きな食べ物。文脈に合わない。", "眠気": "眠くなる感覚。「持っている」と結びつかない。"}, "sentence_index": 0, "correct_answer": "権力"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は権力が豊富で、難しい言葉をたくさん知っている。", "explanation": "ここは〈語彙〉の意味。権力は人を従わせる力で、言葉の量を表す文では使わない。"}, {"text": "彼女は権力が続き、三時間も本を読み続けた。", "explanation": "ここは〈集中力〉の意味。権力は人を動かす力で、物事に集中し続ける力には使わない。"}, {"text": "彼の英語は権力がきれいで、ネイティブのようだ。", "explanation": "ここは〈発音〉の意味。権力は人を支配する力で、音の響きには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d48e443-0dbf-4466-acec-a3edef6548fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37901, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "地図", "is_correct": false, "explanation": "紙や画面に描かれた地形の図。分けることで暴走を防ぐ文脈に合わない。"}, {"text": "権力", "is_correct": true, "explanation": "他者を支配する力のことで、「分けることで、国は暴走を防いでいる」に合う。"}, {"text": "砂糖", "is_correct": false, "explanation": "甘味料。権力の話題とは結びつかない。"}, {"text": "義理", "is_correct": false, "explanation": "人に対して守るべき道理。分けるものとして不自然。"}], "explanations": {"地図": "紙や画面に描かれた地形の図。分けることで暴走を防ぐ文脈に合わない。", "権力": "他者を支配する力のことで、「分けることで、国は暴走を防いでいる」に合う。", "砂糖": "甘味料。権力の話題とは結びつかない。", "義理": "人に対して守るべき道理。分けるものとして不自然。"}, "sentence_index": 6, "correct_answer": "権力"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "患者は権力が早く、一週間で退院できた。", "explanation": "ここは〈回復力〉の意味。権力は人を支配する力で、体の回復の速さには使わない。"}, {"text": "彼は権力が鋭く、料理の塩加減をすぐ見抜く。", "explanation": "ここは〈味覚〉の意味。権力は人を動かす力で、味を感じ取る能力には使わない。"}, {"text": "この町は道が複雑で、権力が鈍い人は迷いやすい。", "explanation": "ここは〈方向感覚〉の意味。権力は人を支配する力で、道筋をつかむ感覚には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d48e443-0dbf-4466-acec-a3edef6548fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37901, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼は権力が振りかざさない。", "corrected_sentence": "彼は権力を振りかざさない。", "error_description": "「振りかざす」は「を」を取る他動詞。「権力が」は誤りで、正しくは「権力を」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d48e443-0dbf-4466-acec-a3edef6548fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37901, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "権力に分けることで、組織は暴走を防げる。", "corrected_sentence": "権力を分けることで、組織は暴走を防げる。", "error_description": "「分ける」は「を」で目的語を取る。「権力に」は誤りで、正しくは「権力を」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d48e443-0dbf-4466-acec-a3edef6548fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37902, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「抑圧が続く」で、抑圧を主語として示す正しい助詞。"}, {"text": "を", "is_correct": false, "explanation": "「続く」は目的語を取らないので、「抑圧を続く」は成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "手段や場所を表す「で」は、「抑圧で続く」の形では主語を示せない。"}, {"text": "より", "is_correct": false, "explanation": "比較を表す「より」は、「抑圧より続く」では文の骨組みに合わない。"}], "correct_answer": "が", "explanations": {"が": "「抑圧が続く」で、抑圧を主語として示す正しい助詞。", "を": "「続く」は目的語を取らないので、「抑圧を続く」は成り立たない。", "で": "手段や場所を表す「で」は、「抑圧で続く」の形では主語を示せない。", "より": "比較を表す「より」は、「抑圧より続く」では文の骨組みに合わない。"}, "error_tags": {"を": "object_with_intransitive", "で": "means_or_location", "より": "comparison"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "解放", "is_correct": true, "explanation": "押さえつけの対義語で、「怒りを抑圧する」の反対に当たる語。"}, {"text": "協調", "is_correct": false, "explanation": "互いに歩み寄る意味で、押さえつける行為の対義語ではない。"}, {"text": "同意", "is_correct": false, "explanation": "相手の考えを認める意味で、抑圧と対になる語ではない。"}, {"text": "集中", "is_correct": false, "explanation": "一つのことに心を向ける意味で、この文の抑圧の対義語ではない。"}], "correct_answer": "解放", "explanations": {"解放": "押さえつけの対義語で、「怒りを抑圧する」の反対に当たる語。", "協調": "互いに歩み寄る意味で、押さえつける行為の対義語ではない。", "同意": "相手の考えを認める意味で、抑圧と対になる語ではない。", "集中": "一つのことに心を向ける意味で、この文の抑圧の対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cccbe2e-caf3-47c6-9a9a-d86ebe2bdee1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37902, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「抑圧が強かった」で、抑圧を主語として示す正しい助詞。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表す「へ」は、「抑圧へ強かった」では述語と結びつかない。"}, {"text": "と", "is_correct": false, "explanation": "並列や引用の「と」は、「抑圧と強かった」では文の形が成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "起点を表す「から」は、「抑圧から強かった」では強いという状態と結びつかない。"}], "correct_answer": "が", "explanations": {"が": "「抑圧が強かった」で、抑圧を主語として示す正しい助詞。", "へ": "方向を表す「へ」は、「抑圧へ強かった」では述語と結びつかない。", "と": "並列や引用の「と」は、「抑圧と強かった」では文の形が成り立たない。", "から": "起点を表す「から」は、「抑圧から強かった」では強いという状態と結びつかない。"}, "error_tags": {"へ": "direction", "と": "quotation_or_with", "から": "source"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "解放", "is_correct": true, "explanation": "抑圧の対義語で、「気持ちを抑圧する」の反対に当たる語。"}, {"text": "承認", "is_correct": false, "explanation": "正式に認める意味で、押さえつけの対義語ではない。"}, {"text": "安心", "is_correct": false, "explanation": "不安がない状態を指し、抑圧と対になる語ではない。"}, {"text": "交流", "is_correct": false, "explanation": "人と行き来する意味で、この文の抑圧の対義語ではない。"}], "correct_answer": "解放", "explanations": {"解放": "抑圧の対義語で、「気持ちを抑圧する」の反対に当たる語。", "承認": "正式に認める意味で、押さえつけの対義語ではない。", "安心": "不安がない状態を指し、抑圧と対になる語ではない。", "交流": "人と行き来する意味で、この文の抑圧の対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cccbe2e-caf3-47c6-9a9a-d86ebe2bdee1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37902, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "人の気持ちや行動を、力で無理に押さえつけること。", "primary_collocate": null, "pronunciation": "よくあつ", "ipa": "jokɯatsɯ", "syllable_count": 4, "sentences": [{"text": "長い間の抑圧から解放され、彼女はやっと自由に笑えるようになった。", "target_word": "抑圧", "complexity_tier": "T3", "furigana": "長[なが]い間[あいだ]の抑圧[よくあつ]から解放[かいほう]され、彼女[かのじょ]はやっと自由[じゆう]に笑[わら]えるようになった。", "sentence_source": "generated"}, {"text": "感情の抑圧が続くと、心の病気になることがある。", "target_word": "抑圧", "complexity_tier": "T3", "furigana": "感情[かんじょう]の抑圧[よくあつ]が続[つづ]くと、心[こころ]の病気[びょうき]になることがある。", "sentence_source": "generated"}, {"text": "厳しい校則による抑圧に、生徒たちは強く反発した。", "target_word": "抑圧", "complexity_tier": "T3", "furigana": "厳[きび]しい校則[こうそく]による抑圧[よくあつ]に、生徒[せいと]たちは強[つよ]く反発[はんぱつ]した。", "sentence_source": "generated"}, {"text": "彼は怒りを抑圧しすぎて、ある日突然爆発してしまった。", "target_word": "抑圧", "complexity_tier": "T3", "furigana": "彼[かれ]は怒[いか]りを抑圧[よくあつ]しすぎて、ある日[ひ]突然[とつぜん]爆発[ばくはつ]してしまった。", "sentence_source": "generated"}, {"text": "子どもの好奇心を抑圧するような教育は避けるべきだ。", "target_word": "抑圧", "complexity_tier": "T3", "furigana": "子[こ]どもの好奇心[こうきしん]を抑圧[よくあつ]するような教育[きょういく]は避[さ]けるべきだ。", "sentence_source": "generated"}, {"text": "独裁政権の抑圧の下で、人々は本音を口にできなかった。", "target_word": "抑圧", "complexity_tier": "T3", "furigana": "独裁[どくさい]政権[せいけん]の抑圧[よくあつ]の下[もと]で、人々[ひとびと]は本音[ほんね]を口[くち]にできなかった。", "sentence_source": "generated"}, {"text": "抑圧された気持ちを日記に書くと、少し楽になる。", "target_word": "抑圧", "complexity_tier": "T3", "furigana": "抑圧[よくあつ]された気持[きも]ちを日記[にっき]に書[か]くと、少[すこ]し楽[らく]になる。", "sentence_source": "generated"}, {"text": "親の抑圧が強かったので、彼は自分の意見を言えない大人になった。", "target_word": "抑圧", "complexity_tier": "T3", "furigana": "親[おや]の抑圧[よくあつ]が強[つよ]かったので、彼[かれ]は自分[じぶん]の意見[いけん]を言[い]えない大人[おとな]になった。", "sentence_source": "generated"}, {"text": "欲望の抑圧は、時にかえって行動を激しくする。", "target_word": "抑圧", "complexity_tier": "T3", "furigana": "欲望[よくぼう]の抑圧[よくあつ]は、時[とき]にかえって行動[こうどう]を激[はげ]しくする。", "sentence_source": "generated"}, {"text": "いつも我慢ばかりで、気持ちを抑圧する癖がついてしまった。", "target_word": "抑圧", "complexity_tier": "T3", "furigana": "いつも我慢[がまん]ばかりで、気持[きも]ちを抑圧[よくあつ]する癖[くせ]がついてしまった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "抑圧する", "label": "辞書形"}, {"form": "抑圧した", "label": "過去形"}, {"form": "抑圧される", "label": "受身形"}, {"form": "抑圧して", "label": "て形"}], "register": "書き言葉・やや硬い", "sense_fingerprint": "気持ちや行動を力で無理に押さえ込むこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2fddf5a-a756-46b3-bbac-8b346c4f6624') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37902, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "抑圧", "is_correct": true, "explanation": "力で押さえつける意味で、「長い間の抑圧から解放され」の空欄に入る語。"}, {"text": "信頼", "is_correct": false, "explanation": "相手を頼りにする気持ちを指し、「長い間の信頼から解放され」は意味が通らない。"}, {"text": "繁栄", "is_correct": false, "explanation": "栄えることを指し、「長い間の繁栄から解放され」は文として成り立たない。"}, {"text": "天候", "is_correct": false, "explanation": "天気の状態を指し、「長い間の天候から解放され」は意味が合わない。"}], "explanations": {"抑圧": "力で押さえつける意味で、「長い間の抑圧から解放され」の空欄に入る語。", "信頼": "相手を頼りにする気持ちを指し、「長い間の信頼から解放され」は意味が通らない。", "繁栄": "栄えることを指し、「長い間の繁栄から解放され」は文として成り立たない。", "天候": "天気の状態を指し、「長い間の天候から解放され」は意味が合わない。"}, "sentence_index": 0, "correct_answer": "抑圧"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "物価の上昇が続いたので、中央銀行は金利を上げて、物価を抑圧した。", "explanation": "ここは〈抑制〉の意味。抑圧は人の気持ちや行動を力で押さえる語で、物価のような数値には使わない。"}, {"text": "このファイルは抑圧して、容量を半分にした。", "explanation": "ここは〈圧縮〉の意味。抑圧は人の感情や行動を押さえる語で、データの容量を減らすときは圧縮を使う。"}, {"text": "走ったあと咳が止まらなかったので、咳を抑圧する薬を飲んだ。", "explanation": "ここは〈抑える〉の意味。咳は体の反応で、人の気持ちや行動ではないので抑圧は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cccbe2e-caf3-47c6-9a9a-d86ebe2bdee1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37902, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "抑圧", "is_correct": true, "explanation": "気持ちを押さえつける意味で、「抑圧された気持ち」に合う語。"}, {"text": "会議", "is_correct": false, "explanation": "話し合いの場を指し、「会議された気持ち」は意味が通らない。"}, {"text": "倹約", "is_correct": false, "explanation": "お金や物を節約する意味で、「倹約された気持ち」は不自然。"}, {"text": "旋律", "is_correct": false, "explanation": "音楽の調べを指し、「旋律された気持ち」は文として成り立たない。"}], "explanations": {"抑圧": "気持ちを押さえつける意味で、「抑圧された気持ち」に合う語。", "会議": "話し合いの場を指し、「会議された気持ち」は意味が通らない。", "倹約": "お金や物を節約する意味で、「倹約された気持ち」は不自然。", "旋律": "音楽の調べを指し、「旋律された気持ち」は文として成り立たない。"}, "sentence_index": 6, "correct_answer": "抑圧"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "ロボットの動きを抑圧して、安全な速度で動かした。", "explanation": "ここは〈制御〉の意味。抑圧は人の気持ちや行動を力で押さえる語で、機械の動きには使わない。"}, {"text": "消防隊が、火の広がりを抑圧して食い止めた。", "explanation": "ここは〈食い止める〉の意味。抑圧は人や人の気持ちを対象にする語で、火の広がりには使わない。"}, {"text": "工場からの排気ガスを抑圧する新しい法律ができた。", "explanation": "ここは〈規制〉の意味。抑圧は人の自由や意見を力で押さえる語で、排出の量には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cccbe2e-caf3-47c6-9a9a-d86ebe2bdee1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37902, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "家族からの抑圧を、彼は長い間苦しんできた。", "corrected_sentence": "家族からの抑圧に、彼は長い間苦しんできた。", "error_description": "「苦しむ」は「〜に苦しむ」の形をとる。抑圧に続く助詞は「に」が正しく、「を」にすると誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cccbe2e-caf3-47c6-9a9a-d86ebe2bdee1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37902, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "長年の抑圧に解放されて、彼は自由に生きられるようになった。", "corrected_sentence": "長年の抑圧から解放されて、彼は自由に生きられるようになった。", "error_description": "「解放される」は「〜から解放される」の形をとる。抑圧に続く助詞は「から」が正しく、「に」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cccbe2e-caf3-47c6-9a9a-d86ebe2bdee1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37903, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「抑圧に」で、対象を示す正しい助詞として「非難の声」の前に続く形に合う。"}, {"text": "を", "is_correct": false, "explanation": "「抑圧を上がった」では、「上がる」は目的語を取らないので成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表す「へ」は、「抑圧へ非難の声が上がった」では意味がつながらない。"}, {"text": "の", "is_correct": false, "explanation": "所有や修飾の「の」は、「抑圧の、非難の声が上がった」では文が宙に浮き、成り立たない。"}], "correct_answer": "に", "explanations": {"に": "「抑圧に」で、対象を示す正しい助詞として「非難の声」の前に続く形に合う。", "を": "「抑圧を上がった」では、「上がる」は目的語を取らないので成り立たない。", "へ": "方向を表す「へ」は、「抑圧へ非難の声が上がった」では意味がつながらない。", "の": "所有や修飾の「の」は、「抑圧の、非難の声が上がった」では文が宙に浮き、成り立たない。"}, "error_tags": {"を": "object_with_intransitive", "へ": "direction", "の": "possessive"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "解放", "is_correct": true, "explanation": "抑圧の対義語で、自由を押さえつける状態の反対を表す語。"}, {"text": "協議", "is_correct": false, "explanation": "話し合って決める意味で、押さえつけの対義語ではない。"}, {"text": "同意", "is_correct": false, "explanation": "相手の考えを認める意味で、抑圧と対になる語ではない。"}, {"text": "集中", "is_correct": false, "explanation": "一つのことに心を向ける意味で、抑圧の対義語ではない。"}], "correct_answer": "解放", "explanations": {"解放": "抑圧の対義語で、自由を押さえつける状態の反対を表す語。", "協議": "話し合って決める意味で、押さえつけの対義語ではない。", "同意": "相手の考えを認める意味で、抑圧と対になる語ではない。", "集中": "一つのことに心を向ける意味で、抑圧の対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cccbe2e-caf3-47c6-9a9a-d86ebe2bdee1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37903, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「抑圧に屈せず」で、屈する対象を示す正しい助詞。"}, {"text": "から", "is_correct": false, "explanation": "起点を表す「から」は、「抑圧から屈せず」では屈する対象の形に合わない。"}, {"text": "と", "is_correct": false, "explanation": "並列や引用の「と」は、「抑圧と屈せず」では文の形が成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "所有や修飾の「の」は、「抑圧の屈せず」では動詞「屈する」と結びつかない。"}], "correct_answer": "に", "explanations": {"に": "「抑圧に屈せず」で、屈する対象を示す正しい助詞。", "から": "起点を表す「から」は、「抑圧から屈せず」では屈する対象の形に合わない。", "と": "並列や引用の「と」は、「抑圧と屈せず」では文の形が成り立たない。", "の": "所有や修飾の「の」は、「抑圧の屈せず」では動詞「屈する」と結びつかない。"}, "error_tags": {"から": "source", "と": "quotation_or_with", "の": "possessive"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "解放", "is_correct": true, "explanation": "抑圧の対義語で、報道の自由を押さえつける状態の反対を表す語。"}, {"text": "承認", "is_correct": false, "explanation": "正式に認める意味で、押さえつけの対義語ではない。"}, {"text": "安心", "is_correct": false, "explanation": "不安がない状態を指し、抑圧と対になる語ではない。"}, {"text": "交流", "is_correct": false, "explanation": "人と行き来する意味で、抑圧の対義語ではない。"}], "correct_answer": "解放", "explanations": {"解放": "抑圧の対義語で、報道の自由を押さえつける状態の反対を表す語。", "承認": "正式に認める意味で、押さえつけの対義語ではない。", "安心": "不安がない状態を指し、抑圧と対になる語ではない。", "交流": "人と行き来する意味で、抑圧の対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cccbe2e-caf3-47c6-9a9a-d86ebe2bdee1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37903, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "相手の自由や意見を、強い力で押さえつけて妨げること。", "primary_collocate": null, "pronunciation": "よくあつ", "ipa": "jokɯatsɯ", "syllable_count": 4, "sentences": [{"text": "政府は言論の抑圧を強め、新聞社に圧力をかけた。", "target_word": "抑圧", "complexity_tier": "T3", "furigana": "政府[せいふ]は言論[げんろん]の抑圧[よくあつ]を強[つよ]め、新聞社[しんぶんしゃ]に圧力[あつりょく]をかけた。", "sentence_source": "generated"}, {"text": "少数民族への抑圧に、国際社会から非難の声が上がった。", "target_word": "抑圧", "complexity_tier": "T3", "furigana": "少数[しょうすう]民族[みんぞく]への抑圧[よくあつ]に、国際[こくさい]社会[しゃかい]から非難[ひなん]の声[こえ]が上[あ]がった。", "sentence_source": "generated"}, {"text": "警察による集会の抑圧は、市民の怒りを招いた。", "target_word": "抑圧", "complexity_tier": "T3", "furigana": "警察[けいさつ]による集会[しゅうかい]の抑圧[よくあつ]は、市民[しみん]の怒[いか]りを招[まね]いた。", "sentence_source": "generated"}, {"text": "権力者は反対意見を抑圧して、自分の地位を守ろうとした。", "target_word": "抑圧", "complexity_tier": "T3", "furigana": "権力者[けんりょくしゃ]は反対[はんたい]意見[いけん]を抑圧[よくあつ]して、自分[じぶん]の地位[ちい]を守[まも]ろうとした。", "sentence_source": "generated"}, {"text": "自由を求める人々は、長年の抑圧に立ち向かった。", "target_word": "抑圧", "complexity_tier": "T3", "furigana": "自由[じゆう]を求[もと]める人々[ひとびと]は、長年[ながねん]の抑圧[よくあつ]に立[た]ち向[む]かった。", "sentence_source": "generated"}, {"text": "女性への抑圧をなくすために、法律が改正された。", "target_word": "抑圧", "complexity_tier": "T3", "furigana": "女性[じょせい]への抑圧[よくあつ]をなくすために、法律[ほうりつ]が改正[かいせい]された。", "sentence_source": "generated"}, {"text": "上司が部下の発言を抑圧すれば、会社は成長しない。", "target_word": "抑圧", "complexity_tier": "T3", "furigana": "上司[じょうし]が部下[ぶか]の発言[はつげん]を抑圧[よくあつ]すれば、会社[かいしゃ]は成長[せいちょう]しない。", "sentence_source": "generated"}, {"text": "抑圧に屈せず、彼女は真実を語り続けた。", "target_word": "抑圧", "complexity_tier": "T3", "furigana": "抑圧[よくあつ]に屈[くっ]せず、彼女[かのじょ]は真実[しんじつ]を語[かた]り続[つづ]けた。", "sentence_source": "generated"}, {"text": "暴力による抑圧では、人の心までは変えられない。", "target_word": "抑圧", "complexity_tier": "T3", "furigana": "暴力[ぼうりょく]による抑圧[よくあつ]では、人[ひと]の心[こころ]までは変[か]えられない。", "sentence_source": "generated"}, {"text": "その国では報道の自由が抑圧され、記者が自由に取材できない。", "target_word": "抑圧", "complexity_tier": "T3", "furigana": "その国[くに]では報道[ほうどう]の自由[じゆう]が抑圧[よくあつ]され、記者[きしゃ]が自由[じゆう]に取材[しゅざい]できない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "抑圧する", "label": "辞書形"}, {"form": "抑圧した", "label": "過去形"}, {"form": "抑圧される", "label": "受身形"}, {"form": "抑圧して", "label": "て形"}], "register": "書き言葉・やや硬い", "sense_fingerprint": "他者の自由や意見を権力や強い力で封じること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2fddf5a-a756-46b3-bbac-8b346c4f6624') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37903, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "抑圧", "is_correct": true, "explanation": "相手の自由や意見を強い力で妨げる意味で、「言論の抑圧を強め」に合う語。"}, {"text": "栽培", "is_correct": false, "explanation": "植物を育てる意味で、「言論の栽培を強め」は成り立たない。"}, {"text": "天候", "is_correct": false, "explanation": "天気の状態を指し、「言論の天候」は意味が合わない。"}, {"text": "会計", "is_correct": false, "explanation": "お金の計算や管理を指し、「言論の会計」は文として不自然。"}], "explanations": {"抑圧": "相手の自由や意見を強い力で妨げる意味で、「言論の抑圧を強め」に合う語。", "栽培": "植物を育てる意味で、「言論の栽培を強め」は成り立たない。", "天候": "天気の状態を指し、「言論の天候」は意味が合わない。", "会計": "お金の計算や管理を指し、「言論の会計」は文として不自然。"}, "sentence_index": 0, "correct_answer": "抑圧"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "暴走する車を抑圧して、ようやく止めることができた。", "explanation": "ここは〈制止〉の意味。抑圧は人の自由や意見を押さえる語で、車の動きを止める場合は制止を使う。"}, {"text": "痛みを抑圧する薬を飲んで、仕事を続けた。", "explanation": "ここは〈抑える〉の意味。痛みは体の感覚で、人の気持ちや行動ではないので抑圧は合わない。"}, {"text": "経費を抑圧して、今年の利益を大きく増やした。", "explanation": "ここは〈削減〉の意味。抑圧は人の自由や意見に使う語で、お金の支出を減らす場合は削減を使う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cccbe2e-caf3-47c6-9a9a-d86ebe2bdee1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37903, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "抑圧", "is_correct": true, "explanation": "部下の発言を力で押さえる意味で、「発言を抑圧すれば」に合う語。"}, {"text": "登山", "is_correct": false, "explanation": "山に登る活動を指し、「発言を登山すれば」は成り立たない。"}, {"text": "栄養", "is_correct": false, "explanation": "体に必要な成分を指し、「発言を栄養すれば」は意味が合わない。"}, {"text": "旋律", "is_correct": false, "explanation": "音楽の調べを指し、「発言を旋律すれば」は文として成り立たない。"}], "explanations": {"抑圧": "部下の発言を力で押さえる意味で、「発言を抑圧すれば」に合う語。", "登山": "山に登る活動を指し、「発言を登山すれば」は成り立たない。", "栄養": "体に必要な成分を指し、「発言を栄養すれば」は意味が合わない。", "旋律": "音楽の調べを指し、「発言を旋律すれば」は文として成り立たない。"}, "sentence_index": 6, "correct_answer": "抑圧"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "熱を抑圧する薬を飲んで、ようやく休めた。", "explanation": "ここは〈解熱〉の意味。抑圧は人の気持ちや行動を押さえる語で、体温には使わない。"}, {"text": "火の勢いを抑圧して、消防士が鎮火させた。", "explanation": "ここは〈鎮火〉の意味。抑圧は人や意見を対象にする語で、火を消す場合は鎮火を使う。"}, {"text": "工場の排気ガスを抑圧する新しい規則ができた。", "explanation": "ここは〈規制〉の意味。抑圧は人の自由や意見を力で押さえる語で、排出物には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cccbe2e-caf3-47c6-9a9a-d86ebe2bdee1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37903, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "政府の抑圧に逃れるため、彼らは国を出た。", "corrected_sentence": "政府の抑圧から逃れるため、彼らは国を出た。", "error_description": "「逃れる」は「〜から逃れる」の形をとる。抑圧に続く助詞は「から」が正しく、「に」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cccbe2e-caf3-47c6-9a9a-d86ebe2bdee1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37903, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "暴力による抑圧を、彼らは最後まで屈しなかった。", "corrected_sentence": "暴力による抑圧に、彼らは最後まで屈しなかった。", "error_description": "「屈する」は「〜に屈する」の形をとる。抑圧に続く助詞は「に」が正しく、「を」にすると誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cccbe2e-caf3-47c6-9a9a-d86ebe2bdee1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37904, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「危機を知らせる」と目的語を示す「を」が入る。"}, {"text": "に", "is_correct": false, "explanation": "「危機に知らせました」は文として成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「危機へ知らせました」は文として成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "「危機の知らせました」は文として成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「危機を知らせる」と目的語を示す「を」が入る。", "に": "「危機に知らせました」は文として成り立たない。", "へ": "「危機へ知らせました」は文として成り立たない。", "の": "「危機の知らせました」は文として成り立たない。"}, "error_tags": {"に": "wrong_case", "へ": "direction", "の": "possessive"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "平穏", "is_correct": true, "explanation": "危ないことがなく穏やかな状態で、危機の反対の語。"}, {"text": "緊急", "is_correct": false, "explanation": "急を要する状況で、危機に近い語。"}, {"text": "危険", "is_correct": false, "explanation": "あぶない状態で、危機の類義語にあたる。"}, {"text": "瀬戸際", "is_correct": false, "explanation": "成否の分かれ目で、危機に近い語。"}], "correct_answer": "平穏", "explanations": {"平穏": "危ないことがなく穏やかな状態で、危機の反対の語。", "緊急": "急を要する状況で、危機に近い語。", "危険": "あぶない状態で、危機の類義語にあたる。", "瀬戸際": "成否の分かれ目で、危機に近い語。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '405ab2ea-93b5-4924-95c2-1986b4082a3c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37904, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「危機が迫る」と主語を示す「が」が入る。"}, {"text": "を", "is_correct": false, "explanation": "「危機を迫っている」は自動詞「迫る」と合わず成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「危機へ迫っている」は文として成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「危機と迫っている」は文として成り立たない。"}], "correct_answer": "が", "explanations": {"が": "「危機が迫る」と主語を示す「が」が入る。", "を": "「危機を迫っている」は自動詞「迫る」と合わず成り立たない。", "へ": "「危機へ迫っている」は文として成り立たない。", "と": "「危機と迫っている」は文として成り立たない。"}, "error_tags": {"を": "object_marker", "へ": "direction", "と": "quotation"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "無事", "is_correct": true, "explanation": "何事もなく安全な状態で、危機の反対の語。"}, {"text": "窮地", "is_correct": false, "explanation": "追い詰められた状況で、危機の類義語にあたる。"}, {"text": "災難", "is_correct": false, "explanation": "思いがけない不幸で、危機に近い語。"}, {"text": "難局", "is_correct": false, "explanation": "困難な状況で、危機の類義語にあたる。"}], "correct_answer": "無事", "explanations": {"無事": "何事もなく安全な状態で、危機の反対の語。", "窮地": "追い詰められた状況で、危機の類義語にあたる。", "災難": "思いがけない不幸で、危機に近い語。", "難局": "困難な状況で、危機の類義語にあたる。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '405ab2ea-93b5-4924-95c2-1986b4082a3c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37904, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "とても危ないことや、大変なことが起こりそうなときのこと。", "primary_collocate": null, "pronunciation": "きき", "ipa": "kiki", "syllable_count": 2, "sentences": [{"text": "大変だ、危機だ！", "target_word": "危機", "complexity_tier": "T1", "furigana": "大変[たいへん]だ、危機[きき]だ！", "sentence_source": "generated"}, {"text": "犬が危機を知らせました。", "target_word": "危機", "complexity_tier": "T2", "furigana": "犬[いぬ]が危機[きき]を知[し]らせました。", "sentence_source": "generated"}, {"text": "山で危機に直面しました。", "target_word": "危機", "complexity_tier": "T2", "furigana": "山[やま]で危機[きき]に直面[ちょくめん]しました。", "sentence_source": "generated"}, {"text": "危機が近づいたとき、鳥は一斉に飛んだ。", "target_word": "危機", "complexity_tier": "T3", "furigana": "危機[きき]が近[ちか]づいたとき、鳥[とり]は一斉[いっせい]に飛[と]んだ。", "sentence_source": "generated"}, {"text": "命の危機を感じて、すぐに逃げた。", "target_word": "危機", "complexity_tier": "T3", "furigana": "命[いのち]の危機[きき]を感[かん]じて、すぐに逃[に]げた。", "sentence_source": "generated"}, {"text": "地震の危機に備えて、水を買っておく。", "target_word": "危機", "complexity_tier": "T3", "furigana": "地震[じしん]の危機[きき]に備[そな]えて、水[みず]を買[か]っておく。", "sentence_source": "generated"}, {"text": "危機の中でも、彼は落ち着いていた。", "target_word": "危機", "complexity_tier": "T3", "furigana": "危機[きき]の中[なか]でも、彼[かれ]は落[お]ち着[つ]いていた。", "sentence_source": "generated"}, {"text": "危機が迫っていることに、誰も気づかなかった。", "target_word": "危機", "complexity_tier": "T4", "furigana": "危機[きき]が迫[せま]っていることに、誰[だれ]も気[き]づかなかった。", "sentence_source": "generated"}, {"text": "危機のときこそ、冷静に行動しなければならない。", "target_word": "危機", "complexity_tier": "T4", "furigana": "危機[きき]のときこそ、冷静[れいせい]に行動[こうどう]しなければならない。", "sentence_source": "generated"}, {"text": "助けが来なければ、私たちは危機から抜け出せなかっただろう。", "target_word": "危機", "complexity_tier": "T4", "furigana": "助[たす]けが来[こ]なければ、私[わたし]たちは危機[きき]から抜[ぬ]け出[だ]せなかっただろう。", "sentence_source": "generated"}], "morphological_forms": [{"form": "危機的", "label": "派生"}, {"form": "危機感", "label": "派生"}, {"form": "危機管理", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | とても危ない、大変な状態", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35403af3-e307-4569-9687-90b6f2030bed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37904, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "危機", "is_correct": true, "explanation": "正解の語「きき」。"}, {"text": "菊", "is_correct": false, "explanation": "「きく」で、末尾の一音が違う。"}, {"text": "霧", "is_correct": false, "explanation": "「きり」で、末尾の一音が違う。"}, {"text": "北", "is_correct": false, "explanation": "「きた」で、末尾の一音が違う。"}, {"text": "息", "is_correct": false, "explanation": "「いき」で、先頭の一音が違う。"}, {"text": "式", "is_correct": false, "explanation": "「しき」で、先頭の一音が違う。"}], "explanations": {"危機": "正解の語「きき」。", "菊": "「きく」で、末尾の一音が違う。", "霧": "「きり」で、末尾の一音が違う。", "北": "「きた」で、末尾の一音が違う。", "息": "「いき」で、先頭の一音が違う。", "式": "「しき」で、先頭の一音が違う。"}, "sentence_index": null, "correct_answer": "危機"}, "level_3": {"options": [{"text": "危機", "is_correct": true, "explanation": "「大変だ」と叫ぶ、とても危ない状況という意味に合う。"}, {"text": "平和", "is_correct": false, "explanation": "形は合うが、「大変だ」と叫ぶ場面に「平和」は意味が合わない。"}, {"text": "安心", "is_correct": false, "explanation": "形は合うが、「大変だ」と叫ぶ場面に「安心」は意味が合わない。"}, {"text": "無事", "is_correct": false, "explanation": "形は合うが、「大変だ」と叫ぶ場面に「無事」は意味が合わない。"}], "explanations": {"危機": "「大変だ」と叫ぶ、とても危ない状況という意味に合う。", "平和": "形は合うが、「大変だ」と叫ぶ場面に「平和」は意味が合わない。", "安心": "形は合うが、「大変だ」と叫ぶ場面に「安心」は意味が合わない。", "無事": "形は合うが、「大変だ」と叫ぶ場面に「無事」は意味が合わない。"}, "sentence_index": 0, "correct_answer": "危機"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "危機を洗って、タオルでふいた。", "explanation": "危機は洗える物ではなく、物のように扱う使い方が誤り。"}, {"text": "危機は安全でうれしいことなので、みんな笑った。", "explanation": "危機は危ない状況で、安全でうれしいという意味は逆。"}, {"text": "危機にご飯を入れて持っていった。", "explanation": "危機は入れ物ではなく、物を入れる場所として使うのは誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '405ab2ea-93b5-4924-95c2-1986b4082a3c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37904, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "危機", "is_correct": true, "explanation": "正解の語「きき」。"}, {"text": "岸", "is_correct": false, "explanation": "「きし」で、末尾の一音が違う。"}, {"text": "金", "is_correct": false, "explanation": "「きん」で、末尾の一音が違う。"}, {"text": "幹", "is_correct": false, "explanation": "「みき」で、先頭の一音が違う。"}, {"text": "君", "is_correct": false, "explanation": "「きみ」で、末尾の一音が違う。"}, {"text": "記事", "is_correct": false, "explanation": "「きじ」で、末尾の一音が濁音になる。"}], "explanations": {"危機": "正解の語「きき」。", "岸": "「きし」で、末尾の一音が違う。", "金": "「きん」で、末尾の一音が違う。", "幹": "「みき」で、先頭の一音が違う。", "君": "「きみ」で、末尾の一音が違う。", "記事": "「きじ」で、末尾の一音が濁音になる。"}, "sentence_index": null, "correct_answer": "危機"}, "level_3": {"options": [{"text": "危機", "is_correct": true, "explanation": "その中でも落ち着いていた、危ない状況という意味に合う。"}, {"text": "辞書", "is_correct": false, "explanation": "形は合うが、辞書の中で落ち着くという意味が合わない。"}, {"text": "財布", "is_correct": false, "explanation": "形は合うが、財布の中で落ち着くという意味が合わない。"}, {"text": "鉛筆", "is_correct": false, "explanation": "形は合うが、鉛筆の中で落ち着くという意味が合わない。"}], "explanations": {"危機": "その中でも落ち着いていた、危ない状況という意味に合う。", "辞書": "形は合うが、辞書の中で落ち着くという意味が合わない。", "財布": "形は合うが、財布の中で落ち着くという意味が合わない。", "鉛筆": "形は合うが、鉛筆の中で落ち着くという意味が合わない。"}, "sentence_index": 6, "correct_answer": "危機"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "危機を飲んだので、のどがかわいた。", "explanation": "危機は飲める物ではなく、飲む対象としての使い方が誤り。"}, {"text": "危機は先生の名前で、教室に来た。", "explanation": "危機は状況を表す語で、人の名前や人物のように使うのは誤り。"}, {"text": "危機はとても静かで、花のにおいがした。", "explanation": "危機を花のにおいがする物のように描くのは意味が合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '405ab2ea-93b5-4924-95c2-1986b4082a3c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_val