INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37905, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事がうまくいかなくなるかもしれない、危険な状態や状況。", "primary_collocate": null, "pronunciation": "きき", "ipa": "kiki", "syllable_count": 2, "sentences": [{"text": "気候変動という地球的危機の緩和に向け、産業セクターにおける排出量の抑制は、持続可能性を担保する上で不可避の責務である。", "target_word": "危機", "complexity_tier": "T6", "furigana": "気候[きこう]変動[へんどう]という地球的[ちきゅうてき]危機[きき]の緩和[かんわ]に向[む]け、産業[さんぎょう]セクターにおける排出量[はいしゅつりょう]の抑制[よくせい]は、持続[じぞく]可能性[かのうせい]を担保[たんぽ]する上[うえ]で不可避[ふかひ]の責務[せきむ]である。", "sentence_source": "mined"}, {"text": "危機が来た。", "target_word": "危機", "complexity_tier": "T1", "furigana": "危機[きき]が来[き]た。", "sentence_source": "generated"}, {"text": "会社は今、危機です。", "target_word": "危機", "complexity_tier": "T2", "furigana": "会社[かいしゃ]は今[いま]、危機[きき]です。", "sentence_source": "generated"}, {"text": "危機を乗り越えました。", "target_word": "危機", "complexity_tier": "T2", "furigana": "危機[きき]を乗[の]り越[こ]えました。", "sentence_source": "generated"}, {"text": "水不足の危機が、町に近づいている。", "target_word": "危機", "complexity_tier": "T3", "furigana": "水不足[みずぶそく]の危機[きき]が、町[まち]に近[ちか]づいている。", "sentence_source": "generated"}, {"text": "世界は食料の危機に向き合っている。", "target_word": "危機", "complexity_tier": "T3", "furigana": "世界[せかい]は食料[しょくりょう]の危機[きき]に向き合[むきあ]っている。", "sentence_source": "generated"}, {"text": "危機が過ぎると、みんな安心した。", "target_word": "危機", "complexity_tier": "T3", "furigana": "危機[きき]が過[す]ぎると、みんな安心[あんしん]した。", "sentence_source": "generated"}, {"text": "危機を防ぐために、早めに対策を立てるべきだ。", "target_word": "危機", "complexity_tier": "T4", "furigana": "危機[きき]を防[ふせ]ぐために、早[はや]めに対策[たいさく]を立[た]てるべきだ。", "sentence_source": "generated"}, {"text": "彼の判断がなければ、会社は危機に陥っていただろう。", "target_word": "危機", "complexity_tier": "T4", "furigana": "彼[かれ]の判断[はんだん]がなければ、会社[かいしゃ]は危機[きき]に陥[おちい]っていただろう。", "sentence_source": "generated"}, {"text": "資金不足という危機を前にして、経営者は大きな決断を迫られた。", "target_word": "危機", "complexity_tier": "T5", "furigana": "資金[しきん]不足[ぶそく]という危機[きき]を前[まえ]にして、経営者[けいえいしゃ]は大[おお]きな決断[けつだん]を迫[せま]られた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "危機的", "label": "派生"}, {"form": "危機感", "label": "派生"}, {"form": "危機管理", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 失敗や破局に至りかねない危うい状況", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35403af3-e307-4569-9687-90b6f2030bed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37905, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "危機", "is_correct": true, "explanation": "正解の語「きき」。"}, {"text": "菊", "is_correct": false, "explanation": "「きく」で、末尾の一音が違う。"}, {"text": "霧", "is_correct": false, "explanation": "「きり」で、末尾の一音が違う。"}, {"text": "北", "is_correct": false, "explanation": "「きた」で、末尾の一音が違う。"}, {"text": "息", "is_correct": false, "explanation": "「いき」で、先頭の一音が違う。"}, {"text": "式", "is_correct": false, "explanation": "「しき」で、先頭の一音が違う。"}], "explanations": {"危機": "正解の語「きき」。", "菊": "「きく」で、末尾の一音が違う。", "霧": "「きり」で、末尾の一音が違う。", "北": "「きた」で、末尾の一音が違う。", "息": "「いき」で、先頭の一音が違う。", "式": "「しき」で、先頭の一音が違う。"}, "sentence_index": null, "correct_answer": "危機"}, "level_3": {"options": [{"text": "危機", "is_correct": true, "explanation": "気候変動を地球規模の悪い状況ととらえる意味に合う。"}, {"text": "祝日", "is_correct": false, "explanation": "形は合うが、気候変動を祝日と呼ぶ意味が合わない。"}, {"text": "景色", "is_correct": false, "explanation": "形は合うが、緩和する対象が景色という意味が合わない。"}, {"text": "贈り物", "is_correct": false, "explanation": "形は合うが、緩和する対象が贈り物という意味が合わない。"}], "explanations": {"危機": "気候変動を地球規模の悪い状況ととらえる意味に合う。", "祝日": "形は合うが、気候変動を祝日と呼ぶ意味が合わない。", "景色": "形は合うが、緩和する対象が景色という意味が合わない。", "贈り物": "形は合うが、緩和する対象が贈り物という意味が合わない。"}, "sentence_index": 0, "correct_answer": "危機"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "危機を食べて、おなかがいっぱいになりました。", "explanation": "危機は食べ物ではなく、食べる対象としての使い方が誤り。"}, {"text": "危機は楽しい旅行で、毎日ワクワクした。", "explanation": "危機は危うい状況で、楽しい旅行という意味は誤り。"}, {"text": "明日の危機に、友達と映画を見に行きます。", "explanation": "危機を時間や日にちのように使っており、意味が誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '405ab2ea-93b5-4924-95c2-1986b4082a3c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37905, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "危機", "is_correct": true, "explanation": "正解の語「きき」。"}, {"text": "岸", "is_correct": false, "explanation": "「きし」で、末尾の一音が違う。"}, {"text": "金", "is_correct": false, "explanation": "「きん」で、末尾の一音が違う。"}, {"text": "幹", "is_correct": false, "explanation": "「みき」で、先頭の一音が違う。"}, {"text": "君", "is_correct": false, "explanation": "「きみ」で、末尾の一音が違う。"}, {"text": "記事", "is_correct": false, "explanation": "「きじ」で、末尾の一音が濁音になる。"}], "explanations": {"危機": "正解の語「きき」。", "岸": "「きし」で、末尾の一音が違う。", "金": "「きん」で、末尾の一音が違う。", "幹": "「みき」で、先頭の一音が違う。", "君": "「きみ」で、末尾の一音が違う。", "記事": "「きじ」で、末尾の一音が濁音になる。"}, "sentence_index": null, "correct_answer": "危機"}, "level_3": {"options": [{"text": "危機", "is_correct": true, "explanation": "過ぎると安心できる危うい状況という意味に合う。"}, {"text": "辞書", "is_correct": false, "explanation": "形は合うが、辞書が過ぎて安心するという意味が合わない。"}, {"text": "机", "is_correct": false, "explanation": "形は合うが、机が過ぎて安心するという意味が合わない。"}, {"text": "靴", "is_correct": false, "explanation": "形は合うが、靴が過ぎて安心するという意味が合わない。"}], "explanations": {"危機": "過ぎると安心できる危うい状況という意味に合う。", "辞書": "形は合うが、辞書が過ぎて安心するという意味が合わない。", "机": "形は合うが、机が過ぎて安心するという意味が合わない。", "靴": "形は合うが、靴が過ぎて安心するという意味が合わない。"}, "sentence_index": 6, "correct_answer": "危機"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "危機は小さな犬で、庭を走り回っている。", "explanation": "危機は状況を表す語で、動物のように使うのは誤り。"}, {"text": "危機のおかげで、今年は大きな利益が出て喜んだ。", "explanation": "危機は悪い状況なので、おかげで喜ぶという使い方は意味が合わない。"}, {"text": "危機を二つ買って、家に飾った。", "explanation": "危機は買って飾れる物ではなく、物のように数える使い方が誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '405ab2ea-93b5-4924-95c2-1986b4082a3c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37905, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "町は大きな危機を食べた。", "corrected_sentence": "町は大きな危機に直面した。", "error_description": "「危機を食べた」は意味が通らず、「危機に直面した」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '405ab2ea-93b5-4924-95c2-1986b4082a3c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37905, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "会社は危機を陥った。", "corrected_sentence": "会社は危機に陥った。", "error_description": "「陥る」は「危機に」と「に」を取るので、「危機を陥った」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '405ab2ea-93b5-4924-95c2-1986b4082a3c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
