INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37906, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "同じことを、ちがう言い方で言うこと。", "primary_collocate": null, "pronunciation": "いいかえる", "ipa": "iːkaeɾɯ", "syllable_count": 5, "sentences": [{"text": "難しい言葉を、やさしい言葉に言い替える。", "target_word": "言い替える", "complexity_tier": "T3", "furigana": "難[むずか]しい言葉[ことば]を、やさしい言葉[ことば]に言[い]い替[か]える。", "sentence_source": "generated"}, {"text": "先生は、同じ意味をもっと簡単に言い替えてくれた。", "target_word": "言い替えて", "complexity_tier": "T3", "furigana": "先生[せんせい]は、同[おな]じ意味[いみ]をもっと簡単[かんたん]に言[い]い替[か]えてくれた。", "sentence_source": "generated"}, {"text": "「死ぬ」を「亡くなる」と言い替えると、やわらかい印象になる。", "target_word": "言い替える", "complexity_tier": "T3", "furigana": "「死[し]ぬ」を「亡[な]くなる」と言[い]い替[か]えると、やわらかい印象[いんしょう]になる。", "sentence_source": "generated"}, {"text": "うまく伝わらなかったので、もっとやさしい言葉で言い替えた。", "target_word": "言い替えた", "complexity_tier": "T3", "furigana": "うまく伝[つた]わらなかったので、もっとやさしい言葉[ことば]で言[い]い替[か]えた。", "sentence_source": "generated"}, {"text": "子どもに説明するときは、専門用語を言い替えたほうがいい。", "target_word": "言い替えた", "complexity_tier": "T3", "furigana": "子[こ]どもに説明[せつめい]するときは、専門用語[せんもんようご]を言[い]い替[か]えたほうがいい。", "sentence_source": "generated"}, {"text": "同じ意味でも、言い替えれば印象が変わる。", "target_word": "言い替えれば", "complexity_tier": "T3", "furigana": "同[おな]じ意味[いみ]でも、言[い]い替[か]えれば印象[いんしょう]が変[か]わる。", "sentence_source": "generated"}, {"text": "作文で同じ言葉が続くので、言い替える言葉を探した。", "target_word": "言い替える", "complexity_tier": "T3", "furigana": "作文[さくぶん]で同[おな]じ言葉[ことば]が続[つづ]くので、言[い]い替[か]える言葉[ことば]を探[さが]した。", "sentence_source": "generated"}, {"text": "相手が怒らないように、きつい言葉を言い替えた。", "target_word": "言い替えた", "complexity_tier": "T3", "furigana": "相手[あいて]が怒[おこ]らないように、きつい言葉[ことば]を言[い]い替[か]えた。", "sentence_source": "generated"}, {"text": "意味がわからないと言われて、もっと短く言い替えた。", "target_word": "言い替えた", "complexity_tier": "T3", "furigana": "意味[いみ]がわからないと言[い]われて、もっと短[みじか]く言[い]い替[か]えた。", "sentence_source": "generated"}, {"text": "「ダメ」を「難しい」と言い替えると、角が立たない。", "target_word": "言い替える", "complexity_tier": "T3", "furigana": "「ダメ」を「難[むずか]しい」と言[い]い替[か]えると、角[かど]が立[た]たない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "言い替える", "label": "終止形"}, {"form": "言い替えた", "label": "過去形"}, {"form": "言い替えて", "label": "て形"}, {"form": "言い替えない", "label": "否定形"}, {"form": "言い替えれば", "label": "仮定形"}, {"form": "言い替えよう", "label": "意志形"}], "register": "標準", "sense_fingerprint": "同じ内容を別の言い方で言う", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a04de0b4-b7c5-4a40-b388-094939d08f82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37906, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "言い替える", "is_correct": true, "explanation": "同じ内容を別の言葉で言い直す意味で、「やさしい言葉に」と自然につながる。"}, {"text": "比べる", "is_correct": false, "explanation": "二つ以上を照らし合わせる意味で、言葉を言い直すことには使わない。"}, {"text": "暗記する", "is_correct": false, "explanation": "覚え込む意味で、言葉を別の言葉に置き換える文脈には合わない。"}, {"text": "聞き流す", "is_correct": false, "explanation": "聞いても気にしない意味で、言葉の言い換えを表せない。"}], "explanations": {"言い替える": "同じ内容を別の言葉で言い直す意味で、「やさしい言葉に」と自然につながる。", "比べる": "二つ以上を照らし合わせる意味で、言葉を言い直すことには使わない。", "暗記する": "覚え込む意味で、言葉を別の言葉に置き換える文脈には合わない。", "聞き流す": "聞いても気にしない意味で、言葉の言い換えを表せない。"}, "sentence_index": 0, "correct_answer": "言い替える"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "髪型を言い替えて、雰囲気が明るくなった。", "explanation": "ここは〈変える〉の意味。髪型は言葉ではないので、言葉を言い直す「言い替える」とは合わない。"}, {"text": "1万円札を千円札に言い替えた。", "explanation": "ここは〈両替える〉の意味。お金を別の紙幣にかえる話で、言葉を言い直す意味ではない。"}, {"text": "古いカーテンを新しいものに言い替えた。", "explanation": "ここは〈置き換える〉の意味。物を別の物に取り替える場面で、言葉の表現について言う「言い替える」とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25c1e5d6-c0e8-4304-9fb4-e18af266873f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37906, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "言い替える", "is_correct": true, "explanation": "連体形で「言葉」を修飾し、「言い替える言葉」として自然に続く。"}, {"text": "言い替えて", "is_correct": false, "explanation": "て形のため「言葉」を修飾できず、文が成り立たない。"}, {"text": "言い替えれば", "is_correct": false, "explanation": "仮定形のため名詞を修飾できず、文が成り立たない。"}, {"text": "言い替えよう", "is_correct": false, "explanation": "意志形のため名詞を修飾できず、文が成り立たない。"}], "explanations": {"言い替える": "連体形で「言葉」を修飾し、「言い替える言葉」として自然に続く。", "言い替えて": "て形のため「言葉」を修飾できず、文が成り立たない。", "言い替えれば": "仮定形のため名詞を修飾できず、文が成り立たない。", "言い替えよう": "意志形のため名詞を修飾できず、文が成り立たない。"}, "sentence_index": 6, "correct_answer": "言い替える"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "新宿駅で電車を言い替えた。", "explanation": "ここは〈乗り換える〉の意味。電車を別の電車に移る意味で、言葉を言い直す意味では使わない。"}, {"text": "誤字を言い替えた。", "explanation": "ここは〈訂正する〉の意味。誤字は直すものであって言い直すものではないので、「言い替える」とは合わない。"}, {"text": "部屋の空気を言い替えた。", "explanation": "ここは〈入れ替える〉の意味。空気を新しいものにかえる意味で、言葉の言い直しには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25c1e5d6-c0e8-4304-9fb4-e18af266873f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37906, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼は、わかりにくい説明が簡単な言葉に言い替えた。", "corrected_sentence": "彼は、わかりにくい説明を簡単な言葉に言い替えた。", "error_description": "「言い替える」は「〜を〜に言い替える」の形で、言い直す対象（説明）に「を」が付く。「が」は主語を示すため誤り。正しくは「説明を」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "言い替えて", "is_correct": true, "explanation": "て形で「くれた」につながり、「言い替えてくれた」となる。"}, {"text": "言い替えた", "is_correct": false, "explanation": "過去形のため「言い替えたくれた」となり、つながらない。"}, {"text": "言い替えない", "is_correct": false, "explanation": "否定形のため「言い替えないくれた」となり、文が成り立たない。"}, {"text": "言い替えれば", "is_correct": false, "explanation": "仮定形のため「くれた」と続けられず、文が成り立たない。"}], "correct_form": "言い替えて", "base_form": "言い替える", "form_label": "て形", "sentence_index": 1, "explanations": {"言い替えて": "て形で「くれた」につながり、「言い替えてくれた」となる。", "言い替えた": "過去形のため「言い替えたくれた」となり、つながらない。", "言い替えない": "否定形のため「言い替えないくれた」となり、文が成り立たない。", "言い替えれば": "仮定形のため「くれた」と続けられず、文が成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25c1e5d6-c0e8-4304-9fb4-e18af266873f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37906, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "先生は、説明を簡単な言葉に言い替えたて、生徒に伝えた。", "corrected_sentence": "先生は、説明を簡単な言葉に言い替えて、生徒に伝えた。", "error_description": "「言い替えた」の後に「て」を付けたのは誤り。「言い替えて」（て形）が正しく、「言い替えたて」は文法的に成り立たない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "言い替えた", "is_correct": true, "explanation": "過去形で文末に置け、「言い替えた。」と文が閉じる。"}, {"text": "言い替えて", "is_correct": false, "explanation": "て形のため文末に置けず、文が閉じない。"}, {"text": "言い替えれば", "is_correct": false, "explanation": "仮定形のため文末に置けず、文が閉じない。"}, {"text": "言い替えたら", "is_correct": false, "explanation": "たら形（仮定）のため文末に置けず、文が閉じない。"}], "correct_form": "言い替えた", "base_form": "言い替える", "form_label": "過去形", "sentence_index": 7, "explanations": {"言い替えた": "過去形で文末に置け、「言い替えた。」と文が閉じる。", "言い替えて": "て形のため文末に置けず、文が閉じない。", "言い替えれば": "仮定形のため文末に置けず、文が閉じない。", "言い替えたら": "たら形（仮定）のため文末に置けず、文が閉じない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25c1e5d6-c0e8-4304-9fb4-e18af266873f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
