INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37907, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "言った内容を、別の表現や別の言葉で置き換えて説明すること。", "primary_collocate": null, "pronunciation": "いいかえる", "ipa": "iːkaeɾɯ", "syllable_count": 5, "sentences": [{"text": "彼は自分の意見を、わかりやすい言葉で言い替えて説明した。", "target_word": "言い替えて", "complexity_tier": "T3", "furigana": "彼[かれ]は自分[じぶん]の意見[いけん]を、わかりやすい言葉[ことば]で言[い]い替[か]えて説明[せつめい]した。", "sentence_source": "generated"}, {"text": "専門家は、難しい話を一般の人向けの言葉に言い替えた。", "target_word": "言い替えた", "complexity_tier": "T3", "furigana": "専門家[せんもんか]は、難[むずか]しい話[はなし]を一般[いっぱん]の人向[ひとむ]けの言葉[ことば]に言[い]い替[か]えた。", "sentence_source": "generated"}, {"text": "会議で「反対」と言ったが、あとで「慎重に考えたい」と言い替えた。", "target_word": "言い替えた", "complexity_tier": "T3", "furigana": "会議[かいぎ]で「反対[はんたい]」と言[い]ったが、あとで「慎重[しんちょう]に考[かんが]えたい」と言[い]い替[か]えた。", "sentence_source": "generated"}, {"text": "通訳の人は、長い説明を短い言葉に言い替えた。", "target_word": "言い替えた", "complexity_tier": "T3", "furigana": "通訳[つうやく]の人[ひと]は、長[なが]い説明[せつめい]を短[みじか]い言葉[ことば]に言[い]い替[か]えた。", "sentence_source": "generated"}, {"text": "話が通じないとき、私は言い替えながら何度も説明した。", "target_word": "言い替え", "complexity_tier": "T3", "furigana": "話[はなし]が通[つう]じないとき、私[わたし]は言[い]い替[か]えながら何度[なんど]も説明[せつめい]した。", "sentence_source": "generated"}, {"text": "司会者は、質問を言い替えて、もう一度たずねた。", "target_word": "言い替えて", "complexity_tier": "T3", "furigana": "司会者[しかいしゃ]は、質問[しつもん]を言[い]い替[か]えて、もう一度[いちど]たずねた。", "sentence_source": "generated"}, {"text": "先生は生徒の答えを、正しい言葉に言い替えた。", "target_word": "言い替えた", "complexity_tier": "T3", "furigana": "先生[せんせい]は生徒[せいと]の答[こた]えを、正[ただ]しい言葉[ことば]に言[い]い替[か]えた。", "sentence_source": "generated"}, {"text": "「できない」を「難しい」と言い替えることもある。", "target_word": "言い替える", "complexity_tier": "T3", "furigana": "「できない」を「難[むずか]しい」と言[い]い替[か]えることもある。", "sentence_source": "generated"}, {"text": "同じことを言い替えると、聞く人の受け取り方が変わる。", "target_word": "言い替える", "complexity_tier": "T3", "furigana": "同[おな]じことを言[い]い替[か]えると、聞[き]く人[ひと]の受[う]け取[と]り方[かた]が変[か]わる。", "sentence_source": "generated"}, {"text": "説明が長くなったので、同じ内容をもっと短く言い替えた。", "target_word": "言い替えた", "complexity_tier": "T3", "furigana": "説明[せつめい]が長[なが]くなったので、同[おな]じ内容[ないよう]をもっと短[みじか]く言[い]い替[か]えた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "言い替える", "label": "終止形"}, {"form": "言い替えた", "label": "過去形"}, {"form": "言い替えて", "label": "て形"}, {"form": "言い替えない", "label": "否定形"}, {"form": "言い替えれば", "label": "仮定形"}, {"form": "言い替えよう", "label": "意志形"}], "register": "標準", "sense_fingerprint": "言った内容を別の表現に置き換えて説明し直す", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a04de0b4-b7c5-4a40-b388-094939d08f82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37907, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "言い替えて", "is_correct": true, "explanation": "て形で「説明した」へつながり、「言い替えて説明した」となる。"}, {"text": "言い替えた", "is_correct": false, "explanation": "過去形のため「説明した」とつながらず、文が成り立たない。"}, {"text": "言い替えれば", "is_correct": false, "explanation": "仮定形のため「説明した」とつながらず、文が成り立たない。"}, {"text": "言い替えよう", "is_correct": false, "explanation": "意志形のため「説明した」とつながらず、文が成り立たない。"}], "explanations": {"言い替えて": "て形で「説明した」へつながり、「言い替えて説明した」となる。", "言い替えた": "過去形のため「説明した」とつながらず、文が成り立たない。", "言い替えれば": "仮定形のため「説明した」とつながらず、文が成り立たない。", "言い替えよう": "意志形のため「説明した」とつながらず、文が成り立たない。"}, "sentence_index": 0, "correct_answer": "言い替えて"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "店で靴を言い替えた。", "explanation": "ここは〈履き替える〉の意味。靴を別の靴に替える場面で、言葉を言い直す意味ではない。"}, {"text": "古いカーテンを新しいものに言い替えた。", "explanation": "ここは〈置き換える〉の意味。物を別の物に取り替える場面で、言葉の言い直しには使わないので合わない。"}, {"text": "朝、急いで服を言い替えた。", "explanation": "ここは〈着替える〉の意味。服を別の服に変える場面で、言葉を言い直す意味では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25c1e5d6-c0e8-4304-9fb4-e18af266873f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37907, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "言い替えた", "is_correct": true, "explanation": "過去形で文末に置け、「言い替えた。」と文が閉じる。"}, {"text": "言い替えて", "is_correct": false, "explanation": "て形のため文末に置けず、文が閉じない。"}, {"text": "言い替えれば", "is_correct": false, "explanation": "仮定形のため文末に置けず、文が閉じない。"}, {"text": "言い替えたら", "is_correct": false, "explanation": "たら形のため文末に置けず、文が閉じない。"}], "explanations": {"言い替えた": "過去形で文末に置け、「言い替えた。」と文が閉じる。", "言い替えて": "て形のため文末に置けず、文が閉じない。", "言い替えれば": "仮定形のため文末に置けず、文が閉じない。", "言い替えたら": "たら形のため文末に置けず、文が閉じない。"}, "sentence_index": 6, "correct_answer": "言い替えた"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "古い家を言い替えた。", "explanation": "ここは〈作り替える〉の意味。家を作り直す意味で、言葉を言い直す意味では使わない。"}, {"text": "誤字を言い替えた。", "explanation": "ここは〈訂正する〉の意味。誤字は直すものなので、言葉を言い直す「言い替える」とは合わない。"}, {"text": "部屋の空気を言い替えた。", "explanation": "ここは〈入れ替える〉の意味。空気を新しいものにかえる意味で、言葉の言い直しには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25c1e5d6-c0e8-4304-9fb4-e18af266873f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37907, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "先生は、同じ話を別の言葉に言い替えてながら、ゆっくり説明した。", "corrected_sentence": "先生は、同じ話を別の言葉に言い替えながら、ゆっくり説明した。", "error_description": "「ながら」は動詞の連用形につく。「言い替えて」の「て」は不要で、正しくは「言い替えながら」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "言い替えた", "is_correct": true, "explanation": "過去形で文末に置け、「言い替えた。」と文が閉じる。"}, {"text": "言い替えて", "is_correct": false, "explanation": "て形のため文末に置けず、文が閉じない。"}, {"text": "言い替えれば", "is_correct": false, "explanation": "仮定形のため文末に置けず、文が閉じない。"}, {"text": "言い替えたら", "is_correct": false, "explanation": "たら形（仮定）のため文末に置けず、文が閉じない。"}], "correct_form": "言い替えた", "base_form": "言い替える", "form_label": "過去形", "sentence_index": 1, "explanations": {"言い替えた": "過去形で文末に置け、「言い替えた。」と文が閉じる。", "言い替えて": "て形のため文末に置けず、文が閉じない。", "言い替えれば": "仮定形のため文末に置けず、文が閉じない。", "言い替えたら": "たら形（仮定）のため文末に置けず、文が閉じない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25c1e5d6-c0e8-4304-9fb4-e18af266873f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37907, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "先生は、難しい言葉を、やさしい言葉に言い付けた。", "corrected_sentence": "先生は、難しい言葉を、やさしい言葉に言い替えた。", "error_description": "「言い替える」は言葉を別の表現で言い直す意味。「言い付ける」は指示や告げ口の意味で、ここでは言い直しを表せない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "言い替える", "is_correct": true, "explanation": "連体形で「こと」を修飾し、「言い替えることもある」と自然に続く。"}, {"text": "言い替えよう", "is_correct": false, "explanation": "意志形のため「こと」を修飾できず、「言い替えようこともある」は成り立たない。"}, {"text": "言い替えろ", "is_correct": false, "explanation": "命令形のため「こと」を修飾できず、文が成り立たない。"}, {"text": "言い替えます", "is_correct": false, "explanation": "丁寧な終止形のため「こと」に続かず、文が成り立たない。"}], "correct_form": "言い替える", "base_form": "言い替える", "form_label": "連体形", "sentence_index": 7, "explanations": {"言い替える": "連体形で「こと」を修飾し、「言い替えることもある」と自然に続く。", "言い替えよう": "意志形のため「こと」を修飾できず、「言い替えようこともある」は成り立たない。", "言い替えろ": "命令形のため「こと」を修飾できず、文が成り立たない。", "言い替えます": "丁寧な終止形のため「こと」に続かず、文が成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25c1e5d6-c0e8-4304-9fb4-e18af266873f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37908, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「隠喩が多くて」で、隠喩の多さを示す正しい助詞。"}, {"text": "を", "is_correct": false, "explanation": "目的語の「を」は、「隠喩を多くて」では形容詞「多い」と結びつかない。"}, {"text": "に", "is_correct": false, "explanation": "「隠喩に多くて」では、多いという状態の主語を示せない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表す「へ」は、「隠喩へ多くて」では意味がつながらない。"}], "correct_answer": "が", "explanations": {"が": "「隠喩が多くて」で、隠喩の多さを示す正しい助詞。", "を": "目的語の「を」は、「隠喩を多くて」では形容詞「多い」と結びつかない。", "に": "「隠喩に多くて」では、多いという状態の主語を示せない。", "へ": "方向を表す「へ」は、「隠喩へ多くて」では意味がつながらない。"}, "error_tags": {"を": "object_marker", "に": "location_or_target", "へ": "direction"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cccbe2e-caf3-47c6-9a9a-d86ebe2bdee1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37908, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "「隠喩は日常の会話にも」で、話題として取り上げる正しい助詞。"}, {"text": "から", "is_correct": false, "explanation": "起点を表す「から」は、「隠喩から日常の会話に出てくる」では文の意味が成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "比較の「より」は、「隠喩より日常の会話に出てくる」では比べる対象がなく不自然。"}, {"text": "で", "is_correct": false, "explanation": "手段を表す「で」は、「隠喩で日常の会話に出てくる」では文の関係が合わない。"}], "correct_answer": "は", "explanations": {"は": "「隠喩は日常の会話にも」で、話題として取り上げる正しい助詞。", "から": "起点を表す「から」は、「隠喩から日常の会話に出てくる」では文の意味が成り立たない。", "より": "比較の「より」は、「隠喩より日常の会話に出てくる」では比べる対象がなく不自然。", "で": "手段を表す「で」は、「隠喩で日常の会話に出てくる」では文の関係が合わない。"}, "error_tags": {"から": "source", "より": "comparison", "で": "means_or_location"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cccbe2e-caf3-47c6-9a9a-d86ebe2bdee1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37908, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "あるものを別のものにたとえて言う言い方。", "primary_collocate": null, "pronunciation": "いんゆ", "ipa": "iɴjɯ", "syllable_count": 3, "sentences": [{"text": "「時は金なり」は、時間をお金にたとえた隠喩だ。", "target_word": "隠喩", "complexity_tier": "T3", "furigana": "「時[とき]は金[かね]なり」は、時間[じかん]をお金[かね]にたとえた隠喩[いんゆ]だ。", "sentence_source": "generated"}, {"text": "この詩は隠喩が多くて、意味を読み取るのが難しい。", "target_word": "隠喩", "complexity_tier": "T3", "furigana": "この詩[し]は隠喩[いんゆ]が多[おお]くて、意味[いみ]を読[よ]み取[と]るのが難[むずか]しい。", "sentence_source": "generated"}, {"text": "「彼は氷のような人だ」は直喩で、「彼は氷だ」は隠喩になる。", "target_word": "隠喩", "complexity_tier": "T3", "furigana": "「彼[かれ]は氷[こおり]のような人[ひと]だ」は直喩[ちょくゆ]で、「彼[かれ]は氷[こおり]だ」は隠喩[いんゆ]になる。", "sentence_source": "generated"}, {"text": "作者は夜の海を隠喩として使い、主人公の不安を表した。", "target_word": "隠喩", "complexity_tier": "T3", "furigana": "作者[さくしゃ]は夜[よる]の海[うみ]を隠喩[いんゆ]として使[つか]い、主人公[しゅじんこう]の不安[ふあん]を表[あらわ]した。", "sentence_source": "generated"}, {"text": "隠喩を使うと、短い言葉で強い印象を残せる。", "target_word": "隠喩", "complexity_tier": "T3", "furigana": "隠喩[いんゆ]を使[つか]うと、短[みじか]い言葉[ことば]で強[つよ]い印象[いんしょう]を残[のこ]せる。", "sentence_source": "generated"}, {"text": "先生は「心は鏡だ」という隠喩の意味を説明した。", "target_word": "隠喩", "complexity_tier": "T3", "furigana": "先生[せんせい]は「心[こころ]は鏡[かがみ]だ」という隠喩[いんゆ]の意味[いみ]を説明[せつめい]した。", "sentence_source": "generated"}, {"text": "小説の中の「灰色の日々」は、退屈な生活の隠喩である。", "target_word": "隠喩", "complexity_tier": "T3", "furigana": "小説[しょうせつ]の中[なか]の「灰色[はいいろ]の日々[ひび]」は、退屈[たいくつ]な生活[せいかつ]の隠喩[いんゆ]である。", "sentence_source": "generated"}, {"text": "隠喩は日常の会話にもよく出てくる。", "target_word": "隠喩", "complexity_tier": "T3", "furigana": "隠喩[いんゆ]は日常[にちじょう]の会話[かいわ]にもよく出[で]てくる。", "sentence_source": "generated"}, {"text": "広告のコピーに隠喩を取り入れると、記憶に残りやすい。", "target_word": "隠喩", "complexity_tier": "T3", "furigana": "広告[こうこく]のコピーに隠喩[いんゆ]を取[と]り入[い]れると、記憶[きおく]に残[のこ]りやすい。", "sentence_source": "generated"}, {"text": "この表現は隠喩なので、文字どおりに受け取ってはいけない。", "target_word": "隠喩", "complexity_tier": "T3", "furigana": "この表現[ひょうげん]は隠喩[いんゆ]なので、文字[もじ]どおりに受[う]け取[と]ってはいけない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "隠喩", "label": "基本形"}, {"form": "隠喩的", "label": "形状詞形"}], "register": "書き言葉・文学的", "sense_fingerprint": "あるものを別のものに見立てて言う、たとえの言い方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2fddf5a-a756-46b3-bbac-8b346c4f6624') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37908, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "隠喩", "is_correct": true, "explanation": "別のものにたとえる修辞を指し、「たとえた隠喩だ」に合う語。"}, {"text": "比率", "is_correct": false, "explanation": "数量の割合を指し、たとえの説明には入らない。"}, {"text": "因果", "is_correct": false, "explanation": "原因と結果の関係を指し、「時間をお金にたとえた因果だ」は意味が合わない。"}, {"text": "配分", "is_correct": false, "explanation": "分けて割り当てる意味で、たとえを説明する語としては合わない。"}], "explanations": {"隠喩": "別のものにたとえる修辞を指し、「たとえた隠喩だ」に合う語。", "比率": "数量の割合を指し、たとえの説明には入らない。", "因果": "原因と結果の関係を指し、「時間をお金にたとえた因果だ」は意味が合わない。", "配分": "分けて割り当てる意味で、たとえを説明する語としては合わない。"}, "sentence_index": 0, "correct_answer": "隠喩"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "引っ越しの日、隠喩を段ボールに詰めて新居へ運んだ。", "explanation": "ここは〈荷物〉の意味。隠喩は言葉の表現方法で、箱に詰めて運ぶ物ではないので合わない。"}, {"text": "隠喩を散歩に連れていって、近所の公園を一周した。", "explanation": "ここは〈ペット〉の意味。隠喩は表現のたとえ方で、散歩に連れて行く生き物ではないので合わない。"}, {"text": "隠喩を夕飯にして、家族みんなで食べた。", "explanation": "ここは〈食べ物〉の意味。隠喩は言葉の表現方法で、夕飯の材料になるものではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cccbe2e-caf3-47c6-9a9a-d86ebe2bdee1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37908, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "隠喩", "is_correct": true, "explanation": "たとえによる修辞を指し、「退屈な生活の隠喩である」に合う語。"}, {"text": "規則", "is_correct": false, "explanation": "守るべき決まりを指し、「退屈な生活の規則である」は意味が合わない。"}, {"text": "会議", "is_correct": false, "explanation": "話し合いの場を指し、「退屈な生活の会議である」は文として成り立たない。"}, {"text": "通帳", "is_correct": false, "explanation": "預金の記録を指し、たとえの説明としては意味が合わない。"}], "explanations": {"隠喩": "たとえによる修辞を指し、「退屈な生活の隠喩である」に合う語。", "規則": "守るべき決まりを指し、「退屈な生活の規則である」は意味が合わない。", "会議": "話し合いの場を指し、「退屈な生活の会議である」は文として成り立たない。", "通帳": "預金の記録を指し、たとえの説明としては意味が合わない。"}, "sentence_index": 6, "correct_answer": "隠喩"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "急に隠喩が降り出して、洗濯物が濡れてしまった。", "explanation": "ここは〈雨〉の意味。隠喩は言葉のたとえ方で、空から降ってくるものではないので合わない。"}, {"text": "試験までの隠喩があと三日しかない。", "explanation": "ここは〈時間〉の意味。隠喩は表現方法で、残りの日数を数える対象ではないので合わない。"}, {"text": "彼は隠喩と大声で叫んで、会場を驚かせた。", "explanation": "ここは〈掛け声〉の意味。隠喩は表現のたとえ方で、大声で発して人を驚かせる言葉ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cccbe2e-caf3-47c6-9a9a-d86ebe2bdee1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37908, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この小説は隠喩を多いので、初心者には難しい。", "corrected_sentence": "この小説は隠喩が多いので、初心者には難しい。", "error_description": "「多い」は「〜が多い」の形をとる。隠喩に続く助詞は「が」が正しく、「を」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cccbe2e-caf3-47c6-9a9a-d86ebe2bdee1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37908, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この授業では隠喩を見分け方を学んだ。", "corrected_sentence": "この授業では隠喩の見分け方を学んだ。", "error_description": "「見分け方」の前は「の」で結ばれる。隠喩の後に「を」を入れると二重の「を」になり誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cccbe2e-caf3-47c6-9a9a-d86ebe2bdee1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
