INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37909, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「隠喩を理解する」で、理解の対象を示す正しい助詞。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表す「へ」は、「隠喩へ理解するには」では理解する対象を示せない。"}, {"text": "の", "is_correct": false, "explanation": "所有や修飾の「の」は、「隠喩の理解するには」では動詞「理解する」と結びつかない。"}, {"text": "に", "is_correct": false, "explanation": "帰着や場所を表す「に」は、「隠喩に理解するには」では理解する対象を示せない。"}], "correct_answer": "を", "explanations": {"を": "「隠喩を理解する」で、理解の対象を示す正しい助詞。", "へ": "方向を表す「へ」は、「隠喩へ理解するには」では理解する対象を示せない。", "の": "所有や修飾の「の」は、「隠喩の理解するには」では動詞「理解する」と結びつかない。", "に": "帰着や場所を表す「に」は、「隠喩に理解するには」では理解する対象を示せない。"}, "error_tags": {"へ": "direction", "の": "possessive", "に": "target_or_location"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cccbe2e-caf3-47c6-9a9a-d86ebe2bdee1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37909, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "直接言わずに、別の物事にたとえて表現する修辞法。例えば、「人生は旅」のように、似ているところを使って意味を伝える。", "primary_collocate": null, "pronunciation": "いんゆ", "ipa": "iɴjɯ", "syllable_count": 3, "sentences": [{"text": "国語の授業で、隠喩という修辞法を習った。", "target_word": "隠喩", "complexity_tier": "T3", "furigana": "国語[こくご]の授業[じゅぎょう]で、隠喩[いんゆ]という修辞法[しゅうじほう]を習[なら]った。", "sentence_source": "generated"}, {"text": "「人生は旅だ」という隠喩は、生き方を旅に重ねて伝えている。", "target_word": "隠喩", "complexity_tier": "T3", "furigana": "「人生[じんせい]は旅[たび]だ」という隠喩[いんゆ]は、生[い]き方[かた]を旅[たび]に重[かさ]ねて伝[つた]えている。", "sentence_source": "generated"}, {"text": "隠喩は「ようだ」を使わない点が、直喩と違う。", "target_word": "隠喩", "complexity_tier": "T3", "furigana": "隠喩[いんゆ]は「ようだ」を使[つか]わない点[てん]が、直喩[ちょくゆ]と違[ちが]う。", "sentence_source": "generated"}, {"text": "詩人は隠喩を巧みに使って、悲しみを描いた。", "target_word": "隠喩", "complexity_tier": "T3", "furigana": "詩人[しじん]は隠喩[いんゆ]を巧[たく]みに使[つか]って、悲[かな]しみを描[えが]いた。", "sentence_source": "generated"}, {"text": "隠喩の効果を調べるために、有名な俳句を読み比べた。", "target_word": "隠喩", "complexity_tier": "T3", "furigana": "隠喩[いんゆ]の効果[こうか]を調[しら]べるために、有名[ゆうめい]な俳句[はいく]を読[よ]み比[くら]べた。", "sentence_source": "generated"}, {"text": "彼のスピーチは隠喩が効いていて、聞く人の心に残った。", "target_word": "隠喩", "complexity_tier": "T3", "furigana": "彼[かれ]のスピーチは隠喩[いんゆ]が効[き]いていて、聞[き]く人[ひと]の心[こころ]に残[のこ]った。", "sentence_source": "generated"}, {"text": "試験では、文の中の隠喩を探す問題が出た。", "target_word": "隠喩", "complexity_tier": "T3", "furigana": "試験[しけん]では、文[ぶん]の中[なか]の隠喩[いんゆ]を探[さが]す問題[もんだい]が出[で]た。", "sentence_source": "generated"}, {"text": "隠喩を理解するには、二つのものの似ているところを考える必要がある。", "target_word": "隠喩", "complexity_tier": "T3", "furigana": "隠喩[いんゆ]を理解[りかい]するには、二[ふた]つのものの似[に]ているところを考[かんが]える必要[ひつよう]がある。", "sentence_source": "generated"}, {"text": "彼女の小説は隠喩に満ちていて、何度読んでも新しい発見がある。", "target_word": "隠喩", "complexity_tier": "T3", "furigana": "彼女[かのじょ]の小説[しょうせつ]は隠喩[いんゆ]に満[み]ちていて、何度[なんど]読[よ]んでも新[あたら]しい発見[はっけん]がある。", "sentence_source": "generated"}, {"text": "「言葉は刃だ」は、言葉の怖さを伝える隠喩だ。", "target_word": "隠喩", "complexity_tier": "T3", "furigana": "「言葉[ことば]は刃[やいば]だ」は、言葉[ことば]の怖[こわ]さを伝[つた]える隠喩[いんゆ]だ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "隠喩", "label": "基本形"}, {"form": "隠喩的", "label": "形状詞形"}], "register": "書き言葉・学術的", "sense_fingerprint": "似た点を利用して意味を伝える修辞法（メタファー）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2fddf5a-a756-46b3-bbac-8b346c4f6624') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37909, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "隠喩", "is_correct": true, "explanation": "たとえによる修辞法を指し、「修辞法という」の前に入る語。"}, {"text": "比率", "is_correct": false, "explanation": "数量の割合を指し、「修辞法」とは結びつかない。"}, {"text": "配分", "is_correct": false, "explanation": "分けて割り当てる意味で、修辞法の名前ではない。"}, {"text": "因果", "is_correct": false, "explanation": "原因と結果の関係を指し、「因果という修辞法」は成り立たない。"}], "explanations": {"隠喩": "たとえによる修辞法を指し、「修辞法という」の前に入る語。", "比率": "数量の割合を指し、「修辞法」とは結びつかない。", "配分": "分けて割り当てる意味で、修辞法の名前ではない。", "因果": "原因と結果の関係を指し、「因果という修辞法」は成り立たない。"}, "sentence_index": 0, "correct_answer": "隠喩"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "隠喩に乗って、遠くの町まで出かけた。", "explanation": "ここは〈乗り物〉の意味。隠喩は言葉のたとえ方で、乗って移動するものではないので合わない。"}, {"text": "隠喩を吹いて、音楽の練習をした。", "explanation": "ここは〈楽器〉の意味。隠喩は表現方法で、吹いて音を出す物ではないので合わない。"}, {"text": "隠喩を鍋で煮て、夕飯のおかずにした。", "explanation": "ここは〈料理〉の意味。隠喩は言葉のたとえ方で、鍋で煮て料理する材料ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cccbe2e-caf3-47c6-9a9a-d86ebe2bdee1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37909, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "隠喩", "is_correct": true, "explanation": "たとえによる修辞を指し、「文の中の隠喩を探す」に合う語。"}, {"text": "規則", "is_correct": false, "explanation": "守るべき決まりを指し、「文の中の規則を探す」は意味が合わない。"}, {"text": "会議", "is_correct": false, "explanation": "話し合いの場を指し、「文の中の会議を探す」は成り立たない。"}, {"text": "通帳", "is_correct": false, "explanation": "預金の記録を指し、「文の中の通帳を探す」は意味が合わない。"}], "explanations": {"隠喩": "たとえによる修辞を指し、「文の中の隠喩を探す」に合う語。", "規則": "守るべき決まりを指し、「文の中の規則を探す」は意味が合わない。", "会議": "話し合いの場を指し、「文の中の会議を探す」は成り立たない。", "通帳": "預金の記録を指し、「文の中の通帳を探す」は意味が合わない。"}, "sentence_index": 6, "correct_answer": "隠喩"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "隠喩で一万円を払って、その服を買った。", "explanation": "ここは〈お金〉の意味。隠喩は言葉のたとえ方で、代金として払える物ではないので合わない。"}, {"text": "隠喩を蹴って、サッカーのゴールを決めた。", "explanation": "ここは〈ボール〉の意味。隠喩は表現方法で、蹴ってゴールに入れる物ではないので合わない。"}, {"text": "隠喩を棚に置いて、本を並べた。", "explanation": "ここは〈家具〉の意味。隠喩は言葉のたとえ方で、棚に置いて並べる物ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cccbe2e-caf3-47c6-9a9a-d86ebe2bdee1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37909, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "作家は隠喩に使って、人の心の弱さを描いた。", "corrected_sentence": "作家は隠喩を使って、人の心の弱さを描いた。", "error_description": "「使う」は「〜を使う」の形をとる。隠喩に続く助詞は「を」が正しく、「に」にすると誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cccbe2e-caf3-47c6-9a9a-d86ebe2bdee1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37909, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼は隠喩を使い方を学んだ。", "corrected_sentence": "彼は隠喩の使い方を学んだ。", "error_description": "「使い方」の前は「の」で結ばれる。隠喩の後に「を」を入れると二重の「を」になり誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cccbe2e-caf3-47c6-9a9a-d86ebe2bdee1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37910, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「創出に力を入れる」の「に」。力を注ぐ対象を示す形で、「〜に力を入れている」と続く。"}, {"text": "を", "is_correct": false, "explanation": "「力を入れる」に「を」は使えない。力を注ぐ対象は「に」で示すので、この位置では文が壊れる。"}, {"text": "が", "is_correct": false, "explanation": "「創出が力を入れている」は主語と述語がつながらず、「力を入れる」の対象も示せない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は場所や手段を表すので、「〜に力を入れる」の対象を示すことはできない。"}], "correct_answer": "に", "explanations": {"に": "「創出に力を入れる」の「に」。力を注ぐ対象を示す形で、「〜に力を入れている」と続く。", "を": "「力を入れる」に「を」は使えない。力を注ぐ対象は「に」で示すので、この位置では文が壊れる。", "が": "「創出が力を入れている」は主語と述語がつながらず、「力を入れる」の対象も示せない。", "で": "「で」は場所や手段を表すので、「〜に力を入れる」の対象を示すことはできない。"}, "error_tags": {"を": "目的語", "が": "主語", "で": "場所・手段"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cccbe2e-caf3-47c6-9a9a-d86ebe2bdee1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37910, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「アイデアの創出には〜が大切だ」の「に」。「には」と続けて、創出に必要な条件として話題を示す。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は向かう先を表すので、「創出へ」では創出を目指すという意味にならず、文の骨組みが合わない。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語を示すが、「創出を」の後に「は」を続けると文が壊れる。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を表すので、創出が出発点になる文にはならず、「大切だ」の前提として合わない。"}], "correct_answer": "に", "explanations": {"に": "「アイデアの創出には〜が大切だ」の「に」。「には」と続けて、創出に必要な条件として話題を示す。", "へ": "「へ」は向かう先を表すので、「創出へ」では創出を目指すという意味にならず、文の骨組みが合わない。", "を": "「を」は目的語を示すが、「創出を」の後に「は」を続けると文が壊れる。", "から": "「から」は起点を表すので、創出が出発点になる文にはならず、「大切だ」の前提として合わない。"}, "error_tags": {"へ": "方向", "と": "並列・相手", "を": "目的語"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cccbe2e-caf3-47c6-9a9a-d86ebe2bdee1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37910, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "新しいものや形を作り出すこと。", "primary_collocate": null, "pronunciation": "そうしゅつ", "ipa": "soːɕɯtsɯ", "syllable_count": 4, "sentences": [{"text": "新しい産業の創出が、地方の大きな課題になっている。", "target_word": "創出", "complexity_tier": "T3", "furigana": "新[あたら]しい産業[さんぎょう]の創出[そうしゅつ]が、地方[ちほう]の大[おお]きな課題[かだい]になっている。", "sentence_source": "generated"}, {"text": "市は若者のための仕事の創出に力を入れている。", "target_word": "創出", "complexity_tier": "T3", "furigana": "市[し]は若者[わかもの]のための仕事[しごと]の創出[そうしゅつ]に力[ちから]を入[い]れている。", "sentence_source": "generated"}, {"text": "芸術家は無から美を創出する仕事だ。", "target_word": "創出", "complexity_tier": "T3", "furigana": "芸術家[げいじゅつか]は無[む]から美[び]を創出[そうしゅつ]する仕事[しごと]だ。", "sentence_source": "generated"}, {"text": "この会社は新しい価値の創出を目標にしている。", "target_word": "創出", "complexity_tier": "T3", "furigana": "この会社[かいしゃ]は新[あたら]しい価値[かち]の創出[そうしゅつ]を目標[もくひょう]にしている。", "sentence_source": "generated"}, {"text": "画家は独自の色彩を創出して、高い評価を受けた。", "target_word": "創出", "complexity_tier": "T3", "furigana": "画家[がか]は独自[どくじ]の色彩[しきさい]を創出[そうしゅつ]して、高[たか]い評価[ひょうか]を受[う]けた。", "sentence_source": "generated"}, {"text": "新技術は多くの雇用を創出するだろう。", "target_word": "創出", "complexity_tier": "T3", "furigana": "新[しん]技術[ぎじゅつ]は多[おお]くの雇用[こよう]を創出[そうしゅつ]するだろう。", "sentence_source": "generated"}, {"text": "研究チームは、新しい素材の創出に成功した。", "target_word": "創出", "complexity_tier": "T3", "furigana": "研究[けんきゅう]チームは、新[あたら]しい素材[そざい]の創出[そうしゅつ]に成功[せいこう]した。", "sentence_source": "generated"}, {"text": "アイデアの創出には、自由に話し合える雰囲気が大切だ。", "target_word": "創出", "complexity_tier": "T3", "furigana": "アイデアの創出[そうしゅつ]には、自由[じゆう]に話[はな]し合[あ]える雰囲気[ふんいき]が大切[たいせつ]だ。", "sentence_source": "generated"}, {"text": "地域の魅力を創出するため、住民がイベントを企画した。", "target_word": "創出", "complexity_tier": "T3", "furigana": "地域[ちいき]の魅力[みりょく]を創出[そうしゅつ]するため、住民[じゅうみん]がイベントを企画[きかく]した。", "sentence_source": "generated"}, {"text": "古い考えにこだわると、新しいものの創出は難しい。", "target_word": "創出", "complexity_tier": "T3", "furigana": "古[ふる]い考[かんが]えにこだわると、新[あたら]しいものの創出[そうしゅつ]は難[むずか]しい。", "sentence_source": "generated"}], "morphological_forms": [{"form": "創出する", "label": "辞書形"}, {"form": "創出した", "label": "過去形"}, {"form": "創出される", "label": "受身形"}, {"form": "創出して", "label": "て形"}], "register": "書き言葉・やや硬い", "sense_fingerprint": "これまでになかった新しいものを生み出すこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2fddf5a-a756-46b3-bbac-8b346c4f6624') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37910, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "創出", "is_correct": true, "explanation": "「新しい産業の創出」で、新しいものを生み出すという意味の名詞。課題の内容を示す主語になる。"}, {"text": "散歩", "is_correct": false, "explanation": "「新しい産業の散歩」は意味をなさない。歩いて気分転換することで、産業とは結びつかない。"}, {"text": "食事", "is_correct": false, "explanation": "「新しい産業の食事」は文として成り立たず、地方の課題の内容にならない。"}, {"text": "睡眠", "is_correct": false, "explanation": "「新しい産業の睡眠」は意味が通らない。休息を表す語で、産業の課題には合わない。"}], "explanations": {"創出": "「新しい産業の創出」で、新しいものを生み出すという意味の名詞。課題の内容を示す主語になる。", "散歩": "「新しい産業の散歩」は意味をなさない。歩いて気分転換することで、産業とは結びつかない。", "食事": "「新しい産業の食事」は文として成り立たず、地方の課題の内容にならない。", "睡眠": "「新しい産業の睡眠」は意味が通らない。休息を表す語で、産業の課題には合わない。"}, "sentence_index": 0, "correct_answer": "創出"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この町では毎年、新しい交通事故が創出されている。", "explanation": "ここは〈発生〉の意味。事故は起きる（発生する）ものなので、新しいものを作り出す〈創出〉とは言わない。"}, {"text": "天文学者が、新しい星を創出した。", "explanation": "ここは〈発見〉の意味。すでにある星を見つけることなので、作り出す〈創出〉では合わない。"}, {"text": "この店は江戸時代の味を創出して、今も出している。", "explanation": "ここは〈再現〉の意味。昔の味を作り直すことは再現で、新しいものを作り出す〈創出〉とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cccbe2e-caf3-47c6-9a9a-d86ebe2bdee1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37910, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "創出", "is_correct": true, "explanation": "「新しい素材の創出に成功した」で、新しい素材を生み出すという意味の名詞。「に成功」の対象になる。"}, {"text": "入浴", "is_correct": false, "explanation": "「新しい素材の入浴に成功した」は意味をなさない。体を湯につけることで、素材とは結びつかない。"}, {"text": "給食", "is_correct": false, "explanation": "「新しい素材の給食に成功した」は文として成り立たない。食事を配ることで、研究の成果にはならない。"}, {"text": "留守番", "is_correct": false, "explanation": "「新しい素材の留守番に成功した」は不自然で、研究の成功を表す文にならない。"}], "explanations": {"創出": "「新しい素材の創出に成功した」で、新しい素材を生み出すという意味の名詞。「に成功」の対象になる。", "入浴": "「新しい素材の入浴に成功した」は意味をなさない。体を湯につけることで、素材とは結びつかない。", "給食": "「新しい素材の給食に成功した」は文として成り立たない。食事を配ることで、研究の成果にはならない。", "留守番": "「新しい素材の留守番に成功した」は不自然で、研究の成功を表す文にならない。"}, "sentence_index": 6, "correct_answer": "創出"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工場では、この液体から成分を創出している。", "explanation": "ここは〈抽出〉の意味。混ざったものから取り出すことは抽出で、新しく作り出す〈創出〉ではない。"}, {"text": "この工場は、同じ部品を毎日創出している。", "explanation": "ここは〈量産〉の意味。同じものを繰り返し大量に作ることは量産で、新しいものを作り出す〈創出〉とは言わない。"}, {"text": "壊れた陶器を創出して、元の形に戻した。", "explanation": "ここは〈修復〉の意味。壊れたものを元に戻すことは修復で、新しいものを作り出す〈創出〉とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cccbe2e-caf3-47c6-9a9a-d86ebe2bdee1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37910, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "市は地域の雇用の創出を力を入れている。", "corrected_sentence": "市は地域の雇用の創出に力を入れている。", "error_description": "「力を入れる」は「〜に力を入れる」の形で、力を注ぐ対象を「に」で示す。「創出を」は誤りで、正しくは「創出に」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cccbe2e-caf3-47c6-9a9a-d86ebe2bdee1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37910, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "研究所は新しい燃料の創出に目指している。", "corrected_sentence": "研究所は新しい燃料の創出を目指している。", "error_description": "「目指す」は目的語に「を」をとる。「創出に目指している」の「に」は誤りで、正しくは「創出を目指している」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cccbe2e-caf3-47c6-9a9a-d86ebe2bdee1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37912, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「風の方向が変わって」の「が」。方向そのものが変わるという主語を示す。"}, {"text": "を", "is_correct": false, "explanation": "自動詞の「変わる」に「を」は使えず、「方向を変わって」は文が成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は場所や手段を表すので、方向が変わるという主語にはならない。"}, {"text": "の", "is_correct": false, "explanation": "「の」は名詞をつなぐ助詞で、「変わって」の主語を示すことはできない。"}], "correct_answer": "が", "explanations": {"が": "「風の方向が変わって」の「が」。方向そのものが変わるという主語を示す。", "を": "自動詞の「変わる」に「を」は使えず、「方向を変わって」は文が成り立たない。", "で": "「で」は場所や手段を表すので、方向が変わるという主語にはならない。", "の": "「の」は名詞をつなぐ助詞で、「変わって」の主語を示すことはできない。"}, "error_tags": {"を": "目的語", "で": "場所・手段", "の": "連体修飾"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cccbe2e-caf3-47c6-9a9a-d86ebe2bdee1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37912, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "から", "options": [{"text": "から", "is_correct": true, "explanation": "「東の方向から昇る」の「から」。太陽が出てくる起点を示す。"}, {"text": "が", "is_correct": false, "explanation": "「東の方向が昇る」では、太陽が昇る動作の主語とつながらず、文が成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "「東の方向の昇る」は名詞の後に動詞を直接続けられず、文が成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較の基準を示すので、昇る方角の起点を表す文にはならない。"}], "correct_answer": "から", "explanations": {"から": "「東の方向から昇る」の「から」。太陽が出てくる起点を示す。", "が": "「東の方向が昇る」では、太陽が昇る動作の主語とつながらず、文が成り立たない。", "の": "「東の方向の昇る」は名詞の後に動詞を直接続けられず、文が成り立たない。", "より": "「より」は比較の基準を示すので、昇る方角の起点を表す文にはならない。"}, "error_tags": {"が": "主語", "と": "相手・並列", "の": "連体修飾"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cccbe2e-caf3-47c6-9a9a-d86ebe2bdee1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37912, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "むいている ほう。", "primary_collocate": null, "pronunciation": "ほうこう", "ipa": "hoːkoː", "syllable_count": 4, "sentences": [{"text": "駅は、この道をまっすぐ行った方向にあります。", "target_word": "方向", "complexity_tier": "T3", "furigana": "駅[えき]は、この道[みち]をまっすぐ行[い]った方向[ほうこう]にあります。", "sentence_source": "generated"}, {"text": "風の方向が変わって、急に寒くなった。", "target_word": "方向", "complexity_tier": "T3", "furigana": "風[かぜ]の方向[ほうこう]が変[か]わって、急[きゅう]に寒[さむ]くなった。", "sentence_source": "generated"}, {"text": "地図を見ても、どちらの方向に歩けばいいかわからない。", "target_word": "方向", "complexity_tier": "T3", "furigana": "地図[ちず]を見[み]ても、どちらの方向[ほうこう]に歩[ある]けばいいかわからない。", "sentence_source": "generated"}, {"text": "彼は迷ったとき、いつも自分の進みたい方向を考える。", "target_word": "方向", "complexity_tier": "T3", "furigana": "彼[かれ]は迷[まよ]ったとき、いつも自分[じぶん]の進[すす]みたい方向[ほうこう]を考[かんが]える。", "sentence_source": "generated"}, {"text": "矢印の方向に進むと、出口に着きます。", "target_word": "方向", "complexity_tier": "T3", "furigana": "矢印[やじるし]の方向[ほうこう]に進[すす]むと、出口[でぐち]に着[つ]きます。", "sentence_source": "generated"}, {"text": "会議では、プロジェクトの方向を決めた。", "target_word": "方向", "complexity_tier": "T3", "furigana": "会議[かいぎ]では、プロジェクトの方向[ほうこう]を決[き]めた。", "sentence_source": "generated"}, {"text": "私は方向がわからなくて、道に迷ってしまった。", "target_word": "方向", "complexity_tier": "T3", "furigana": "私[わたし]は方向[ほうこう]がわからなくて、道[みち]に迷[まよ]ってしまった。", "sentence_source": "generated"}, {"text": "太陽は東の方向から昇る。", "target_word": "方向", "complexity_tier": "T3", "furigana": "太陽[たいよう]は東[ひがし]の方向[ほうこう]から昇[のぼ]る。", "sentence_source": "generated"}, {"text": "反対の方向へ行く電車に乗ってしまった。", "target_word": "方向", "complexity_tier": "T3", "furigana": "反対[はんたい]の方向[ほうこう]へ行[い]く電車[でんしゃ]に乗[の]ってしまった。", "sentence_source": "generated"}, {"text": "話が思わぬ方向に進んで、みんな驚いた。", "target_word": "方向", "complexity_tier": "T3", "furigana": "話[はなし]が思[おも]わぬ方向[ほうこう]に進[すす]んで、みんな驚[おどろ]いた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "方向", "label": "基本形"}, {"form": "方向に", "label": "に格形"}], "register": "中立・日常", "sense_fingerprint": "向かっている先や進む先の側、向き", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2fddf5a-a756-46b3-bbac-8b346c4f6624') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37912, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "方向", "is_correct": true, "explanation": "「まっすぐ行った方向にあります」で、進んでいく先の側を示す名詞。位置を表す文に合う。"}, {"text": "天気", "is_correct": false, "explanation": "「まっすぐ行った天気にあります」は意味をなさない。空模様を表す語で、位置の説明には合わない。"}, {"text": "料金", "is_correct": false, "explanation": "「まっすぐ行った料金にあります」は不自然で、駅の位置を示す文にならない。"}, {"text": "期限", "is_correct": false, "explanation": "「まっすぐ行った期限にあります」は意味が通らない。時間の区切りを表す語で、場所の説明には合わない。"}], "explanations": {"方向": "「まっすぐ行った方向にあります」で、進んでいく先の側を示す名詞。位置を表す文に合う。", "天気": "「まっすぐ行った天気にあります」は意味をなさない。空模様を表す語で、位置の説明には合わない。", "料金": "「まっすぐ行った料金にあります」は不自然で、駅の位置を示す文にならない。", "期限": "「まっすぐ行った期限にあります」は意味が通らない。時間の区切りを表す語で、場所の説明には合わない。"}, "sentence_index": 0, "correct_answer": "方向"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "祖母が話す方向がうまく聞き取れなくて、困った。", "explanation": "ここは〈方言〉の意味。地域独特の言葉は方言で、進む先の向きを表す〈方向〉とは言わないので合わない。"}, {"text": "この絵は、青みの方向が強い。", "explanation": "ここは〈色合い〉の意味。色味の濃さは色合いで表し、〈方向〉とは言わないので合わない。"}, {"text": "このギターは、音の方向が柔らかい。", "explanation": "ここは〈音色〉の意味。楽器の響きの質は音色で表し、進む先の向きを表す〈方向〉では合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cccbe2e-caf3-47c6-9a9a-d86ebe2bdee1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37912, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "方向", "is_correct": true, "explanation": "「方向がわからなくて」で、どちらへ進めばよいかという向きを表す名詞。主語として自然。"}, {"text": "値段", "is_correct": false, "explanation": "「値段がわからなくて道に迷ってしまった」は意味が通らない。価格を表す語で、道の文脈には合わない。"}, {"text": "会費", "is_correct": false, "explanation": "「会費がわからなくて道に迷った」は不自然で、迷った理由として成り立たない。"}, {"text": "人数", "is_correct": false, "explanation": "「人数がわからなくて道に迷った」は文として成り立たず、道に迷う理由にならない。"}], "explanations": {"方向": "「方向がわからなくて」で、どちらへ進めばよいかという向きを表す名詞。主語として自然。", "値段": "「値段がわからなくて道に迷ってしまった」は意味が通らない。価格を表す語で、道の文脈には合わない。", "会費": "「会費がわからなくて道に迷った」は不自然で、迷った理由として成り立たない。", "人数": "「人数がわからなくて道に迷った」は文として成り立たず、道に迷う理由にならない。"}, "sentence_index": 6, "correct_answer": "方向"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "その本の方向を読んで、とても感動した。", "explanation": "ここは〈内容〉の意味。文章の中身は内容と言い、進む先を表す〈方向〉では合わない。"}, {"text": "彼の方向を考えると、悲しくなった。", "explanation": "ここは〈気持ち〉の意味。人の心情は気持ちとして考えるもので、〈方向〉とは言わない。"}, {"text": "母は料理の方向を、順番にメモに書いてくれた。", "explanation": "ここは〈手順〉の意味。作業の順序は手順と言い、進む先の向きを表す〈方向〉では合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cccbe2e-caf3-47c6-9a9a-d86ebe2bdee1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37912, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "このバスは、駅の方向で向かいます。", "corrected_sentence": "このバスは、駅の方向へ向かいます。", "error_description": "「向かう」は行き先を「へ」で示す。「駅の方向で向かいます」の「で」は誤りで、正しくは「駅の方向へ」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cccbe2e-caf3-47c6-9a9a-d86ebe2bdee1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37912, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼は、会社の方向が変えようとした。", "corrected_sentence": "彼は、会社の方向を変えようとした。", "error_description": "「変える」は目的語に「を」をとる。「方向が変えよう」の「が」は誤りで、正しくは「方向を変えよう」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cccbe2e-caf3-47c6-9a9a-d86ebe2bdee1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37913, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「風の方向が急に変わって」の「が」。風の方向そのものが変わるという主語を示す。"}, {"text": "を", "is_correct": false, "explanation": "自動詞の「変わる」に「を」は使えず、「方向を変わって」は文が成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は場所や手段を表すので、方向が変わる主語にはならない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は相手や並列を表すので、「方向と急に変わって」では意味が通らない。"}], "correct_answer": "が", "explanations": {"が": "「風の方向が急に変わって」の「が」。風の方向そのものが変わるという主語を示す。", "を": "自動詞の「変わる」に「を」は使えず、「方向を変わって」は文が成り立たない。", "で": "「で」は場所や手段を表すので、方向が変わる主語にはならない。", "と": "「と」は相手や並列を表すので、「方向と急に変わって」では意味が通らない。"}, "error_tags": {"を": "目的語", "で": "場所・手段", "と": "相手・並列"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cccbe2e-caf3-47c6-9a9a-d86ebe2bdee1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37913, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「日本の方向に近づいています」の「に」。近づいていく先を示す。"}, {"text": "の", "is_correct": false, "explanation": "「日本の方向の近づいています」は動詞の対象を示せず、文として成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較の基準を示すので、台風が近づく先を表す文にはならない。"}, {"text": "を", "is_correct": false, "explanation": "「を」は対象を示すが、「近づく」は対象を取らないので文が成り立たない。"}], "correct_answer": "に", "explanations": {"に": "「日本の方向に近づいています」の「に」。近づいていく先を示す。", "の": "「日本の方向の近づいています」は動詞の対象を示せず、文として成り立たない。", "より": "「より」は比較の基準を示すので、台風が近づく先を表す文にはならない。", "を": "「を」は対象を示すが、「近づく」は対象を取らないので文が成り立たない。"}, "error_tags": {"の": "連体修飾", "より": "比較", "を": "目的語"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cccbe2e-caf3-47c6-9a9a-d86ebe2bdee1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37913, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "向いている方。進んでいく方。", "primary_collocate": null, "pronunciation": "ほうこう", "ipa": "hoːkoː", "syllable_count": 4, "sentences": [{"text": "駅は右の方向にあります。", "target_word": "方向", "complexity_tier": "T3", "furigana": "駅[えき]は右[みぎ]の方向[ほうこう]にあります。", "sentence_source": "generated"}, {"text": "風の方向が急に変わって、ヨットが大きくゆれた。", "target_word": "方向", "complexity_tier": "T3", "furigana": "風[かぜ]の方向[ほうこう]が急[きゅう]に変[か]わって、ヨットが大[おお]きくゆれた。", "sentence_source": "generated"}, {"text": "道に迷って、反対の方向へ歩いてしまった。", "target_word": "方向", "complexity_tier": "T3", "furigana": "道[みち]に迷[まよ]って、反対[はんたい]の方向[ほうこう]へ歩[ある]いてしまった。", "sentence_source": "generated"}, {"text": "地図を見て、行きたい方向を確かめた。", "target_word": "方向", "complexity_tier": "T3", "furigana": "地図[ちず]を見[み]て、行[い]きたい方向[ほうこう]を確[たし]かめた。", "sentence_source": "generated"}, {"text": "鳥たちは南の方向へ飛んでいきました。", "target_word": "方向", "complexity_tier": "T3", "furigana": "鳥[とり]たちは南[みなみ]の方向[ほうこう]へ飛[と]んでいきました。", "sentence_source": "generated"}, {"text": "先生は、私が進む方向についていっしょに考えてくれた。", "target_word": "方向", "complexity_tier": "T3", "furigana": "先生[せんせい]は、私[わたし]が進[すす]む方向[ほうこう]についていっしょに考[かんが]えてくれた。", "sentence_source": "generated"}, {"text": "音が聞こえた方向を見ると、犬が走っていた。", "target_word": "方向", "complexity_tier": "T3", "furigana": "音[おと]が聞[き]こえた方向[ほうこう]を見[み]ると、犬[いぬ]が走[はし]っていた。", "sentence_source": "generated"}, {"text": "台風は日本の方向に近づいています。", "target_word": "方向", "complexity_tier": "T3", "furigana": "台風[たいふう]は日本[にほん]の方向[ほうこう]に近[ちか]づいています。", "sentence_source": "generated"}, {"text": "二人は別々の方向に歩き出した。", "target_word": "方向", "complexity_tier": "T3", "furigana": "二人[ふたり]は別々[べつべつ]の方向[ほうこう]に歩[ある]き出[だ]した。", "sentence_source": "generated"}, {"text": "会社が進む方向が決まるまで、何度も話し合った。", "target_word": "方向", "complexity_tier": "T3", "furigana": "会社[かいしゃ]が進[すす]む方向[ほうこう]が決[き]まるまで、何度[なんど]も話[はな]し合[あ]った。", "sentence_source": "generated"}], "morphological_forms": [{"form": "方向", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "向いている先、進んでいく先を表す名詞。道・風・音・考えなどの向かう先", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2fddf5a-a756-46b3-bbac-8b346c4f6624') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37913, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "方向", "is_correct": true, "explanation": "「右の方向にあります」で、向いている側を示す名詞。位置を説明する文に合う。"}, {"text": "料金", "is_correct": false, "explanation": "「右の料金にあります」は意味をなさない。金額を表す語で、駅の位置には合わない。"}, {"text": "期限", "is_correct": false, "explanation": "「右の期限にあります」は不自然。時間の区切りを表す語で、場所の説明には使えない。"}, {"text": "天気", "is_correct": false, "explanation": "「右の天気にあります」は文として成り立たない。空模様の語で、駅の位置とは結びつかない。"}], "explanations": {"方向": "「右の方向にあります」で、向いている側を示す名詞。位置を説明する文に合う。", "料金": "「右の料金にあります」は意味をなさない。金額を表す語で、駅の位置には合わない。", "期限": "「右の期限にあります」は不自然。時間の区切りを表す語で、場所の説明には使えない。", "天気": "「右の天気にあります」は文として成り立たない。空模様の語で、駅の位置とは結びつかない。"}, "sentence_index": 0, "correct_answer": "方向"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "新しい機械の使い方の方向を、店員に聞いた。", "explanation": "ここは〈方法〉の意味。使い方のやり方は方法と言い、進む先の向きを表す〈方向〉では合わない。"}, {"text": "私は甘い方向が好きだ。", "explanation": "ここは〈好み〉の意味。味の好みは好みや好きなものとして表すので、〈方向〉とは言わない。"}, {"text": "ケーキ作りの方向を、順番に紙に書いた。", "explanation": "ここは〈手順〉の意味。作業の順序は手順と言い、進む先の向きを表す〈方向〉では合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cccbe2e-caf3-47c6-9a9a-d86ebe2bdee1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37913, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "方向", "is_correct": true, "explanation": "「音が聞こえた方向を見ると」で、音がしてきた先の側を示す名詞。見る対象として自然。"}, {"text": "金額", "is_correct": false, "explanation": "「音が聞こえた金額を見ると」は意味をなさない。お金の量を表す語で、音の文脈には合わない。"}, {"text": "人数", "is_correct": false, "explanation": "「音が聞こえた人数を見ると」は不自然で、犬が走っていたという場面につながらない。"}, {"text": "会費", "is_correct": false, "explanation": "「音が聞こえた会費を見ると」は文として成り立たず、音や犬の場面と結びつかない。"}], "explanations": {"方向": "「音が聞こえた方向を見ると」で、音がしてきた先の側を示す名詞。見る対象として自然。", "金額": "「音が聞こえた金額を見ると」は意味をなさない。お金の量を表す語で、音の文脈には合わない。", "人数": "「音が聞こえた人数を見ると」は不自然で、犬が走っていたという場面につながらない。", "会費": "「音が聞こえた会費を見ると」は文として成り立たず、音や犬の場面と結びつかない。"}, "sentence_index": 6, "correct_answer": "方向"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この薬の方向を、一日三回に分けて飲む。", "explanation": "ここは〈用量〉の意味。薬の分量は用量で表し、進む先の向きを表す〈方向〉とは言わないので合わない。"}, {"text": "あの歌手は若者の方向が高い。", "explanation": "ここは〈人気〉の意味。世間からの支持の高さは人気で表し、〈方向〉では表せない。"}, {"text": "この商品は価格の方向が高い。", "explanation": "ここは〈価格〉の意味。値段の高さは価格が高いと言い、〈方向〉とは言わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cccbe2e-caf3-47c6-9a9a-d86ebe2bdee1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37913, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ボールは、ゴールの方向で転がっていった。", "corrected_sentence": "ボールは、ゴールの方向へ転がっていった。", "error_description": "「転がる」は行き先を「へ」で示す。「方向で転がっていった」の「で」は誤りで、正しくは「方向へ」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cccbe2e-caf3-47c6-9a9a-d86ebe2bdee1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37913, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼は、会社の方向が変えようとした。", "corrected_sentence": "彼は、会社の方向を変えようとした。", "error_description": "「変える」は目的語に「を」をとる。「方向が変えよう」の「が」は誤りで、正しくは「方向を変えよう」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cccbe2e-caf3-47c6-9a9a-d86ebe2bdee1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37914, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「語り手が」で、語り手が古い物語を聞かせる主語になる。"}, {"text": "を", "is_correct": false, "explanation": "「語り手を」だと「物語を」と目的語が二つ並び、文が成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "「語り手で」は手段や場所を表し、ここで聞かせる主体を示せないので合わない。"}, {"text": "から", "is_correct": false, "explanation": "「語り手から」は起点を表し、語り手が物語を聞かせる主体にならないので合わない。"}], "correct_answer": "が", "explanations": {"が": "「語り手が」で、語り手が古い物語を聞かせる主語になる。", "を": "「語り手を」だと「物語を」と目的語が二つ並び、文が成り立たない。", "で": "「語り手で」は手段や場所を表し、ここで聞かせる主体を示せないので合わない。", "から": "「語り手から」は起点を表し、語り手が物語を聞かせる主体にならないので合わない。"}, "error_tags": {"を": "目的語の重複", "で": "手段・場所", "から": "起点"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '807bae3e-67f7-4a5e-9415-bec4623c0c7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37914, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「語り手の話し方」と名詞をつなぐ所有の「の」で、語り手の話し方を指す。"}, {"text": "に", "is_correct": false, "explanation": "「語り手に話し方」は受け手を表し、話し方の持ち主を示せないので合わない。"}, {"text": "を", "is_correct": false, "explanation": "「語り手を話し方が」では目的語が重なり、「うまい」の主語を示せないので合わない。"}, {"text": "と", "is_correct": false, "explanation": "「語り手と話し方」は並べる意味になり、語り手の話し方という所属関係を示せないので合わない。"}], "correct_answer": "の", "explanations": {"の": "「語り手の話し方」と名詞をつなぐ所有の「の」で、語り手の話し方を指す。", "に": "「語り手に話し方」は受け手を表し、話し方の持ち主を示せないので合わない。", "を": "「語り手を話し方が」では目的語が重なり、「うまい」の主語を示せないので合わない。", "と": "「語り手と話し方」は並べる意味になり、語り手の話し方という所属関係を示せないので合わない。"}, "error_tags": {"に": "受け手", "へ": "方向", "を": "目的語"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '807bae3e-67f7-4a5e-9415-bec4623c0c7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37914, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "昔話や物語を人に語って聞かせる人のこと。", "primary_collocate": null, "pronunciation": "かたりて", "ipa": "kataɾite", "syllable_count": 4, "sentences": [{"text": "あの語り手は、昔話を面白く話してくれる。", "target_word": "語り手", "complexity_tier": "T3", "furigana": "あの語[かた]り手[て]は、昔話[むかしばなし]を面白[おもしろ]く話[はな]してくれる。", "sentence_source": "generated"}, {"text": "祭りの夜、村の語り手が古い物語を聞かせた。", "target_word": "語り手", "complexity_tier": "T3", "furigana": "祭[まつ]りの夜[よる]、村[むら]の語[かた]り手[て]が古[ふる]い物語[ものがたり]を聞[き]かせた。", "sentence_source": "generated"}, {"text": "語り手の声が静かで、子どもたちはすぐに眠った。", "target_word": "語り手", "complexity_tier": "T3", "furigana": "語[かた]り手[て]の声[こえ]が静[しず]かで、子[こ]どもたちはすぐに眠[ねむ]った。", "sentence_source": "generated"}, {"text": "彼は有名な語り手で、各地から話を頼まれる。", "target_word": "語り手", "complexity_tier": "T3", "furigana": "彼[かれ]は有名[ゆうめい]な語[かた]り手[て]で、各地[かくち]から話[はなし]を頼[たの]まれる。", "sentence_source": "generated"}, {"text": "語り手が間を置くと、会場は静かになった。", "target_word": "語り手", "complexity_tier": "T3", "furigana": "語[かた]り手[て]が間[ま]を置[お]くと、会場[かいじょう]は静[しず]かになった。", "sentence_source": "generated"}, {"text": "おばあさんは村で一番の語り手だった。", "target_word": "語り手", "complexity_tier": "T3", "furigana": "おばあさんは村[むら]で一番[いちばん]の語[かた]り手[て]だった。", "sentence_source": "generated"}, {"text": "図書館に語り手を呼んで、読み聞かせの会を開いた。", "target_word": "語り手", "complexity_tier": "T3", "furigana": "図書館[としょかん]に語[かた]り手[て]を呼[よ]んで、読[よ]み聞[き]かせの会[かい]を開[ひら]いた。", "sentence_source": "generated"}, {"text": "語り手の話し方がうまいので、短い話でも心に残る。", "target_word": "語り手", "complexity_tier": "T3", "furigana": "語[かた]り手[て]の話[はな]し方[かた]がうまいので、短[みじか]い話[はなし]でも心[こころ]に残[のこ]る。", "sentence_source": "generated"}, {"text": "若い語り手は、祖父から昔の話を教わった。", "target_word": "語り手", "complexity_tier": "T3", "furigana": "若[わか]い語[かた]り手[て]は、祖父[そふ]から昔[むかし]の話[はなし]を教[おし]わった。", "sentence_source": "generated"}, {"text": "その語り手は笑いながら、怖い話を始めた。", "target_word": "語り手", "complexity_tier": "T3", "furigana": "その語[かた]り手[て]は笑[わら]いながら、怖[こわ]い話[はなし]を始[はじ]めた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "語り手", "label": "基本形"}], "register": "中立", "sense_fingerprint": "昔話や物語を人に語って聞かせる人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8b339ca1-4d9a-445d-b929-d025d7d80de9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37914, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "語り手", "is_correct": true, "explanation": "「語り手」は昔話を語って聞かせる人を指すので、「話してくれる」の主語に合う。"}, {"text": "聞き手", "is_correct": false, "explanation": "「聞き手」は話を聞く側なので、昔話を面白く話す主語にはならない。"}, {"text": "観客", "is_correct": false, "explanation": "「観客」は見物する人で、話をして聞かせる役ではないので合わない。"}, {"text": "批評家", "is_correct": false, "explanation": "「批評家」は作品を評価する人で、昔話を語る役ではないので合わない。"}], "explanations": {"語り手": "「語り手」は昔話を語って聞かせる人を指すので、「話してくれる」の主語に合う。", "聞き手": "「聞き手」は話を聞く側なので、昔話を面白く話す主語にはならない。", "観客": "「観客」は見物する人で、話をして聞かせる役ではないので合わない。", "批評家": "「批評家」は作品を評価する人で、昔話を語る役ではないので合わない。"}, "sentence_index": 0, "correct_answer": "語り手"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "会議で語り手が長々と意見を述べたので、みんなうんざりした。", "explanation": "ここは〈話し手〉（発言者）の意味。「語り手」は物語を語る人を指すので、会議での発言者には使わない。"}, {"text": "その語り手は観客の前で新曲を歌い、大きな拍手を受けた。", "explanation": "ここは〈歌い手〉の意味。「語り手」は話や物語を語る人なので、歌を歌う人には合わない。"}, {"text": "会議の内容は、語り手が正確に英語へ訳した。", "explanation": "ここは〈通訳〉の意味。「語り手」は話を語って聞かせる人で、言葉を訳す人ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '807bae3e-67f7-4a5e-9415-bec4623c0c7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37914, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "語り手", "is_correct": true, "explanation": "「図書館に語り手を呼んで」は、読み聞かせを担当する語り手を招く意味に合う。"}, {"text": "絵本", "is_correct": false, "explanation": "「絵本」は人のように呼んで来てもらう対象ではないので合わない。"}, {"text": "本棚", "is_correct": false, "explanation": "「本棚」は呼んで会を担当してもらうものではないので合わない。"}, {"text": "書架", "is_correct": false, "explanation": "「書架」は本を置く棚で、読み聞かせの担い手として呼ぶことはできないので合わない。"}], "explanations": {"語り手": "「図書館に語り手を呼んで」は、読み聞かせを担当する語り手を招く意味に合う。", "絵本": "「絵本」は人のように呼んで来てもらう対象ではないので合わない。", "本棚": "「本棚」は呼んで会を担当してもらうものではないので合わない。", "書架": "「書架」は本を置く棚で、読み聞かせの担い手として呼ぶことはできないので合わない。"}, "sentence_index": 6, "correct_answer": "語り手"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この授業では、語り手が生徒に九九を分かりやすく教えた。", "explanation": "ここは〈教師〉の意味。「語り手」は話を語る人で、授業で教える人ではないので合わない。"}, {"text": "雨の道でも、語り手はゆっくり車を走らせた。", "explanation": "ここは〈運転手〉の意味。車を走らせるのは運転手で、「語り手」には合わない。"}, {"text": "夕焼けの村を、語り手は何枚も写真に撮った。", "explanation": "ここは〈写真家〉の意味。写真を撮る人を指すので、「語り手」とは別の役割になる。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '807bae3e-67f7-4a5e-9415-bec4623c0c7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37914, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "夜の集会で、語り手を話を子どもたちが静かに聞いた。", "corrected_sentence": "夜の集会で、語り手の話を子どもたちが静かに聞いた。", "error_description": "「語り手」に続く助詞は「の」が正しく、「語り手の話」と名詞をつなぐ形になる。「を」にすると語り手が目的語になり、文の形が崩れる。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '807bae3e-67f7-4a5e-9415-bec4623c0c7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37914, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "語り手は、子どもたちに昔話を聞いて聞かせた。", "corrected_sentence": "語り手は、子どもたちに昔話を語って聞かせた。", "error_description": "「語り手」が行うのは「語る」ことなので、「語って聞かせた」が正しい。「聞いて」にすると語り手の役割と合わず、不自然になる。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '807bae3e-67f7-4a5e-9415-bec4623c0c7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37915, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「語り手が」で、「私」を名乗る語り手が主語となり、「読者は…分かる」の理由になる。"}, {"text": "を", "is_correct": false, "explanation": "「語り手を」だと目的語になり、「「私」なので」とつながらない。"}, {"text": "へ", "is_correct": false, "explanation": "「語り手へ「私」なので」は方向を表し、理由を示す節として成り立たないので合わない。"}, {"text": "に", "is_correct": false, "explanation": "「語り手に」は受け手を表し、一人称であることの説明として意味が通らない。"}], "correct_answer": "が", "explanations": {"が": "「語り手が」で、「私」を名乗る語り手が主語となり、「読者は…分かる」の理由になる。", "を": "「語り手を」だと目的語になり、「「私」なので」とつながらない。", "へ": "「語り手へ「私」なので」は方向を表し、理由を示す節として成り立たないので合わない。", "に": "「語り手に」は受け手を表し、一人称であることの説明として意味が通らない。"}, "error_tags": {"を": "目的語", "へ": "方向", "に": "受け手"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '807bae3e-67f7-4a5e-9415-bec4623c0c7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37915, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「語り手の言葉」と所有の「の」で続け、語り手が話す言葉を指す。"}, {"text": "で", "is_correct": false, "explanation": "「語り手で言葉をすべて信じると」は場所・手段を表すが、「信じる」の対象を示せず不自然。"}, {"text": "ね", "is_correct": false, "explanation": "「語り手ね言葉を」のように文中に終助詞が来ると文が成り立たない。"}, {"text": "か", "is_correct": false, "explanation": "「か」は選択を表すが、「語り手か言葉を」では選ぶ相手が揃わず、「すべて信じる」と続けると不自然。"}], "correct_answer": "の", "explanations": {"の": "「語り手の言葉」と所有の「の」で続け、語り手が話す言葉を指す。", "で": "「語り手で言葉をすべて信じると」は場所・手段を表すが、「信じる」の対象を示せず不自然。", "ね": "「語り手ね言葉を」のように文中に終助詞が来ると文が成り立たない。", "か": "「か」は選択を表すが、「語り手か言葉を」では選ぶ相手が揃わず、「すべて信じる」と続けると不自然。"}, "error_tags": {"で": "場所・手段", "ね": "終助詞", "か": "選択"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '807bae3e-67f7-4a5e-9415-bec4623c0c7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37915, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "話の中での、話す役割をする人。物語を進めるために、出来事や気持ちを説明する人。", "primary_collocate": null, "pronunciation": "かたりて", "ipa": "kataɾite", "syllable_count": 4, "sentences": [{"text": "この小説の語り手は、十歳の少女だ。", "target_word": "語り手", "complexity_tier": "T3", "furigana": "この小説[しょうせつ]の語[かた]り手[て]は、十歳[じゅっさい]の少女[しょうじょ]だ。", "sentence_source": "generated"}, {"text": "語り手が「私」なので、読者は彼女の気持ちがよく分かる。", "target_word": "語り手", "complexity_tier": "T3", "furigana": "語[かた]り手[て]が「私[わたし]」なので、読者[どくしゃ]は彼女[かのじょ]の気持[きも]ちがよく分[わ]かる。", "sentence_source": "generated"}, {"text": "物語の語り手は、事件のあとで初めて真実を知る。", "target_word": "語り手", "complexity_tier": "T3", "furigana": "物語[ものがたり]の語[かた]り手[て]は、事件[じけん]のあとで初[はじ]めて真実[しんじつ]を知[し]る。", "sentence_source": "generated"}, {"text": "映画では、年を取った主人公が語り手になっている。", "target_word": "語り手", "complexity_tier": "T3", "furigana": "映画[えいが]では、年[とし]を取[と]った主人公[しゅじんこう]が語[かた]り手[て]になっている。", "sentence_source": "generated"}, {"text": "語り手が途中で変わるので、少し読みにくい。", "target_word": "語り手", "complexity_tier": "T3", "furigana": "語[かた]り手[て]が途中[とちゅう]で変[か]わるので、少[すこ]し読[よ]みにくい。", "sentence_source": "generated"}, {"text": "語り手は出来事だけでなく、自分の気持ちも説明する。", "target_word": "語り手", "complexity_tier": "T3", "furigana": "語[かた]り手[て]は出来事[できごと]だけでなく、自分[じぶん]の気持[きも]ちも説明[せつめい]する。", "sentence_source": "generated"}, {"text": "この作品では猫が語り手を務める。", "target_word": "語り手", "complexity_tier": "T3", "furigana": "この作品[さくひん]では猫[ねこ]が語[かた]り手[て]を務[つと]める。", "sentence_source": "generated"}, {"text": "語り手の言葉をすべて信じると、結末に驚くだろう。", "target_word": "語り手", "complexity_tier": "T3", "furigana": "語[かた]り手[て]の言葉[ことば]をすべて信[しん]じると、結末[けつまつ]に驚[おどろ]くだろう。", "sentence_source": "generated"}, {"text": "授業で、物語の語り手はだれかを考えた。", "target_word": "語り手", "complexity_tier": "T3", "furigana": "授業[じゅぎょう]で、物語[ものがたり]の語[かた]り手[て]はだれかを考[かんが]えた。", "sentence_source": "generated"}, {"text": "語り手が子どものころの話から始まるので、親しみやすい。", "target_word": "語り手", "complexity_tier": "T3", "furigana": "語[かた]り手[て]が子[こ]どものころの話[はなし]から始[はじ]まるので、親[した]しみやすい。", "sentence_source": "generated"}], "morphological_forms": [{"form": "語り手", "label": "基本形"}], "register": "中立", "sense_fingerprint": "小説や映画の中で出来事や気持ちを説明して話を進める役の人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8b339ca1-4d9a-445d-b929-d025d7d80de9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37915, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "語り手", "is_correct": true, "explanation": "「語り手」は作品の中で物語を進める人を指し、「この小説の語り手は十歳の少女だ」の主語に合う。"}, {"text": "聞き手", "is_correct": false, "explanation": "「聞き手」は話を聞く側で、作品の中で物語を進める役ではないので合わない。"}, {"text": "挿絵画家", "is_correct": false, "explanation": "「挿絵画家」は絵を描く人で、物語の語りの役割を指さないので合わない。"}, {"text": "出版社", "is_correct": false, "explanation": "「出版社」は会社で、人物の属性を述べる主語としては意味が通らないので合わない。"}], "explanations": {"語り手": "「語り手」は作品の中で物語を進める人を指し、「この小説の語り手は十歳の少女だ」の主語に合う。", "聞き手": "「聞き手」は話を聞く側で、作品の中で物語を進める役ではないので合わない。", "挿絵画家": "「挿絵画家」は絵を描く人で、物語の語りの役割を指さないので合わない。", "出版社": "「出版社」は会社で、人物の属性を述べる主語としては意味が通らないので合わない。"}, "sentence_index": 0, "correct_answer": "語り手"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "夕方の台所で、語り手は魚を三枚におろした。", "explanation": "ここは〈料理人〉の意味。魚をおろすのは料理人の仕事で、「語り手」は物語を進める役なので合わない。"}, {"text": "コンサートでは、語り手が観客の前で新曲を歌った。", "explanation": "ここは〈歌い手〉の意味。「語り手」は話を進める役で、歌を歌う人ではないので合わない。"}, {"text": "難しい詩は、語り手が一行ずつ日本語に訳した。", "explanation": "ここは〈翻訳家〉の意味。「語り手」は物語を進める役で、外国語の詩を訳す人を指さないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '807bae3e-67f7-4a5e-9415-bec4623c0c7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37915, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "語り手", "is_correct": true, "explanation": "「語り手を務める」は作品の中で物語を進める役を担うことで、猫がその役を務めるという文に合う。"}, {"text": "字幕", "is_correct": false, "explanation": "「字幕」は務める役ではないので、「猫が字幕を務める」は意味が通らない。"}, {"text": "主題歌", "is_correct": false, "explanation": "「主題歌」は務める役ではないので、「猫が主題歌を務める」は合わない。"}, {"text": "照明", "is_correct": false, "explanation": "「照明」は務める役ではないので、「猫が照明を務める」は合わない。"}], "explanations": {"語り手": "「語り手を務める」は作品の中で物語を進める役を担うことで、猫がその役を務めるという文に合う。", "字幕": "「字幕」は務める役ではないので、「猫が字幕を務める」は意味が通らない。", "主題歌": "「主題歌」は務める役ではないので、「猫が主題歌を務める」は合わない。", "照明": "「照明」は務める役ではないので、「猫が照明を務める」は合わない。"}, "sentence_index": 6, "correct_answer": "語り手"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "その教室では、語り手が生徒に計算問題を出して採点した。", "explanation": "ここは〈教師〉の意味。「語り手」は話を進める役で、授業で問題を出して採点する人ではないので合わない。"}, {"text": "早朝の駅前で、語り手はタクシーを走らせて客を乗せた。", "explanation": "ここは〈運転手〉の意味。タクシーを走らせて客を乗せるのは運転手で、「語り手」には合わない。"}, {"text": "窯の前で、語り手は茶碗を一つずつ焼き上げた。", "explanation": "ここは〈陶芸家〉の意味。茶碗を焼き上げる人を指すので、「語り手」の役割とは別になる。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '807bae3e-67f7-4a5e-9415-bec4623c0c7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37915, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この小説の語り手を、主人公の気持ちを説明する。", "corrected_sentence": "この小説の語り手は、主人公の気持ちを説明する。", "error_description": "「語り手」が主語として「説明する」動作をする文なので、「は」が正しい。「を」にすると語り手が目的語になり、文の主語がなくなって不自然になる。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '807bae3e-67f7-4a5e-9415-bec4623c0c7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37915, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "語り手の、読者に出来事の背景を説明する。", "corrected_sentence": "語り手は、読者に出来事の背景を説明する。", "error_description": "「語り手」が主語なので「は」が必要。「の」では文に主語がなく、「説明する」の主体が定まらないので不自然になる。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '807bae3e-67f7-4a5e-9415-bec4623c0c7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37916, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「間を取る」の「を」。取る対象として間を示し、「取ることが大切だ」と続く。"}, {"text": "が", "is_correct": false, "explanation": "「間が取る」は主語と動詞がつながらず、「取る」の対象を示せない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は場所や手段を表すので、「間で取る」は取る対象を示せない。"}, {"text": "の", "is_correct": false, "explanation": "「の」は名詞をつなぐ助詞で、「取る」の対象を示すことはできない。"}], "correct_answer": "を", "explanations": {"を": "「間を取る」の「を」。取る対象として間を示し、「取ることが大切だ」と続く。", "が": "「間が取る」は主語と動詞がつながらず、「取る」の対象を示せない。", "で": "「で」は場所や手段を表すので、「間で取る」は取る対象を示せない。", "の": "「の」は名詞をつなぐ助詞で、「取る」の対象を示すことはできない。"}, "error_tags": {"が": "主語", "で": "場所・手段", "の": "連体修飾"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cccbe2e-caf3-47c6-9a9a-d86ebe2bdee1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37916, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「間がよくて聞きやすい」の「が」。話し方の間の良さを主語として示す。"}, {"text": "に", "is_correct": false, "explanation": "「間によくて」は形容詞の主語を示せず、「よい」とつながらない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や相手を表すので、「間とよくて」は意味が通らない。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を表すので、「間からよくて」では話し方の評価として成り立たない。"}], "correct_answer": "が", "explanations": {"が": "「間がよくて聞きやすい」の「が」。話し方の間の良さを主語として示す。", "に": "「間によくて」は形容詞の主語を示せず、「よい」とつながらない。", "と": "「と」は並列や相手を表すので、「間とよくて」は意味が通らない。", "から": "「から」は起点を表すので、「間からよくて」では話し方の評価として成り立たない。"}, "error_tags": {"に": "位置・方向", "と": "並列・相手", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cccbe2e-caf3-47c6-9a9a-d86ebe2bdee1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37916, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "話や動作のあいだの、時間のとぎれ。", "primary_collocate": null, "pronunciation": "ま", "ipa": "ma", "syllable_count": 1, "sentences": [{"text": "彼は少し間を置いてから、答えを話し始めた。", "target_word": "間", "complexity_tier": "T3", "furigana": "彼[かれ]は少[すこ]し間[ま]を置[お]いてから、答[こた]えを話[はな]し始[はじ]めた。", "sentence_source": "generated"}, {"text": "話すときは、相手が聞きやすいように間を取ることが大切だ。", "target_word": "間", "complexity_tier": "T3", "furigana": "話[はな]すときは、相手[あいて]が聞[き]きやすいように間[ま]を取[と]ることが大切[たいせつ]だ。", "sentence_source": "generated"}, {"text": "落語家は、客を笑わせるために絶妙な間で話した。", "target_word": "間", "complexity_tier": "T3", "furigana": "落語家[らくごか]は、客[きゃく]を笑[わら]わせるために絶妙[ぜつみょう]な間[ま]で話[はな]した。", "sentence_source": "generated"}, {"text": "会話に間があいて、気まずい空気になった。", "target_word": "間", "complexity_tier": "T3", "furigana": "会話[かいわ]に間[ま]があいて、気[き]まずい空気[くうき]になった。", "sentence_source": "generated"}, {"text": "出発まで少し間があるから、お茶を飲もう。", "target_word": "間", "complexity_tier": "T3", "furigana": "出発[しゅっぱつ]まで少[すこ]し間[ま]があるから、お茶[ちゃ]を飲[の]もう。", "sentence_source": "generated"}, {"text": "兄はいつも間が悪くて、大事な電話に出られない。", "target_word": "間", "complexity_tier": "T3", "furigana": "兄[あに]はいつも間[ま]が悪[わる]くて、大事[だいじ]な電話[でんわ]に出[で]られない。", "sentence_source": "generated"}, {"text": "返事をする前に、彼は不自然な間をあけた。", "target_word": "間", "complexity_tier": "T3", "furigana": "返事[へんじ]をする前[まえ]に、彼[かれ]は不自然[ふしぜん]な間[ま]をあけた。", "sentence_source": "generated"}, {"text": "彼女の話し方は、間がよくて聞きやすい。", "target_word": "間", "complexity_tier": "T3", "furigana": "彼女[かのじょ]の話[はな]し方[かた]は、間[ま]がよくて聞[き]きやすい。", "sentence_source": "generated"}, {"text": "間をあけずに質問されて、うまく答えられなかった。", "target_word": "間", "complexity_tier": "T3", "furigana": "間[ま]をあけずに質問[しつもん]されて、うまく答[こた]えられなかった。", "sentence_source": "generated"}, {"text": "漫才では、笑いをとるために間の取り方が大切だ。", "target_word": "間", "complexity_tier": "T3", "furigana": "漫才[まんざい]では、笑[わら]いをとるために間[ま]の取[と]り方[かた]が大切[たいせつ]だ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "間", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "「ま」と読む、ものとものの間の時間的なへだたり・とぎれ。間を置く、間が悪いなど", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 2 above tier T1: 3 words above tier T1 (max 2): 落語 (Zipf 3.86), 笑わせる (Zipf 3.93), 絶妙 (Zipf 3.79)']::text[], 'd2fddf5a-a756-46b3-bbac-8b346c4f6624') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37916, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "間", "is_correct": true, "explanation": "「少し間を置いてから」で、話す前のとぎれを表す「ま」の名詞。「間を置く」として自然に続く。"}, {"text": "息", "is_correct": false, "explanation": "「少し息を置いてから」は言わない。「息をつく」とは言えても、「息を置く」は不自然。"}, {"text": "声", "is_correct": false, "explanation": "「少し声を置いてから」は言えず、話を始める前のとぎれを表せない。"}, {"text": "色", "is_correct": false, "explanation": "「少し色を置いてから」は意味をなさない。話のとぎれを表す語ではない。"}], "explanations": {"間": "「少し間を置いてから」で、話す前のとぎれを表す「ま」の名詞。「間を置く」として自然に続く。", "息": "「少し息を置いてから」は言わない。「息をつく」とは言えても、「息を置く」は不自然。", "声": "「少し声を置いてから」は言えず、話を始める前のとぎれを表せない。", "色": "「少し色を置いてから」は意味をなさない。話のとぎれを表す語ではない。"}, "sentence_index": 0, "correct_answer": "間"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は間が強くて、いつも試験に受かる。", "explanation": "ここは〈運〉の意味。運の強さは運が強いと言い、とぎれを表す〈間〉では合わない。"}, {"text": "この作業は、間が一時間もかかる。", "explanation": "ここは〈時間〉の意味。作業にかかる長さは時間で表し、話のとぎれを表す〈間〉では言わない。"}, {"text": "会話に期間があいて、気まずい空気になった。", "explanation": "ここは〈期間〉の意味。区切られた時期は期間と言い、会話のとぎれは〈間〉で表すので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cccbe2e-caf3-47c6-9a9a-d86ebe2bdee1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37916, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "間", "is_correct": true, "explanation": "「不自然な間をあけた」で、返事の前のとぎれを表す「ま」の名詞。「あけた」の対象になる。"}, {"text": "数", "is_correct": false, "explanation": "「不自然な数をあけた」は言えず、話のとぎれを表せない。"}, {"text": "音", "is_correct": false, "explanation": "「不自然な音をあけた」は不自然で、返事の前のとぎれという意味にならない。"}, {"text": "点", "is_correct": false, "explanation": "「不自然な点をあけた」は言えず、話の流れのとぎれを表す語ではない。"}], "explanations": {"間": "「不自然な間をあけた」で、返事の前のとぎれを表す「ま」の名詞。「あけた」の対象になる。", "数": "「不自然な数をあけた」は言えず、話のとぎれを表せない。", "音": "「不自然な音をあけた」は不自然で、返事の前のとぎれという意味にならない。", "点": "「不自然な点をあけた」は言えず、話の流れのとぎれを表す語ではない。"}, "sentence_index": 6, "correct_answer": "間"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "漫才では、笑いをとるために雰囲気の取り方が大切だ。", "explanation": "ここは〈雰囲気〉の意味。場の空気の感じは雰囲気で表し、話のとぎれを表す〈間〉の取り方とは言わない。"}, {"text": "彼は話すときに余裕をあけて、聞きやすくする。", "explanation": "ここは〈余裕〉の意味。心や時間のゆとりは余裕で表し、話のとぎれには〈間〉を使うので合わない。"}, {"text": "二つの建物の間に、小さな公園がある。", "explanation": "ここは〈空間〉の意味（読みは「あいだ」）。場所のすきまは、時間のとぎれを表す〈間〉とは別の語義。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cccbe2e-caf3-47c6-9a9a-d86ebe2bdee1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37916, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "発表の前に、深呼吸して間で取った。", "corrected_sentence": "発表の前に、深呼吸して間を取った。", "error_description": "「取る」は目的語に「を」をとる。「間で取った」の「で」は誤りで、正しくは「間を取った」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cccbe2e-caf3-47c6-9a9a-d86ebe2bdee1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37916, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼は、話の間を水を飲んだ。", "corrected_sentence": "彼は、話の間に水を飲んだ。", "error_description": "「話の間に」で、話の途中のとぎれという時点を「に」で示す。「間を水を飲んだ」の「を」は誤りで、正しくは「間に」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cccbe2e-caf3-47c6-9a9a-d86ebe2bdee1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37918, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "目的語を示す。「名刺の交換をした」の形で正しい。"}, {"text": "が", "is_correct": false, "explanation": "主語を示す。「交換が」は交換の対象を示さず、「交換をした」の形に合わない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す。「交換へ」は動作の方向として不自然。"}, {"text": "から", "is_correct": false, "explanation": "起点を示す。「交換から」は「交換をした」の文脈では意味が通らない。"}], "correct_answer": "を", "explanations": {"を": "目的語を示す。「名刺の交換をした」の形で正しい。", "が": "主語を示す。「交換が」は交換の対象を示さず、「交換をした」の形に合わない。", "へ": "方向を示す。「交換へ」は動作の方向として不自然。", "から": "起点を示す。「交換から」は「交換をした」の文脈では意味が通らない。"}, "error_tags": {"を": "目的語を示す。「名刺の交換をした」の形で正しい。", "が": "主語を示す。「交換が」は交換の対象を示さず、「交換をした」の形に合わない。", "へ": "方向を示す。「交換へ」は動作の方向として不自然。", "から": "起点を示す。「交換から」は「交換をした」の文脈では意味が通らない。"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cccbe2e-caf3-47c6-9a9a-d86ebe2bdee1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37918, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "目的語を示す。「本を交換して」の形で正しい。"}, {"text": "より", "is_correct": false, "explanation": "比較を示す。「本より交換して」は文脈に合わない。"}, {"text": "の", "is_correct": false, "explanation": "連体修飾を示す。「本の交換して」は述語として成り立たない。"}, {"text": "が", "is_correct": false, "explanation": "主語を示す。「本が交換して読んでいる」は本が自ら交換する意味になり不自然。"}], "correct_answer": "を", "explanations": {"を": "目的語を示す。「本を交換して」の形で正しい。", "より": "比較を示す。「本より交換して」は文脈に合わない。", "の": "連体修飾を示す。「本の交換して」は述語として成り立たない。", "が": "主語を示す。「本が交換して読んでいる」は本が自ら交換する意味になり不自然。"}, "error_tags": {"を": "目的語を示す。「本を交換して」の形で正しい。", "より": "比較を示す。「本より交換して」は文脈に合わない。", "の": "連体修飾を示す。「本の交換して」は述語として成り立たない。", "が": "主語を示す。「本が交換して読んでいる」は不自然。"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cccbe2e-caf3-47c6-9a9a-d86ebe2bdee1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37918, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "何かをあげたりもらったりすること。", "primary_collocate": null, "pronunciation": "こうかん", "ipa": "koːkaɴ", "syllable_count": 4, "sentences": [{"text": "友だちとクリスマスのプレゼントの交換をした。", "target_word": "交換", "complexity_tier": "T3", "furigana": "友[とも]だちとクリスマスのプレゼントの交換[こうかん]をした。", "sentence_source": "generated"}, {"text": "初めて会った人と、名刺の交換をした。", "target_word": "交換", "complexity_tier": "T3", "furigana": "初[はじ]めて会[あ]った人[ひと]と、名刺[めいし]の交換[こうかん]をした。", "sentence_source": "generated"}, {"text": "旅行で知り合った友だちと、連絡先を交換した。", "target_word": "交換", "complexity_tier": "T3", "furigana": "旅行[りょこう]で知[し]り合[あ]った友[とも]だちと、連絡先[れんらくさき]を交換[こうかん]した。", "sentence_source": "generated"}, {"text": "手紙の交換を、もう十年も続けている。", "target_word": "交換", "complexity_tier": "T3", "furigana": "手紙[てがみ]の交換[こうかん]を、もう十年[じゅうねん]も続[つづ]けている。", "sentence_source": "generated"}, {"text": "私たちは旅行先で買ったお菓子を友だちと交換して、楽しく食べた。", "target_word": "交換", "complexity_tier": "T3", "furigana": "私[わたし]たちは旅行先[りょこうさき]で買[か]ったお菓子[かし]を友[とも]だちと交換[こうかん]して、楽[たの]しく食[た]べた。", "sentence_source": "generated"}, {"text": "留学生と年賀状を交換するのが、毎年の楽しみだ。", "target_word": "交換", "complexity_tier": "T3", "furigana": "留学生[りゅうがくせい]と年賀状[ねんがじょう]を交換[こうかん]するのが、毎年[まいとし]の楽[たの]しみだ。", "sentence_source": "generated"}, {"text": "会議では、自由に意見を交換することができた。", "target_word": "交換", "complexity_tier": "T3", "furigana": "会議[かいぎ]では、自由[じゆう]に意見[いけん]を交換[こうかん]することができた。", "sentence_source": "generated"}, {"text": "姉とは、読み終わった本を交換して読んでいる。", "target_word": "交換", "complexity_tier": "T3", "furigana": "姉[あね]とは、読[よ]み終[お]わった本[ほん]を交換[こうかん]して読[よ]んでいる。", "sentence_source": "generated"}, {"text": "出会った二人は、住所を交換して別れた。", "target_word": "交換", "complexity_tier": "T3", "furigana": "出会[であ]った二人[ふたり]は、住所[じゅうしょ]を交換[こうかん]して別[わか]れた。", "sentence_source": "generated"}, {"text": "誕生日に、クラスの全員でカードの交換をした。", "target_word": "交換", "complexity_tier": "T3", "furigana": "誕生日[たんじょうび]に、クラスの全員[ぜんいん]でカードの交換[こうかん]をした。", "sentence_source": "generated"}], "morphological_forms": [{"form": "交換する", "label": "終止形"}, {"form": "交換します", "label": "丁寧形"}, {"form": "交換した", "label": "過去形"}, {"form": "交換して", "label": "て形"}, {"form": "交換しない", "label": "否定形"}], "register": "neutral", "sense_fingerprint": "贈り物・手紙・情報・連絡先などを互いにあげたりもらったりすること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2fddf5a-a756-46b3-bbac-8b346c4f6624') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37918, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "交換", "is_correct": true, "explanation": "「プレゼントを互いにやりとりする」の意味で、「プレゼントの交換をした」は自然な組み合わせ。"}, {"text": "散歩", "is_correct": false, "explanation": "「プレゼントの散歩」は意味が通らない。散歩は歩いて出かけること。"}, {"text": "出発", "is_correct": false, "explanation": "「プレゼントの出発」は不自然。出発は場所を離れることで、物には使わない。"}, {"text": "運動", "is_correct": false, "explanation": "「プレゼントの運動」は意味が通らない。運動は体を動かすこと。"}], "explanations": {"交換": "「プレゼントを互いにやりとりする」の意味で、「プレゼントの交換をした」は自然な組み合わせ。", "散歩": "「プレゼントの散歩」は意味が通らない。散歩は歩いて出かけること。", "出発": "「プレゼントの出発」は不自然。出発は場所を離れることで、物には使わない。", "運動": "「プレゼントの運動」は意味が通らない。運動は体を動かすこと。"}, "sentence_index": 0, "correct_answer": "交換"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "借りていた本を、図書館に交換した。", "explanation": "ここは〈返却〉の意味。交換は互いに物をやりとりすることなので、借りた本を返すだけの場合には合わない。"}, {"text": "祖父は使わなくなった自転車を、弟に無料で交換した。", "explanation": "ここは〈譲渡〉の意味。相手から何も受け取らずに渡すことは、交換ではなく譲ると言う。"}, {"text": "途中の駅で、電車を交換した。", "explanation": "ここは〈乗り換え〉の意味。乗り物を替えることは乗り換えと言い、交換とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cccbe2e-caf3-47c6-9a9a-d86ebe2bdee1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37918, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "交換", "is_correct": true, "explanation": "「意見を互いにやりとりする」の意味で、「意見を交換することができた」は自然。"}, {"text": "洗濯", "is_correct": false, "explanation": "「意見を洗濯」は意味が通らない。洗濯は衣類を洗うこと。"}, {"text": "呼吸", "is_correct": false, "explanation": "「意見を呼吸」は意味が通らない。呼吸は息をすること。"}, {"text": "点火", "is_correct": false, "explanation": "「意見を点火」は意味が通らない。点火は火をつけること。"}], "explanations": {"交換": "「意見を互いにやりとりする」の意味で、「意見を交換することができた」は自然。", "洗濯": "「意見を洗濯」は意味が通らない。洗濯は衣類を洗うこと。", "呼吸": "「意見を呼吸」は意味が通らない。呼吸は息をすること。", "点火": "「意見を点火」は意味が通らない。点火は火をつけること。"}, "sentence_index": 6, "correct_answer": "交換"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "雨のせいで、お弁当の代金を交換した。", "explanation": "ここは〈支払い〉の意味。代金は払うもので、互いに物を取りかえる交換とは言わない。"}, {"text": "会長は社員全員に、トロフィーを交換した。", "explanation": "ここは〈贈呈〉の意味。一方的に贈る場合は、交換とは言わない。"}, {"text": "地域の人たちと、交換を深めた。", "explanation": "ここは〈交流〉の意味。人と親しくなることは交換とは言わず、「交流を深める」が正しい。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cccbe2e-caf3-47c6-9a9a-d86ebe2bdee1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37918, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "祖母とは、季節ごとに手紙を交換ている。", "corrected_sentence": "祖母とは、季節ごとに手紙を交換している。", "error_description": "「交換」は「する」と結びついて「交換している」の形になる。「交換ている」は「し」が抜けた誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cccbe2e-caf3-47c6-9a9a-d86ebe2bdee1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37918, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "私は友だちと本が交換した。", "corrected_sentence": "私は友だちと本を交換した。", "error_description": "「交換」の目的語は「を」で示す。「本が」は主語を示すので、「本が交換した」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cccbe2e-caf3-47c6-9a9a-d86ebe2bdee1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37919, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "目的語を示す。「魚を交換して」の形で正しい。"}, {"text": "が", "is_correct": false, "explanation": "主語を示す。「魚が交換して」は文の主語として合わない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す。「魚へ交換して」は不自然。"}, {"text": "から", "is_correct": false, "explanation": "起点を示す。「魚から交換して」は交換する対象を示せない。"}], "correct_answer": "を", "explanations": {"を": "目的語を示す。「魚を交換して」の形で正しい。", "が": "主語を示す。「魚が交換して」は文の主語として合わない。", "へ": "方向を示す。「魚へ交換して」は不自然。", "から": "起点を示す。「魚から交換して」は交換する対象を示せない。"}, "error_tags": {"を": "目的語を示す。「魚を交換して」の形で正しい。", "が": "主語を示す。「魚が交換して」は文の主語として合わない。", "へ": "方向を示す。「魚へ交換して」は不自然。", "から": "起点を示す。「魚から交換して」は交換する対象を示せない。"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cccbe2e-caf3-47c6-9a9a-d86ebe2bdee1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
