INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37919, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "互いに自分のものと相手のものを取りかえること。", "primary_collocate": null, "pronunciation": "こうかん", "ipa": "koːkaɴ", "syllable_count": 4, "sentences": [{"text": "黒板が見にくかったので、後ろの人と席を交換してもらった。", "target_word": "交換", "complexity_tier": "T3", "furigana": "黒板[こくばん]が見[み]にくかったので、後[うし]ろの人[ひと]と席[せき]を交換[こうかん]してもらった。", "sentence_source": "generated"}, {"text": "昔の人は、米と魚を交換して暮らしていたそうだ。", "target_word": "交換", "complexity_tier": "T3", "furigana": "昔[むかし]の人[ひと]は、米[こめ]と魚[さかな]を交換[こうかん]して暮[く]らしていたそうだ。", "sentence_source": "generated"}, {"text": "兄とは、ゲームソフトを交換して遊んでいる。", "target_word": "交換", "complexity_tier": "T3", "furigana": "兄[あに]とは、ゲームソフトを交換[こうかん]して遊[あそ]んでいる。", "sentence_source": "generated"}, {"text": "試合のあと、両チームの選手はユニフォームを交換した。", "target_word": "交換", "complexity_tier": "T3", "furigana": "試合[しあい]のあと、両[りょう]チームの選手[せんしゅ]はユニフォームを交換[こうかん]した。", "sentence_source": "generated"}, {"text": "二人は友情の印として、帽子を交換した。", "target_word": "交換", "complexity_tier": "T3", "furigana": "二人[ふたり]は友情[ゆうじょう]の印[しるし]として、帽子[ぼうし]を交換[こうかん]した。", "sentence_source": "generated"}, {"text": "弟と部屋を交換したら、朝日が入って気持ちがいい。", "target_word": "交換", "complexity_tier": "T3", "furigana": "弟[おとうと]と部屋[へや]を交換[こうかん]したら、朝日[あさひ]が入[はい]って気持[きも]ちがいい。", "sentence_source": "generated"}, {"text": "昼ご飯のとき、友だちと自分のおかずを交換した。", "target_word": "交換", "complexity_tier": "T3", "furigana": "昼[ひる]ご飯[はん]のとき、友[とも]だちと自分[じぶん]のおかずを交換[こうかん]した。", "sentence_source": "generated"}, {"text": "先生の許可をもらって、私たちは掃除の当番を交換した。", "target_word": "交換", "complexity_tier": "T3", "furigana": "先生[せんせい]の許可[きょか]をもらって、私[わたし]たちは掃除[そうじ]の当番[とうばん]を交換[こうかん]した。", "sentence_source": "generated"}, {"text": "子どもたちは、集めたシールを交換している。", "target_word": "交換", "complexity_tier": "T3", "furigana": "子[こ]どもたちは、集[あつ]めたシールを交換[こうかん]している。", "sentence_source": "generated"}, {"text": "田中さんと担当の仕事を交換することになった。", "target_word": "交換", "complexity_tier": "T3", "furigana": "田中[たなか]さんと担当[たんとう]の仕事[しごと]を交換[こうかん]することになった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "交換する", "label": "終止形"}, {"form": "交換します", "label": "丁寧形"}, {"form": "交換した", "label": "過去形"}, {"form": "交換して", "label": "て形"}, {"form": "交換しない", "label": "否定形"}], "register": "neutral", "sense_fingerprint": "席・当番・持ち物などを、互いに相手のものと取りかえること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T2: contains vocabulary far above tier T2: 見にくかっ (Zipf 1.4)']::text[], 'd2fddf5a-a756-46b3-bbac-8b346c4f6624') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37919, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "交換", "is_correct": true, "explanation": "「席を互いに取りかえる」の意味で、「席を交換してもらった」は自然。"}, {"text": "消火", "is_correct": false, "explanation": "「席を消火」は意味が通らない。消火は火を消すこと。"}, {"text": "照明", "is_correct": false, "explanation": "「席を照明」は意味が通らない。照明は光を当てること。"}, {"text": "呼吸", "is_correct": false, "explanation": "「席を呼吸」は意味が通らない。呼吸は息をすること。"}], "explanations": {"交換": "「席を互いに取りかえる」の意味で、「席を交換してもらった」は自然。", "消火": "「席を消火」は意味が通らない。消火は火を消すこと。", "照明": "「席を照明」は意味が通らない。照明は光を当てること。", "呼吸": "「席を呼吸」は意味が通らない。呼吸は息をすること。"}, "sentence_index": 0, "correct_answer": "交換"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "困った私は、先生に進路を交換した。", "explanation": "ここは〈相談〉の意味。進路について話し合うことは、物を取りかえる交換とは言わない。"}, {"text": "お客さんは店員に、代金を交換した。", "explanation": "ここは〈支払い〉の意味。代金は払うもので、品物を取りかえる交換とは言わない。"}, {"text": "携帯電話の契約を交換した。", "explanation": "ここは〈解約〉の意味。契約をやめることは、交換とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cccbe2e-caf3-47c6-9a9a-d86ebe2bdee1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37919, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "交換", "is_correct": true, "explanation": "「おかずを互いにやりとりする」の意味で、「おかずを交換した」は自然。"}, {"text": "洗濯", "is_correct": false, "explanation": "「おかずを洗濯」は意味が通らない。洗濯は衣類を洗うこと。"}, {"text": "点火", "is_correct": false, "explanation": "「おかずを点火」は意味が通らない。点火は火をつけること。"}, {"text": "散歩", "is_correct": false, "explanation": "「おかずを散歩」は意味が通らない。散歩は歩いて出かけること。"}], "explanations": {"交換": "「おかずを互いにやりとりする」の意味で、「おかずを交換した」は自然。", "洗濯": "「おかずを洗濯」は意味が通らない。洗濯は衣類を洗うこと。", "点火": "「おかずを点火」は意味が通らない。点火は火をつけること。", "散歩": "「おかずを散歩」は意味が通らない。散歩は歩いて出かけること。"}, "sentence_index": 6, "correct_answer": "交換"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "前任者は田中さんに、担当の仕事を交換した。", "explanation": "ここは〈引き継ぎ〉の意味。仕事を一方的に渡すだけの場合は、交換とは言わない。"}, {"text": "社長は田中さんに、判断を交換した。", "explanation": "ここは〈委任〉の意味。判断を任せることは、互いに取りかえる交換とは言わない。"}, {"text": "会社は田中さんを、支店へ交換した。", "explanation": "ここは〈派遣〉の意味。人を一方的に送る場合は、交換とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cccbe2e-caf3-47c6-9a9a-d86ebe2bdee1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37919, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "私は友だちと消しゴムに交換した。", "corrected_sentence": "私は友だちと消しゴムを交換した。", "error_description": "「交換」の目的語は「を」で示す。「に」は着点を表すので、「消しゴムに交換した」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cccbe2e-caf3-47c6-9a9a-d86ebe2bdee1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37919, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "私は兄と、お風呂掃除の当番を交換だ。", "corrected_sentence": "私は兄と、お風呂掃除の当番を交換した。", "error_description": "「当番を交換だ」は、目的語「を」を取る動作の文に名詞の断定「だ」を続けた誤り。過去の動作として「交換した」の形にする必要がある。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cccbe2e-caf3-47c6-9a9a-d86ebe2bdee1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37920, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "「暗い表情で」は様子や仕方を表し、表情のままで部屋に入ったという意味が通る。"}, {"text": "を", "is_correct": false, "explanation": "「表情を部屋に入ってきた」は、表情を通り道のように扱うことになり不自然。"}, {"text": "に", "is_correct": false, "explanation": "「表情に」は対象にならず、部屋に入るのは「部屋に」の方なので文が崩れる。"}, {"text": "が", "is_correct": false, "explanation": "「表情が部屋に入ってきた」だと表情が入ってくる主体になり、意味が通らない。"}], "correct_answer": "で", "explanations": {"で": "「暗い表情で」は様子や仕方を表し、表情のままで部屋に入ったという意味が通る。", "を": "「表情を部屋に入ってきた」は、表情を通り道のように扱うことになり不自然。", "に": "「表情に」は対象にならず、部屋に入るのは「部屋に」の方なので文が崩れる。", "が": "「表情が部屋に入ってきた」だと表情が入ってくる主体になり、意味が通らない。"}, "error_tags": {"で": "様子・手段", "を": "目的語", "に": "帰着点", "が": "主語"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2130322-bc1d-4da0-bd0a-c22bb2978233') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37920, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「表情を見る」の目的語を示す。見る対象は彼女の表情。"}, {"text": "と", "is_correct": false, "explanation": "「表情と見る」は並列の意味になり、見る対象としては成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「表情へ見る」は方向を示す形で、見る対象にはならない。"}, {"text": "の", "is_correct": false, "explanation": "「表情の見る機会」は目的語が欠けて文が成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「表情を見る」の目的語を示す。見る対象は彼女の表情。", "と": "「表情と見る」は並列の意味になり、見る対象としては成り立たない。", "へ": "「表情へ見る」は方向を示す形で、見る対象にはならない。", "の": "「表情の見る機会」は目的語が欠けて文が成り立たない。"}, "error_tags": {"を": "目的語", "と": "並列", "へ": "方向", "の": "連体修飾"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2130322-bc1d-4da0-bd0a-c22bb2978233') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37920, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "顔のようす。気持ちが顔に出たもの。", "primary_collocate": null, "pronunciation": "ひょうじょう", "ipa": "çjoːdʑoː", "syllable_count": 4, "sentences": [{"text": "駅で会った友人は、疲れた表情をしていた。", "target_word": "表情", "complexity_tier": "T3", "furigana": "駅[えき]で会[あ]った友人[ゆうじん]は、疲[つか]れた表情[ひょうじょう]をしていた。", "sentence_source": "generated"}, {"text": "弟は、テストの結果を見て、暗い表情で部屋に入ってきた。", "target_word": "表情", "complexity_tier": "T3", "furigana": "弟[おとうと]は、テストの結果[けっか]を見[み]て、暗[くら]い表情[ひょうじょう]で部屋[へや]に入[はい]ってきた。", "sentence_source": "generated"}, {"text": "彼の表情が明るいのは、いい知らせがあったからだろう。", "target_word": "表情", "complexity_tier": "T3", "furigana": "彼[かれ]の表情[ひょうじょう]が明[あか]るいのは、いい知[し]らせがあったからだろう。", "sentence_source": "generated"}, {"text": "子どもたちは、プレゼントを開けるとき、うれしそうな表情になった。", "target_word": "表情", "complexity_tier": "T3", "furigana": "子[こ]どもたちは、プレゼントを開[あ]けるとき、うれしそうな表情[ひょうじょう]になった。", "sentence_source": "generated"}, {"text": "医者は、真剣な表情で検査の結果を説明した。", "target_word": "表情", "complexity_tier": "T3", "furigana": "医者[いしゃ]は、真剣[しんけん]な表情[ひょうじょう]で検査[けんさ]の結果[けっか]を説明[せつめい]した。", "sentence_source": "generated"}, {"text": "母の表情がくもったので、何かあったのだと分かった。", "target_word": "表情", "complexity_tier": "T3", "furigana": "母[はは]の表情[ひょうじょう]がくもったので、何[なに]かあったのだと分[わ]かった。", "sentence_source": "generated"}, {"text": "夜道で見た男の表情は、暗くてよく分からなかった。", "target_word": "表情", "complexity_tier": "T3", "furigana": "夜道[よみち]で見[み]た男[おとこ]の表情[ひょうじょう]は、暗[くら]くてよく分[わ]からなかった。", "sentence_source": "generated"}, {"text": "笑顔の写真ばかりで、彼女のほかの表情を見る機会は少ない。", "target_word": "表情", "complexity_tier": "T3", "furigana": "笑顔[えがお]の写真[しゃしん]ばかりで、彼女[かのじょ]のほかの表情[ひょうじょう]を見[み]る機会[きかい]は少[すく]ない。", "sentence_source": "generated"}, {"text": "飼い主が帰ってくると、犬の表情がぱっと変わる。", "target_word": "表情", "complexity_tier": "T3", "furigana": "飼[か]い主[ぬし]が帰[かえ]ってくると、犬[いぬ]の表情[ひょうじょう]がぱっと変[か]わる。", "sentence_source": "generated"}, {"text": "彼は何を言われても表情を変えず、静かに話を聞いていた。", "target_word": "表情", "complexity_tier": "T3", "furigana": "彼[かれ]は何[なに]を言[い]われても表情[ひょうじょう]を変[か]えず、静[しず]かに話[はなし]を聞[き]いていた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "表情", "label": "基本形"}, {"form": "無表情", "label": "否定形（無〜）"}, {"form": "表情豊か", "label": "複合形"}], "register": "標準", "sense_fingerprint": "見た目に表れた顔のようす。気持ちが顔に出たもの", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 5 above tier T2: contains vocabulary far above tier T2: くもっ (Zipf 2.15)']::text[], '349bdf37-e6c1-493d-99ce-08b9d759cd57') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37920, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "表情", "is_correct": true, "explanation": "疲れが顔に出ていた様子を表し、「疲れた」に続けて自然に入る。"}, {"text": "時刻", "is_correct": false, "explanation": "時刻は時間の一点を指し、「疲れた」の後に続けると意味が通らない。"}, {"text": "湿度", "is_correct": false, "explanation": "湿度は空気中の水分の割合で、人の疲れた様子には使えない。"}, {"text": "距離", "is_correct": false, "explanation": "距離は二点間の長さで、「疲れた距離をしていた」とは言えない。"}], "explanations": {"表情": "疲れが顔に出ていた様子を表し、「疲れた」に続けて自然に入る。", "時刻": "時刻は時間の一点を指し、「疲れた」の後に続けると意味が通らない。", "湿度": "湿度は空気中の水分の割合で、人の疲れた様子には使えない。", "距離": "距離は二点間の長さで、「疲れた距離をしていた」とは言えない。"}, "sentence_index": 0, "correct_answer": "表情"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "玄関に表情を掛け、家族全員の名前を書いた。", "explanation": "ここは〈家の名前を書いた札〉の意味。玄関に掛けるのは表札で、顔に出る気持ちの表情とは言わない。"}, {"text": "この木のテーブルは表情がなめらかで、手で触ると気持ちがいい。", "explanation": "ここは〈表面〉の意味。木の表面はなめらかと言い、表情とは言わない。"}, {"text": "雨で本の表情がふやけ、ページが読めなくなった。", "explanation": "ここは〈本の外側を覆う紙〉の意味。本の外側は表紙と言い、顔色の表情とは区別する。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2130322-bc1d-4da0-bd0a-c22bb2978233') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37920, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "表情", "is_correct": true, "explanation": "暗がりで見て分からなかった顔のようす、という意味で文に合う。"}, {"text": "音程", "is_correct": false, "explanation": "音程は音の高さの差を表し、男を見た話には使えない。"}, {"text": "配線", "is_correct": false, "explanation": "配線は電気の線をつなぐことで、人の様子とは結びつかない。"}, {"text": "時差", "is_correct": false, "explanation": "時差は地域間の時間のずれで、「男の時差」は意味をなさない。"}], "explanations": {"表情": "暗がりで見て分からなかった顔のようす、という意味で文に合う。", "音程": "音程は音の高さの差を表し、男を見た話には使えない。", "配線": "配線は電気の線をつなぐことで、人の様子とは結びつかない。", "時差": "時差は地域間の時間のずれで、「男の時差」は意味をなさない。"}, "sentence_index": 6, "correct_answer": "表情"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は大会で表情を受け、会場から大きな拍手をもらった。", "explanation": "ここは〈表彰〉の意味。賞を受けるのは表彰で、顔に出る気持ちの表情とは言わない。"}, {"text": "パソコンの画面に、表情が出てエラーを知らせた。", "explanation": "ここは〈表示〉の意味。画面に映す文字や図は表示と言い、表情とは言わない。"}, {"text": "彼は英語の表情が深く、難しい文章もすらすら読める。", "explanation": "ここは〈理解〉の意味。語学の習熟は理解と言い、顔に出る気持ちの表情は使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2130322-bc1d-4da0-bd0a-c22bb2978233') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37920, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "父は暗い表情を塗って、黙って席についた。", "corrected_sentence": "父は暗い表情を浮かべて、黙って席についた。", "error_description": "「表情」と組む動詞は「浮かべる」「見せる」など。「塗る」は表情には使えない（動詞の選択の誤り）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2130322-bc1d-4da0-bd0a-c22bb2978233') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37920, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "夜道では男の表情を見えなかった。", "corrected_sentence": "夜道では男の表情が見えなかった。", "error_description": "「見えない」は主語を「が」で示し、目的語の「を」は取れない。正しくは「表情が見えなかった」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2130322-bc1d-4da0-bd0a-c22bb2978233') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37921, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「表情を隠す」の目的語を示す。隠そうとしているのは悲しい表情。"}, {"text": "が", "is_correct": false, "explanation": "「表情が隠そうとして」だと表情が主語になるが、隠す行為には人が要るので不自然。"}, {"text": "に", "is_correct": false, "explanation": "「表情に隠そうとして」は対象を示す格として成り立たず、不自然。"}, {"text": "と", "is_correct": false, "explanation": "「表情と隠そうとして」は並列の意味になり、文が通らない。"}], "correct_answer": "を", "explanations": {"を": "「表情を隠す」の目的語を示す。隠そうとしているのは悲しい表情。", "が": "「表情が隠そうとして」だと表情が主語になるが、隠す行為には人が要るので不自然。", "に": "「表情に隠そうとして」は対象を示す格として成り立たず、不自然。", "と": "「表情と隠そうとして」は並列の意味になり、文が通らない。"}, "error_tags": {"を": "目的語", "が": "主語", "に": "位置・方向", "と": "並列・共同"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2130322-bc1d-4da0-bd0a-c22bb2978233') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37921, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「表情に出す」は、気持ちが顔に現れることを示す慣用の形。"}, {"text": "を", "is_correct": false, "explanation": "「表情を出す」とは言わず、気持ちが顔に出る場合は「に出す」を使う。"}, {"text": "で", "is_correct": false, "explanation": "「表情で出す」は手段としても出す対象としても不自然。"}, {"text": "へ", "is_correct": false, "explanation": "「表情へ出す」は方向を示すが、顔に気持ちが出るという意味とは合わない。"}], "correct_answer": "に", "explanations": {"に": "「表情に出す」は、気持ちが顔に現れることを示す慣用の形。", "を": "「表情を出す」とは言わず、気持ちが顔に出る場合は「に出す」を使う。", "で": "「表情で出す」は手段としても出す対象としても不自然。", "へ": "「表情へ出す」は方向を示すが、顔に気持ちが出るという意味とは合わない。"}, "error_tags": {"に": "位置・帰着", "を": "目的語", "で": "手段・場所", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2130322-bc1d-4da0-bd0a-c22bb2978233') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37921, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "顔の動きや色などで、心の中の気持ちや考えを表したもの。", "primary_collocate": null, "pronunciation": "ひょうじょう", "ipa": "çjoːdʑoː", "syllable_count": 4, "sentences": [{"text": "汗が滴る中でも、その表情は穏やかだ。", "target_word": "表情", "complexity_tier": "T3", "furigana": "汗[あせ]が滴[したた]る中[なか]でも、その表情[ひょうじょう]は穏[おだ]やかだ。", "sentence_source": "mined"}, {"text": "彼女は悲しい表情を隠そうとして、わざと明るく笑った。", "target_word": "表情", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は悲[かな]しい表情[ひょうじょう]を隠[かく]そうとして、わざと明[あか]るく笑[わら]った。", "sentence_source": "generated"}, {"text": "試合に勝った選手たちの表情には、喜びがあふれていた。", "target_word": "表情", "complexity_tier": "T3", "furigana": "試合[しあい]に勝[か]った選手[せんしゅ]たちの表情[ひょうじょう]には、喜[よろこ]びがあふれていた。", "sentence_source": "generated"}, {"text": "先生の表情が急に厳しくなったので、教室は静まりかえった。", "target_word": "表情", "complexity_tier": "T3", "furigana": "先生[せんせい]の表情[ひょうじょう]が急[きゅう]に厳[きび]しくなったので、教室[きょうしつ]は静[しず]まりかえった。", "sentence_source": "generated"}, {"text": "母は電話を切ったあと、ほっとした表情を見せた。", "target_word": "表情", "complexity_tier": "T3", "furigana": "母[はは]は電話[でんわ]を切[き]ったあと、ほっとした表情[ひょうじょう]を見[み]せた。", "sentence_source": "generated"}, {"text": "言葉が通じなくても、相手の表情から気持ちを読み取ることができる。", "target_word": "表情", "complexity_tier": "T3", "furigana": "言葉[ことば]が通[つう]じなくても、相手[あいて]の表情[ひょうじょう]から気持[きも]ちを読[よ]み取[と]ることができる。", "sentence_source": "generated"}, {"text": "面接の前は、緊張した表情の人ばかりだった。", "target_word": "表情", "complexity_tier": "T3", "furigana": "面接[めんせつ]の前[まえ]は、緊張[きんちょう]した表情[ひょうじょう]の人[ひと]ばかりだった。", "sentence_source": "generated"}, {"text": "彼は怒っていたが、その気持ちを表情に出さなかった。", "target_word": "表情", "complexity_tier": "T3", "furigana": "彼[かれ]は怒[おこ]っていたが、その気持[きも]ちを表情[ひょうじょう]に出[だ]さなかった。", "sentence_source": "generated"}, {"text": "赤ちゃんは、レモンをなめると、おもしろい表情をした。", "target_word": "表情", "complexity_tier": "T3", "furigana": "赤[あか]ちゃんは、レモンをなめると、おもしろい表情[ひょうじょう]をした。", "sentence_source": "generated"}, {"text": "彼女は何も言わなかったが、その表情から不満がはっきり読み取れた。", "target_word": "表情", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は何[なに]も言[い]わなかったが、その表情[ひょうじょう]から不満[ふまん]がはっきり読[よ]み取[と]れた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "表情", "label": "基本形"}, {"form": "無表情", "label": "否定形（無〜）"}, {"form": "表情豊か", "label": "複合形"}], "register": "標準", "sense_fingerprint": "顔の動きや色で心の中の気持ちや考えを外に表したもの", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 3 above tier T2: contains vocabulary far above tier T2: 静まりかえっ (Zipf 1.92)']::text[], '349bdf37-e6c1-493d-99ce-08b9d759cd57') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37921, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "表情", "is_correct": true, "explanation": "顔に気持ちが表れたものを指し、「穏やかだ」という様子に合う。"}, {"text": "体重", "is_correct": false, "explanation": "体重は体の重さのことで、「穏やかだ」と結びつかない。"}, {"text": "電圧", "is_correct": false, "explanation": "電圧は電気の圧力を表し、人の穏やかさの話には使えない。"}, {"text": "残高", "is_correct": false, "explanation": "残高は口座などに残った金額のことで、穏やかさとは関係ない。"}], "explanations": {"表情": "顔に気持ちが表れたものを指し、「穏やかだ」という様子に合う。", "体重": "体重は体の重さのことで、「穏やかだ」と結びつかない。", "電圧": "電圧は電気の圧力を表し、人の穏やかさの話には使えない。", "残高": "残高は口座などに残った金額のことで、穏やかさとは関係ない。"}, "sentence_index": 0, "correct_answer": "表情"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この本は表情が破れていて、中身も読みにくい。", "explanation": "ここは〈本の外側を覆う紙〉の意味。本の外側は表紙と言い、顔に出る気持ちの表情とは言わない。"}, {"text": "この壁は表情がなめらかで、手で触ると気持ちがいい。", "explanation": "ここは〈表面〉の意味。壁の手触りは表面と言い、表情とは言わない。"}, {"text": "このランプの表情が点いて、電源が入ったことが分かった。", "explanation": "ここは〈表示〉の意味。ランプの点灯は表示と言い、顔に出る気持ちの表情とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2130322-bc1d-4da0-bd0a-c22bb2978233') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37921, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "表情", "is_correct": true, "explanation": "緊張が顔に出た人、という意味で、「緊張した」に続けて自然に入る。"}, {"text": "体温", "is_correct": false, "explanation": "体温は体の温度で、「緊張した」の後に続けると意味が通らない。"}, {"text": "身長", "is_correct": false, "explanation": "身長は背の高さのことで、緊張の様子とは結びつかない。"}, {"text": "声量", "is_correct": false, "explanation": "声量は声の大きさを表し、「緊張した声量の人」とは言えない。"}], "explanations": {"表情": "緊張が顔に出た人、という意味で、「緊張した」に続けて自然に入る。", "体温": "体温は体の温度で、「緊張した」の後に続けると意味が通らない。", "身長": "身長は背の高さのことで、緊張の様子とは結びつかない。", "声量": "声量は声の大きさを表し、「緊張した声量の人」とは言えない。"}, "sentence_index": 6, "correct_answer": "表情"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この資料は、人名の表情が統一されていない。", "explanation": "ここは〈文字での書き方〉の意味。人名の書き方は表記と言い、顔つきの表情とは言わない。"}, {"text": "会社は、功績の大きい社員に表情を授けた。", "explanation": "ここは〈賞を与えて褒めること〉の意味。授けるのは表彰で、顔に出る気持ちの表情とは言わない。"}, {"text": "画面に表情が出て、読み込みが終わったことを知らせる。", "explanation": "ここは〈表示〉の意味。画面に映る文字や図は表示と言い、表情とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2130322-bc1d-4da0-bd0a-c22bb2978233') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37921, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼は笑いをこらえて、硬い表情に浮かべた。", "corrected_sentence": "彼は笑いをこらえて、硬い表情を浮かべた。", "error_description": "「浮かべる」の対象は「を」で示す。「に」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2130322-bc1d-4da0-bd0a-c22bb2978233') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37921, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼は笑って、表情が柔らかくなられた。", "corrected_sentence": "彼は笑って、表情が柔らかくなった。", "error_description": "「なる」に尊敬の「〜られる」を付けるのは誤り。表情は敬う対象ではないので「なった」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2130322-bc1d-4da0-bd0a-c22bb2978233') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37922, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "正解。様子や仕方を示す「で」で、低い調子で話したことを表す。"}, {"text": "が", "is_correct": false, "explanation": "主語の助詞。主語は「彼女は」で示されているので、重ねると文が崩れる。"}, {"text": "を", "is_correct": false, "explanation": "目的語の助詞。「話す」の対象にトーンは立たない。"}, {"text": "の", "is_correct": false, "explanation": "名詞をつなぐ助詞で、続きの文が成り立たない。"}], "correct_answer": "で", "explanations": {"で": "正解。様子や仕方を示す「で」で、低い調子で話したことを表す。", "が": "主語の助詞。主語は「彼女は」で示されているので、重ねると文が崩れる。", "を": "目的語の助詞。「話す」の対象にトーンは立たない。", "の": "名詞をつなぐ助詞で、続きの文が成り立たない。"}, "error_tags": {"が": "主格の重複", "を": "目的語", "の": "連体修飾"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33cacc52-1f04-4931-b665-a81d12f7965e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37922, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "正解。様子を示す「で」。"}, {"text": "に", "is_correct": false, "explanation": "位置や相手を示す助詞。「高いトーンに」は様子を表せない。"}, {"text": "へ", "is_correct": false, "explanation": "方向の助詞。「高いトーンへ」は意味が通らない。"}, {"text": "を", "is_correct": false, "explanation": "目的語の助詞。「トーンを」は目的語にならず、文が崩れる。"}], "correct_answer": "で", "explanations": {"で": "正解。様子を示す「で」。", "に": "位置や相手を示す助詞。「高いトーンに」は様子を表せない。", "へ": "方向の助詞。「高いトーンへ」は意味が通らない。", "を": "目的語の助詞。「トーンを」は目的語にならず、文が崩れる。"}, "error_tags": {"に": "相手・位置", "へ": "方向", "を": "目的語"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33cacc52-1f04-4931-b665-a81d12f7965e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37922, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "話し声の高さや低さのこと。", "primary_collocate": null, "pronunciation": "とーん", "ipa": "toːɴ", "syllable_count": 3, "sentences": [{"text": "電話では、声のトーンを少し上げて話します。", "target_word": "トーン", "complexity_tier": "T3", "furigana": "電話[でんわ]では、声[こえ]のトーンを少[すこ]し上[あ]げて話[はな]します。", "sentence_source": "generated"}, {"text": "彼女は低いトーンで、ゆっくり話した。", "target_word": "トーン", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は低[ひく]いトーンで、ゆっくり話[はな]した。", "sentence_source": "generated"}, {"text": "先生は声のトーンを変えて、文を読んだ。", "target_word": "トーン", "complexity_tier": "T3", "furigana": "先生[せんせい]は声[こえ]のトーンを変[か]えて、文[ぶん]を読[よ]んだ。", "sentence_source": "generated"}, {"text": "緊張して、声のトーンが高くなってしまった。", "target_word": "トーン", "complexity_tier": "T3", "furigana": "緊張[きんちょう]して、声[こえ]のトーンが高[たか]くなってしまった。", "sentence_source": "generated"}, {"text": "質問するときは、文の終わりのトーンを上げる。", "target_word": "トーン", "complexity_tier": "T3", "furigana": "質問[しつもん]するときは、文[ぶん]の終[お]わりのトーンを上[あ]げる。", "sentence_source": "generated"}, {"text": "赤ちゃんには、高いトーンで話しかけるとよい。", "target_word": "トーン", "complexity_tier": "T3", "furigana": "赤[あか]ちゃんには、高[たか]いトーンで話[はな]しかけるとよい。", "sentence_source": "generated"}, {"text": "電話の相手は、低いトーンで話を切り上げた。", "target_word": "トーン", "complexity_tier": "T3", "furigana": "電話[でんわ]の相手[あいて]は、低[ひく]いトーンで話[はなし]を切[き]り上[あ]げた。", "sentence_source": "generated"}, {"text": "司会者は高いトーンで、会場に声をかけた。", "target_word": "トーン", "complexity_tier": "T3", "furigana": "司会者[しかいしゃ]は高[たか]いトーンで、会場[かいじょう]に声[こえ]をかけた。", "sentence_source": "generated"}, {"text": "声のトーンを下げると、落ち着いた感じになる。", "target_word": "トーン", "complexity_tier": "T3", "furigana": "声[こえ]のトーンを下[さ]げると、落[お]ち着[つ]いた感[かん]じになる。", "sentence_source": "generated"}, {"text": "彼の声はトーンが低くて、後ろの席まで届かない。", "target_word": "トーン", "complexity_tier": "T3", "furigana": "彼[かれ]の声[こえ]はトーンが低[ひく]くて、後[うし]ろの席[せき]まで届[とど]かない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "トーン", "label": "base"}], "register": "中立", "sense_fingerprint": "声の高さ・低さ", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54f5b9e3-f2d6-4f8e-8908-7999cfe0d07d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37922, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "トーン", "is_correct": true, "explanation": "正解。声の高さや低さを表す語。"}, {"text": "ドア", "is_correct": false, "explanation": "開閉する扉で、声の高さを表さない。"}, {"text": "ベッド", "is_correct": false, "explanation": "寝るための家具で、声には使わない。"}, {"text": "切符", "is_correct": false, "explanation": "乗車などに使う券で、声の高さとは関係ない。"}], "explanations": {"トーン": "正解。声の高さや低さを表す語。", "ドア": "開閉する扉で、声の高さを表さない。", "ベッド": "寝るための家具で、声には使わない。", "切符": "乗車などに使う券で、声の高さとは関係ない。"}, "sentence_index": 0, "correct_answer": "トーン"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この部屋は、落ち着いたトーンの色でまとめた。", "explanation": "ここは〈色の調子〉の意味。声の高さを表すこの語義は色には使えず、部屋の色の話になる。"}, {"text": "原稿の背景に、トーンを一枚貼った。", "explanation": "ここは〈スクリーントーン（漫画の網点シート）〉の意味。紙に貼る材料を指すので、声の高さの語義では使わない。"}, {"text": "夜中なので、トーンを絞って音量を小さくした。", "explanation": "ここは〈音量〉の意味。音の大きさを絞るのは音量で、声の高さを表すトーンは絞れない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33cacc52-1f04-4931-b665-a81d12f7965e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37922, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "トーン", "is_correct": true, "explanation": "正解。声の高さや低さを表す語。"}, {"text": "手紙", "is_correct": false, "explanation": "文字で伝える書類で、話し方を表さない。"}, {"text": "鉛筆", "is_correct": false, "explanation": "書く道具で、声の調子ではない。"}, {"text": "座布団", "is_correct": false, "explanation": "座るための敷物で、関係ない。"}], "explanations": {"トーン": "正解。声の高さや低さを表す語。", "手紙": "文字で伝える書類で、話し方を表さない。", "鉛筆": "書く道具で、声の調子ではない。", "座布団": "座るための敷物で、関係ない。"}, "sentence_index": 6, "correct_answer": "トーン"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "電話の着信トーンを変えて、音を小さくした。", "explanation": "ここは〈着信音〉の意味。電話の着信メロディを指すので、話し手の声の高さを表すトーンとは違う。"}, {"text": "店のトーンが落ち着いていて、長居したくなる。", "explanation": "ここは〈雰囲気〉の意味。店の空気を表すのは雰囲気で、声の高さを指すトーンは当てはまらない。"}, {"text": "トーンを減らして、レシピを作り直した。", "explanation": "ここは〈分量〉の意味。料理の量を減らすのは分量で、声の高さを表すトーンは減らせない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33cacc52-1f04-4931-b665-a81d12f7965e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37922, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "電話では、声のトーンを少し下がって話します。", "corrected_sentence": "電話では、声のトーンを少し下げて話します。", "error_description": "「下がる」は自動詞なので「を」の目的語を取れない。他動詞「下げる」にすると正しい。誤りは動詞の形。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33cacc52-1f04-4931-b665-a81d12f7965e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37922, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼女は明るいトーンを、会場に挨拶した。", "corrected_sentence": "彼女は明るいトーンで、会場に挨拶した。", "error_description": "「明るいトーンで」は様子を表す「で」。「を」にすると「トーンを」が目的語になり、「挨拶した」と結びつかず文が崩れる。正しくは「で」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33cacc52-1f04-4931-b665-a81d12f7965e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37923, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "正解。「違う」の主語を示す助詞。"}, {"text": "を", "is_correct": false, "explanation": "目的語の助詞。「違う」は目的語を取らないので合わない。"}, {"text": "へ", "is_correct": false, "explanation": "方向の助詞。「トーンへちがう」は意味が通らない。"}, {"text": "に", "is_correct": false, "explanation": "相手や位置の助詞。「違う」の形にはならない。"}], "correct_answer": "が", "explanations": {"が": "正解。「違う」の主語を示す助詞。", "を": "目的語の助詞。「違う」は目的語を取らないので合わない。", "へ": "方向の助詞。「トーンへちがう」は意味が通らない。", "に": "相手や位置の助詞。「違う」の形にはならない。"}, "error_tags": {"を": "目的語", "へ": "方向", "に": "相手・位置"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33cacc52-1f04-4931-b665-a81d12f7965e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37923, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "正解。変わる主体のトーンを示す主語。"}, {"text": "で", "is_correct": false, "explanation": "手段・場所の助詞。「トーンで変わる」は意味が通らない。"}, {"text": "を", "is_correct": false, "explanation": "目的語の助詞。「変わる」は目的語を取らないので合わない。"}, {"text": "の", "is_correct": false, "explanation": "連体修飾の助詞。「変わり」の主語にはならない。"}], "correct_answer": "が", "explanations": {"が": "正解。変わる主体のトーンを示す主語。", "で": "手段・場所の助詞。「トーンで変わる」は意味が通らない。", "を": "目的語の助詞。「変わる」は目的語を取らないので合わない。", "の": "連体修飾の助詞。「変わり」の主語にはならない。"}, "error_tags": {"で": "手段・場所", "を": "目的語", "の": "連体修飾"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33cacc52-1f04-4931-b665-a81d12f7965e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37923, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "話し手の感情や態度を表す、声の高さや強さの変化。", "primary_collocate": null, "pronunciation": "とーん", "ipa": "toːɴ", "syllable_count": 3, "sentences": [{"text": "母の声のトーンで、怒っているとすぐ分かった。", "target_word": "トーン", "complexity_tier": "T3", "furigana": "母[はは]の声[こえ]のトーンで、怒[おこ]っているとすぐ分[わ]かった。", "sentence_source": "generated"}, {"text": "冗談を言うときと、まじめに話すときでは、トーンがちがう。", "target_word": "トーン", "complexity_tier": "T3", "furigana": "冗談[じょうだん]を言[い]うときと、まじめに話[はな]すときでは、トーンがちがう。", "sentence_source": "generated"}, {"text": "彼はいつもと同じトーンで、悲しい知らせを伝えた。", "target_word": "トーン", "complexity_tier": "T3", "furigana": "彼[かれ]はいつもと同[おな]じトーンで、悲[かな]しい知[し]らせを伝[つた]えた。", "sentence_source": "generated"}, {"text": "電話のトーンから、彼女が喜んでいるのが分かった。", "target_word": "トーン", "complexity_tier": "T3", "furigana": "電話[でんわ]のトーンから、彼女[かのじょ]が喜[よろこ]んでいるのが分[わ]かった。", "sentence_source": "generated"}, {"text": "先生の話すトーンが急に強くなって、教室が静かになった。", "target_word": "トーン", "complexity_tier": "T3", "furigana": "先生[せんせい]の話[はな]すトーンが急[きゅう]に強[つよ]くなって、教室[きょうしつ]が静[しず]かになった。", "sentence_source": "generated"}, {"text": "相手のトーンに合わせて、返事をした。", "target_word": "トーン", "complexity_tier": "T3", "furigana": "相手[あいて]のトーンに合[あ]わせて、返事[へんじ]をした。", "sentence_source": "generated"}, {"text": "彼のトーンがやさしかったので、私は安心した。", "target_word": "トーン", "complexity_tier": "T3", "furigana": "彼[かれ]のトーンがやさしかったので、私[わたし]は安心[あんしん]した。", "sentence_source": "generated"}, {"text": "話の途中でトーンが変わり、本気だと感じた。", "target_word": "トーン", "complexity_tier": "T3", "furigana": "話[はなし]の途中[とちゅう]でトーンが変[か]わり、本気[ほんき]だと感[かん]じた。", "sentence_source": "generated"}, {"text": "強いトーンで言われて、何も言い返せなかった。", "target_word": "トーン", "complexity_tier": "T3", "furigana": "強[つよ]いトーンで言[い]われて、何[なに]も言[い]い返[かえ]せなかった。", "sentence_source": "generated"}, {"text": "お客様に失礼のないように、丁寧なトーンで話す。", "target_word": "トーン", "complexity_tier": "T3", "furigana": "お客様[きゃくさま]に失礼[しつれい]のないように、丁寧[ていねい]なトーンで話[はな]す。", "sentence_source": "generated"}], "morphological_forms": [{"form": "トーン", "label": "base"}], "register": "中立", "sense_fingerprint": "感情や態度を表す声の調子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 6 above tier T3: contains vocabulary far above tier T3: やさしかっ (Zipf 1.99)']::text[], '54f5b9e3-f2d6-4f8e-8908-7999cfe0d07d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37923, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "トーン", "is_correct": true, "explanation": "正解。話し手の感情や態度を表す声の調子を指す語。"}, {"text": "座布団", "is_correct": false, "explanation": "座るための敷物で、感情を表す語ではない。"}, {"text": "鉛筆", "is_correct": false, "explanation": "書く道具で、声には関係ない。"}, {"text": "窓", "is_correct": false, "explanation": "建物の開口部で、声の調子を指さない。"}], "explanations": {"トーン": "正解。話し手の感情や態度を表す声の調子を指す語。", "座布団": "座るための敷物で、感情を表す語ではない。", "鉛筆": "書く道具で、声には関係ない。", "窓": "建物の開口部で、声の調子を指さない。"}, "sentence_index": 0, "correct_answer": "トーン"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この壁は、明るいトーンの色で塗った。", "explanation": "ここは〈色の明るさ・濃淡〉の意味。感情や態度を表すこの語義では、色の話には使わない。"}, {"text": "ピアノのトーンが一音ずれていたので、曲が崩れた。", "explanation": "ここは〈音程〉の意味。音の高さの正確さを指す語で、感情や態度を表す語義とは違う。"}, {"text": "彼女はトーンが広く、高音から低音まで歌える。", "explanation": "ここは〈音域〉の意味。歌える高さの範囲を指す語で、感情の調子を表すトーンとは違う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33cacc52-1f04-4931-b665-a81d12f7965e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37923, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "トーン", "is_correct": true, "explanation": "正解。丁寧な態度を表す声の調子を指す語。"}, {"text": "冷蔵庫", "is_correct": false, "explanation": "食品を冷やす家電で、声の調子とは関係ない。"}, {"text": "階段", "is_correct": false, "explanation": "建物の段差で、やさしさを表さない。"}, {"text": "天井", "is_correct": false, "explanation": "室内の上面で、人の態度を表さない。"}], "explanations": {"トーン": "正解。丁寧な態度を表す声の調子を指す語。", "冷蔵庫": "食品を冷やす家電で、声の調子とは関係ない。", "階段": "建物の段差で、やさしさを表さない。", "天井": "室内の上面で、人の態度を表さない。"}, "sentence_index": 6, "correct_answer": "トーン"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "マンガの影に、トーンを貼って陰影をつけた。", "explanation": "ここは〈スクリーントーン（漫画の網点シート）〉の意味。紙に貼る材料を指すので、話し手の感情を表す声の調子とは違う。"}, {"text": "レシピを作るとき、トーンを量って決めた。", "explanation": "ここは〈分量〉の意味。料理の量を量るのは分量で、話し手の感情を表す声の調子のトーンは量れない。"}, {"text": "電話が鳴ると、着信トーンが流れた。", "explanation": "ここは〈着信音〉の意味。電話の着信メロディを指すので、話し手の感情を表すトーンとは違う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33cacc52-1f04-4931-b665-a81d12f7965e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37923, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "母の声のトーンを、笑っているとすぐ分かった。", "corrected_sentence": "母の声のトーンで、笑っているとすぐ分かった。", "error_description": "「分かった」の根拠を示すのは「で」。「を」にすると目的語の位置に入り、文が崩れる。正しくは「で」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33cacc52-1f04-4931-b665-a81d12f7965e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37923, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼のトーンを穏やかだったので、私は安心した。", "corrected_sentence": "彼のトーンが穏やかだったので、私は安心した。", "error_description": "形容動詞「穏やかだ」の主語は「が」で示す。「を」を使うと主語が立たず、文が崩れる。正しくは「が」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33cacc52-1f04-4931-b665-a81d12f7965e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
