INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37924, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "目的語を示す。「花を一本取って」の形で正しい。"}, {"text": "に", "is_correct": false, "explanation": "着点や相手を示す。「花に一本取って」は目的語に「を」が必要なので不自然。"}, {"text": "の", "is_correct": false, "explanation": "連体修飾を示す。「花の一本取って」は文として成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "並列や相手を示す。「花と一本取って」は動作の対象として合わない。"}], "correct_answer": "を", "explanations": {"を": "目的語を示す。「花を一本取って」の形で正しい。", "に": "着点や相手を示す。「花に一本取って」は目的語に「を」が必要なので不自然。", "の": "連体修飾を示す。「花の一本取って」は文として成り立たない。", "と": "並列や相手を示す。「花と一本取って」は動作の対象として合わない。"}, "error_tags": {"に": "着点や相手を示す。「花に一本取って」は目的語に「を」が必要なので不自然。", "の": "連体修飾を示す。「花の一本取って」は文として成り立たない。", "と": "並列や相手を示す。「花と一本取って」は動作の対象として合わない。", "を": "目的語を示す。「花を一本取って」の形で正しい。"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cccbe2e-caf3-47c6-9a9a-d86ebe2bdee1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37924, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "手で持つこと。", "primary_collocate": null, "pronunciation": "とる", "ipa": "toɾɯ", "syllable_count": 2, "sentences": [{"text": "背が低いので、高い棚の本は台に乗って取る。", "target_word": "取る", "complexity_tier": "T3", "furigana": "背[せ]が低[ひく]いので、高[たか]い棚[たな]の本[ほん]は台[だい]に乗[の]って取[と]る。", "sentence_source": "generated"}, {"text": "彼は手を伸ばして、テーブルの上のりんごを取った。", "target_word": "取った", "complexity_tier": "T3", "furigana": "彼[かれ]は手[て]を伸[の]ばして、テーブルの上[うえ]のりんごを取[と]った。", "sentence_source": "generated"}, {"text": "すみませんが、そこのしょうゆを取ってください。", "target_word": "取って", "complexity_tier": "T3", "furigana": "すみませんが、そこのしょうゆを取[と]ってください。", "sentence_source": "generated"}, {"text": "子どもが落ちたボールを取って、投げ返してくれた。", "target_word": "取って", "complexity_tier": "T3", "furigana": "子[こ]どもが落[お]ちたボールを取[と]って、投[な]げ返[かえ]してくれた。", "sentence_source": "generated"}, {"text": "木になっているみかんを、手で取って食べた。", "target_word": "取って", "complexity_tier": "T3", "furigana": "木[き]になっているみかんを、手[て]で取[と]って食[た]べた。", "sentence_source": "generated"}, {"text": "母は引き出しからはさみを取って、私に渡した。", "target_word": "取って", "complexity_tier": "T3", "furigana": "母[はは]は引[ひ]き出[だ]しからはさみを取[と]って、私[わたし]に渡[わた]した。", "sentence_source": "generated"}, {"text": "赤ちゃんは、おもちゃを取ろうとして手を動かした。", "target_word": "取ろう", "complexity_tier": "T3", "furigana": "赤[あか]ちゃんは、おもちゃを取[と]ろうとして手[て]を動[うご]かした。", "sentence_source": "generated"}, {"text": "彼女は花びんの花を一本取って、においをかいだ。", "target_word": "取って", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は花[か]びんの花[はな]を一本[いっぽん]取[と]って、においをかいだ。", "sentence_source": "generated"}, {"text": "網棚の荷物を取るとき、隣の人にぶつかってしまった。", "target_word": "取る", "complexity_tier": "T3", "furigana": "網棚[あみだな]の荷物[にもつ]を取[と]るとき、隣[となり]の人[ひと]にぶつかってしまった。", "sentence_source": "generated"}, {"text": "料理を大皿から取って、自分の皿に入れた。", "target_word": "取って", "complexity_tier": "T3", "furigana": "料理[りょうり]を大皿[おおざら]から取[と]って、自分[じぶん]の皿[さら]に入[い]れた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "取る", "label": "終止形"}, {"form": "取ります", "label": "丁寧形"}, {"form": "取らない", "label": "否定形"}, {"form": "取って", "label": "て形"}, {"form": "取った", "label": "過去形"}, {"form": "取れば", "label": "仮定形"}, {"form": "取ろう", "label": "意向形"}, {"form": "取られる", "label": "受身形"}], "register": "neutral", "sense_fingerprint": "手を使ってものをつかみ、手に持つ・手に取ること(取る=手でつかむ)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 7 above tier T2: contains vocabulary far above tier T2: 花びん (Zipf 1.51)','sentence 8 above tier T2: contains vocabulary far above tier T2: 網棚 (Zipf 2.22)']::text[], 'd2fddf5a-a756-46b3-bbac-8b346c4f6624') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37924, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "取る", "is_correct": true, "explanation": "「台に乗って手で取る」の意味で、高い棚の本を取る文脈に合う。"}, {"text": "眠る", "is_correct": false, "explanation": "「台に乗って眠る」は文脈に合わない。高い棚の本を手で取る動作ではない。"}, {"text": "凍る", "is_correct": false, "explanation": "「台に乗って凍る」は文脈に合わない。本を取る動作を表さない。"}, {"text": "焦げる", "is_correct": false, "explanation": "「台に乗って焦げる」は意味が通らない。本を取る動作を表さない。"}], "explanations": {"取る": "「台に乗って手で取る」の意味で、高い棚の本を取る文脈に合う。", "眠る": "「台に乗って眠る」は文脈に合わない。高い棚の本を手で取る動作ではない。", "凍る": "「台に乗って凍る」は文脈に合わない。本を取る動作を表さない。", "焦げる": "「台に乗って焦げる」は意味が通らない。本を取る動作を表さない。"}, "sentence_index": 0, "correct_answer": "取る"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は三人の子どもを取っている。", "explanation": "ここは〈持つ（所有する）〉の意味。子どもは持つもので、手でつかむ意味の取るとは言わない。"}, {"text": "友だちから手紙を取った。", "explanation": "ここは〈受け取る〉の意味。取るは手でつかむ動作で、人から物を受け取る意味では使わない。"}, {"text": "エレベーターのボタンを取った。", "explanation": "ここは〈押す〉の意味。ボタンは押すもので、つかんで取るものではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cccbe2e-caf3-47c6-9a9a-d86ebe2bdee1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37924, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "取ろう", "is_correct": true, "explanation": "意向形。「おもちゃを取ろうとして」の形で、手を伸ばす動作に合う。"}, {"text": "微笑もう", "is_correct": false, "explanation": "「おもちゃを微笑もう」は意味が通らない。微笑むは目的語を取らない。"}, {"text": "尋ねよう", "is_correct": false, "explanation": "「おもちゃを尋ねよう」は意味が通らない。尋ねるは人に聞く動作。"}, {"text": "生まれよう", "is_correct": false, "explanation": "「おもちゃを生まれよう」は誤り。生まれるは自動詞で目的語を取れない。"}], "explanations": {"取ろう": "意向形。「おもちゃを取ろうとして」の形で、手を伸ばす動作に合う。", "微笑もう": "「おもちゃを微笑もう」は意味が通らない。微笑むは目的語を取らない。", "尋ねよう": "「おもちゃを尋ねよう」は意味が通らない。尋ねるは人に聞く動作。", "生まれよう": "「おもちゃを生まれよう」は誤り。生まれるは自動詞で目的語を取れない。"}, "sentence_index": 6, "correct_answer": "取ろう"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "夏休みに、地域のボランティアを取った。", "explanation": "ここは〈引き受ける〉の意味。役目や仕事を引き受けることは、手で持つ意味の取るとは言わない。"}, {"text": "窓を開けて、深く息を取った。", "explanation": "ここは〈吸う〉の意味。息は吸うもので、手で持つ意味の取るとは言わない。"}, {"text": "テーブルを布で取った。", "explanation": "ここは〈拭く〉の意味。布で汚れをふき取る動作は、手で持つことではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cccbe2e-caf3-47c6-9a9a-d86ebe2bdee1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37924, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "母は戸棚から皿を取ったり、食卓に並べた。", "corrected_sentence": "母は戸棚から皿を取って、食卓に並べた。", "error_description": "「取る」は「取って」の形で動作の順序を示す。「取ったり」は「〜たり〜たりする」の形で、後ろに「したり」が必要なので誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "取った", "is_correct": true, "explanation": "過去形。過去の動作として「りんごを取った」と述べる文に合う。"}, {"text": "取らない", "is_correct": false, "explanation": "否定形。「取らない」は現在の否定になり、実際に取った過去の出来事と合わない。"}, {"text": "取られる", "is_correct": false, "explanation": "受身形。誰かに取られる意味になり、主語が自分で取る文と合わない。"}, {"text": "取ろう", "is_correct": false, "explanation": "意向形。これから取る意志を表し、過去の出来事を述べる文と合わない。"}], "correct_form": "取った", "base_form": "取る", "form_label": "過去形", "sentence_index": 1, "explanations": {"取った": "過去形。過去の動作として「りんごを取った」と述べる文に合う。", "取らない": "否定形。「取らない」は現在の否定になり、実際に取った過去の出来事と合わない。", "取られる": "受身形。誰かに取られる意味になり、主語が自分で取る文と合わない。", "取ろう": "意向形。これから取る意志を表し、過去の出来事を述べる文と合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cccbe2e-caf3-47c6-9a9a-d86ebe2bdee1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37924, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妹は、棚の高いところにある箱に取ってくれた。", "corrected_sentence": "妹は、棚の高いところにある箱を取ってくれた。", "error_description": "「取る」の目的語は「を」で示す。「箱に」は場所を表すので、ここでは誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "取って", "is_correct": true, "explanation": "て形。「取って、においをかいだ」と動作の順序を示す形で合う。"}, {"text": "取ります", "is_correct": false, "explanation": "丁寧形。文末に来る形で、「取ります、においをかいだ」とはつながらない。"}, {"text": "取らせる", "is_correct": false, "explanation": "使役形。誰かに取らせる意味になり、彼女自身が取った文脈と合わない。"}, {"text": "取れる", "is_correct": false, "explanation": "可能形。取ることができる意味になり、実際に取った動作を表さない。"}], "correct_form": "取って", "base_form": "取る", "form_label": "て形", "sentence_index": 7, "explanations": {"取って": "て形。「取って、においをかいだ」と動作の順序を示す形で合う。", "取ります": "丁寧形。文末に来る形で、「取ります、においをかいだ」とはつながらない。", "取らせる": "使役形。誰かに取らせる意味になり、彼女自身が取った文脈と合わない。", "取れる": "可能形。取ることができる意味になり、実際に取った動作を表さない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cccbe2e-caf3-47c6-9a9a-d86ebe2bdee1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37926, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "乏しい", "is_correct": true, "explanation": "「豊か」の対義語。水の量が少なく足りないことを表し、ここの意味と反対になる。"}, {"text": "狭い", "is_correct": false, "explanation": "広さを表す語で、量の多少の対義語にはならない。"}, {"text": "浅い", "is_correct": false, "explanation": "深さを表す語で、水の量の多少を表す語にはならない。"}, {"text": "重い", "is_correct": false, "explanation": "重さを表す語で、水の豊かさの対義語にはならない。"}], "correct_answer": "乏しい", "explanations": {"乏しい": "「豊か」の対義語。水の量が少なく足りないことを表し、ここの意味と反対になる。", "狭い": "広さを表す語で、量の多少の対義語にはならない。", "浅い": "深さを表す語で、水の量の多少を表す語にはならない。", "重い": "重さを表す語で、水の豊かさの対義語にはならない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06e8f94a-57eb-4070-a427-4784d52d32e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37926, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "乏しい", "is_correct": true, "explanation": "「豊か」の対義語。実りが少ないことを表し、ここの意味と反対になる。"}, {"text": "薄い", "is_correct": false, "explanation": "厚さを表す語で、量の多少の対義語にはならない。"}, {"text": "軽い", "is_correct": false, "explanation": "重さを表す語で、実りの多さの対義語にはならない。"}, {"text": "遅い", "is_correct": false, "explanation": "速さを表す語で、実りの多少とは関係がない。"}], "correct_answer": "乏しい", "explanations": {"乏しい": "「豊か」の対義語。実りが少ないことを表し、ここの意味と反対になる。", "薄い": "厚さを表す語で、量の多少の対義語にはならない。", "軽い": "重さを表す語で、実りの多さの対義語にはならない。", "遅い": "速さを表す語で、実りの多少とは関係がない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06e8f94a-57eb-4070-a427-4784d52d32e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37926, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "たくさんあって、ゆたかなこと。", "primary_collocate": null, "pronunciation": "ゆたか", "ipa": "jɯtaka", "syllable_count": 3, "sentences": [{"text": "この町は、緑が豊かで、空気もきれいだ。", "target_word": "豊か", "complexity_tier": "T3", "furigana": "この町[まち]は、緑[みどり]が豊[ゆた]かで、空気[くうき]もきれいだ。", "sentence_source": "generated"}, {"text": "豊かな海には、たくさんの魚がいる。", "target_word": "豊か", "complexity_tier": "T3", "furigana": "豊[ゆた]かな海[うみ]には、たくさんの魚[さかな]がいる。", "sentence_source": "generated"}, {"text": "祖父は、経験が豊かなので、何でも教えてくれる。", "target_word": "豊か", "complexity_tier": "T3", "furigana": "祖父[そふ]は、経験[けいけん]が豊[ゆた]かなので、何[なん]でも教[おし]えてくれる。", "sentence_source": "generated"}, {"text": "雨が多い国なので、豊かな水が川を流れている。", "target_word": "豊か", "complexity_tier": "T3", "furigana": "雨が多い国なので、豊[ゆた]かな水が川を流れている。", "sentence_source": "generated"}, {"text": "この畑は土が豊かで、野菜がよく育つ。", "target_word": "豊か", "complexity_tier": "T3", "furigana": "この畑[はたけ]は土[つち]が豊[ゆた]かで、野菜[やさい]がよく育[そだ]つ。", "sentence_source": "generated"}, {"text": "彼女は表情が豊かで、見ていて楽しい。", "target_word": "豊か", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は表情[ひょうじょう]が豊[ゆた]かで、見[み]ていて楽[たの]しい。", "sentence_source": "generated"}, {"text": "豊かな森があるおかげで、山には動物がたくさん住んでいる。", "target_word": "豊か", "complexity_tier": "T3", "furigana": "豊[ゆた]かな森[もり]があるおかげで、山[やま]には動物[どうぶつ]がたくさん住[す]んでいる。", "sentence_source": "generated"}, {"text": "この図書館は、本の種類が豊かで、調べ物にも便利だ。", "target_word": "豊か", "complexity_tier": "T3", "furigana": "この図書館は、本の種類が豊[ゆた]かで、調べ物にも便利だ。", "sentence_source": "generated"}, {"text": "この果物は栄養が豊かだから、毎日食べるといい。", "target_word": "豊か", "complexity_tier": "T3", "furigana": "この果物は栄養が豊[ゆた]かだから、毎日食べるといい。", "sentence_source": "generated"}, {"text": "秋は実りが豊かで、市場に果物がたくさん並ぶ。", "target_word": "豊か", "complexity_tier": "T3", "furigana": "秋[あき]は実[みの]りが豊[ゆた]かで、市場[いちば]に果物[くだもの]がたくさん並[なら]ぶ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "豊かだ", "label": "終止形"}, {"form": "豊かな", "label": "連体形"}, {"form": "豊かに", "label": "連用形"}, {"form": "豊かで", "label": "て形"}], "register": "普通体（日常）", "sense_fingerprint": "物や資源、内容などが十分にたくさんあるようす", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd744feb5-cce0-45db-a3b7-f31e2c301cc9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37926, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "豊か", "is_correct": true, "explanation": "緑がたくさん茂る様子を表し、空気もきれいだという文脈に合う。"}, {"text": "頑丈", "is_correct": false, "explanation": "丈夫さを表す語で、緑の様子を言うには合わない。"}, {"text": "厳格", "is_correct": false, "explanation": "規律に厳しい様子を表す語で、緑には使わない。"}, {"text": "無口", "is_correct": false, "explanation": "話さない性質を表す語で、植物の様子には当てはまらない。"}], "explanations": {"豊か": "緑がたくさん茂る様子を表し、空気もきれいだという文脈に合う。", "頑丈": "丈夫さを表す語で、緑の様子を言うには合わない。", "厳格": "規律に厳しい様子を表す語で、緑には使わない。", "無口": "話さない性質を表す語で、植物の様子には当てはまらない。"}, "sentence_index": 0, "correct_answer": "豊か"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "祖父の代から家が豊かで、暮らしに困ったことがない。", "explanation": "ここは〈裕福〉の意味。豊かは物や内容の量の多さを表し、家の経済状態を言う使い方とは区別される。"}, {"text": "今月は豊かなスケジュールで、休みがない。", "explanation": "ここは〈過密〉の意味。豊かは恵みや内容が十分なことで、詰まった予定を表さない。"}, {"text": "この仕事は豊かな作業で、誰でもすぐ覚えられる。", "explanation": "ここは〈単純〉の意味。豊かは内容の充実を表すので、手間の少なさを表す語にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06e8f94a-57eb-4070-a427-4784d52d32e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37926, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "豊か", "is_correct": true, "explanation": "森の多さや恵みを表し、動物がたくさん住む文脈に合う。"}, {"text": "几帳面", "is_correct": false, "explanation": "物事を正確に行う性格を表す語で、森には使わない。"}, {"text": "大胆", "is_correct": false, "explanation": "恐れない態度を表す語で、森の様子とは合わない。"}, {"text": "慎重", "is_correct": false, "explanation": "注意深い態度を表す語で、森の状態を表す語にはならない。"}], "explanations": {"豊か": "森の多さや恵みを表し、動物がたくさん住む文脈に合う。", "几帳面": "物事を正確に行う性格を表す語で、森には使わない。", "大胆": "恐れない態度を表す語で、森の様子とは合わない。", "慎重": "注意深い態度を表す語で、森の状態を表す語にはならない。"}, "sentence_index": 6, "correct_answer": "豊か"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "豊かな計算で、お釣りを間違えた。", "explanation": "ここは〈正確〉の意味。豊かは量や内容の充実を表すので、計算の正しさを表す語にはならない。"}, {"text": "豊かな寒さが、三月まで続いた。", "explanation": "ここは〈厳しい〉の意味。豊かは恵みや量が十分なことで、寒さの厳しさは表せない。"}, {"text": "豊かな進歩で、暮らしが変わった。", "explanation": "ここは〈急速〉の意味。豊かは量や内容の充実を表し、進む速さを表す語ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06e8f94a-57eb-4070-a427-4784d52d32e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37926, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この湖は、水が豊かな、魚がよく育つ。", "corrected_sentence": "この湖は、水が豊かで、魚がよく育つ。", "error_description": "文の途中で続くときは「豊かで」（て形）を使う。「豊かな」は名詞に続く形で、ここでは誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "豊かな", "is_correct": true, "explanation": "連体形。名詞「海」を修飾しているので「な」が付く。"}, {"text": "豊かだ", "is_correct": false, "explanation": "終止形。名詞を直接修飾できず、「海」に続けられない。"}, {"text": "豊かに", "is_correct": false, "explanation": "連用形。動詞や形容詞を修飾する形で、名詞「海」には続かない。"}, {"text": "豊かで", "is_correct": false, "explanation": "て形。名詞を修飾する形ではないので、「海」の前には置けない。"}], "correct_form": "豊かな", "base_form": "豊かだ", "form_label": "連体形", "sentence_index": 1, "explanations": {"豊かな": "連体形。名詞「海」を修飾しているので「な」が付く。", "豊かだ": "終止形。名詞を直接修飾できず、「海」に続けられない。", "豊かに": "連用形。動詞や形容詞を修飾する形で、名詞「海」には続かない。", "豊かで": "て形。名詞を修飾する形ではないので、「海」の前には置けない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06e8f94a-57eb-4070-a427-4784d52d32e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37926, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この地域は、畑の実りが豊かくなって、食べ物が増えた。", "corrected_sentence": "この地域は、畑の実りが豊かになって、食べ物が増えた。", "error_description": "「豊か」は形状詞なので、「になる」の形で「に」を使う。「くなる」は形容詞の活用で、ここでは誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "豊かで", "is_correct": true, "explanation": "て形。「本の種類が豊かで、〜便利だ」と文中で続くので、「で」の形が正しい。"}, {"text": "豊かな", "is_correct": false, "explanation": "連体形。「、」の前で文が切れず、名詞を修飾しない位置では成り立たない。"}, {"text": "豊かさ", "is_correct": false, "explanation": "名詞形。「本の種類が豊かさ、」では述語にならず、文が成り立たない。"}, {"text": "豊かに", "is_correct": false, "explanation": "連用形。「、」の前で述語として働かず、文が成り立たない。"}], "correct_form": "豊かで", "base_form": "豊かだ", "form_label": "て形", "sentence_index": 7, "explanations": {"豊かで": "て形。「本の種類が豊かで、〜便利だ」と文中で続くので、「で」の形が正しい。", "豊かな": "連体形。「、」の前で文が切れず、名詞を修飾しない位置では成り立たない。", "豊かさ": "名詞形。「本の種類が豊かさ、」では述語にならず、文が成り立たない。", "豊かに": "連用形。「、」の前で述語として働かず、文が成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06e8f94a-57eb-4070-a427-4784d52d32e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37928, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「この森の存続」の形で、森の状態を示す「の」が存続の前に付く。"}, {"text": "を", "is_correct": false, "explanation": "「この森を存続は」は目的語の形として成り立たず、文が崩れる。"}, {"text": "に", "is_correct": false, "explanation": "「この森に存続は」は場所や対象を示す形で、主語句の修飾にはならない。"}, {"text": "から", "is_correct": false, "explanation": "「この森から存続は」は起点の形になり、存続の所属を表せず不自然。"}], "correct_answer": "の", "explanations": {"の": "「この森の存続」の形で、森の状態を示す「の」が存続の前に付く。", "を": "「この森を存続は」は目的語の形として成り立たず、文が崩れる。", "に": "「この森に存続は」は場所や対象を示す形で、主語句の修飾にはならない。", "から": "「この森から存続は」は起点の形になり、存続の所属を表せず不自然。"}, "error_tags": {"を": "object_marker", "に": "wrong_case", "から": "source"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "消滅", "is_correct": true, "explanation": "存続の対義語。なくなって消えてしまうことで、ずっとあり続けることの反対になる。"}, {"text": "誕生", "is_correct": false, "explanation": "新しく生まれることで、存続の対義語とは辞書でも結ばれない。"}, {"text": "増加", "is_correct": false, "explanation": "数や量が増えることで、続いていく状態との対義関係はない。"}, {"text": "発展", "is_correct": false, "explanation": "物事が伸びて広がることで、なくならずに続くことの反対にはならない。"}], "correct_answer": "消滅", "explanations": {"消滅": "存続の対義語。なくなって消えてしまうことで、ずっとあり続けることの反対になる。", "誕生": "新しく生まれることで、存続の対義語とは辞書でも結ばれない。", "増加": "数や量が増えることで、続いていく状態との対義関係はない。", "発展": "物事が伸びて広がることで、なくならずに続くことの反対にはならない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '680ef75a-81d1-4bc5-bb10-20c120ed0987') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37928, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "消滅", "is_correct": true, "explanation": "存続の対義語。会社などがなくなって消えることを指し、存続がかかっている状況と対になる。"}, {"text": "復活", "is_correct": false, "explanation": "一度なくなったものが生き返ることで、存続の対義語とは言えない。"}, {"text": "建設", "is_correct": false, "explanation": "新しく建てることで、続いていく状態との対義関係はない。"}, {"text": "増築", "is_correct": false, "explanation": "建物を増やして広げることで、存続とは対義関係にない。"}], "correct_answer": "消滅", "explanations": {"消滅": "存続の対義語。会社などがなくなって消えることを指し、存続がかかっている状況と対になる。", "復活": "一度なくなったものが生き返ることで、存続の対義語とは言えない。", "建設": "新しく建てることで、続いていく状態との対義関係はない。", "増築": "建物を増やして広げることで、存続とは対義関係にない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '680ef75a-81d1-4bc5-bb10-20c120ed0987') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37928, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "ずっとなくならないで、あること。", "primary_collocate": null, "pronunciation": "そんぞく", "ipa": "soɴzokɯ", "syllable_count": 4, "sentences": [{"text": "この小さな店の存続を、町の人はみんな願っている。", "target_word": "存続", "complexity_tier": "T3", "furigana": "この小[ちい]さな店[みせ]の存続[そんぞく]を、町[まち]の人[ひと]はみんな願[ねが]っている。", "sentence_source": "generated"}, {"text": "水が足りないと、この森の存続は危うくなる。", "target_word": "存続", "complexity_tier": "T3", "furigana": "水[みず]が足[た]りないと、この森[もり]の存続[そんぞく]は危[あやう]くなる。", "sentence_source": "generated"}, {"text": "学校の存続のために、卒業生がお金を集めた。", "target_word": "存続", "complexity_tier": "T3", "furigana": "学校[がっこう]の存続[そんぞく]のために、卒業生[そつぎょうせい]がお金[かね]を集[あつ]めた。", "sentence_source": "generated"}, {"text": "動物たちは、種の存続のために子どもを産み育てる。", "target_word": "存続", "complexity_tier": "T3", "furigana": "動物[どうぶつ]たちは、種[しゅ]の存続[そんぞく]のために子[こ]どもを産[う]み育[そだ]てる。", "sentence_source": "generated"}, {"text": "部員が足りなくて、サッカー部の存続が心配だ。", "target_word": "存続", "complexity_tier": "T3", "furigana": "部員[ぶいん]が足[た]りなくて、サッカー部[ぶ]の存続[そんぞく]が心配[しんぱい]だ。", "sentence_source": "generated"}, {"text": "古い祭りの存続を決めたのは、地元の人たちだ。", "target_word": "存続", "complexity_tier": "T3", "furigana": "古[ふる]い祭[まつ]りの存続[そんぞく]を決[き]めたのは、地元[じもと]の人[ひと]たちだ。", "sentence_source": "generated"}, {"text": "客が減って、駅前の映画館は存続できなくなった。", "target_word": "存続", "complexity_tier": "T3", "furigana": "客[きゃく]が減[へ]って、駅前[えきまえ]の映画館[えいがかん]は存続[そんぞく]できなくなった。", "sentence_source": "generated"}, {"text": "人気があるおかげで、この古い劇場は存続している。", "target_word": "存続", "complexity_tier": "T3", "furigana": "人気[にんき]があるおかげで、この古[ふる]い劇場[げきじょう]は存続[そんぞく]している。", "sentence_source": "generated"}, {"text": "森が守られれば、鳥たちの存続にもつながる。", "target_word": "存続", "complexity_tier": "T3", "furigana": "森[もり]が守[まも]られれば、鳥[とり]たちの存続[そんぞく]にもつながる。", "sentence_source": "generated"}, {"text": "会社の存続がかかっているので、社長は朝から晩まで働いた。", "target_word": "存続", "complexity_tier": "T3", "furigana": "会社[かいしゃ]の存続[そんぞく]がかかっているので、社長[しゃちょう]は朝[あさ]から晩[ばん]まで働[はたら]いた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "存続", "label": "基本形(名詞)"}, {"form": "存続する", "label": "辞書形"}, {"form": "存続した", "label": "過去形"}, {"form": "存続しない", "label": "否定形"}, {"form": "存続できる", "label": "可能形"}], "register": "neutral", "sense_fingerprint": "店・学校・生き物などがなくならずに、ずっとあり続けること(やさしい説明)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'babc5005-4b09-4076-ab17-d13e22e3c839') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37928, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "存続", "is_correct": true, "explanation": "「店の存続を願う」は、店がなくならずに続くことを願う意味で自然に成り立つ。"}, {"text": "宿題", "is_correct": false, "explanation": "「店の宿題を願う」は意味が通らず、町の人の願いとして成り立たない。"}, {"text": "掃除", "is_correct": false, "explanation": "「店の掃除を願う」は行為を願う文にならず、文脈に合わない。"}, {"text": "出張", "is_correct": false, "explanation": "店は出張しないので、「店の出張を願う」は成り立たない。"}], "explanations": {"存続": "「店の存続を願う」は、店がなくならずに続くことを願う意味で自然に成り立つ。", "宿題": "「店の宿題を願う」は意味が通らず、町の人の願いとして成り立たない。", "掃除": "「店の掃除を願う」は行為を願う文にならず、文脈に合わない。", "出張": "店は出張しないので、「店の出張を願う」は成り立たない。"}, "sentence_index": 0, "correct_answer": "存続"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "毎日の散歩を存続している。", "explanation": "ここは〈継続〉の意味。存続は店や学校などが消えずにあり続けることを指すので、個人の散歩には使わない。"}, {"text": "部屋の温度を存続させるために、毎日エアコンをつける。", "explanation": "ここは〈維持〉の意味。室温のように状態を一定に保つ場合は維持を使い、存続は合わない。"}, {"text": "焼け跡から存続物を探した。", "explanation": "ここは〈残存〉の意味。焼け跡に残っている物を指すので、続いていくことを表す存続は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '680ef75a-81d1-4bc5-bb10-20c120ed0987') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
